-- Step 2: Import Book of Mormon verses
-- (4208 verses)

INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-3', 'coc-bom-1908', 'I Nephi', 1, 3, 'For it came to pass in the commencement of the first year of the reign of Zedekiah, king of Judah (my father Lehi having dwelt at Jerusalem in all his days), and in that same year there came many prophets, prophesying unto the people that they must repent or the great city Jerusalem must be destroyed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-4', 'coc-bom-1908', 'I Nephi', 1, 4, 'Wherefore, it came to pass that my father Lehi, as he went forth, prayed unto the Lord, yea, even with all his heart in behalf of his people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-10', 'coc-bom-1908', 'I Nephi', 1, 10, 'And the first came, and stood before my father, and gave unto him a book, and bade him that he should read.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-12', 'coc-bom-1908', 'I Nephi', 1, 12, 'Yea, and many things did my father read concerning Jerusalem--that it should be destroyed, and the inhabitants thereof, many should perish by the sword, and many should be carried away captive into Babylon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-18', 'coc-bom-1908', 'I Nephi', 1, 18, 'Therefore, I would that ye should know that after the Lord had shown so many marvelous things unto my father Lehi, yea, concerning the destruction of Jerusalem, behold, he went forth among the people and began to prophesy and to declare unto them concerning the things which he had both seen and heard.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-20', 'coc-bom-1908', 'I Nephi', 1, 20, 'And he testified that the things which he saw and heard, and also the things which he read in the book, manifested plainly of the coming of a Messiah and also the redemption of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-22', 'coc-bom-1908', 'I Nephi', 1, 22, 'And they also sought his life, that they might take it away.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-23', 'coc-bom-1908', 'I Nephi', 1, 23, 'But behold, I, Nephi, will show unto you that the tender mercies of the Lord are over all those whom he hath chosen, because of their faith, to make them mighty even unto the power of deliverance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-25', 'coc-bom-1908', 'I Nephi', 1, 25, 'And because thou hast been faithful and declared unto this people the things which I commanded thee, behold, they seek to take away thy life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-26', 'coc-bom-1908', 'I Nephi', 1, 26, 'And it came to pass that the Lord commanded my father, even in a dream, that he should take his family and depart into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-28', 'coc-bom-1908', 'I Nephi', 1, 28, 'And it came to pass that he departed into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-32', 'coc-bom-1908', 'I Nephi', 1, 32, 'And he did travel in the wilderness with his family, which consisted of my mother Sariah, and my elder brothers, who were Laman, Lemuel, and Sam.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-33', 'coc-bom-1908', 'I Nephi', 1, 33, 'And it came to pass that when he had traveled three days in the wilderness, he pitched his tent in a valley by the side of a river of water.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-34', 'coc-bom-1908', 'I Nephi', 1, 34, 'And it came to pass that he built an altar of stones, and he made an offering unto the Lord and gave thanks unto the Lord, our God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-36', 'coc-bom-1908', 'I Nephi', 1, 36, 'And when my father saw that the waters of the river emptied into the fountain of the Red Sea, he spake unto Laman, saying, Oh, that thou mightest be like unto this river, continually running into the fountain of all righteousness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-37', 'coc-bom-1908', 'I Nephi', 1, 37, 'And he also spake unto Lemuel: Oh, that thou mightest be like unto this valley--firm, and steadfast, and immovable in keeping the commandments of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-39', 'coc-bom-1908', 'I Nephi', 1, 39, 'And this they said he had done because of the foolish imaginations of his heart.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-40', 'coc-bom-1908', 'I Nephi', 1, 40, 'And thus Laman and Lemuel, being the eldest, did murmur against their father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-41', 'coc-bom-1908', 'I Nephi', 1, 41, 'And they did murmur because they knew not the dealings of that God who had created them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-42', 'coc-bom-1908', 'I Nephi', 1, 42, 'Neither did they believe that Jerusalem, that great city, could be destroyed according to the words of the prophets.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-43', 'coc-bom-1908', 'I Nephi', 1, 43, 'And they were like unto the Jews, who were at Jerusalem, who sought to take away the life of my father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-44', 'coc-bom-1908', 'I Nephi', 1, 44, 'And it came to pass that my father did speak unto them in the valley of Lemuel, with power, being filled with the Spirit, until their frames did shake before him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-46', 'coc-bom-1908', 'I Nephi', 1, 46, 'And my father dwelt in a tent.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-47', 'coc-bom-1908', 'I Nephi', 1, 47, 'And it came to pass that I, Nephi, being exceeding young, nevertheless, being large in stature, and also having great desires to know of the mysteries of God,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-49', 'coc-bom-1908', 'I Nephi', 1, 49, 'And I spake unto Sam, making known unto him the things which the Lord had manifested unto me by his Holy Spirit.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-52', 'coc-bom-1908', 'I Nephi', 1, 52, 'And being grieved because of the hardness of their hearts, I cried unto the Lord for them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-54', 'coc-bom-1908', 'I Nephi', 1, 54, 'And inasmuch as ye shall keep my commandments, ye shall prosper and shall be led to a land of promise, yea, even a land which I have prepared for you, yea, a land which is choice above all other lands.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-55', 'coc-bom-1908', 'I Nephi', 1, 55, 'And inasmuch as thy brethren shall rebel against thee, they shall be cut off from the presence of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-56', 'coc-bom-1908', 'I Nephi', 1, 56, 'And inasmuch as thou shalt keep my commandments, thou shalt be made a ruler and a teacher over thy brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-58', 'coc-bom-1908', 'I Nephi', 1, 58, 'And if it so be that they rebel against me, they shall be a scourge unto thy seed, to stir them up in the ways of remembrance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-59', 'coc-bom-1908', 'I Nephi', 1, 59, 'And it came to pass that I, Nephi, returned from speaking with the Lord, to the tent of my father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-60', 'coc-bom-1908', 'I Nephi', 1, 60, 'And it came to pass that he spake unto me, saying, Behold, I have dreamed a dream, in the which the Lord hath commanded me that thou and thy brethren shall return to Jerusalem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-61', 'coc-bom-1908', 'I Nephi', 1, 61, 'For behold, Laban hath the record of the Jews and also a genealogy of thy forefathers, and they are engraven upon plates of brass.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-62', 'coc-bom-1908', 'I Nephi', 1, 62, 'Wherefore, the Lord hath commanded me that thou and thy brothers should go unto the house of Laban, and seek the records, and bring them down hither into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-64', 'coc-bom-1908', 'I Nephi', 1, 64, 'Therefore, go, my son, and thou shalt be favored of the Lord because thou hast not murmured.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-66', 'coc-bom-1908', 'I Nephi', 1, 66, 'And it came to pass that when my father had heard these words, he was exceeding glad, for he knew that I had been blessed of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-67', 'coc-bom-1908', 'I Nephi', 1, 67, 'And I, Nephi, and my brethren took our journey in the wilderness with our tents, to go up to the land of Jerusalem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-70', 'coc-bom-1908', 'I Nephi', 1, 70, 'And he desired of Laban the records which were engraven upon the plates of brass, which contained the genealogy of my father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-72', 'coc-bom-1908', 'I Nephi', 1, 72, 'Wherefore, he said unto him, Behold, thou art a robber, and I will slay thee.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-73', 'coc-bom-1908', 'I Nephi', 1, 73, 'But Laman fled out of his presence and told the things which Laban had done, unto us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-74', 'coc-bom-1908', 'I Nephi', 1, 74, 'And we began to be exceeding sorrowful, and my brethren were about to return unto my father in the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-75', 'coc-bom-1908', 'I Nephi', 1, 75, 'But behold, I said unto them, that as the Lord liveth, and as we live, we will not go down unto our father in the wilderness until we have accomplished the thing which the Lord hath commanded us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-79', 'coc-bom-1908', 'I Nephi', 1, 79, 'For behold, they have rejected the words of the prophets--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-80', 'coc-bom-1908', 'I Nephi', 1, 80, 'Wherefore, if my father should dwell in the land after he hath been commanded to flee out of the land, behold, he would also perish.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-81', 'coc-bom-1908', 'I Nephi', 1, 81, 'Wherefore, it must needs be that he flee out of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-82', 'coc-bom-1908', 'I Nephi', 1, 82, 'And behold, it is wisdom in God that we should obtain these records, that we may preserve unto our children the language of our fathers,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-83', 'coc-bom-1908', 'I Nephi', 1, 83, 'And also that we may preserve unto them the words which have been spoken by the mouth of all the holy prophets, which have been delivered unto them by the Spirit and power of God since the world began, even down unto this present time.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-84', 'coc-bom-1908', 'I Nephi', 1, 84, 'And it came to pass that after this manner of language did I persuade my brethren, that they might be faithful in keeping the commandments of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-85', 'coc-bom-1908', 'I Nephi', 1, 85, 'And it came to pass that we went down to the land of our inheritance, and we did gather together our gold, and our silver, and our precious things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-86', 'coc-bom-1908', 'I Nephi', 1, 86, 'And after we had gathered these things together, we went up again unto the house of Laban.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-87', 'coc-bom-1908', 'I Nephi', 1, 87, 'And it came to pass that we went in unto Laban and desired him that he would give unto us the records which were engraven upon the plates of brass, for which we would give unto him our gold, and our silver, and all our precious things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-88', 'coc-bom-1908', 'I Nephi', 1, 88, 'And it came to pass that when Laban saw our property, that it was exceeding great, he did lust after it, insomuch that he thrust us out and sent his servants to slay us, that he might obtain our property.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-90', 'coc-bom-1908', 'I Nephi', 1, 90, 'And it came to pass that we fled into the wilderness, and the servants of Laban did not overtake us, and we hid ourselves in the cavity of a rock.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-92', 'coc-bom-1908', 'I Nephi', 1, 92, 'Wherefore, Laman and Lemuel did speak many hard words unto us, their younger brothers, and they did smite us even with a rod.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-94', 'coc-bom-1908', 'I Nephi', 1, 94, 'Know ye not that the Lord hath chosen him to be a ruler over you, and this because of your iniquities?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-95', 'coc-bom-1908', 'I Nephi', 1, 95, 'Behold, ye shall go up to Jerusalem again, and the Lord will deliver Laban into your hands.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-96', 'coc-bom-1908', 'I Nephi', 1, 96, 'And after the angel had spoken unto us, he departed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-97', 'coc-bom-1908', 'I Nephi', 1, 97, 'And after the angel had departed, Laman and Lemuel again began to murmur, saying, How is it possible that the Lord will deliver Laban into our hands?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-104', 'coc-bom-1908', 'I Nephi', 1, 104, 'And it was by night, and I caused that they should hide themselves without the walls.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-105', 'coc-bom-1908', 'I Nephi', 1, 105, 'And after they had hid themselves, I, Nephi, crept into the city and went forth towards the house of Laban.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-106', 'coc-bom-1908', 'I Nephi', 1, 106, 'And I was led by the Spirit, not knowing beforehand the things which I should do.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-108', 'coc-bom-1908', 'I Nephi', 1, 108, 'And when I came to him, I found that it was Laban.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-113', 'coc-bom-1908', 'I Nephi', 1, 113, 'And it came to pass that the Spirit said unto me again, Slay him, for the Lord hath delivered him into thy hands.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-114', 'coc-bom-1908', 'I Nephi', 1, 114, 'Behold, the Lord slayeth the wicked to bring forth his righteous purposes.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-115', 'coc-bom-1908', 'I Nephi', 1, 115, 'It is better that one man should perish than that a nation should dwindle and perish in unbelief.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-116', 'coc-bom-1908', 'I Nephi', 1, 116, 'And now, when I, Nephi, had heard these words, I remembered the words of the Lord which he spake unto me in the wilderness, saying that, Inasmuch as thy seed shall keep my commandments, they shall prosper in the land of promise.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-117', 'coc-bom-1908', 'I Nephi', 1, 117, 'Yea, and I also thought that they could not keep the commandments of the Lord according to the law of Moses, save they should have the law.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-118', 'coc-bom-1908', 'I Nephi', 1, 118, 'And I also knew that the law was engraven upon the plates of brass.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-119', 'coc-bom-1908', 'I Nephi', 1, 119, 'And again, I knew that the Lord had delivered Laban into my hands for this cause, that I might obtain the records according to his commandments.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-122', 'coc-bom-1908', 'I Nephi', 1, 122, 'And after I had done this, I went forth unto the treasury of Laban.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-123', 'coc-bom-1908', 'I Nephi', 1, 123, 'And as I went forth towards the treasury of Laban, behold, I saw the servant of Laban, who had the keys of the treasury.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-125', 'coc-bom-1908', 'I Nephi', 1, 125, 'And he spake unto me concerning the elders of the Jews, he knowing that his master Laban had been out by night among them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-126', 'coc-bom-1908', 'I Nephi', 1, 126, 'And I spake unto him as if it had been Laban.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-127', 'coc-bom-1908', 'I Nephi', 1, 127, 'And I also spake unto him that I should carry the engravings which were upon the plates of brass to my elder brethren, who were without the walls.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-128', 'coc-bom-1908', 'I Nephi', 1, 128, 'And I also bade him that he should follow me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-129', 'coc-bom-1908', 'I Nephi', 1, 129, 'And he, supposing that I spake of the brethren of the church and that I was truly that Laban whom I had slain, wherefore, he did follow me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-130', 'coc-bom-1908', 'I Nephi', 1, 130, 'And he spake unto me many times concerning the elders of the Jews as I went forth unto my brethren, who were without the walls.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-131', 'coc-bom-1908', 'I Nephi', 1, 131, 'And it came to pass that when Laman saw me, he was exceedingly frightened, and also Lemuel and Sam.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-134', 'coc-bom-1908', 'I Nephi', 1, 134, 'And it came to pass that when the servant of Laban beheld my brethren, he began to tremble and was about to flee from before me and return to the city of Jerusalem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-135', 'coc-bom-1908', 'I Nephi', 1, 135, 'And now, I, Nephi, being a man large in stature, and also having received much strength of the Lord, therefore, I did seize upon the servant of Laban and held him that he should not flee.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-136', 'coc-bom-1908', 'I Nephi', 1, 136, 'And it came to pass that I spake with him, that if he would hearken unto my words, as the Lord liveth and as I live, even so, that if he would hearken unto our words, we would spare his life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-137', 'coc-bom-1908', 'I Nephi', 1, 137, 'And I spake unto him, even with an oath, that he need not fear--that he should be a free man like unto us if he would go down in the wilderness with us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-138', 'coc-bom-1908', 'I Nephi', 1, 138, 'And I also spake unto him, saying, Surely the Lord hath commanded us to do this thing. And shall we not be diligent in keeping the commandments of the Lord?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-139', 'coc-bom-1908', 'I Nephi', 1, 139, 'Therefore, if thou wilt go down into the wilderness to my father, thou shalt have place with us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-140', 'coc-bom-1908', 'I Nephi', 1, 140, 'And it came to pass that Zoram did take courage at the words which I spake.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-142', 'coc-bom-1908', 'I Nephi', 1, 142, 'And he also made an oath unto us that he would tarry with us from that time forth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-143', 'coc-bom-1908', 'I Nephi', 1, 143, 'Now we were desirous that he should tarry with us for this cause, that the Jews might not know concerning our flight into the wilderness, lest they should pursue us and destroy us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-144', 'coc-bom-1908', 'I Nephi', 1, 144, 'And it came to pass that when Zoram had made an oath unto us, our fears did cease concerning him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-145', 'coc-bom-1908', 'I Nephi', 1, 145, 'And it came to pass that we took the plates of brass and the servant of Laban, and departed into the wilderness, and journeyed unto the tent of our father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-147', 'coc-bom-1908', 'I Nephi', 1, 147, 'And she also had complained against my father, telling him that he was a visionary man, saying, Behold, thou hast led us forth from the land of our inheritance, and my sons are no more, and we perish in the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-148', 'coc-bom-1908', 'I Nephi', 1, 148, 'And after this manner of language had my mother complained against my father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-151', 'coc-bom-1908', 'I Nephi', 1, 151, 'Yea, and I know that the Lord will deliver my sons out of the hands of Laban and bring them down again unto us in the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-152', 'coc-bom-1908', 'I Nephi', 1, 152, 'And after this manner of language did my father Lehi comfort my mother Sariah concerning us, while we journeyed in the wilderness up to the land of Jerusalem to obtain the record of the Jews.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-155', 'coc-bom-1908', 'I Nephi', 1, 155, 'Yea, and I also know of a surety that the Lord hath protected my sons, and delivered them out of the hands of Laban, and gave them power whereby they could accomplish the thing which the Lord hath commanded them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-156', 'coc-bom-1908', 'I Nephi', 1, 156, 'And after this manner of language did she speak.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-158', 'coc-bom-1908', 'I Nephi', 1, 158, 'And after they had given thanks unto the God of Israel, my father Lehi took the records which were engraven upon the plates of brass, and he did search them from the beginning.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-159', 'coc-bom-1908', 'I Nephi', 1, 159, 'And he beheld that they did contain the five books of Moses, which gave an account of the creation of the world,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-160', 'coc-bom-1908', 'I Nephi', 1, 160, 'And also of Adam and Eve, who were our first parents,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-161', 'coc-bom-1908', 'I Nephi', 1, 161, 'And also a record of the Jews from the beginning, even down to the commencement of the reign of Zedekiah, king of Judah,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-162', 'coc-bom-1908', 'I Nephi', 1, 162, 'And also the prophecies of the holy prophets, from the beginning, even down to the commencement of the reign of Zedekiah,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-163', 'coc-bom-1908', 'I Nephi', 1, 163, 'And also many prophecies which have been spoken by the mouth of Jeremiah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-165', 'coc-bom-1908', 'I Nephi', 1, 165, 'Wherefore, he knew that he was a descendant of Joseph, yea, even that Joseph who was the son of Jacob, who was sold into Egypt and who was preserved by the hand of the Lord, that he might preserve his father Jacob and all his household from perishing with famine.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-166', 'coc-bom-1908', 'I Nephi', 1, 166, 'And they were also led out of captivity and out of the land of Egypt by that same God who had preserved them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-167', 'coc-bom-1908', 'I Nephi', 1, 167, 'And thus my father Lehi did discover the genealogy of his fathers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-169', 'coc-bom-1908', 'I Nephi', 1, 169, 'And now, when my father saw all these things, he was filled with the Spirit and began to prophesy concerning his seed--that these plates of brass should go forth unto all nations, kindreds, tongues, and people who were of his seed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-170', 'coc-bom-1908', 'I Nephi', 1, 170, 'Wherefore, he said that these plates of brass should never perish, neither should they be dimmed any more by time.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-171', 'coc-bom-1908', 'I Nephi', 1, 171, 'And he prophesied many things concerning his seed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-172', 'coc-bom-1908', 'I Nephi', 1, 172, 'And it came to pass that, thus far, I and my father had kept the commandments wherewith the Lord had commanded us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-173', 'coc-bom-1908', 'I Nephi', 1, 173, 'And we had obtained the records which the Lord had commanded us, and searched them, and found that they were desirable, yea, even of great worth unto us, insomuch that we could preserve the commandments of the Lord unto our children.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-1-174', 'coc-bom-1908', 'I Nephi', 1, 174, 'Wherefore, it was wisdom in the Lord that we should carry them with us as we journeyed in the wilderness towards the land of promise.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-2', 'coc-bom-1908', 'I Nephi', 2, 2, 'For it sufficeth me to say that we are a descendant of Joseph.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-3', 'coc-bom-1908', 'I Nephi', 2, 3, 'And it mattereth not to me that I am particular to give a full account of all the things of my father, for they cannot be written upon these plates, for I desire the room that I may write of the things of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-4', 'coc-bom-1908', 'I Nephi', 2, 4, 'For the fullness of mine intent is that I may persuade men to come unto the God of Abraham, and the God of Isaac, and the God of Jacob, and be saved.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-5', 'coc-bom-1908', 'I Nephi', 2, 5, 'Wherefore, the things which are pleasing unto the world, I do not write, but the things which are pleasing unto God and unto those who are not of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-6', 'coc-bom-1908', 'I Nephi', 2, 6, 'Wherefore, I shall give commandment unto my seed that they shall not occupy these plates with things which are not of worth unto the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-8', 'coc-bom-1908', 'I Nephi', 2, 8, 'And it came to pass that the Lord commanded him that I, Nephi, and my brethren should again return unto the land of Jerusalem and bring down Ishmael and his family into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-9', 'coc-bom-1908', 'I Nephi', 2, 9, 'And it came to pass that I, Nephi, did again, with my brethren, go forth into the wilderness to go up to Jerusalem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-10', 'coc-bom-1908', 'I Nephi', 2, 10, 'And it came to pass that we went up unto the house of Ishmael, and we did gain favor in the sight of Ishmael, insomuch that we did speak unto him the words of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-11', 'coc-bom-1908', 'I Nephi', 2, 11, 'And it came to pass that the Lord did soften the heart of Ishmael and also his household, insomuch that they took their journey with us down into the wilderness to the tent of our father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-12', 'coc-bom-1908', 'I Nephi', 2, 12, 'And it came to pass that as we journeyed in the wilderness, behold, Laman and Lemuel, and two of the daughters of Ishmael, and the two sons of Ishmael, and their families did rebel against us--yea, against me, Nephi, and Sam, and their father Ishmael, and his wife, and his three other daughters.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-13', 'coc-bom-1908', 'I Nephi', 2, 13, 'And it came to pass in the which rebellion they were desirous to return unto the land of Jerusalem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-14', 'coc-bom-1908', 'I Nephi', 2, 14, 'And now, I, Nephi, being grieved for the hardness of their hearts, therefore, I spake unto them, saying, yea, even unto Laman and unto Lemuel, Behold, ye are mine elder brethren. And how is it that ye are so hard in your hearts, and so blind in your minds, that ye have need that I, your younger brother, should speak unto you, yea, and set an example for you?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-15', 'coc-bom-1908', 'I Nephi', 2, 15, 'How is it that ye have not hearkened unto the word of the Lord?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-16', 'coc-bom-1908', 'I Nephi', 2, 16, 'How is it that ye have forgotten that ye have seen an angel of the Lord?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-17', 'coc-bom-1908', 'I Nephi', 2, 17, 'Yea, and how is it that ye have forgotten what great things the Lord hath done for us in delivering us out of the hands of Laban, and also that we should obtain the record?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-18', 'coc-bom-1908', 'I Nephi', 2, 18, 'Yea, and how is it that ye have forgotten that the Lord is able to do all things according to his will for the children of men if it so be that they exercise faith in him? Wherefore, let us be faithful to him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-20', 'coc-bom-1908', 'I Nephi', 2, 20, 'For all things which the Lord hath spoken concerning the destruction of Jerusalem must be fulfilled.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-22', 'coc-bom-1908', 'I Nephi', 2, 22, 'For behold, they have rejected the prophets, and Jeremiah have they cast into prison.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-23', 'coc-bom-1908', 'I Nephi', 2, 23, 'And they have sought to take away the life of my father, insomuch that they have driven him out of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-24', 'coc-bom-1908', 'I Nephi', 2, 24, 'Now behold, I say unto you that if ye will return unto Jerusalem, ye shall also perish with them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-26', 'coc-bom-1908', 'I Nephi', 2, 26, 'And it came to pass that when I, Nephi, had spoken these words unto my brethren, they were angry with me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-27', 'coc-bom-1908', 'I Nephi', 2, 27, 'And it came to pass that they did lay their hands upon me--for behold, they were exceeding wroth--and they did bind me with cords, for they sought to take away my life, that they might leave me in the wilderness to be devoured by wild beasts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-28', 'coc-bom-1908', 'I Nephi', 2, 28, 'But it came to pass that I prayed unto the Lord, saying, O Lord, according to my faith which is in thee, wilt thou deliver me from the hands of my brethren,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-29', 'coc-bom-1908', 'I Nephi', 2, 29, 'Yea, even give me strength that I may burst these bands with which I am bound.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-30', 'coc-bom-1908', 'I Nephi', 2, 30, 'And it came to pass that when I had said these words, behold, the bands were loosed from off my hands and feet, and I stood before my brethren, and I spake unto them again.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-33', 'coc-bom-1908', 'I Nephi', 2, 33, 'And it came to pass that they were sorrowful because of their wickedness, insomuch that they did bow down before me and did plead with me that I would forgive them of the thing that they had done against me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-34', 'coc-bom-1908', 'I Nephi', 2, 34, 'And it came to pass that I did frankly forgive them all that they had done, and I did exhort them that they would pray unto the Lord, their God, for forgiveness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-35', 'coc-bom-1908', 'I Nephi', 2, 35, 'And it came to pass that they did so.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-36', 'coc-bom-1908', 'I Nephi', 2, 36, 'And after they had done praying unto the Lord, we did again travel on our journey toward the tent of our father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-37', 'coc-bom-1908', 'I Nephi', 2, 37, 'And it came to pass that we did come down unto the tent of our father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-39', 'coc-bom-1908', 'I Nephi', 2, 39, 'And they did offer sacrifice and burnt offerings unto him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-40', 'coc-bom-1908', 'I Nephi', 2, 40, 'And it came to pass that we had gathered together all manner of seeds of every kind--both of grain of every kind and also of the seeds of fruits of every kind.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-45', 'coc-bom-1908', 'I Nephi', 2, 45, 'And it came to pass that he spake unto me and bade me follow him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-46', 'coc-bom-1908', 'I Nephi', 2, 46, 'And it came to pass that as I followed him, I beheld myself that I was in a dark and dreary waste.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-47', 'coc-bom-1908', 'I Nephi', 2, 47, 'And after I had traveled for the space of many hours in darkness, I began to pray unto the Lord that he would have mercy on me according to the multitude of his tender mercies.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-48', 'coc-bom-1908', 'I Nephi', 2, 48, 'And it came to pass after I had prayed unto the Lord, I beheld a large and spacious field.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-49', 'coc-bom-1908', 'I Nephi', 2, 49, 'And it came to pass that I beheld a tree, whose fruit was desirable to make one happy.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-51', 'coc-bom-1908', 'I Nephi', 2, 51, 'Yea, and I beheld that the fruit thereof was white, to exceed all the whiteness that I had ever seen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-58', 'coc-bom-1908', 'I Nephi', 2, 58, 'And it came to pass that they did come unto me and partake of the fruit also.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-60', 'coc-bom-1908', 'I Nephi', 2, 60, 'Wherefore, I cast mine eyes towards the head of the river, that perhaps I might see them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-61', 'coc-bom-1908', 'I Nephi', 2, 61, 'And it came to pass that I saw them, but they would not come unto me and partake of the fruit.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-65', 'coc-bom-1908', 'I Nephi', 2, 65, 'And I saw numberless concourses of people, many of whom were pressing forward, that they might obtain the path which led unto the tree by which I stood.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-66', 'coc-bom-1908', 'I Nephi', 2, 66, 'And it came to pass that they did come forth and commence in the path which led to the tree.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-67', 'coc-bom-1908', 'I Nephi', 2, 67, 'And it came to pass that there arose a mist of darkness, yea, even an exceeding great mist of darkness, insomuch that they who had commenced in the path did lose their way, that they wandered off and were lost.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-69', 'coc-bom-1908', 'I Nephi', 2, 69, 'And they did press forward through the mist of darkness, clinging to the rod of iron, even until they did come forth and partake of the fruit of the tree.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-70', 'coc-bom-1908', 'I Nephi', 2, 70, 'And after they had partaken of the fruit of the tree, they did cast their eyes about as if they were ashamed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-72', 'coc-bom-1908', 'I Nephi', 2, 72, 'And it stood as it were in the air, high above the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-75', 'coc-bom-1908', 'I Nephi', 2, 75, 'And they were in the attitude of mocking and pointing their fingers towards those who had come at and were partaking of the fruit.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-77', 'coc-bom-1908', 'I Nephi', 2, 77, 'And now, I, Nephi, do not speak all the words of my father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-79', 'coc-bom-1908', 'I Nephi', 2, 79, 'And he also saw other multitudes feeling their way towards that great and spacious building.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-81', 'coc-bom-1908', 'I Nephi', 2, 81, 'And many were lost from his view, wandering in strange roads.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-82', 'coc-bom-1908', 'I Nephi', 2, 82, 'And great was the multitude that did enter into that strange building.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-84', 'coc-bom-1908', 'I Nephi', 2, 84, 'These are the words of my father: For as many as heeded them, had fallen away.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-85', 'coc-bom-1908', 'I Nephi', 2, 85, 'And Laman and Lemuel partook not of the fruit, said my father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-87', 'coc-bom-1908', 'I Nephi', 2, 87, 'Yea, he feared lest they should be cast off from the presence of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-89', 'coc-bom-1908', 'I Nephi', 2, 89, 'Yea, my father did preach unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-91', 'coc-bom-1908', 'I Nephi', 2, 91, 'And he did cease speaking unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-92', 'coc-bom-1908', 'I Nephi', 2, 92, 'And all these things did my father see, and hear, and speak as he dwelt in a tent, in the valley of Lemuel--and also a great many more things, which cannot be written upon these plates.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-96', 'coc-bom-1908', 'I Nephi', 2, 96, 'Nevertheless, I have received a commandment of the Lord that I should make these plates for the special purpose, that there should be an account engraven of the ministry of my people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-99', 'coc-bom-1908', 'I Nephi', 2, 99, 'Wherefore, the Lord hath commanded me to make these plates for a wise purpose in him, which purpose I know not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-2-102', 'coc-bom-1908', 'I Nephi', 2, 102, 'And thus it is. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-3', 'coc-bom-1908', 'I Nephi', 3, 3, 'And after they should be brought back out of captivity, they should possess again the land of their inheritance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-4', 'coc-bom-1908', 'I Nephi', 3, 4, 'Yea, even six hundred years from the time that my father left Jerusalem, a prophet would the Lord God raise up among the Jews, even a Messiah or, in other words, a Savior of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-5', 'coc-bom-1908', 'I Nephi', 3, 5, 'And he also spake concerning the prophets--how great a number had testified of these things concerning this Messiah of whom he had spoken, or this Redeemer of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-6', 'coc-bom-1908', 'I Nephi', 3, 6, 'Wherefore, all mankind were in a lost and in a fallen state and ever would be, save they should rely on this Redeemer.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-10', 'coc-bom-1908', 'I Nephi', 3, 10, 'And much spake my father concerning this thing.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-12', 'coc-bom-1908', 'I Nephi', 3, 12, 'And after he had baptized the Messiah with water, he should behold and bear record that he had baptized the Lamb of God, who should take away the sins of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-13', 'coc-bom-1908', 'I Nephi', 3, 13, 'And it came to pass after my father had spoken these words, he spake unto my brethren concerning the gospel which should be preached among the Jews,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-14', 'coc-bom-1908', 'I Nephi', 3, 14, 'And also concerning the dwindling of the Jews in unbelief.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-15', 'coc-bom-1908', 'I Nephi', 3, 15, 'And after they had slain the Messiah who should come, and after he had been slain, he should rise from the dead and should make himself manifest by the Holy Ghost unto the Gentiles.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-16', 'coc-bom-1908', 'I Nephi', 3, 16, 'Yea, even my father spake much concerning the Gentiles and also concerning the house of Israel, that they should be compared like unto an olive tree, whose branches should be broken off and should be scattered upon all the face of the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-17', 'coc-bom-1908', 'I Nephi', 3, 17, 'Wherefore, he said it must needs be that we should be led with one accord into the land of promise, unto the fulfilling of the word of the Lord that we should be scattered upon all the face of the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-19', 'coc-bom-1908', 'I Nephi', 3, 19, 'Or, in fine, after the Gentiles had received the fullness of the gospel, the natural branches of the olive tree, or the remnants of the house of Israel, should be grafted in, or come to the knowledge of the true Messiah, their Lord and their Redeemer.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-20', 'coc-bom-1908', 'I Nephi', 3, 20, 'And after this manner of language did my father prophesy and speak unto my brethren,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-22', 'coc-bom-1908', 'I Nephi', 3, 22, 'And all these things of which I have spoken were done as my father dwelt in a tent in the valley of Lemuel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-23', 'coc-bom-1908', 'I Nephi', 3, 23, 'And it came to pass after I, Nephi, having heard all the words of my father concerning the things which he saw in a vision,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-24', 'coc-bom-1908', 'I Nephi', 3, 24, 'And also the things which he spake by the power of the Holy Ghost, which power he received by faith on the Son of God--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-25', 'coc-bom-1908', 'I Nephi', 3, 25, 'And the Son of God was the Messiah who should come--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-26', 'coc-bom-1908', 'I Nephi', 3, 26, 'I, Nephi, was desirous also that I might see, and hear, and know of these things by the power of the Holy Ghost, which is the gift of God unto all those who diligently seek him, as well in times of old as in the time that he should manifest himself unto the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-27', 'coc-bom-1908', 'I Nephi', 3, 27, 'For he is the same yesterday, today, and forever.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-30', 'coc-bom-1908', 'I Nephi', 3, 30, 'And the mysteries of God shall be unfolded unto them by the power of the Holy Ghost, as well in this time as in times of old,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-32', 'coc-bom-1908', 'I Nephi', 3, 32, 'Wherefore, the course of the Lord is one eternal round.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-33', 'coc-bom-1908', 'I Nephi', 3, 33, 'Therefore, remember, O man, for all thy doings thou shalt be brought into judgment.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-36', 'coc-bom-1908', 'I Nephi', 3, 36, 'And the Holy Ghost giveth authority that I should speak these things and deny them not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-37', 'coc-bom-1908', 'I Nephi', 3, 37, 'For it came to pass after I had desired to know the things that my father had seen--and believing that the Lord was able to make them known unto me--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-38', 'coc-bom-1908', 'I Nephi', 3, 38, 'As I sat pondering in mine heart, I was caught away in the Spirit of the Lord, yea, into an exceeding high mountain, which I never had before seen and upon which I never had before set my foot.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-39', 'coc-bom-1908', 'I Nephi', 3, 39, 'And the Spirit said unto me, Behold, what desirest thou?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-40', 'coc-bom-1908', 'I Nephi', 3, 40, 'And I said, I desire to behold the things which my father saw.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-41', 'coc-bom-1908', 'I Nephi', 3, 41, 'And the Spirit said unto me, Believest thou that thy father saw the tree of which he hath spoken?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-42', 'coc-bom-1908', 'I Nephi', 3, 42, 'And I said, Yea, thou knowest that I believe all the words of my father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-47', 'coc-bom-1908', 'I Nephi', 3, 47, 'And it came to pass after I had seen the tree, I said unto the Spirit, I behold thou hast shown unto me the tree which is precious above all.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-48', 'coc-bom-1908', 'I Nephi', 3, 48, 'And he said unto me, What desirest thou?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-49', 'coc-bom-1908', 'I Nephi', 3, 49, 'And I said unto him, To know the interpretation thereof.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-52', 'coc-bom-1908', 'I Nephi', 3, 52, 'And it came to pass that I looked and beheld the great city of Jerusalem and also other cities.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-55', 'coc-bom-1908', 'I Nephi', 3, 55, 'And I said unto him, A virgin, most beautiful and fair above all other virgins.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-56', 'coc-bom-1908', 'I Nephi', 3, 56, 'And he said unto me, Knowest thou the condescension of God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-58', 'coc-bom-1908', 'I Nephi', 3, 58, 'And he said unto me, Behold, the virgin whom thou seest is the mother of the Son of God, after the manner of the flesh.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-60', 'coc-bom-1908', 'I Nephi', 3, 60, 'And after she had been carried away in the Spirit for the space of a time, the angel spake unto me, saying, Look!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-61', 'coc-bom-1908', 'I Nephi', 3, 61, 'And I looked and beheld the virgin again, bearing a child in her arms.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-62', 'coc-bom-1908', 'I Nephi', 3, 62, 'And the angel said unto me, Behold the Lamb of God, yea, even the Son of the Eternal Father!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-63', 'coc-bom-1908', 'I Nephi', 3, 63, 'Knowest thou the meaning of the tree which thy father saw?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-65', 'coc-bom-1908', 'I Nephi', 3, 65, 'And he spake unto me, saying, Yea, and the most joyous to the soul.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-67', 'coc-bom-1908', 'I Nephi', 3, 67, 'And I saw many fall down at his feet and worship him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-69', 'coc-bom-1908', 'I Nephi', 3, 69, 'And I also beheld that the tree of life was a representation of the love of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-70', 'coc-bom-1908', 'I Nephi', 3, 70, 'And the angel said unto me again, Look and behold the condescension of God!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-72', 'coc-bom-1908', 'I Nephi', 3, 72, 'And I also beheld the prophet who should prepare the way before him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-74', 'coc-bom-1908', 'I Nephi', 3, 74, 'And after he was baptized, I beheld the heavens open, and the Holy Ghost come down out of heaven and abode upon him in the form of a dove.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-77', 'coc-bom-1908', 'I Nephi', 3, 77, 'And I beheld that they cast him out from among them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-78', 'coc-bom-1908', 'I Nephi', 3, 78, 'And I also beheld twelve others following him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-79', 'coc-bom-1908', 'I Nephi', 3, 79, 'And it came to pass that they were carried away in the Spirit from before my face, and I saw them not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-80', 'coc-bom-1908', 'I Nephi', 3, 80, 'And it came to pass that the angel spake unto me again, saying, Look! And I looked, and I beheld the heavens open again,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-82', 'coc-bom-1908', 'I Nephi', 3, 82, 'And he spake unto me again, saying, Look! And I looked, and I beheld the Lamb of God going forth among the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-84', 'coc-bom-1908', 'I Nephi', 3, 84, 'And the angel spake and showed all these things unto me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-85', 'coc-bom-1908', 'I Nephi', 3, 85, 'And they were healed by the power of the Lamb of God, and the devils and the unclean spirits were cast out.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-87', 'coc-bom-1908', 'I Nephi', 3, 87, 'And I, Nephi, saw that he was lifted up upon the cross and slain for the sins of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-90', 'coc-bom-1908', 'I Nephi', 3, 90, 'And I beheld that they were in a large and spacious building, like unto the building which my father saw.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-92', 'coc-bom-1908', 'I Nephi', 3, 92, 'Yea, behold, the house of Israel hath gathered together to fight against the twelve apostles of the Lamb.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-95', 'coc-bom-1908', 'I Nephi', 3, 95, 'And the angel of the Lord spake unto me again, saying, Thus shall be the destruction of all nations, kindreds, tongues, and people that shall fight against the twelve apostles of the Lamb.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-96', 'coc-bom-1908', 'I Nephi', 3, 96, 'And it came to pass that the angel said unto me, Look, and behold thy seed and also the seed of thy brethren!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-98', 'coc-bom-1908', 'I Nephi', 3, 98, 'And I beheld multitudes of people, yea, even as it were in number as many as the sand of the sea.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-101', 'coc-bom-1908', 'I Nephi', 3, 101, 'And I beheld many cities, yea, even that I did not number them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-102', 'coc-bom-1908', 'I Nephi', 3, 102, 'And it came to pass that I saw a mist of darkness on the face of the land of promise.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-109', 'coc-bom-1908', 'I Nephi', 3, 109, 'And I saw many that did tumble to the earth because of the quaking thereof.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-111', 'coc-bom-1908', 'I Nephi', 3, 111, 'And behold, I saw multitudes who had not fallen because of the great and terrible judgments of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-113', 'coc-bom-1908', 'I Nephi', 3, 113, 'And I also saw and bear record that the Holy Ghost fell upon twelve others, and they were ordained of God and chosen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-114', 'coc-bom-1908', 'I Nephi', 3, 114, 'And the angel spake unto me, saying, Behold the twelve disciples of the Lamb, who are chosen to minister unto thy seed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-115', 'coc-bom-1908', 'I Nephi', 3, 115, 'And he said unto me, Thou remembereth the twelve apostles of the Lamb? Behold, they are they who shall judge the twelve tribes of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-118', 'coc-bom-1908', 'I Nephi', 3, 118, 'And the angel said unto me, Look! And I looked and beheld three generations pass away in righteousness, and their garments were white, even like unto the Lamb of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-119', 'coc-bom-1908', 'I Nephi', 3, 119, 'And the angel said unto me, These are made white in the blood of the Lamb because of their faith in him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-120', 'coc-bom-1908', 'I Nephi', 3, 120, 'And I, Nephi, also saw many of the fourth generation, who passed away in righteousness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-121', 'coc-bom-1908', 'I Nephi', 3, 121, 'And it came to pass that I saw the multitudes of the earth gathered together.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-122', 'coc-bom-1908', 'I Nephi', 3, 122, 'And the angel said unto me, Behold thy seed and also the seed of thy brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-126', 'coc-bom-1908', 'I Nephi', 3, 126, 'And the large and spacious building which thy father saw is vain imaginations and the pride of the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-127', 'coc-bom-1908', 'I Nephi', 3, 127, 'And a great and a terrible gulf divideth them, yea, even the word of the justice of the eternal God and the Messiah, who is the Lamb of God, of whom the Holy Ghost beareth record, from the beginning of the world until this time, and from this time henceforth and forever.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-129', 'coc-bom-1908', 'I Nephi', 3, 129, 'And because of the pride of my seed and the temptations of the devil, I beheld that the seed of my brethren did overpower the people of my seed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-133', 'coc-bom-1908', 'I Nephi', 3, 133, 'And the angel said unto me, Behold, these shall dwindle in unbelief.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-134', 'coc-bom-1908', 'I Nephi', 3, 134, 'And it came to pass that I beheld after they had dwindled in unbelief, they became a dark, and loathsome, and a filthy people, full of idleness and all manner of abominations.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-135', 'coc-bom-1908', 'I Nephi', 3, 135, 'And it came to pass that the angel spake unto me, saying, Look! And I looked and beheld many nations and kingdoms.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-136', 'coc-bom-1908', 'I Nephi', 3, 136, 'And the angel said unto me, What beholdest thou?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-137', 'coc-bom-1908', 'I Nephi', 3, 137, 'And I said, I behold many nations and kingdoms.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-138', 'coc-bom-1908', 'I Nephi', 3, 138, 'And he said unto me, These are the nations and kingdoms of the Gentiles.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-139', 'coc-bom-1908', 'I Nephi', 3, 139, 'And it came to pass that I saw among the nations of the Gentiles the foundation of a great church.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-140', 'coc-bom-1908', 'I Nephi', 3, 140, 'And the angel said unto me, Behold the foundation of a church, which is most abominable above all other churches, which slayeth the saints of God, yea, and tortureth them, and bindeth them down, and yoketh them with a yoke of iron, and bringeth them down into captivity.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-144', 'coc-bom-1908', 'I Nephi', 3, 144, 'And also for the praise of the world do they destroy the saints of God and bring them down into captivity.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-146', 'coc-bom-1908', 'I Nephi', 3, 146, 'And it came to pass that the angel said unto me, Behold, the wrath of God is upon the seed of thy brethren!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-152', 'coc-bom-1908', 'I Nephi', 3, 152, 'And it came to pass that I, Nephi, beheld that the Gentiles who had gone forth out of captivity did humble themselves before the Lord, and the power of the Lord was with them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-154', 'coc-bom-1908', 'I Nephi', 3, 154, 'And I beheld that the power of God was with them and also that the wrath of God was upon all those that were gathered together against them to battle.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-155', 'coc-bom-1908', 'I Nephi', 3, 155, 'And I, Nephi, beheld that the Gentiles that had gone out of captivity were delivered by the power of God out of the hands of all other nations.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-156', 'coc-bom-1908', 'I Nephi', 3, 156, 'And it came to pass that I, Nephi, beheld that they did prosper in the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-157', 'coc-bom-1908', 'I Nephi', 3, 157, 'And I beheld a book, and it was carried forth among them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-158', 'coc-bom-1908', 'I Nephi', 3, 158, 'And the angel said unto me, Knowest thou the meaning of the book?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-159', 'coc-bom-1908', 'I Nephi', 3, 159, 'And I said unto him, I know not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-164', 'coc-bom-1908', 'I Nephi', 3, 164, 'Wherefore, they are of great worth unto the Gentiles.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-166', 'coc-bom-1908', 'I Nephi', 3, 166, 'Wherefore, these things go forth from the Jews in purity unto the Gentiles, according to the truth which is in God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-170', 'coc-bom-1908', 'I Nephi', 3, 170, 'And all this have they done that they might pervert the right ways of the Lord, that they might blind the eyes and harden the hearts of the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-173', 'coc-bom-1908', 'I Nephi', 3, 173, 'And after it goeth forth unto all the nations of the Gentiles, yea, even across the many waters which thou hast seen, with the Gentiles which have gone forth out of captivity,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-174', 'coc-bom-1908', 'I Nephi', 3, 174, 'Thou seest because of the many plain and precious things which have been taken out of the book, which were plain unto the understanding of the children of men, according to the plainness which is in the Lamb of God,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-175', 'coc-bom-1908', 'I Nephi', 3, 175, 'Because of these things which are taken away out of the gospel of the Lamb, an exceeding great many do stumble, yea, insomuch that Satan hath great power over them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-176', 'coc-bom-1908', 'I Nephi', 3, 176, 'Nevertheless, thou beholdest that the Gentiles--who have gone forth out of captivity and have been lifted up by the power of God above all other nations upon the face of the land, which is choice above all other lands,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-179', 'coc-bom-1908', 'I Nephi', 3, 179, 'Neither will the Lord God suffer that the Gentiles shall forever remain in that awful state of blindness, which thou beholdest they are in because of the plain and most precious parts of the gospel of the Lamb which have been kept back by that abominable church, whose formation thou hast seen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-180', 'coc-bom-1908', 'I Nephi', 3, 180, 'Wherefore, saith the Lamb of God, I will be merciful unto the Gentiles, unto the visiting of the remnant of the house of Israel in great judgment.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-181', 'coc-bom-1908', 'I Nephi', 3, 181, 'And it came to pass that the angel of the Lord spake unto me, saying, Behold, saith the Lamb of God, after I have visited the remnant of the house of Israel, and this remnant of whom I speak is the seed of thy father,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-182', 'coc-bom-1908', 'I Nephi', 3, 182, 'Wherefore, after I have visited them in judgment and smitten them by the hand of the Gentiles,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-183', 'coc-bom-1908', 'I Nephi', 3, 183, 'And after the Gentiles do stumble exceedingly because of the most plain and precious parts of the gospel of the Lamb which have been kept back by that abominable church, which is the mother of harlots, saith the Lamb, I will be merciful unto the Gentiles in that day, insomuch that I will bring forth unto them in mine own power much of my gospel, which shall be plain and precious, saith the Lamb.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-186', 'coc-bom-1908', 'I Nephi', 3, 186, 'And in them shall be written my gospel, saith the Lamb, and my rock and my salvation.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-189', 'coc-bom-1908', 'I Nephi', 3, 189, 'And whoso shall publish peace, yea, tidings of great joy, how beautiful upon the mountains shall they be.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-191', 'coc-bom-1908', 'I Nephi', 3, 191, 'And after it had come forth unto them, I beheld other books which came forth by the power of the Lamb from the Gentiles unto them, unto the convincing of the Gentiles, and the remnant of the seed of my brethren, and also the Jews, who were scattered upon all the face of the earth, that the records of the prophets and of the twelve apostles of the Lamb are true.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-194', 'coc-bom-1908', 'I Nephi', 3, 194, 'And they must come according to the words which shall be established by the mouth of the Lamb.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-197', 'coc-bom-1908', 'I Nephi', 3, 197, 'For there is one God and one Shepherd over all the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-198', 'coc-bom-1908', 'I Nephi', 3, 198, 'And the time cometh that he shall manifest himself unto all nations, both unto the Jews and also unto the Gentiles.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-199', 'coc-bom-1908', 'I Nephi', 3, 199, 'And after he has manifested himself unto the Jews and also unto the Gentiles, then he shall manifest himself unto the Gentiles and also unto the Jews.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-200', 'coc-bom-1908', 'I Nephi', 3, 200, 'And the last shall be first, and the first shall be last.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-203', 'coc-bom-1908', 'I Nephi', 3, 203, 'And they shall be a blessed people upon the promised land forever.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-206', 'coc-bom-1908', 'I Nephi', 3, 206, 'And that great pit which hath been digged for them by that great and abominable church, which was founded by the devil and his children, that he might lead away the souls of men down to hell,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-207', 'coc-bom-1908', 'I Nephi', 3, 207, 'Yea, that great pit which hath been digged for the destruction of men shall be filled by those who digged it, unto their utter destruction, saith the Lamb of God--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-209', 'coc-bom-1908', 'I Nephi', 3, 209, 'For behold, this is according to the captivity of the devil and also according to the justice of God, upon all those who will work wickedness and abomination before him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-214', 'coc-bom-1908', 'I Nephi', 3, 214, 'For the time cometh, saith the Lamb of God, that I will work a great and a marvelous work among the children of men:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-215', 'coc-bom-1908', 'I Nephi', 3, 215, 'A work which shall be everlasting, either on the one hand or on the other--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-216', 'coc-bom-1908', 'I Nephi', 3, 216, 'Either to the convincing of them unto peace and life eternal, or unto the deliverance of them to the hardness of their hearts and the blindness of their minds, unto their being brought down into captivity and also unto destruction, both temporally and spiritually, according to the captivity of the devil, of which I have spoken.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-217', 'coc-bom-1908', 'I Nephi', 3, 217, 'And it came to pass that when the angel had spoken these words, he said unto me, Remember thou the covenants of the Father unto the house of Israel?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-218', 'coc-bom-1908', 'I Nephi', 3, 218, 'I said unto him, Yea.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-219', 'coc-bom-1908', 'I Nephi', 3, 219, 'And it came to pass that he said unto me, Look and behold that great and abominable church, which is the mother of abominations, whose founder is the devil.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-220', 'coc-bom-1908', 'I Nephi', 3, 220, 'And he said unto me, Behold, there are save two churches only:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-223', 'coc-bom-1908', 'I Nephi', 3, 223, 'And she is the whore of all the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-225', 'coc-bom-1908', 'I Nephi', 3, 225, 'And she had dominion over all the earth, among all nations, kindreds, tongues, and people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-228', 'coc-bom-1908', 'I Nephi', 3, 228, 'And their dominions upon the face of the earth were small because of the wickedness of the great whore whom I saw.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-229', 'coc-bom-1908', 'I Nephi', 3, 229, 'And it came to pass that I beheld that the great mother of abominations did gather together in multitudes upon the face of all the earth, among all the nations of the Gentiles, to fight against the Lamb of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-231', 'coc-bom-1908', 'I Nephi', 3, 231, 'And they were armed with righteousness and with the power of God in great glory.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-233', 'coc-bom-1908', 'I Nephi', 3, 233, 'And as there began to be wars and rumors of wars among all the nations which belonged to the mother of abominations, the angel spake unto me, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-236', 'coc-bom-1908', 'I Nephi', 3, 236, 'And when the day cometh that the wrath of God is poured out upon the mother of harlots, which is the great and abominable church of all the earth, whose foundation is the devil,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-237', 'coc-bom-1908', 'I Nephi', 3, 237, 'Then at that day, the work of the Father shall commence in preparing the way for the fulfilling of his covenants which he hath made to his people, who are of the house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-238', 'coc-bom-1908', 'I Nephi', 3, 238, 'And it came to pass that the angel spake unto me, saying, Look! And I looked and beheld a man, and he was dressed in a white robe.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-239', 'coc-bom-1908', 'I Nephi', 3, 239, 'And the angel said unto me, Behold one of the twelve apostles of the Lamb!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-245', 'coc-bom-1908', 'I Nephi', 3, 245, 'And at the time they proceeded out of the mouth of the Jew, or at the time the book proceeded out of the mouth of the Jew, the things which were written were plain, and pure, and most precious, and easy to the understanding of all men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-250', 'coc-bom-1908', 'I Nephi', 3, 250, 'And they are sealed up, to come forth in their purity according to the truth which is in the Lamb, in the own due time of the Lord, unto the house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-251', 'coc-bom-1908', 'I Nephi', 3, 251, 'And I, Nephi, heard and bear record, that the name of the apostle of the Lamb was John, according to the word of the angel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-253', 'coc-bom-1908', 'I Nephi', 3, 253, 'And I have not written but a small part of the things which I saw.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-254', 'coc-bom-1908', 'I Nephi', 3, 254, 'And I bear record that I saw the things which my father saw, and the angel of the Lord did make them known unto me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-3-256', 'coc-bom-1908', 'I Nephi', 3, 256, 'And if all the things which I saw are not written, the things which I have written are true. And thus it is. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-1', 'coc-bom-1908', 'I Nephi', 4, 1, 'And it came to pass that after I, Nephi, had been carried away in the Spirit and seen all these things, I returned to the tent of my father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-4', 'coc-bom-1908', 'I Nephi', 4, 4, 'And they, being hard in their hearts, therefore, they did not look unto the Lord as they ought.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-5', 'coc-bom-1908', 'I Nephi', 4, 5, 'And now, I, Nephi, was grieved because of the hardness of their hearts, and also because of the things which I had seen, and knew they must unavoidably come to pass because of the great wickedness of the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-7', 'coc-bom-1908', 'I Nephi', 4, 7, 'And it came to pass that after I had received strength, I spake unto my brethren, desiring to know of them the cause of their disputations.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-8', 'coc-bom-1908', 'I Nephi', 4, 8, 'And they said, Behold, we cannot understand the words which our father hath spoken concerning the natural branches of the olive tree and also concerning the Gentiles.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-9', 'coc-bom-1908', 'I Nephi', 4, 9, 'And I said unto them, Have ye inquired of the Lord?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-11', 'coc-bom-1908', 'I Nephi', 4, 11, 'Behold, I said unto them, How is it that ye do not keep the commandments of the Lord?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-12', 'coc-bom-1908', 'I Nephi', 4, 12, 'How is it that ye will perish because of the hardness of your hearts?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-13', 'coc-bom-1908', 'I Nephi', 4, 13, 'Do ye not remember the things which the Lord hath said, If ye will not harden your hearts and ask me in faith, believing that ye shall receive, with diligence in keeping my commandments, surely these things shall be made known unto you?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-15', 'coc-bom-1908', 'I Nephi', 4, 15, 'And behold, are we not broken off from the house of Israel? And are we not a branch of the house of Israel?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-19', 'coc-bom-1908', 'I Nephi', 4, 19, 'Wherefore, they shall come to the knowledge of their Redeemer and the very points of his doctrine, that they may know how to come unto him and be saved.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-20', 'coc-bom-1908', 'I Nephi', 4, 20, 'And then at that day will they not rejoice and give praise unto their everlasting God, their rock and their salvation?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-21', 'coc-bom-1908', 'I Nephi', 4, 21, 'Yea, at that day, will they not receive the strength and nourishment from the true vine?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-22', 'coc-bom-1908', 'I Nephi', 4, 22, 'Yea, will they not come unto the true fold of God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-25', 'coc-bom-1908', 'I Nephi', 4, 25, 'And this is what our father meaneth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-27', 'coc-bom-1908', 'I Nephi', 4, 27, 'And he meaneth that it shall come by way of the Gentiles, that the Lord may show his power unto the Gentiles, for the very cause that he shall be rejected of the Jews, or of the house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-28', 'coc-bom-1908', 'I Nephi', 4, 28, 'Wherefore, our father hath not spoken of our seed alone, but also of all the house of Israel, pointing to the covenant which should be fulfilled in the latter days,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-29', 'coc-bom-1908', 'I Nephi', 4, 29, 'Which covenant the Lord made to our father Abraham, saying, In thy seed shall all the kindreds of the earth be blessed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-33', 'coc-bom-1908', 'I Nephi', 4, 33, 'And after they were restored, they should no more be confounded, neither should they be scattered again.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-34', 'coc-bom-1908', 'I Nephi', 4, 34, 'And it came to pass that I did speak many words unto my brethren, that they were pacified and did humble themselves before the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-35', 'coc-bom-1908', 'I Nephi', 4, 35, 'And it came to pass that they did speak unto me again, saying, What meaneth this thing which our father saw in a dream?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-36', 'coc-bom-1908', 'I Nephi', 4, 36, 'What meaneth the tree which he saw?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-37', 'coc-bom-1908', 'I Nephi', 4, 37, 'And I said unto them, It was a representation of the tree of life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-38', 'coc-bom-1908', 'I Nephi', 4, 38, 'And they said unto me, What meaneth the rod of iron which our father saw that led to the tree?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-40', 'coc-bom-1908', 'I Nephi', 4, 40, 'Neither could the temptations and the fiery darts of the adversary overpower them unto blindness, to lead them away to destruction.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-42', 'coc-bom-1908', 'I Nephi', 4, 42, 'Yea, I did exhort them with all the energies of my soul and with all the faculty which I possessed, that they would give heed to the word of God and remember to keep his commandments always, in all things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-43', 'coc-bom-1908', 'I Nephi', 4, 43, 'And they said unto me, What meaneth the river of water which our father saw?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-46', 'coc-bom-1908', 'I Nephi', 4, 46, 'And I said unto them that it was an awful gulf, which separateth the wicked from the tree of life and also from the saints of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-47', 'coc-bom-1908', 'I Nephi', 4, 47, 'And I said unto them that it was a representation of that awful hell, which the angel said unto me was prepared for the wicked.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-49', 'coc-bom-1908', 'I Nephi', 4, 49, 'And the brightness thereof was like unto the brightness of a flaming fire, which ascendeth up unto God forever and ever, and hath no end.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-50', 'coc-bom-1908', 'I Nephi', 4, 50, 'And they said unto me, Doth this thing mean the torment of the body in the days of probation, or doth it mean the final state of the soul after the death of the temporal body, or doth it speak of the things which are temporal?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-54', 'coc-bom-1908', 'I Nephi', 4, 54, 'Wherefore, they must be brought to stand before God to be judged of their works.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-57', 'coc-bom-1908', 'I Nephi', 4, 57, 'If so, the kingdom of God must be filthy also.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-59', 'coc-bom-1908', 'I Nephi', 4, 59, 'Wherefore, there must needs be a place of filthiness prepared for that which is filthy.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-63', 'coc-bom-1908', 'I Nephi', 4, 63, 'Yea, and it is the greatest of all the gifts of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-4-64', 'coc-bom-1908', 'I Nephi', 4, 64, 'And thus I spake unto my brethren. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-1', 'coc-bom-1908', 'I Nephi', 5, 1, 'And now, it came to pass that after I, Nephi, had made an end of speaking to my brethren, behold, they said unto me, Thou hast declared unto us hard things, more than we are able to bear.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-3', 'coc-bom-1908', 'I Nephi', 5, 3, 'And now, my brethren, if ye were righteous and were willing to hearken to the truth and give heed unto it, that ye might walk uprightly before God, then ye would not murmur because of the truth and say, Thou speakest hard things against us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-4', 'coc-bom-1908', 'I Nephi', 5, 4, 'And it came to pass that I, Nephi, did exhort my brethren, with all diligence, to keep the commandments of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-5', 'coc-bom-1908', 'I Nephi', 5, 5, 'And it came to pass that they did humble themselves before the Lord, insomuch that I had joy and great hopes of them, that they would walk in the paths of righteousness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-6', 'coc-bom-1908', 'I Nephi', 5, 6, 'Now all these things were said and done as my father dwelt in a tent in the valley which he called Lemuel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-8', 'coc-bom-1908', 'I Nephi', 5, 8, 'And thus my father had fulfilled all the commandments of the Lord which had been given unto him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-9', 'coc-bom-1908', 'I Nephi', 5, 9, 'And also, I, Nephi, had been blessed of the Lord exceedingly.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-10', 'coc-bom-1908', 'I Nephi', 5, 10, 'And it came to pass that the voice of the Lord spake unto my father by night, and commanded him, that on the morrow he should take his journey into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-14', 'coc-bom-1908', 'I Nephi', 5, 14, 'And we did take seed of every kind, that we might carry into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-15', 'coc-bom-1908', 'I Nephi', 5, 15, 'And it came to pass that we did take our tents, and depart into the wilderness, across the river Laman.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-18', 'coc-bom-1908', 'I Nephi', 5, 18, 'And we did go forth again in the wilderness, following the same direction, keeping in the most fertile parts of the wilderness, which were in the borders near the Red Sea.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-20', 'coc-bom-1908', 'I Nephi', 5, 20, 'And we did follow the directions of the ball, which led us in the more fertile parts of the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-21', 'coc-bom-1908', 'I Nephi', 5, 21, 'And after we had traveled for the space of many days, we did pitch our tents for the space of a time, that we might again rest ourselves and obtain food for our families.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-23', 'coc-bom-1908', 'I Nephi', 5, 23, 'And it came to pass that we did return without food to our families.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-24', 'coc-bom-1908', 'I Nephi', 5, 24, 'And being much fatigued because of their journeying, they did suffer much for the want of food.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-27', 'coc-bom-1908', 'I Nephi', 5, 27, 'And it came to pass that I, Nephi, did speak much unto my brethren because they had hardened their hearts again, even unto complaining against the Lord, their God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-29', 'coc-bom-1908', 'I Nephi', 5, 29, 'And I said unto my father, Whither shall I go to obtain food?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-32', 'coc-bom-1908', 'I Nephi', 5, 32, 'And it came to pass that the voice of the Lord said unto him, Look upon the ball, and behold the things which are written!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-33', 'coc-bom-1908', 'I Nephi', 5, 33, 'And it came to pass that when my father beheld the things which were written upon the ball, he did fear and tremble exceedingly, and also my brethren, and the sons of Ishmael, and our wives.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-34', 'coc-bom-1908', 'I Nephi', 5, 34, 'And it came to pass that I, Nephi, beheld the pointers which were in the ball, that they did work according to the faith, and diligence, and heed which we did give unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-36', 'coc-bom-1908', 'I Nephi', 5, 36, 'And thus we see that by small means the Lord can bring about great things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-37', 'coc-bom-1908', 'I Nephi', 5, 37, 'And it came to pass that I, Nephi, did go forth up into the top of the mountain, according to the directions which were given upon the ball.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-38', 'coc-bom-1908', 'I Nephi', 5, 38, 'And it came to pass that I did slay wild beasts, insomuch that I did obtain food for our families.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-40', 'coc-bom-1908', 'I Nephi', 5, 40, 'And now, when they beheld that I had obtained food, how great was their joy.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-41', 'coc-bom-1908', 'I Nephi', 5, 41, 'And it came to pass that they did humble themselves before the Lord and did give thanks unto him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-43', 'coc-bom-1908', 'I Nephi', 5, 43, 'And after we had traveled for the space of many days, we did pitch our tents again, that we might tarry for the space of a time.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-44', 'coc-bom-1908', 'I Nephi', 5, 44, 'And it came to pass that Ishmael died and was buried in the place which was called Nahom.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-48', 'coc-bom-1908', 'I Nephi', 5, 48, 'And Laman said unto Lemuel and also unto the sons of Ishmael, Behold, let us slay our father and also our brother Nephi, who has taken it upon him to be our ruler and our teacher, who are his elder brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-49', 'coc-bom-1908', 'I Nephi', 5, 49, 'Now he says that the Lord has talked with him and also that angels have ministered unto him!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-51', 'coc-bom-1908', 'I Nephi', 5, 51, 'And after he has led us away, he has thought to make himself a king and a ruler over us, that he may do with us according to his will and pleasure.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-52', 'coc-bom-1908', 'I Nephi', 5, 52, 'And after this manner did my brother Laman stir up their hearts to anger.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-54', 'coc-bom-1908', 'I Nephi', 5, 54, 'And after they were chastened by the voice of the Lord, they did turn away their anger and did repent of their sins, insomuch that the Lord did bless us again with food, that we did not perish.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-58', 'coc-bom-1908', 'I Nephi', 5, 58, 'And thus we see that the commandments of God must be fulfilled.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-60', 'coc-bom-1908', 'I Nephi', 5, 60, 'Wherefore, he did provide means for us while we did sojourn in the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-61', 'coc-bom-1908', 'I Nephi', 5, 61, 'And we did sojourn for the space of many years, yea, even eight years in the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-63', 'coc-bom-1908', 'I Nephi', 5, 63, 'And all these things were prepared of the Lord that we might not perish.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-64', 'coc-bom-1908', 'I Nephi', 5, 64, 'And we beheld the sea, which we called Irreantum, which, being interpreted, is many waters.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-67', 'coc-bom-1908', 'I Nephi', 5, 67, 'And we called the place Bountiful because of its much fruit.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-68', 'coc-bom-1908', 'I Nephi', 5, 68, 'And it came to pass that after I, Nephi, had been in the land of Bountiful for the space of many days, the voice of the Lord came unto me, saying, Arise, and get thee into the mountain.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-69', 'coc-bom-1908', 'I Nephi', 5, 69, 'And it came to pass that I arose, and went up into the mountain, and cried unto the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-70', 'coc-bom-1908', 'I Nephi', 5, 70, 'And it came to pass that the Lord spake unto me, saying, Thou shalt construct a ship after the manner which I shall show thee, that I may carry thy people across these waters.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-71', 'coc-bom-1908', 'I Nephi', 5, 71, 'And I said, Lord, whither shall I go, that I may find ore to molten, that I may make tools to construct the ship after the manner which thou hast shown unto me?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-72', 'coc-bom-1908', 'I Nephi', 5, 72, 'And it came to pass that the Lord told me whither I should go to find ore, that I might make tools.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-74', 'coc-bom-1908', 'I Nephi', 5, 74, 'And after I had made bellows, that I might have wherewith to blow the fire, I did smite two stones together, that I might make fire.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-80', 'coc-bom-1908', 'I Nephi', 5, 80, 'Yea, and the Lord said also that, After ye have arrived to the promised land, ye shall know that I, the Lord, am God,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-81', 'coc-bom-1908', 'I Nephi', 5, 81, 'And that I, the Lord, did deliver you from destruction,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-82', 'coc-bom-1908', 'I Nephi', 5, 82, 'Yea, that I did bring you out of the land of Jerusalem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-83', 'coc-bom-1908', 'I Nephi', 5, 83, 'Wherefore, I, Nephi, did strive to keep the commandments of the Lord, and I did exhort my brethren to faithfulness and diligence.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-84', 'coc-bom-1908', 'I Nephi', 5, 84, 'And it came to pass that I did make tools of the ore which I did molten out of the rock.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-85', 'coc-bom-1908', 'I Nephi', 5, 85, 'And when my brethren saw that I was about to build a ship, they began to murmur against me, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-87', 'coc-bom-1908', 'I Nephi', 5, 87, 'Yea, and he also thinketh that he can cross these great waters.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-89', 'coc-bom-1908', 'I Nephi', 5, 89, 'Neither would they believe that I was instructed of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-91', 'coc-bom-1908', 'I Nephi', 5, 91, 'And now, when they saw that I began to be sorrowful, they were glad in their hearts, insomuch that they did rejoice over me, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-96', 'coc-bom-1908', 'I Nephi', 5, 96, 'And it would have been better that they had died before they came out of Jerusalem, than to have suffered these afflictions.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-101', 'coc-bom-1908', 'I Nephi', 5, 101, 'Yea, and our brother is like unto him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-102', 'coc-bom-1908', 'I Nephi', 5, 102, 'And after this manner of language did my brethren murmur and complain against us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-103', 'coc-bom-1908', 'I Nephi', 5, 103, 'And it came to pass that I, Nephi, spake unto them, saying, Do ye believe that our fathers, who were the children of Israel, would have been led away out of the hands of the Egyptians if they had not hearkened unto the words of the Lord?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-104', 'coc-bom-1908', 'I Nephi', 5, 104, 'Yea, do ye suppose that they would have been led out of bondage if the Lord had not commanded Moses that he should lead them out of bondage?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-106', 'coc-bom-1908', 'I Nephi', 5, 106, 'Wherefore, ye know that it must needs be a good thing for them, that they should be brought out of bondage.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-108', 'coc-bom-1908', 'I Nephi', 5, 108, 'And ye know that by his word the waters of the Red Sea were divided hither and thither, and they passed through on dry ground.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-109', 'coc-bom-1908', 'I Nephi', 5, 109, 'But ye know that the Egyptians were drowned in the Red Sea, who were the armies of Pharaoh.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-112', 'coc-bom-1908', 'I Nephi', 5, 112, 'And notwithstanding they being led--the Lord, their God, their Redeemer, going before them, leading them by day and giving light unto them by night, and doing all things for them which were expedient for man to receive--they hardened their hearts, and blinded their minds, and reviled against Moses and against the true and living God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-116', 'coc-bom-1908', 'I Nephi', 5, 116, 'And there was not anything done, save it were by his word.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-117', 'coc-bom-1908', 'I Nephi', 5, 117, 'And after they had crossed the river Jordan, he did make them mighty, unto the driving out the children of the land, yea, unto the scattering them to destruction.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-118', 'coc-bom-1908', 'I Nephi', 5, 118, 'And now, do ye suppose that the children of this land, who were in the land of promise, who were driven out by our fathers, do ye suppose that they were righteous? Behold, I say unto you, Nay.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-119', 'coc-bom-1908', 'I Nephi', 5, 119, 'Do ye suppose that our fathers would have been more choice than they if they had been righteous?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-121', 'coc-bom-1908', 'I Nephi', 5, 121, 'Behold, the Lord esteemeth all flesh in one.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-122', 'coc-bom-1908', 'I Nephi', 5, 122, 'He that is righteous is favored of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-125', 'coc-bom-1908', 'I Nephi', 5, 125, 'And he did bless it unto our fathers, unto their obtaining power over it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-127', 'coc-bom-1908', 'I Nephi', 5, 127, 'And he hath created his children, that they should possess it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-128', 'coc-bom-1908', 'I Nephi', 5, 128, 'And he raiseth up a righteous nation and destroyeth the nations of the wicked.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-129', 'coc-bom-1908', 'I Nephi', 5, 129, 'And he leadeth away the righteous into precious lands, and the wicked he destroyeth and curseth the land unto them for their sakes.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-130', 'coc-bom-1908', 'I Nephi', 5, 130, 'He ruleth high in the heavens, for it is his throne, and this earth is his footstool.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-131', 'coc-bom-1908', 'I Nephi', 5, 131, 'And he loveth those who will have him to be their God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-137', 'coc-bom-1908', 'I Nephi', 5, 137, 'Nevertheless, ye know that they were led forth by his matchless power into the land of promise.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-143', 'coc-bom-1908', 'I Nephi', 5, 143, 'Wherefore, ye are murderers in your hearts, and ye are like unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-144', 'coc-bom-1908', 'I Nephi', 5, 144, 'Ye are swift to do iniquity but slow to remember the Lord, your God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-147', 'coc-bom-1908', 'I Nephi', 5, 147, 'Wherefore, he has spoken unto you like unto the voice of thunder, which did cause the earth to shake as if it were to divide asunder.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-149', 'coc-bom-1908', 'I Nephi', 5, 149, 'Yea, and ye know that by his word he can cause the rough places to be made smooth, and smooth places shall be broken up.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-150', 'coc-bom-1908', 'I Nephi', 5, 150, 'Oh, then, why is it that ye can be so hard in your hearts?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-152', 'coc-bom-1908', 'I Nephi', 5, 152, 'Behold, I am full of the Spirit of God, insomuch that my frame has no strength.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-156', 'coc-bom-1908', 'I Nephi', 5, 156, 'And it came to pass that I, Nephi, said unto them that they should murmur no more against their father, neither should they withhold their labor from me, for God had commanded me that I should build a ship.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-157', 'coc-bom-1908', 'I Nephi', 5, 157, 'And I said unto them, If God had commanded me to do all things, I could do them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-159', 'coc-bom-1908', 'I Nephi', 5, 159, 'And now, if the Lord has such great power and has wrought so many miracles among the children of men, how is it that he cannot instruct me that I should build a ship?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-161', 'coc-bom-1908', 'I Nephi', 5, 161, 'Neither durst they lay their hands upon me, nor touch me with their fingers, even for the space of many days.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-165', 'coc-bom-1908', 'I Nephi', 5, 165, 'And now, they said, We know of a surety that the Lord is with thee, for we know that it is the power of the Lord that has shaken us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-167', 'coc-bom-1908', 'I Nephi', 5, 167, 'Wherefore, worship the Lord, thy God, and honor thy father and thy mother, that thy days may be long in the land which the Lord, thy God, shall give thee.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-169', 'coc-bom-1908', 'I Nephi', 5, 169, 'And the Lord did show me from time to time after what manner I should work the timbers of the ship.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-174', 'coc-bom-1908', 'I Nephi', 5, 174, 'Wherefore, they did humble themselves again before the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-175', 'coc-bom-1908', 'I Nephi', 5, 175, 'And it came to pass that the voice of the Lord came unto my father, that we should arise and go down into the ship.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-176', 'coc-bom-1908', 'I Nephi', 5, 176, 'And it came to pass that on the morrow, after we had prepared all things--much fruits and meat from the wilderness, and honey in abundance, and provisions, according to that which the Lord had commanded us--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-178', 'coc-bom-1908', 'I Nephi', 5, 178, 'Wherefore, we did all go down into the ship with our wives and our children.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-180', 'coc-bom-1908', 'I Nephi', 5, 180, 'And it came to pass after we had all gone down into the ship and had taken with us our provisions and things which had been commanded us,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-182', 'coc-bom-1908', 'I Nephi', 5, 182, 'And after we had been driven forth before the wind for the space of many days, behold, my brethren, and the sons of Ishmael, and also their wives began to make themselves merry, insomuch that they began to dance, and to sing, and to speak with much rudeness,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-184', 'coc-bom-1908', 'I Nephi', 5, 184, 'Yea, they were lifted up unto exceeding rudeness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-187', 'coc-bom-1908', 'I Nephi', 5, 187, 'But behold, they were angry with me, saying, We will not that our younger brother shall be a ruler over us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-189', 'coc-bom-1908', 'I Nephi', 5, 189, 'Nevertheless, the Lord did suffer it, that he might show forth his power, unto the fulfilling of his word which he had spoken concerning the wicked.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-192', 'coc-bom-1908', 'I Nephi', 5, 192, 'And we were driven back upon the waters for the space of three days.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-194', 'coc-bom-1908', 'I Nephi', 5, 194, 'Nevertheless, they did not loose me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-195', 'coc-bom-1908', 'I Nephi', 5, 195, 'And on the fourth day which we had been driven back, the tempest began to be exceeding sore.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-196', 'coc-bom-1908', 'I Nephi', 5, 196, 'And it came to pass that we were about to be swallowed up in the depths of the sea.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-201', 'coc-bom-1908', 'I Nephi', 5, 201, 'And my parents, being stricken in years and having suffered much grief because of their children, they were brought down, yea, even upon their sickbeds.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-204', 'coc-bom-1908', 'I Nephi', 5, 204, 'Yea, even they were near to be cast, with sorrow, into a watery grave.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-208', 'coc-bom-1908', 'I Nephi', 5, 208, 'Wherefore, when they saw that they were about to be swallowed up in the depths of the sea, they repented of the thing which they had done, insomuch that they loosed me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-209', 'coc-bom-1908', 'I Nephi', 5, 209, 'And it came to pass after they had loosed me, behold, I took the compass, and it did work whither I desired it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-211', 'coc-bom-1908', 'I Nephi', 5, 211, 'And it came to pass that I, Nephi, did guide the ship, that we sailed again towards the promised land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-216', 'coc-bom-1908', 'I Nephi', 5, 216, 'And it came to pass that we did find upon the land of promise as we journeyed in the wilderness, that there were beasts in the forests of every kind: both the cow, and the ox, and the ass, and the horse, and the goat, and the wild goat, and all manner of wild animals, which were for the use of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-217', 'coc-bom-1908', 'I Nephi', 5, 217, 'And we did find all manner of ore: both of gold, and of silver, and of copper.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-222', 'coc-bom-1908', 'I Nephi', 5, 222, 'Wherefore, the things which transpired before I made these plates are, of a truth, more particularly made mention upon the first plates.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-223', 'coc-bom-1908', 'I Nephi', 5, 223, 'And after I had made these plates by way of commandment, I, Nephi, received a commandment that the ministry and the prophecies--the more plain and precious parts of them--should be written upon these plates,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-225', 'coc-bom-1908', 'I Nephi', 5, 225, 'Wherefore, I, Nephi, did make a record upon the other plates, which gives an account, or which gives a greater account, of the wars, and contentions, and destructions of my people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-226', 'coc-bom-1908', 'I Nephi', 5, 226, 'And this have I done and commanded my people what they should do after I was gone, and that these plates should be handed down from one generation to another, or from one prophet to another, until further commandments of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-229', 'coc-bom-1908', 'I Nephi', 5, 229, 'Nevertheless, I do not write anything upon plates, save it be that I think it be sacred.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-230', 'coc-bom-1908', 'I Nephi', 5, 230, 'And now, if I do err, even did they err of old.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-231', 'coc-bom-1908', 'I Nephi', 5, 231, 'Not that I would excuse myself because of other men, but because of the weakness which is in me, according to the flesh, I would excuse myself.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-232', 'coc-bom-1908', 'I Nephi', 5, 232, 'For the things which some men esteem to be of great worth, both to the body and soul, others set at naught and trample under their feet.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-235', 'coc-bom-1908', 'I Nephi', 5, 235, 'They set him at naught and hearken not to the voice of his counsels.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-236', 'coc-bom-1908', 'I Nephi', 5, 236, 'And behold, he cometh, according to the words of the angel, in six hundred years from the time my father left Jerusalem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-238', 'coc-bom-1908', 'I Nephi', 5, 238, 'Yea, they spit upon him, and he suffereth it because of his loving-kindness and his long-sufferings towards the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-239', 'coc-bom-1908', 'I Nephi', 5, 239, 'And the God of our fathers--who were led out of Egypt, out of bondage, and also were preserved in the wilderness by him--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-240', 'coc-bom-1908', 'I Nephi', 5, 240, 'Yea, the God of Abraham, and of Isaac, and the God of Jacob yieldeth himself, according to the words of the angel, as a man, into the hands of wicked men, to be lifted up, according to the words of Zenock,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-241', 'coc-bom-1908', 'I Nephi', 5, 241, 'And to be crucified, according to the words of Neum,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-242', 'coc-bom-1908', 'I Nephi', 5, 242, 'And to be buried in a sepulcher, according to the words of Zenos, which he spake concerning the three days of darkness,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-243', 'coc-bom-1908', 'I Nephi', 5, 243, 'Which should be a sign given of his death, unto those who should inhabit the isles of the sea--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-244', 'coc-bom-1908', 'I Nephi', 5, 244, 'More especially given unto those who are of the house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-245', 'coc-bom-1908', 'I Nephi', 5, 245, 'For thus spake the prophet, The Lord God surely shall visit all the house of Israel at that day:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-246', 'coc-bom-1908', 'I Nephi', 5, 246, 'Some with his voice because of their righteousness, unto their great joy and salvation,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-247', 'coc-bom-1908', 'I Nephi', 5, 247, 'And others with the thunderings and the lightnings of his power, by tempest, by fire, and by smoke, and vapor of darkness, and by the opening of the earth, and by mountains which shall be carried up.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-248', 'coc-bom-1908', 'I Nephi', 5, 248, 'And all these things must surely come, saith the prophet Zenos.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-250', 'coc-bom-1908', 'I Nephi', 5, 250, 'And because of the groanings of the earth, many of the kings of the isles of the sea shall be wrought upon by the Spirit of God to exclaim, The God of nature suffers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-252', 'coc-bom-1908', 'I Nephi', 5, 252, 'And because they turn their hearts aside, saith the prophet, and have despised the Holy One of Israel, they shall wander in the flesh, and perish, and become a hiss and a byword, and be hated among all nations.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-257', 'coc-bom-1908', 'I Nephi', 5, 257, 'Every nation, kindred, tongue, and people shall be blessed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-259', 'coc-bom-1908', 'I Nephi', 5, 259, 'Wherefore, I speak unto all the house of Israel if it so be that they should obtain these things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-5-264', 'coc-bom-1908', 'I Nephi', 5, 264, 'Wherefore, it must needs be that we know concerning them, for they are written upon the plates of brass.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-6-1', 'coc-bom-1908', 'I Nephi', 6, 1, 'Now it came to pass that I, Nephi, did teach my brethren these things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-6-2', 'coc-bom-1908', 'I Nephi', 6, 2, 'And it came to pass that I did read many things to them which were engraven upon the plates of brass, that they might know concerning the doings of the Lord in other lands among people of old.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-6-3', 'coc-bom-1908', 'I Nephi', 6, 3, 'And I did read many things unto them which were written in the book of Moses.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-6-5', 'coc-bom-1908', 'I Nephi', 6, 5, 'For I did liken all scriptures unto us, that it might be for our profit and learning.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-6-7', 'coc-bom-1908', 'I Nephi', 6, 7, 'For after this manner has the prophet written:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-6-13', 'coc-bom-1908', 'I Nephi', 6, 13, 'Thou hast seen and heard all this. And will ye not declare them? And that I have showed thee new things from this time, even hidden things, and thou didst not know them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-6-16', 'coc-bom-1908', 'I Nephi', 6, 16, 'Nevertheless, for my name''s sake will I defer mine anger, and for my praise will I refrain from thee, that I cut thee not off.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-6-24', 'coc-bom-1908', 'I Nephi', 6, 24, 'And thus saith the Lord, thy Redeemer, the Holy One of Israel: I have sent him, the Lord, thy God, who teacheth thee to profit, who leadeth thee by the way thou shouldest go, has done it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-6-29', 'coc-bom-1908', 'I Nephi', 6, 29, 'And notwithstanding he hath done all this and greater also, there is no peace, saith the Lord, unto the wicked.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-6-30', 'coc-bom-1908', 'I Nephi', 6, 30, 'And again, Hearken, O ye house of Israel, all ye that are broken off and are driven out because of the wickedness of the pastors of my people, yea, all ye that are broken off, that are scattered abroad, who are of my people, O house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-6-33', 'coc-bom-1908', 'I Nephi', 6, 33, 'And said unto me, Thou art my servant, O Israel, in whom I will be glorified.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-6-35', 'coc-bom-1908', 'I Nephi', 6, 35, 'And now, saith the Lord that formed me from the womb, that I should be his servant to bring Jacob again to him: Though Israel be not gathered, yet shall I be glorious in the eyes of the Lord, and my God shall be my strength.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-6-36', 'coc-bom-1908', 'I Nephi', 6, 36, 'And he said, It is a light thing that thou shouldest be my servant to raise up the tribes of Jacob and to restore the preserved of Israel. I will also give thee for a light to the Gentiles, that thou mayest be my salvation unto the ends of the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-6-41', 'coc-bom-1908', 'I Nephi', 6, 41, 'And I will make all my mountains a way, and my highways shall be exalted.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-6-42', 'coc-bom-1908', 'I Nephi', 6, 42, 'And then, O house of Israel, behold, these shall come from far, and lo, these from the north and from the west, and these from the land of Sinim.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-6-48', 'coc-bom-1908', 'I Nephi', 6, 48, 'Lift up thine eyes round about, and behold--all these gather themselves together, and they shall come to thee. And as I live, saith the Lord, thou shalt surely clothe thee with them all, as with an ornament, and bind them on even as a bride.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-6-51', 'coc-bom-1908', 'I Nephi', 6, 51, 'Then shalt thou say in thine heart, Who hath begotten me these, seeing I have lost my children and am desolate, a captive, and removing to and fro? And who hath brought up these? Behold, I was left alone. These, where have they been?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-6-54', 'coc-bom-1908', 'I Nephi', 6, 54, 'For shall the prey be taken from the mighty, or the lawful captives delivered?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-1', 'coc-bom-1908', 'I Nephi', 7, 1, 'And now, it came to pass that after I, Nephi, had read these things which were engraven upon the plates of brass, my brethren came unto me and said unto me, What meaneth these things which ye have read?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-2', 'coc-bom-1908', 'I Nephi', 7, 2, 'Behold, are they to be understood according to the things which are spiritual, which shall come to pass according to the spirit and not the flesh?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-4', 'coc-bom-1908', 'I Nephi', 7, 4, 'For by the Spirit are all things made known unto the prophets, which shall come upon the children of men according to the flesh.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-5', 'coc-bom-1908', 'I Nephi', 7, 5, 'Wherefore, the things of which I have read are things pertaining to things both temporal and spiritual.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-6', 'coc-bom-1908', 'I Nephi', 7, 6, 'For it appears that the house of Israel, sooner or later, will be scattered upon all the face of the earth and also among all nations.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-7', 'coc-bom-1908', 'I Nephi', 7, 7, 'And behold, there are many who are already lost from the knowledge of those who are at Jerusalem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-10', 'coc-bom-1908', 'I Nephi', 7, 10, 'And whither they are, none of us knoweth, save that we know that they have been led away.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-12', 'coc-bom-1908', 'I Nephi', 7, 12, 'Wherefore, they shall be scattered among all nations and shall be hated of all men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-14', 'coc-bom-1908', 'I Nephi', 7, 14, 'And it meaneth us in the days to come and also all our brethren who are of the house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-16', 'coc-bom-1908', 'I Nephi', 7, 16, 'And by them shall our seed be scattered.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-18', 'coc-bom-1908', 'I Nephi', 7, 18, 'Wherefore, it is likened unto their being nourished by the Gentiles and being carried in their arms and upon their shoulders.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-19', 'coc-bom-1908', 'I Nephi', 7, 19, 'And it shall also be of worth unto the Gentiles--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-20', 'coc-bom-1908', 'I Nephi', 7, 20, 'And not only unto the Gentiles, but unto all the house of Israel--unto the making known of the covenants of the Father of heaven unto Abraham, saying, In thy seed shall all the kindreds of the earth be blessed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-21', 'coc-bom-1908', 'I Nephi', 7, 21, 'And I would, my brethren, that ye should know that all the kindreds of the earth cannot be blessed unless he shall make bare his arm in the eyes of the nations.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-22', 'coc-bom-1908', 'I Nephi', 7, 22, 'Wherefore, the Lord God will proceed to make bare his arm in the eyes of all the nations, in bringing about his covenants and his gospel unto those who are of the house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-25', 'coc-bom-1908', 'I Nephi', 7, 25, 'And they shall know that the Lord is their Savior and their Redeemer, the Mighty One of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-27', 'coc-bom-1908', 'I Nephi', 7, 27, 'For they shall war among themselves, and the sword of their own hands shall fall upon their own heads, and they shall be drunken with their own blood.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-28', 'coc-bom-1908', 'I Nephi', 7, 28, 'And every nation which shall war against thee, O house of Israel, shall be turned one against another.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-29', 'coc-bom-1908', 'I Nephi', 7, 29, 'And they shall fall into the pit which they digged to ensnare the people of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-30', 'coc-bom-1908', 'I Nephi', 7, 30, 'And all that fight against Zion shall be destroyed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-35', 'coc-bom-1908', 'I Nephi', 7, 35, 'For he will not suffer that the wicked shall destroy the righteous.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-36', 'coc-bom-1908', 'I Nephi', 7, 36, 'Wherefore, he will preserve the righteous by his power, even if it be so that the fullness of his wrath must come and the righteous be preserved, even unto the destruction of their enemies by fire.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-39', 'coc-bom-1908', 'I Nephi', 7, 39, 'And it must needs be upon the face of this earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-42', 'coc-bom-1908', 'I Nephi', 7, 42, 'For the time surely must come that all they who fight against Zion shall be cut off.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-43', 'coc-bom-1908', 'I Nephi', 7, 43, 'And the Lord will surely prepare a way for his people, unto the fulfilling of the words of Moses, which he spake, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-45', 'coc-bom-1908', 'I Nephi', 7, 45, 'And it shall come to pass that all those who will not hear that prophet shall be cut off from among the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-49', 'coc-bom-1908', 'I Nephi', 7, 49, 'But it is the kingdom of the devil which shall be built up among the children of men, which kingdom is established among them which are in the flesh.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-50', 'coc-bom-1908', 'I Nephi', 7, 50, 'For the time speedily shall come that all churches which are built up to get gain, and all those who are built up to get power over the flesh, and those who are built up to become popular in the eyes of the world, and those who seek the lusts of the flesh and the things of the world, and to do all manner of iniquity,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-54', 'coc-bom-1908', 'I Nephi', 7, 54, 'And this is according to the words of the prophet.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-59', 'coc-bom-1908', 'I Nephi', 7, 59, 'And he shall feed his sheep, and in him they shall find pasture.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-63', 'coc-bom-1908', 'I Nephi', 7, 63, 'And now, behold, I, Nephi, say unto you that all these things must come according to the flesh.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-64', 'coc-bom-1908', 'I Nephi', 7, 64, 'But behold, all nations, kindreds, tongues, and people shall dwell safely in the Holy One of Israel if it so be that they will repent.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-67', 'coc-bom-1908', 'I Nephi', 7, 67, 'And they testify that a man must be obedient to the commandments of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-68', 'coc-bom-1908', 'I Nephi', 7, 68, 'Wherefore, ye need not suppose that I and my father are the only ones that have testified and also taught them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-69', 'coc-bom-1908', 'I Nephi', 7, 69, 'Wherefore, if ye shall be obedient to the commandments and endure to the end, ye shall be saved at the last day.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:i-nephi-7-70', 'coc-bom-1908', 'I Nephi', 7, 70, 'And thus it is. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-1', 'coc-bom-1908', 'II Nephi', 1, 1, 'And now, it came to pass after I, Nephi, had made an end of teaching my brethren, our father Lehi also spake many things unto them--how great things the Lord had done for them in bringing them out of the land of Jerusalem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-2', 'coc-bom-1908', 'II Nephi', 1, 2, 'And he spake unto them concerning their rebellions upon the waters and the mercies of God in sparing their lives, that they were not swallowed up in the sea.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-3', 'coc-bom-1908', 'II Nephi', 1, 3, 'And he also spake unto them concerning the land of promise which they had obtained--how merciful the Lord had been in warning us that we should flee out of the land of Jerusalem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-5', 'coc-bom-1908', 'II Nephi', 1, 5, 'And had we remained in Jerusalem, we should also have perished.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-6', 'coc-bom-1908', 'II Nephi', 1, 6, 'But, said he, notwithstanding our afflictions, we have obtained a land of promise, a land which is choice above all other lands,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-7', 'coc-bom-1908', 'II Nephi', 1, 7, 'A land which the Lord God hath covenanted with me should be a land for the inheritance of my seed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-8', 'coc-bom-1908', 'II Nephi', 1, 8, 'Yea, the Lord hath consecrated this land unto me and to my children forever,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-9', 'coc-bom-1908', 'II Nephi', 1, 9, 'And also all those who should be led out of other countries by the hand of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-10', 'coc-bom-1908', 'II Nephi', 1, 10, 'Wherefore, I, Lehi, prophesy, according to the workings of the Spirit which is in me, that there shall none come into this land, save they shall be brought by the hand of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-11', 'coc-bom-1908', 'II Nephi', 1, 11, 'Wherefore, this land is consecrated unto him whom he shall bring.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-15', 'coc-bom-1908', 'II Nephi', 1, 15, 'But unto the righteous, it shall be blessed forever.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-17', 'coc-bom-1908', 'II Nephi', 1, 17, 'For, behold, many nations would overrun the land, that there would be no place for an inheritance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-19', 'coc-bom-1908', 'II Nephi', 1, 19, 'And they shall be kept from all other nations, that they may possess this land unto themselves.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-20', 'coc-bom-1908', 'II Nephi', 1, 20, 'And if it so be that they shall keep his commandments, they shall be blessed upon the face of this land,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-22', 'coc-bom-1908', 'II Nephi', 1, 22, 'But behold, when the time cometh that they shall dwindle in unbelief, after they have received so great blessings from the hand of the Lord--having a knowledge of the creation of the earth and all men, knowing the great and marvelous works of the Lord from the creation of the world, having power given them to do all things by faith, having all the commandments from the beginning, and having been brought by his infinite goodness into this precious land of promise--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-23', 'coc-bom-1908', 'II Nephi', 1, 23, 'Behold, I say, If the day shall come that they will reject the Holy One of Israel, the true Messiah, their Redeemer and their God, behold, the judgments of him that is just shall rest upon them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-26', 'coc-bom-1908', 'II Nephi', 1, 26, 'Wherefore, my sons, I would that ye would remember, yea, I would that ye would hearken unto my words.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-32', 'coc-bom-1908', 'II Nephi', 1, 32, 'Or that a cursing should come upon you for the space of many generations, and ye are visited by sword and by famine, and are hated, and are led according to the will and captivity of the devil.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-33', 'coc-bom-1908', 'II Nephi', 1, 33, 'O my sons, that these things might not come upon you, but that ye might be a choice and a favored people of the Lord!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-35', 'coc-bom-1908', 'II Nephi', 1, 35, 'And now, that my soul might have joy in you, and that my heart might leave this world with gladness because of you, that I might not be brought down with grief and sorrow to the grave,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-36', 'coc-bom-1908', 'II Nephi', 1, 36, 'Arise from the dust, my sons, and be men, and be determined in one mind, and in one heart united in all things, that ye may not come down into captivity, that ye may not be cursed with a sore cursing,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-37', 'coc-bom-1908', 'II Nephi', 1, 37, 'And also, that ye may not incur the displeasure of a just God upon you, unto the destruction, yea, the eternal destruction of both soul and body.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-39', 'coc-bom-1908', 'II Nephi', 1, 39, 'Shake off the chains with which ye are bound, and come forth out of obscurity, and arise from the dust.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-46', 'coc-bom-1908', 'II Nephi', 1, 46, 'And ye have murmured because he hath been plain unto you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-49', 'coc-bom-1908', 'II Nephi', 1, 49, 'And that which ye call anger was the truth, according to that which is in God, which he could not restrain, manifesting boldly concerning your iniquities.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-50', 'coc-bom-1908', 'II Nephi', 1, 50, 'And it must needs be that the power of God must be with him, even unto his commanding you, that ye must obey.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-51', 'coc-bom-1908', 'II Nephi', 1, 51, 'But behold, it was not him, but it was the Spirit of the Lord which was in him, which opened his mouth to utterance, that he could not shut it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-52', 'coc-bom-1908', 'II Nephi', 1, 52, 'And now, my son Laman, and also Lemuel and Sam, and also my sons who are the sons of Ishmael, behold, if ye will hearken unto the voice of Nephi, ye shall not perish.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-53', 'coc-bom-1908', 'II Nephi', 1, 53, 'And if ye will hearken unto him, I leave unto you a blessing, yea, even my first blessing.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-57', 'coc-bom-1908', 'II Nephi', 1, 57, 'And nothing, save it shall be iniquity among them, shall harm or disturb their prosperity upon the face of this land forever.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-58', 'coc-bom-1908', 'II Nephi', 1, 58, 'Wherefore, if ye shall keep the commandments of the Lord, the Lord hath consecrated this land for the security of thy seed with the seed of my son.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-59', 'coc-bom-1908', 'II Nephi', 1, 59, 'And now, Jacob, I speak unto you: Thou art my firstborn in the days of my tribulation in the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-60', 'coc-bom-1908', 'II Nephi', 1, 60, 'And behold, in thy childhood thou hast suffered afflictions and much sorrow because of the rudeness of thy brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-65', 'coc-bom-1908', 'II Nephi', 1, 65, 'For the Spirit is the same--yesterday, today, and forever.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-66', 'coc-bom-1908', 'II Nephi', 1, 66, 'And the way is prepared from the fall of man, and salvation is free.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-67', 'coc-bom-1908', 'II Nephi', 1, 67, 'And men are instructed sufficiently, that they know good from evil.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-68', 'coc-bom-1908', 'II Nephi', 1, 68, 'And the law is given unto men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-69', 'coc-bom-1908', 'II Nephi', 1, 69, 'And by the law, no flesh is justified, or, by the law, men are cut off.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-73', 'coc-bom-1908', 'II Nephi', 1, 73, 'Wherefore, how great the importance to make these things known unto the inhabitants of the earth, that they may know that there is no flesh that can dwell in the presence of God, save it be through the merits, and mercy, and grace of the holy Messiah,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-74', 'coc-bom-1908', 'II Nephi', 1, 74, 'Who layeth down his life according to the flesh and taketh it again by the power of the Spirit,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-75', 'coc-bom-1908', 'II Nephi', 1, 75, 'That he may bring to pass the resurrection of the dead, being the first that should rise.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-77', 'coc-bom-1908', 'II Nephi', 1, 77, 'And they that believe in him shall be saved.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-79', 'coc-bom-1908', 'II Nephi', 1, 79, 'Wherefore, they stand in the presence of him, to be judged of him, according to the truth and holiness which is in him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-81', 'coc-bom-1908', 'II Nephi', 1, 81, 'For it must needs be that there is an opposition in all things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-82', 'coc-bom-1908', 'II Nephi', 1, 82, 'If not so, my firstborn in the wilderness, righteousness could not be brought to pass, neither wickedness, neither holiness nor misery, neither good nor bad.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-84', 'coc-bom-1908', 'II Nephi', 1, 84, 'Wherefore, if it should be one body, it must needs remain as dead, having no life, neither death nor corruption, nor incorruption, happiness nor misery, neither sense nor insensibility.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-86', 'coc-bom-1908', 'II Nephi', 1, 86, 'Wherefore, there would have been no purpose in the end of its creation.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-87', 'coc-bom-1908', 'II Nephi', 1, 87, 'Wherefore, this thing must needs destroy the wisdom of God and his eternal purposes, and also the power, and the mercy, and the justice of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-88', 'coc-bom-1908', 'II Nephi', 1, 88, 'And if ye shall say there is no law, ye shall also say there is no sin.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-89', 'coc-bom-1908', 'II Nephi', 1, 89, 'And if ye shall say there is no sin, ye shall also say there is no righteousness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-90', 'coc-bom-1908', 'II Nephi', 1, 90, 'And if there be no righteousness, there be no happiness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-91', 'coc-bom-1908', 'II Nephi', 1, 91, 'And if there be no righteousness nor happiness, there be no punishment nor misery.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-92', 'coc-bom-1908', 'II Nephi', 1, 92, 'And if these things are not, there is no God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-94', 'coc-bom-1908', 'II Nephi', 1, 94, 'And now, my son, I speak unto you these things for your profit and learning:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-96', 'coc-bom-1908', 'II Nephi', 1, 96, 'Both things to act and things to be acted upon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-97', 'coc-bom-1908', 'II Nephi', 1, 97, 'And to bring about his eternal purposes in the end of man, after he had created our first parents, and the beasts of the field, and the fowls of the air, and, in fine, all things which are created, it must needs be that there was an opposition--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-98', 'coc-bom-1908', 'II Nephi', 1, 98, 'Even the forbidden fruit in opposition to the tree of life--the one being sweet and the other bitter.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-99', 'coc-bom-1908', 'II Nephi', 1, 99, 'Wherefore, the Lord God gave unto man that he should act for himself.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-100', 'coc-bom-1908', 'II Nephi', 1, 100, 'Wherefore, man could not act for himself, save it should be that he was enticed by the one or the other.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-102', 'coc-bom-1908', 'II Nephi', 1, 102, 'Wherefore, he became a devil, having sought that which was evil before God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-103', 'coc-bom-1908', 'II Nephi', 1, 103, 'And because he had fallen from heaven and had become miserable forever, he sought also the misery of all mankind.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-105', 'coc-bom-1908', 'II Nephi', 1, 105, 'And after Adam and Eve had partaken of the forbidden fruit, they were driven out of the garden of Eden to till the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-106', 'coc-bom-1908', 'II Nephi', 1, 106, 'And they have brought forth children, yea, even the family of all the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-108', 'coc-bom-1908', 'II Nephi', 1, 108, 'Wherefore, their state became a state of probation, and their time was lengthened, according to the commandments which the Lord God gave unto the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-110', 'coc-bom-1908', 'II Nephi', 1, 110, 'For he showed unto all men that they were lost because of the transgression of their parents.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-114', 'coc-bom-1908', 'II Nephi', 1, 114, 'But behold, all things have been done in the wisdom of him who knoweth all things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-116', 'coc-bom-1908', 'II Nephi', 1, 116, 'And the Messiah cometh in the fullness of time, that he may redeem the children of men from the fall.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-117', 'coc-bom-1908', 'II Nephi', 1, 117, 'And because that they are redeemed from the fall, they have become free forever, knowing good from evil,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-118', 'coc-bom-1908', 'II Nephi', 1, 118, 'To act for themselves and not to be acted upon, save it be by the punishment of the Lord, at the great and last day, according to the commandments which God hath given.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-121', 'coc-bom-1908', 'II Nephi', 1, 121, 'For he seeketh that all men might be miserable like unto himself.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-122', 'coc-bom-1908', 'II Nephi', 1, 122, 'And now, my sons, I would that ye should look to the great Mediator, and hearken unto his great commandments,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-123', 'coc-bom-1908', 'II Nephi', 1, 123, 'And be faithful unto his words, and choose eternal life, according to the will of his Holy Spirit,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-124', 'coc-bom-1908', 'II Nephi', 1, 124, 'And not choose eternal death, according to the will of the flesh and the evil which is therein,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-125', 'coc-bom-1908', 'II Nephi', 1, 125, 'Which giveth the spirit of the devil power to captivate, to bring you down to hell, that he may reign over you in his own kingdom.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-127', 'coc-bom-1908', 'II Nephi', 1, 127, 'And I have chosen the good part, according to the words of the prophet.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-1-128', 'coc-bom-1908', 'II Nephi', 1, 128, 'And I have none other object, save it be the everlasting welfare of your souls. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-1', 'coc-bom-1908', 'II Nephi', 2, 1, 'And now, I speak unto you, Joseph, my last born.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-3', 'coc-bom-1908', 'II Nephi', 2, 3, 'And may the Lord consecrate also unto thee this land, which is a most precious land, for thine inheritance and the inheritance of thy seed with thy brethren, for thy security forever--if it so be that ye shall keep the commandments of the Holy One of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-4', 'coc-bom-1908', 'II Nephi', 2, 4, 'And now, Joseph, my last born, whom I have brought out of the wilderness of mine afflictions, may the Lord bless thee forever, for thy seed shall not utterly be destroyed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-7', 'coc-bom-1908', 'II Nephi', 2, 7, 'And he obtained a promise of the Lord, that out of the fruit of his loins the Lord God would raise up a righteous branch unto the house of Israel--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-8', 'coc-bom-1908', 'II Nephi', 2, 8, 'Not the Messiah, but a branch which was to be broken off, nevertheless, to be remembered in the covenants of the Lord,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-9', 'coc-bom-1908', 'II Nephi', 2, 9, 'That the Messiah should be made manifest unto them in the latter days, in the spirit of power, unto the bringing of them out of darkness unto light, yea, out of hidden darkness and out of captivity unto freedom.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-10', 'coc-bom-1908', 'II Nephi', 2, 10, 'For Joseph truly testified, saying, A seer shall the Lord, my God, raise up, who shall be a choice seer unto the fruit of my loins.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-12', 'coc-bom-1908', 'II Nephi', 2, 12, 'And unto him will I give commandment, that he shall do a work for the fruit of thy loins, his brethren, which shall be of great worth unto them, even to the bringing of them to the knowledge of the covenants which I have made with thy fathers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-13', 'coc-bom-1908', 'II Nephi', 2, 13, 'And I will give unto him a commandment, that he shall do none other work save the work which I shall command him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-14', 'coc-bom-1908', 'II Nephi', 2, 14, 'And I will make him great in mine eyes, for he shall do my work.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-15', 'coc-bom-1908', 'II Nephi', 2, 15, 'And he shall be great like unto Moses, whom I have said I would raise up unto you to deliver my people, O house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-16', 'coc-bom-1908', 'II Nephi', 2, 16, 'And Moses will I raise up to deliver thy people out of the land of Egypt.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-18', 'coc-bom-1908', 'II Nephi', 2, 18, 'And not to the bringing forth my word only, saith the Lord, but to the convincing them of my word, which shall have already gone forth among them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-20', 'coc-bom-1908', 'II Nephi', 2, 20, 'And that which shall be written by the fruit of thy loins and also that which shall be written by the fruit of the loins of Judah shall grow together,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-21', 'coc-bom-1908', 'II Nephi', 2, 21, 'Unto the confounding of false doctrines, and laying down of contentions, and establishing peace among the fruit of thy loins,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-22', 'coc-bom-1908', 'II Nephi', 2, 22, 'And bringing them to the knowledge of their fathers in the latter days,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-23', 'coc-bom-1908', 'II Nephi', 2, 23, 'And also to the knowledge of my covenants, saith the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-24', 'coc-bom-1908', 'II Nephi', 2, 24, 'And out of weakness he shall be made strong, in that day when my work shall commence among all my people, unto the restoring thee, O house of Israel, saith the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-27', 'coc-bom-1908', 'II Nephi', 2, 27, 'For this promise, of which I have obtained of the Lord of the fruit of thy loins, shall be fulfilled.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-28', 'coc-bom-1908', 'II Nephi', 2, 28, 'Behold, I am sure of the fulfilling of this promise.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-33', 'coc-bom-1908', 'II Nephi', 2, 33, 'And I will give judgment unto him in writing.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-36', 'coc-bom-1908', 'II Nephi', 2, 36, 'And the Lord said unto me also, I will raise up unto the fruit of thy loins, and I will make for him a spokesman.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-38', 'coc-bom-1908', 'II Nephi', 2, 38, 'And the words which he shall write shall be the words which are expedient in my wisdom should go forth unto the fruit of thy loins.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-40', 'coc-bom-1908', 'II Nephi', 2, 40, 'And they shall cry from the dust, yea, even repentance unto their brethren, even after many generations have gone by them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-41', 'coc-bom-1908', 'II Nephi', 2, 41, 'And it shall come to pass that their cry shall go, even according to the simpleness of their words.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-43', 'coc-bom-1908', 'II Nephi', 2, 43, 'And the weakness of their words will I make strong in their faith, unto the remembering of my covenant which I made unto thy fathers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-44', 'coc-bom-1908', 'II Nephi', 2, 44, 'And now, behold, my son Joseph, after this manner did my father of old prophesy.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-45', 'coc-bom-1908', 'II Nephi', 2, 45, 'Wherefore, because of this covenant thou art blessed, for thy seed shall not be destroyed, for they shall hearken unto the words of the book.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-46', 'coc-bom-1908', 'II Nephi', 2, 46, 'And there shall rise up one mighty among them, who shall do much good, both in word and in deed, being an instrument in the hands of God, with exceeding faith,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-47', 'coc-bom-1908', 'II Nephi', 2, 47, 'To work mighty wonders and do that thing which is great in the sight of God, unto the bringing to pass much restoration unto the house of Israel and unto the seed of thy brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-48', 'coc-bom-1908', 'II Nephi', 2, 48, 'And now, blessed art thou, Joseph.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-2-50', 'coc-bom-1908', 'II Nephi', 2, 50, 'Remember the words of thy dying father. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-1', 'coc-bom-1908', 'II Nephi', 3, 1, 'And now, I, Nephi, speak concerning the prophecies of which my father hath spoken concerning Joseph, who was carried into Egypt:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-2', 'coc-bom-1908', 'II Nephi', 3, 2, 'For behold, he truly prophesied concerning all his seed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-3', 'coc-bom-1908', 'II Nephi', 3, 3, 'And the prophecies which he wrote, there are not many greater.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-5', 'coc-bom-1908', 'II Nephi', 3, 5, 'And they are written upon the plates of brass.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-6', 'coc-bom-1908', 'II Nephi', 3, 6, 'Wherefore, after my father had made an end of speaking concerning the prophecies of Joseph, he called the children of Laman, his sons and his daughters, and said unto them,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-9', 'coc-bom-1908', 'II Nephi', 3, 9, 'And inasmuch as ye will not keep my commandments, ye shall be cut off from my presence.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-11', 'coc-bom-1908', 'II Nephi', 3, 11, 'For behold, I know that if ye are brought up in the way ye should go, ye will not depart from it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-12', 'coc-bom-1908', 'II Nephi', 3, 12, 'Wherefore, if ye are cursed, behold, I leave my blessing upon you, that the cursing may be taken from you and be answered upon the heads of your parents.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-14', 'coc-bom-1908', 'II Nephi', 3, 14, 'And it came to pass that after my father had made an end of speaking to the sons and daughters of Laman, he caused the sons and daughters of Lemuel to be brought before him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-15', 'coc-bom-1908', 'II Nephi', 3, 15, 'And he spake unto them, saying, Behold, my sons and my daughters, who are the sons and the daughters of my second son,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-17', 'coc-bom-1908', 'II Nephi', 3, 17, 'And it came to pass that when my father had made an end of speaking unto them, behold, he spake unto the sons of Ishmael, yea, and even all his household.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-18', 'coc-bom-1908', 'II Nephi', 3, 18, 'And after he had made an end of speaking unto them, he spake unto Sam, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-22', 'coc-bom-1908', 'II Nephi', 3, 22, 'And it came to pass after my father Lehi had spoken unto all his household, according to the feelings of his heart and the Spirit of the Lord which was in him, he waxed old.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-23', 'coc-bom-1908', 'II Nephi', 3, 23, 'And it came to pass that he died and was buried.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-25', 'coc-bom-1908', 'II Nephi', 3, 25, 'For I, Nephi, was constrained to speak unto them according to his word.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-26', 'coc-bom-1908', 'II Nephi', 3, 26, 'For I had spoken many things unto them, and also my father before his death,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-29', 'coc-bom-1908', 'II Nephi', 3, 29, 'For my soul delighteth in the scriptures, and my heart pondereth them and writeth them for the learning and the profit of my children.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-31', 'coc-bom-1908', 'II Nephi', 3, 31, 'Nevertheless, the great goodness of the Lord, in showing me his great and marvelous works, my heart exclaimeth, O wretched man that I am! Yea, my heart sorroweth because of my flesh.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-32', 'coc-bom-1908', 'II Nephi', 3, 32, 'My soul grieveth because of mine iniquities.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-33', 'coc-bom-1908', 'II Nephi', 3, 33, 'I am encompassed about because of the temptations and the sins which doth so easily beset me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-36', 'coc-bom-1908', 'II Nephi', 3, 36, 'He hath filled me with his love, even unto the consuming of my flesh.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-37', 'coc-bom-1908', 'II Nephi', 3, 37, 'He hath confounded mine enemies unto the causing of them to quake before me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-38', 'coc-bom-1908', 'II Nephi', 3, 38, 'Behold, he hath heard my cry by day, and he hath given me knowledge by visions in the nighttime.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-40', 'coc-bom-1908', 'II Nephi', 3, 40, 'And upon the wings of his Spirit hath my body been carried away upon exceeding high mountains.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-42', 'coc-bom-1908', 'II Nephi', 3, 42, 'Oh, then, if I have seen so great things, if the Lord in his condescension unto the children of men hath visited me in so much mercy, why should my heart weep, and my soul linger in the valley of sorrow, and my flesh waste away, and my strength slacken because of mine afflictions?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-43', 'coc-bom-1908', 'II Nephi', 3, 43, 'And why should I yield to sin because of my flesh?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-44', 'coc-bom-1908', 'II Nephi', 3, 44, 'Yea, why should I give way to temptations, that the evil one have place in my heart to destroy my peace and afflict my soul?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-45', 'coc-bom-1908', 'II Nephi', 3, 45, 'Why am I angry because of mine enemy?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-46', 'coc-bom-1908', 'II Nephi', 3, 46, 'Awake, my soul! No longer droop in sin!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-47', 'coc-bom-1908', 'II Nephi', 3, 47, 'Rejoice, O my heart, and give place no more for the enemy of my soul!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-48', 'coc-bom-1908', 'II Nephi', 3, 48, 'Do not anger again because of mine enemies.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-49', 'coc-bom-1908', 'II Nephi', 3, 49, 'Do not slacken my strength because of mine afflictions.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-50', 'coc-bom-1908', 'II Nephi', 3, 50, 'Rejoice, O my heart, and cry unto the Lord, and say, O Lord, I will praise thee forever! Yea, my soul will rejoice in thee, my God, and the rock of my salvation!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-51', 'coc-bom-1908', 'II Nephi', 3, 51, 'O Lord, wilt thou redeem my soul?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-52', 'coc-bom-1908', 'II Nephi', 3, 52, 'Wilt thou deliver me out of the hands of mine enemies?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-53', 'coc-bom-1908', 'II Nephi', 3, 53, 'Wilt thou make me that I may shake at the appearance of sin?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-54', 'coc-bom-1908', 'II Nephi', 3, 54, 'May the gates of hell be shut continually before me because that my heart is broken and my spirit is contrite?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-55', 'coc-bom-1908', 'II Nephi', 3, 55, 'O Lord, wilt thou not shut the gates of thy righteousness before me, that I may walk in the path of the low valley, that I may be strict in the plain road?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-56', 'coc-bom-1908', 'II Nephi', 3, 56, 'O Lord, wilt thou encircle me around in the robe of thy righteousness?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-57', 'coc-bom-1908', 'II Nephi', 3, 57, 'O Lord, wilt thou make a way for mine escape before mine enemies?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-58', 'coc-bom-1908', 'II Nephi', 3, 58, 'Wilt thou make my path straight before me?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-59', 'coc-bom-1908', 'II Nephi', 3, 59, 'Wilt thou not place a stumbling block in my way?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-60', 'coc-bom-1908', 'II Nephi', 3, 60, 'But that thou wouldest clear my way before me and hedge not up my way, but the ways of mine enemy.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-61', 'coc-bom-1908', 'II Nephi', 3, 61, 'O Lord, I have trusted in thee, and I will trust in thee forever.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-63', 'coc-bom-1908', 'II Nephi', 3, 63, 'Yea, cursed is he that putteth his trust in man or maketh flesh his arm.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-64', 'coc-bom-1908', 'II Nephi', 3, 64, 'Yea, I know that God will give liberally to him that asketh.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-3-66', 'coc-bom-1908', 'II Nephi', 3, 66, 'Behold, my voice shall forever ascend up unto thee, my rock and mine everlasting God. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-1', 'coc-bom-1908', 'II Nephi', 4, 1, 'Behold, it came to pass that I, Nephi, did cry much unto the Lord, my God, because of the anger of my brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-2', 'coc-bom-1908', 'II Nephi', 4, 2, 'But behold, their anger did increase against me, insomuch that they did seek to take away my life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-5', 'coc-bom-1908', 'II Nephi', 4, 5, 'Now I do not write upon these plates all the words which they murmured against me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-6', 'coc-bom-1908', 'II Nephi', 4, 6, 'But it sufficeth me to say that they did seek to take away my life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-7', 'coc-bom-1908', 'II Nephi', 4, 7, 'And it came to pass that the Lord did warn me that I, Nephi, should depart from them and flee into the wilderness, and all those who would go with me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-8', 'coc-bom-1908', 'II Nephi', 4, 8, 'Wherefore, it came to pass that I, Nephi, did take my family, and also Zoram and his family, and Sam, mine elder brother, and his family, and Jacob and Joseph, my younger brethren, and also my sisters, and all those who would go with me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-10', 'coc-bom-1908', 'II Nephi', 4, 10, 'And we did take our tents and whatsoever things were possible for us and did journey in the wilderness for the space of many days.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-11', 'coc-bom-1908', 'II Nephi', 4, 11, 'And after we had journeyed for the space of many days, we did pitch our tents.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-13', 'coc-bom-1908', 'II Nephi', 4, 13, 'And all those who were with me did take upon them to call themselves the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-14', 'coc-bom-1908', 'II Nephi', 4, 14, 'And we did observe to keep the judgments, and the statutes, and the commandments of the Lord in all things, according to the law of Moses.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-16', 'coc-bom-1908', 'II Nephi', 4, 16, 'And we began to raise flocks, and herds, and animals of every kind.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-17', 'coc-bom-1908', 'II Nephi', 4, 17, 'And I, Nephi, had also brought the records which were engraven upon the plates of brass and also the ball, or compass, which was prepared for my father by the hand of the Lord, according to that which is written.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-18', 'coc-bom-1908', 'II Nephi', 4, 18, 'And it came to pass that we began to prosper exceedingly and to multiply in the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-20', 'coc-bom-1908', 'II Nephi', 4, 20, 'For I knew their hatred towards me, and my children, and those who were called my people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-21', 'coc-bom-1908', 'II Nephi', 4, 21, 'And I did teach my people to build buildings and to work in all manner of wood, and of iron, and of copper, and of brass, and of steel, and of gold, and of silver, and of precious ores, which were in great abundance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-24', 'coc-bom-1908', 'II Nephi', 4, 24, 'Wherefore, it could not be built like unto Solomon''s temple.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-26', 'coc-bom-1908', 'II Nephi', 4, 26, 'And it came to pass that I, Nephi, did cause my people to be industrious and to labor with their hands.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-27', 'coc-bom-1908', 'II Nephi', 4, 27, 'And it came to pass that they would that I should be their king.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-30', 'coc-bom-1908', 'II Nephi', 4, 30, 'Wherefore, I had been their ruler and their teacher, according to the commandment of the Lord, until the time they sought to take away my life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-31', 'coc-bom-1908', 'II Nephi', 4, 31, 'Wherefore, the word of the Lord was fulfilled which he spake unto me, saying that, Inasmuch as they will not hearken unto thy words, they shall be cut off from the presence of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-32', 'coc-bom-1908', 'II Nephi', 4, 32, 'And behold, they were cut off from his presence.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-33', 'coc-bom-1908', 'II Nephi', 4, 33, 'And he had caused the cursing to come upon them, yea, even a sore cursing, because of their iniquity.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-35', 'coc-bom-1908', 'II Nephi', 4, 35, 'Wherefore, as they were white, and exceeding fair, and delightsome, that they might not be enticing unto my people, the Lord God did cause a skin of blackness to come upon them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-36', 'coc-bom-1908', 'II Nephi', 4, 36, 'And thus saith the Lord God, I will cause that they shall be loathsome unto thy people, save they shall repent of their iniquities.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-38', 'coc-bom-1908', 'II Nephi', 4, 38, 'And the Lord spake it, and it was done.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-39', 'coc-bom-1908', 'II Nephi', 4, 39, 'And because of their cursing which was upon them, they did become an idle people, full of mischief and subtlety, and did seek in the wilderness for beasts of prey.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-41', 'coc-bom-1908', 'II Nephi', 4, 41, 'And inasmuch as they will not remember me and hearken unto my words, they shall scourge them even unto destruction.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-42', 'coc-bom-1908', 'II Nephi', 4, 42, 'And it came to pass that I, Nephi, did consecrate Jacob and Joseph, that they should be priests and teachers over the land of my people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-43', 'coc-bom-1908', 'II Nephi', 4, 43, 'And it came to pass that we lived after the manner of happiness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-44', 'coc-bom-1908', 'II Nephi', 4, 44, 'And thirty years had passed away from the time we left Jerusalem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-45', 'coc-bom-1908', 'II Nephi', 4, 45, 'And I, Nephi, had kept the records upon my plates, which I had made of my people thus far.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-47', 'coc-bom-1908', 'II Nephi', 4, 47, 'Wherefore, I, Nephi, to be obedient to the commandments of the Lord, went and made these plates upon which I have engraven these things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-48', 'coc-bom-1908', 'II Nephi', 4, 48, 'And I engraved that which is pleasing unto God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-49', 'coc-bom-1908', 'II Nephi', 4, 49, 'And if my people are pleased with the things of God, they will be pleased with mine engravings which are upon these plates.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-50', 'coc-bom-1908', 'II Nephi', 4, 50, 'And if my people desire to know the more particular part of the history of my people, they must search mine other plates.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-4-51', 'coc-bom-1908', 'II Nephi', 4, 51, 'And it sufficeth me to say that forty years had passed away, and we had already had wars and contentions with our brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-1', 'coc-bom-1908', 'II Nephi', 5, 1, 'The word of Jacob, the brother of Nephi, which he spake unto the people of Nephi:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-2', 'coc-bom-1908', 'II Nephi', 5, 2, 'Behold, my beloved brethren, I, Jacob, having been called of God, and ordained after the manner of his holy order,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-3', 'coc-bom-1908', 'II Nephi', 5, 3, 'And having been consecrated by my brother, Nephi, unto whom ye look as a king or a protector, and on whom ye depend for safety,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-8', 'coc-bom-1908', 'II Nephi', 5, 8, 'And I have spoken unto you concerning all things which are written from the creation of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-10', 'coc-bom-1908', 'II Nephi', 5, 10, 'Wherefore, I will read you the words of Isaiah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-11', 'coc-bom-1908', 'II Nephi', 5, 11, 'And they are the words which my brother has desired that I should speak unto you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-12', 'coc-bom-1908', 'II Nephi', 5, 12, 'And I speak them unto you for your sakes, that ye may learn and glorify the name of your God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-15', 'coc-bom-1908', 'II Nephi', 5, 15, 'And there are many things which have been spoken by Isaiah, which may be likened unto you because ye are of the house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-16', 'coc-bom-1908', 'II Nephi', 5, 16, 'And now, these are the words:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-18', 'coc-bom-1908', 'II Nephi', 5, 18, 'And they shall bring thy sons in their arms, and thy daughters shall be carried upon their shoulders.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-23', 'coc-bom-1908', 'II Nephi', 5, 23, 'Nevertheless, the Lord has shown unto me that they should return again.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-25', 'coc-bom-1908', 'II Nephi', 5, 25, 'And after he should manifest himself, they should scourge him and crucify him, according to the words of the angel, who spake it unto me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-26', 'coc-bom-1908', 'II Nephi', 5, 26, 'And after they have hardened their hearts and stiffened their necks against the Holy One of Israel, behold, the judgments of the Holy One of Israel shall come upon them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-27', 'coc-bom-1908', 'II Nephi', 5, 27, 'And the day cometh that they shall be smitten and afflicted.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-29', 'coc-bom-1908', 'II Nephi', 5, 29, 'Nevertheless, the Lord will be merciful unto them, that when they shall come to the knowledge of their Redeemer, they shall be gathered together again to the lands of their inheritance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-34', 'coc-bom-1908', 'II Nephi', 5, 34, 'And the people of the Lord shall not be ashamed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-38', 'coc-bom-1908', 'II Nephi', 5, 38, 'And none will he destroy that believe in him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-39', 'coc-bom-1908', 'II Nephi', 5, 39, 'And they that believe not in him shall be destroyed, both by fire, and by tempest, and by earthquakes, and by bloodsheds, and by pestilence, and by famine.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-40', 'coc-bom-1908', 'II Nephi', 5, 40, 'And they shall know that the Lord is God, the Holy One of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-41', 'coc-bom-1908', 'II Nephi', 5, 41, 'For shall the prey be taken from the mighty, or the lawful captive delivered?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-45', 'coc-bom-1908', 'II Nephi', 5, 45, 'And all flesh shall know that I, the Lord, am thy Savior and thy Redeemer, the Mighty One of Jacob.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-46', 'coc-bom-1908', 'II Nephi', 5, 46, 'Yea, for thus saith the Lord, Have I put thee away, or have I cast thee off forever?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-47', 'coc-bom-1908', 'II Nephi', 5, 47, 'For thus saith the Lord, Where is the bill of your mother''s divorcement?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-48', 'coc-bom-1908', 'II Nephi', 5, 48, 'To whom have I put thee away, or to which of my creditors have I sold you?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-49', 'coc-bom-1908', 'II Nephi', 5, 49, 'Yea, to whom have I sold you?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-52', 'coc-bom-1908', 'II Nephi', 5, 52, 'O house of Israel, is my hand shortened at all that it cannot redeem, or have I no power to deliver?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-54', 'coc-bom-1908', 'II Nephi', 5, 54, 'I clothe the heavens with blackness, and I make sackcloth their covering.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-55', 'coc-bom-1908', 'II Nephi', 5, 55, 'The Lord God hath given me the tongue of the learned, that I should know how to speak a word in season unto thee, O house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-56', 'coc-bom-1908', 'II Nephi', 5, 56, 'When ye are weary, he waketh morning by morning.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-57', 'coc-bom-1908', 'II Nephi', 5, 57, 'He waketh mine ear to hear as the learned.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-58', 'coc-bom-1908', 'II Nephi', 5, 58, 'The Lord God hath appointed mine ear, and I was not rebellious, neither turned away back.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-59', 'coc-bom-1908', 'II Nephi', 5, 59, 'I gave my back to the smiter and my cheeks to them that plucked off the hair.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-62', 'coc-bom-1908', 'II Nephi', 5, 62, 'Who will contend with me?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-63', 'coc-bom-1908', 'II Nephi', 5, 63, 'Let us stand together.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-64', 'coc-bom-1908', 'II Nephi', 5, 64, 'Who is mine adversary?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-66', 'coc-bom-1908', 'II Nephi', 5, 66, 'And all they who shall condemn me, behold, all they shall wax old as a garment, and the moth shall eat them up.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-67', 'coc-bom-1908', 'II Nephi', 5, 67, 'Who is among you that feareth the Lord, that obeyeth the voice of his servant, that walketh in darkness and hath no light?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-68', 'coc-bom-1908', 'II Nephi', 5, 68, 'Behold, all ye that kindle fire, that compass yourselves about with sparks, walk in the light of your fire and in the sparks which ye have kindled.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-69', 'coc-bom-1908', 'II Nephi', 5, 69, 'This shall ye have of mine hand: Ye shall lie down in sorrow.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-70', 'coc-bom-1908', 'II Nephi', 5, 70, 'Hearken unto me, ye that follow after righteousness. Look unto the rock from whence ye are hewn and to the hole of the pit from whence ye are digged.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-73', 'coc-bom-1908', 'II Nephi', 5, 73, 'And he will make her wilderness like Eden and her desert like the garden of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-74', 'coc-bom-1908', 'II Nephi', 5, 74, 'Joy and gladness shall be found therein--thanksgiving and the voice of melody.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-75', 'coc-bom-1908', 'II Nephi', 5, 75, 'Hearken unto me, my people, and give ear unto me, O my nation:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-76', 'coc-bom-1908', 'II Nephi', 5, 76, 'For a law shall proceed from me, and I will make my judgment to rest for a light for the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-78', 'coc-bom-1908', 'II Nephi', 5, 78, 'The isles shall wait upon me, and on mine arm shall they trust.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-84', 'coc-bom-1908', 'II Nephi', 5, 84, 'For the moth shall eat them up like a garment, and the worm shall eat them like wool.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-85', 'coc-bom-1908', 'II Nephi', 5, 85, 'But my righteousness shall be forever, and my salvation from generation to generation.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-86', 'coc-bom-1908', 'II Nephi', 5, 86, 'Awake, awake! Put on strength, O arm of the Lord! Awake as in the ancient days.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-87', 'coc-bom-1908', 'II Nephi', 5, 87, 'Art thou not it that hath cut Rahab and wounded the dragon?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-88', 'coc-bom-1908', 'II Nephi', 5, 88, 'Art thou not it which hath dried the sea, the waters of the great deep,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-89', 'coc-bom-1908', 'II Nephi', 5, 89, 'That hath made the depths of the sea a way for the ransomed to pass over?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-93', 'coc-bom-1908', 'II Nephi', 5, 93, 'Behold, who art thou, that thou shouldest be afraid of man, who shall die, and of the son of man, who shall be made like unto grass,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-94', 'coc-bom-1908', 'II Nephi', 5, 94, 'And forgettest the Lord, thy Maker, that hath stretched forth the heavens and laid the foundations of the earth,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-95', 'coc-bom-1908', 'II Nephi', 5, 95, 'And hast feared continually every day because of the fury of the oppressor, as if he were ready to destroy?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-96', 'coc-bom-1908', 'II Nephi', 5, 96, 'And where is the fury of the oppressor?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-97', 'coc-bom-1908', 'II Nephi', 5, 97, 'The captive exile hasteneth, that he may be loosed, and that he should not die in the pit, nor that his bread should fail.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-99', 'coc-bom-1908', 'II Nephi', 5, 99, 'And I have put my words in thy mouth and have covered thee in the shadow of mine hand, that I may plant the heavens, and lay the foundations of the earth, and say unto Zion, Behold, thou art my people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-101', 'coc-bom-1908', 'II Nephi', 5, 101, 'Thou hast drunk the dregs of the cup of trembling wrung out,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-102', 'coc-bom-1908', 'II Nephi', 5, 102, 'And none to guide her among all the sons she hath brought forth,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-103', 'coc-bom-1908', 'II Nephi', 5, 103, 'Neither that taketh her by the hand, of all the sons she hath brought up.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-105', 'coc-bom-1908', 'II Nephi', 5, 105, 'And by whom shall I comfort thee?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-107', 'coc-bom-1908', 'II Nephi', 5, 107, 'Therefore, hear now this, thou afflicted, and drunken, and not with wine:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-111', 'coc-bom-1908', 'II Nephi', 5, 111, 'And thou hast laid thy body as the ground, and as the street to them that went over.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-5-113', 'coc-bom-1908', 'II Nephi', 5, 113, 'For henceforth there shall no more come into thee, the uncircumcised and the unclean.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-2', 'coc-bom-1908', 'II Nephi', 6, 2, 'That he has spoken unto the Jews by the mouth of his holy prophets, even from the beginning down, from generation to generation, until the time comes that they shall be restored to the true church and fold of God,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-3', 'coc-bom-1908', 'II Nephi', 6, 3, 'When they shall be gathered home to the lands of their inheritance and shall be established in all their lands of promise.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-4', 'coc-bom-1908', 'II Nephi', 6, 4, 'Behold, my beloved brethren, I speak unto you these things that ye may rejoice and lift up your heads forever because of the blessings which the Lord God shall bestow upon your children.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-7', 'coc-bom-1908', 'II Nephi', 6, 7, 'Nevertheless, in our bodies we shall see God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-10', 'coc-bom-1908', 'II Nephi', 6, 10, 'For it behooveth the great Creator that he suffereth himself to become subject unto man in the flesh and die for all men, that all men might become subject unto him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-11', 'coc-bom-1908', 'II Nephi', 6, 11, 'For as death hath passed upon all men, to fulfill the merciful plan of the great Creator, there must needs be a power of resurrection.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-15', 'coc-bom-1908', 'II Nephi', 6, 15, 'Wherefore, it must needs be an infinite atonement.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-16', 'coc-bom-1908', 'II Nephi', 6, 16, 'Save it should be an infinite atonement, this corruption could not put on incorruption.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-17', 'coc-bom-1908', 'II Nephi', 6, 17, 'Wherefore, the first judgment which came upon man must needs have remained to an endless duration.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-18', 'coc-bom-1908', 'II Nephi', 6, 18, 'And if so, this flesh must have lain down to rot and to crumble to its mother earth, to rise no more.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-19', 'coc-bom-1908', 'II Nephi', 6, 19, 'Oh, the wisdom of God! His mercy and grace!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-20', 'coc-bom-1908', 'II Nephi', 6, 20, 'For behold, if the flesh should rise no more, our spirits must become subject to that angel who fell from before the presence of the eternal God and became the devil, to rise no more.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-21', 'coc-bom-1908', 'II Nephi', 6, 21, 'And our spirits must have become like unto him, and we become devils, angels to a devil, to be shut out from the presence of our God and to remain with the father of lies, in misery, like unto himself,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-22', 'coc-bom-1908', 'II Nephi', 6, 22, 'Yea, to that being who beguiled our first parents,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-23', 'coc-bom-1908', 'II Nephi', 6, 23, 'Who transformeth himself nigh unto an angel of light and stirreth up the children of men unto secret combinations of murder and all manner of secret works of darkness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-24', 'coc-bom-1908', 'II Nephi', 6, 24, 'Oh, how great the goodness of our God, who prepareth a way for our escape from the grasp of this awful monster,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-25', 'coc-bom-1908', 'II Nephi', 6, 25, 'Yea, that monster, death and hell, which I call the death of the body and also the death of the spirit.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-26', 'coc-bom-1908', 'II Nephi', 6, 26, 'And because of the way of deliverance of our God, the Holy One of Israel, this death of which I have spoken, which is the temporal, shall deliver up its dead, which death is the grave.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-28', 'coc-bom-1908', 'II Nephi', 6, 28, 'Wherefore, death and hell must deliver up their dead, and hell must deliver up its captive spirits.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-30', 'coc-bom-1908', 'II Nephi', 6, 30, 'And it is by the power of the resurrection of the Holy One of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-33', 'coc-bom-1908', 'II Nephi', 6, 33, 'Save it be that our knowledge shall be perfect.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-35', 'coc-bom-1908', 'II Nephi', 6, 35, 'And the righteous shall have a perfect knowledge of their enjoyment and their righteousness, being clothed with purity, yea, even with the robe of righteousness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-38', 'coc-bom-1908', 'II Nephi', 6, 38, 'And assuredly, as the Lord liveth--for the Lord God hath spoken it, and it is his eternal word, which cannot pass away--that they who are righteous shall be righteous still, and they who are filthy shall be filthy still.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-43', 'coc-bom-1908', 'II Nephi', 6, 43, 'Oh, the greatness of the mercy of our God, the Holy One of Israel! For he delivereth his saints from that awful monster the devil, and death, and hell, and that lake of fire and brimstone, which is endless torment.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-44', 'coc-bom-1908', 'II Nephi', 6, 44, 'Oh, how great the holiness of our God! For he knoweth all things, and there is not anything save he knows it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-46', 'coc-bom-1908', 'II Nephi', 6, 46, 'For behold, he suffereth the pains of all men, yea, the pains of every living creature--both men, women, and children, who belong to the family of Adam.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-47', 'coc-bom-1908', 'II Nephi', 6, 47, 'And he suffereth this that the resurrection might pass upon all men, that all might stand before him at the great and judgment day.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-48', 'coc-bom-1908', 'II Nephi', 6, 48, 'And he commandeth all men that they must repent and be baptized in his name, having perfect faith in the Holy One of Israel, or they cannot be saved in the kingdom of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-50', 'coc-bom-1908', 'II Nephi', 6, 50, 'For the Lord God, the Holy One of Israel, hath spoken it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-53', 'coc-bom-1908', 'II Nephi', 6, 53, 'And where there is no condemnation, the mercies of the Holy One of Israel have claim upon them because of the atonement.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-55', 'coc-bom-1908', 'II Nephi', 6, 55, 'And they are restored to that God who gave them breath, which is the Holy One of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-57', 'coc-bom-1908', 'II Nephi', 6, 57, 'Oh, that cunning plan of the evil one!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-58', 'coc-bom-1908', 'II Nephi', 6, 58, 'Oh, the vainness, and the frailties, and the foolishness of men!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-60', 'coc-bom-1908', 'II Nephi', 6, 60, 'Wherefore, their wisdom is foolishness, and it profiteth them not. And they shall perish.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-61', 'coc-bom-1908', 'II Nephi', 6, 61, 'But to be learned is good if they hearken unto the counsels of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-62', 'coc-bom-1908', 'II Nephi', 6, 62, 'But wo unto the rich, who are rich as to the things of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-64', 'coc-bom-1908', 'II Nephi', 6, 64, 'And behold, their treasure shall perish with them also.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-73', 'coc-bom-1908', 'II Nephi', 6, 73, 'O my beloved brethren, remember the awfulness in transgressing against that Holy God, and also the awfulness of yielding to the enticings of that cunning one.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-74', 'coc-bom-1908', 'II Nephi', 6, 74, 'Remember, to be carnally minded is death, and to be spiritually minded is life eternal.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-75', 'coc-bom-1908', 'II Nephi', 6, 75, 'O my beloved brethren, give ear to my words.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-76', 'coc-bom-1908', 'II Nephi', 6, 76, 'Remember the greatness of the Holy One of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-79', 'coc-bom-1908', 'II Nephi', 6, 79, 'O, then, my beloved brethren, come unto the Lord, the Holy One.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-80', 'coc-bom-1908', 'II Nephi', 6, 80, 'Remember that his paths are righteousness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-84', 'coc-bom-1908', 'II Nephi', 6, 84, 'And save they shall cast these things away, and consider themselves fools before God, and come down in the depths of humility, he will not open unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-85', 'coc-bom-1908', 'II Nephi', 6, 85, 'But the things of the wise and the prudent shall be hid from them forever, yea, that happiness which is prepared for the saints.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-86', 'coc-bom-1908', 'II Nephi', 6, 86, 'O my beloved brethren, remember my words: Behold, I take off my garments, and I shake them before you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-88', 'coc-bom-1908', 'II Nephi', 6, 88, 'Wherefore, ye shall know at the last day, when all men shall be judged of their works, that the God of Israel did witness that I shook your iniquities from my soul, and that I stand with brightness before him, and am rid of your blood.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-90', 'coc-bom-1908', 'II Nephi', 6, 90, 'Come unto that God who is the rock of your salvation.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-91', 'coc-bom-1908', 'II Nephi', 6, 91, 'Prepare your souls for that glorious day, when justice shall be administered unto the righteous, even the day of judgment, that ye may not shrink with awful fear,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-92', 'coc-bom-1908', 'II Nephi', 6, 92, 'That ye may not remember your awful guilt in perfectness and be constrained to exclaim, Holy, holy are thy judgments, O Lord God Almighty!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-94', 'coc-bom-1908', 'II Nephi', 6, 94, 'But behold, my brethren, is it expedient that I should awake you to an awful reality of these things?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-95', 'coc-bom-1908', 'II Nephi', 6, 95, 'Would I harrow up your souls if your minds were pure?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-96', 'coc-bom-1908', 'II Nephi', 6, 96, 'Would I be plain unto you according to the plainness of the truth if ye were freed from sin?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-6-100', 'coc-bom-1908', 'II Nephi', 6, 100, 'Wherefore, do not spend money for that which is of no worth, nor your labor for that which cannot satisfy.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-7-1', 'coc-bom-1908', 'II Nephi', 7, 1, 'And now, I, Jacob, speak unto you again, my beloved brethren, concerning this righteous branch of which I have spoken.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-7-4', 'coc-bom-1908', 'II Nephi', 7, 4, 'And our children shall be restored, that they may come to that which will give them the true knowledge of their Redeemer.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-7-7', 'coc-bom-1908', 'II Nephi', 7, 7, 'And there is none other nation on earth that would crucify their God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-7-9', 'coc-bom-1908', 'II Nephi', 7, 9, 'But because of priestcrafts and iniquities, they at Jerusalem will stiffen their necks against him, that he be crucified.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-7-11', 'coc-bom-1908', 'II Nephi', 7, 11, 'And they who shall not be destroyed shall be scattered among all nations.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-7-12', 'coc-bom-1908', 'II Nephi', 7, 12, 'But behold, thus saith the Lord God, When the day cometh that they shall believe in me, that I am Christ, then have I covenanted with their fathers that they shall be restored in the flesh upon the earth, unto the lands of their inheritance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-7-14', 'coc-bom-1908', 'II Nephi', 7, 14, 'And the nations of the Gentiles shall be great in the eyes of me, saith God, in carrying them forth to the lands of their inheritance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-7-16', 'coc-bom-1908', 'II Nephi', 7, 16, 'Wherefore, the promises of the Lord are great unto the Gentiles, for he hath spoken it. And who can dispute?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-7-25', 'coc-bom-1908', 'II Nephi', 7, 25, 'For they who are not for me are against me, saith our God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-7-26', 'coc-bom-1908', 'II Nephi', 7, 26, 'For I will fulfill my promises which I have made unto the children of men, that I will do unto them while they are in the flesh.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-7-29', 'coc-bom-1908', 'II Nephi', 7, 29, 'Wherefore, the Gentiles shall be blessed and numbered among the house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-7-32', 'coc-bom-1908', 'II Nephi', 7, 32, 'Wherefore, I will have all men that dwell thereon, that they shall worship me, saith God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-7-35', 'coc-bom-1908', 'II Nephi', 7, 35, 'For the Lord has made the sea our path, and we are upon an isle of the sea.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-7-38', 'coc-bom-1908', 'II Nephi', 7, 38, 'For behold, the Lord God has led away from time to time from the house of Israel according to his will and pleasure.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-7-40', 'coc-bom-1908', 'II Nephi', 7, 40, 'Therefore, cheer up your hearts and remember that ye are free to act for yourselves, to choose the way of everlasting death or the way of eternal life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-7-42', 'coc-bom-1908', 'II Nephi', 7, 42, 'And remember, after ye are reconciled unto God, that it is only in and through the grace of God that ye are saved.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-7-43', 'coc-bom-1908', 'II Nephi', 7, 43, 'Wherefore, may God raise you from death by the power of the resurrection and also from everlasting death by the power of the atonement,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-7-44', 'coc-bom-1908', 'II Nephi', 7, 44, 'That ye may be received into the eternal kingdom of God, that ye may praise him through grace divine. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-5', 'coc-bom-1908', 'II Nephi', 8, 5, 'Wherefore, by the words of three, God hath said, I will establish my word.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-9', 'coc-bom-1908', 'II Nephi', 8, 9, 'And all things which have been given of God from the beginning of the world unto man are the typifying of him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-11', 'coc-bom-1908', 'II Nephi', 8, 11, 'Yea, my soul delighteth in his grace, and his justice, and power, and mercy, in the great and eternal plan of deliverance from death.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-12', 'coc-bom-1908', 'II Nephi', 8, 12, 'And my soul delighteth in proving unto my people that, save Christ should come, all men must perish.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-15', 'coc-bom-1908', 'II Nephi', 8, 15, 'And now, I write some of the words of Isaiah, that whoso of my people shall see these words may lift up their hearts and rejoice for all men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-17', 'coc-bom-1908', 'II Nephi', 8, 17, 'The word that Isaiah, the son of Amoz, saw concerning Judah and Jerusalem:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-18', 'coc-bom-1908', 'II Nephi', 8, 18, 'And it shall come to pass in the last days, when the mountain of the Lord''s house shall be established in the top of the mountains, and shall be exalted above the hills, and all nations shall flow unto it,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-22', 'coc-bom-1908', 'II Nephi', 8, 22, 'Therefore, O Lord, thou hast forsaken thy people, the house of Jacob, because they be replenished from the east, and hearken unto soothsayers like the Philistines, and they please themselves in the children of strangers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-27', 'coc-bom-1908', 'II Nephi', 8, 27, 'And it shall come to pass that the lofty looks of man shall be humbled, and the haughtiness of men shall be bowed down, and the Lord alone shall be exalted in that day.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-29', 'coc-bom-1908', 'II Nephi', 8, 29, 'Yea, and the day of the Lord shall come upon all the cedars of Lebanon, for they are high and lifted up, and upon all the oaks of Bashan,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-30', 'coc-bom-1908', 'II Nephi', 8, 30, 'And upon all the high mountains, and upon all the hills, and upon all the nations which are lifted up,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-31', 'coc-bom-1908', 'II Nephi', 8, 31, 'And upon every people, and upon every high tower, and upon every fenced wall,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-32', 'coc-bom-1908', 'II Nephi', 8, 32, 'And upon all the ships of the sea, and upon all the ships of Tarshish, and upon all pleasant pictures.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-34', 'coc-bom-1908', 'II Nephi', 8, 34, 'And the idols he shall utterly abolish.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-36', 'coc-bom-1908', 'II Nephi', 8, 36, 'In that day a man shall cast his idols of silver and his idols of gold, which he hath made for himself to worship, to the moles and to the bats,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-37', 'coc-bom-1908', 'II Nephi', 8, 37, 'To go into the clefts of the rocks and into the tops of the ragged rocks, for the fear of the Lord shall come upon them, and the majesty of his glory shall smite them when he ariseth to shake terribly the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-38', 'coc-bom-1908', 'II Nephi', 8, 38, 'Cease ye from man, whose breath is in his nostrils. For wherein is he to be accounted of?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-39', 'coc-bom-1908', 'II Nephi', 8, 39, 'For behold, the Lord, the Lord of hosts, doth take away from Jerusalem and from Judah the stay and the staff, the whole staff of bread, and the whole stay of water,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-40', 'coc-bom-1908', 'II Nephi', 8, 40, 'The mighty man, and the man of war, the judge, and the prophet, and the prudent, and the ancient,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-41', 'coc-bom-1908', 'II Nephi', 8, 41, 'The captain of fifty, and the honorable man, and the counselor, and the cunning artificer, and the eloquent orator.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-42', 'coc-bom-1908', 'II Nephi', 8, 42, 'And I will give children unto them to be their princes, and babes shall rule over them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-46', 'coc-bom-1908', 'II Nephi', 8, 46, 'For Jerusalem is ruined, and Judah is fallen because their tongues and their doings have been against the Lord, to provoke the eyes of his glory.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-47', 'coc-bom-1908', 'II Nephi', 8, 47, 'The show of their countenance doth witness against them and doth declare their sin to be even as Sodom, and they cannot hide it. Wo unto their souls, for they have rewarded evil unto themselves.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-50', 'coc-bom-1908', 'II Nephi', 8, 50, 'And my people, children are their oppressors, and women rule over them. O my people, they who lead thee cause thee to err and destroy the way of thy paths.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-51', 'coc-bom-1908', 'II Nephi', 8, 51, 'The Lord standeth up to plead and standeth to judge the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-53', 'coc-bom-1908', 'II Nephi', 8, 53, 'What mean ye? Ye beat my people to pieces and grind the faces of the poor, saith the Lord God of hosts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-54', 'coc-bom-1908', 'II Nephi', 8, 54, 'Moreover, the Lord saith, Because the daughters of Zion are haughty and walk with stretched forth necks and wanton eyes, walking and mincing as they go, and making a tinkling with their feet,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-55', 'coc-bom-1908', 'II Nephi', 8, 55, 'Therefore, the Lord will smite with a scab the crown of the head of the daughters of Zion, and the Lord will discover their secret parts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-56', 'coc-bom-1908', 'II Nephi', 8, 56, 'In that day the Lord will take away the bravery of their tinkling ornaments, and cauls, and round tires like the moon,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-57', 'coc-bom-1908', 'II Nephi', 8, 57, 'The chains and the bracelets, and the mufflers,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-58', 'coc-bom-1908', 'II Nephi', 8, 58, 'The bonnets, and the ornaments of the legs, and the headbands, and the tablets, and the earrings,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-59', 'coc-bom-1908', 'II Nephi', 8, 59, 'The rings, and nose jewels,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-60', 'coc-bom-1908', 'II Nephi', 8, 60, 'The changeable suits of apparel, and the mantles, and the wimples, and the crisping-pins,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-61', 'coc-bom-1908', 'II Nephi', 8, 61, 'The glasses, and the fine linen, and hoods, and the veils.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-63', 'coc-bom-1908', 'II Nephi', 8, 63, 'Thy men shall fall by the sword and thy mighty in the war.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-66', 'coc-bom-1908', 'II Nephi', 8, 66, 'In that day shall the branch of the Lord be beautiful and glorious, the fruit of the earth excellent and comely to them that are escaped of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-67', 'coc-bom-1908', 'II Nephi', 8, 67, 'And it shall come to pass, they that are left in Zion and remain in Jerusalem shall be called holy, everyone that is written among the living in Jerusalem,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-68', 'coc-bom-1908', 'II Nephi', 8, 68, 'When the Lord shall have washed away the filth of the daughters of Zion and shall have purged the blood of Jerusalem from the midst thereof by the spirit of judgment and by the spirit of burning.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-70', 'coc-bom-1908', 'II Nephi', 8, 70, 'And there shall be a tabernacle for a shadow in the daytime from the heat, and for a place of refuge, and a covert from storm and from rain.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-73', 'coc-bom-1908', 'II Nephi', 8, 73, 'And now, O inhabitants of Jerusalem and men of Judah, judge, I pray you, betwixt me and my vineyard.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-74', 'coc-bom-1908', 'II Nephi', 8, 74, 'What could have been done more to my vineyard that I have not done in it? Wherefore, when I looked that it should bring forth grapes, it brought forth wild grapes.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-78', 'coc-bom-1908', 'II Nephi', 8, 78, 'Wo unto them that join house to house till there can be no place, that they may be placed alone in the midst of the earth!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-79', 'coc-bom-1908', 'II Nephi', 8, 79, 'In mine ears, saith the Lord of hosts, of a truth many houses shall be desolate, and great and fair cities without inhabitant.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-80', 'coc-bom-1908', 'II Nephi', 8, 80, 'Yea, ten acres of vineyard shall yield one bath, and the seed of a homer shall yield an ephah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-81', 'coc-bom-1908', 'II Nephi', 8, 81, 'Wo unto them that rise up early in the morning, that they may follow strong drink--that continue until night, and wine inflame them!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-86', 'coc-bom-1908', 'II Nephi', 8, 86, 'But the Lord of hosts shall be exalted in judgment, and God that is holy shall be sanctified in righteousness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-87', 'coc-bom-1908', 'II Nephi', 8, 87, 'Then shall the lambs feed after their manner, and the waste places of the fat ones shall strangers eat.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-90', 'coc-bom-1908', 'II Nephi', 8, 90, 'Wo unto them that call evil good and good evil, that put darkness for light and light for darkness, that put bitter for sweet and sweet for bitter!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-91', 'coc-bom-1908', 'II Nephi', 8, 91, 'Wo unto the wise in their own eyes and prudent in their own sight!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-92', 'coc-bom-1908', 'II Nephi', 8, 92, 'Wo unto the mighty to drink wine, and men of strength to mingle strong drink,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-93', 'coc-bom-1908', 'II Nephi', 8, 93, 'Who justify the wicked for reward and take away the righteousness of the righteous from him!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-8-94', 'coc-bom-1908', 'II Nephi', 8, 94, 'Therefore, as the fire devoureth the stubble and the flame consumeth the chaff, their root shall be rottenness, and their blossoms shall go up as dust because they have cast away the law of the Lord of hosts and despised the word of the Holy One of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-4', 'coc-bom-1908', 'II Nephi', 9, 4, 'And the posts of the door moved at the voice of him that cried, and the house was filled with smoke.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-10', 'coc-bom-1908', 'II Nephi', 9, 10, 'Make the heart of this people fat, and make their ears heavy, and shut their eyes, lest they see with their eyes, and hear with their ears, and understand with their heart, and be converted, and be healed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-11', 'coc-bom-1908', 'II Nephi', 9, 11, 'Then said I, Lord, how long? And he said, Until the cities be wasted without inhabitant, and the houses without man, and the land be utterly desolate,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-12', 'coc-bom-1908', 'II Nephi', 9, 12, 'And the Lord have removed men far away, for there shall be a great forsaking in the midst of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-14', 'coc-bom-1908', 'II Nephi', 9, 14, 'And it came to pass in the days of Ahaz, the son of Jotham, the son of Uzziah, king of Judah, that Rezin, king of Syria, and Pekah, the son of Remaliah, king of Israel, went up towards Jerusalem to war against it, but could not prevail against it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-15', 'coc-bom-1908', 'II Nephi', 9, 15, 'And it was told the house of David, saying, Syria is confederate with Ephraim. And his heart was moved, and the heart of his people, as the trees of the wood are moved with the wind.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-16', 'coc-bom-1908', 'II Nephi', 9, 16, 'Then said the Lord unto Isaiah, Go forth now to meet Ahaz, thou and Shear-jashub, thy son, at the end of the conduit of the upper pool in the highway of the fuller''s field,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-18', 'coc-bom-1908', 'II Nephi', 9, 18, 'Because Syria, Ephraim, and the son of Remaliah have taken evil counsel against thee, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-19', 'coc-bom-1908', 'II Nephi', 9, 19, 'Let us go up against Judah and vex it, and let us make a breach therein for us and set a king in the midst of it, yea, the son of Tabeal.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-22', 'coc-bom-1908', 'II Nephi', 9, 22, 'And the head of Ephraim is Samaria, and the head of Samaria is Remaliah''s son. If ye will not believe, surely ye shall not be established.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-23', 'coc-bom-1908', 'II Nephi', 9, 23, 'Moreover, the Lord spake again unto Ahaz, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-27', 'coc-bom-1908', 'II Nephi', 9, 27, 'Therefore, the Lord himself shall give you a sign: Behold, a virgin shall conceive, and shall bear a son, and shall call his name Immanuel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-28', 'coc-bom-1908', 'II Nephi', 9, 28, 'Butter and honey shall he eat, that he may know to refuse the evil and to choose the good.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-29', 'coc-bom-1908', 'II Nephi', 9, 29, 'For before the child shall know to refuse the evil and choose the good, the land that thou abhorrest shall be forsaken of both her kings.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-30', 'coc-bom-1908', 'II Nephi', 9, 30, 'The Lord shall bring upon thee, and upon thy people, and upon thy father''s house days that have not come, from the day that Ephraim departed from Judah, the king of Assyria.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-31', 'coc-bom-1908', 'II Nephi', 9, 31, 'And it shall come to pass in that day, that the Lord shall hiss for the fly that is in the uttermost part of Egypt and for the bee that is in the land of Assyria.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-32', 'coc-bom-1908', 'II Nephi', 9, 32, 'And they shall come and shall rest, all of them in the desolate valleys, and in the holes of the rocks, and upon all thorns, and upon all bushes.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-36', 'coc-bom-1908', 'II Nephi', 9, 36, 'And it shall come to pass in that day, every place shall be, where there were a thousand vines at a thousand silverlings, which shall be for briers and thorns.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-37', 'coc-bom-1908', 'II Nephi', 9, 37, 'With arrows and with bows shall men come thither because all the land shall become briers and thorns.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-39', 'coc-bom-1908', 'II Nephi', 9, 39, 'Moreover, the word of the Lord said unto me, Take thee a great roll, and write in it with a man''s pen concerning Maher-shalal-hash-baz.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-40', 'coc-bom-1908', 'II Nephi', 9, 40, 'And I took unto me faithful witnesses to record: Uriah, the priest, and Zechariah, the son of Jeberechiah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-42', 'coc-bom-1908', 'II Nephi', 9, 42, 'For behold, the child shall not have knowledge to cry, My father and my mother, before the riches of Damascus and the spoil of Samaria shall be taken away before the king of Assyria.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-43', 'coc-bom-1908', 'II Nephi', 9, 43, 'The Lord spake also unto me again, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-44', 'coc-bom-1908', 'II Nephi', 9, 44, 'Forasmuch as this people refuseth the waters of Shiloah that go softly and rejoice in Rezin and Remaliah''s son,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-49', 'coc-bom-1908', 'II Nephi', 9, 49, 'For the Lord spake thus to me with a strong hand and instructed me that I should not walk in the way of this people, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-51', 'coc-bom-1908', 'II Nephi', 9, 51, 'Sanctify the Lord of hosts himself, and let him be your fear, and let him be your dread.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-53', 'coc-bom-1908', 'II Nephi', 9, 53, 'And many among them shall stumble, and fall, and be broken, and be snared, and be taken.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-55', 'coc-bom-1908', 'II Nephi', 9, 55, 'And I will wait upon the Lord, that hideth his face from the house of Jacob, and I will look for him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-56', 'coc-bom-1908', 'II Nephi', 9, 56, 'Behold, I and the children whom the Lord hath given me are for signs and for wonders in Israel from the Lord of hosts, which dwelleth in Mount Zion.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-57', 'coc-bom-1908', 'II Nephi', 9, 57, 'And when they shall say unto you, Seek unto them that have familiar spirits and unto wizards that peep and mutter, should not a people seek unto their God? For the living to hear from the dead?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-58', 'coc-bom-1908', 'II Nephi', 9, 58, 'To the law and to the testimony--and if they speak not according to this word, it is because there is no light in them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-60', 'coc-bom-1908', 'II Nephi', 9, 60, 'And they shall look unto the earth and behold trouble and darkness, dimness of anguish, and shall be driven to darkness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-61', 'coc-bom-1908', 'II Nephi', 9, 61, 'Nevertheless, the dimness shall not be such as was in her vexation, when at the first he lightly afflicted the land of Zebulun, and the land of Naphtali, and afterward did more grievously afflict by the way of the Red Sea beyond Jordan in Galilee of the nations.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-64', 'coc-bom-1908', 'II Nephi', 9, 64, 'For thou hast broken the yoke of his burden and the staff of his shoulder, the rod of his oppressor,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-67', 'coc-bom-1908', 'II Nephi', 9, 67, 'Of the increase of government and peace there is no end, upon the throne of David, and upon his kingdom, to order it and to establish it with judgment and with justice from henceforth, even forever. The zeal of the Lord of hosts will perform this.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-68', 'coc-bom-1908', 'II Nephi', 9, 68, 'The Lord sent his word unto Jacob, and it hath lighted upon Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-69', 'coc-bom-1908', 'II Nephi', 9, 69, 'And all the people shall know, even Ephraim and the inhabitants of Samaria, that say in the pride and stoutness of heart,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-71', 'coc-bom-1908', 'II Nephi', 9, 71, 'Therefore, the Lord shall set up the adversaries of Rezin against him and join his enemies together,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-73', 'coc-bom-1908', 'II Nephi', 9, 73, 'For the people turneth not unto him that smiteth them, neither do they seek the Lord of hosts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-74', 'coc-bom-1908', 'II Nephi', 9, 74, 'Therefore will the Lord cut off from Israel head and tail, branch and rush, in one day.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-82', 'coc-bom-1908', 'II Nephi', 9, 82, 'Wo unto them that decree unrighteous decrees and that write grievousness which they have prescribed,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-83', 'coc-bom-1908', 'II Nephi', 9, 83, 'To turn aside the needy from judgment and to take away the right from the poor of my people, that widows may be their prey and that they may rob the fatherless.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-84', 'coc-bom-1908', 'II Nephi', 9, 84, 'And what will ye do in the day of visitation and in the desolation which shall come from far? To whom will ye flee for help? And where will ye leave your glory?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-85', 'coc-bom-1908', 'II Nephi', 9, 85, 'Without me they shall bow down under the prisoners, and they shall fall under the slain. For all this, his anger is not turned away, but his hand is stretched out still.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-86', 'coc-bom-1908', 'II Nephi', 9, 86, 'O Assyrian, the rod of mine anger and the staff in their hand is their indignation.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-87', 'coc-bom-1908', 'II Nephi', 9, 87, 'I will send him against a hypocritical nation, and against the people of my wrath will I give him a charge, to take the spoil, and to take the prey, and to tread them down like the mire of the streets.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-89', 'coc-bom-1908', 'II Nephi', 9, 89, 'For he saith, Are not my princes altogether kings?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-90', 'coc-bom-1908', 'II Nephi', 9, 90, 'Is not Calno as Carchemish? Is not Hamath as Arpad? Is not Samaria as Damascus?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-91', 'coc-bom-1908', 'II Nephi', 9, 91, 'As my hand hath founded the kingdoms of the idols, and whose graven images did excel them of Jerusalem and of Samaria,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-92', 'coc-bom-1908', 'II Nephi', 9, 92, 'Shall I not, as I have done unto Samaria and her idols, so do to Jerusalem and to her idols?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-93', 'coc-bom-1908', 'II Nephi', 9, 93, 'Wherefore, it shall come to pass, that when the Lord hath performed his whole work upon Mount Zion and upon Jerusalem, I will punish the fruit of the stout heart of the king of Assyria and the glory of his high looks.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-96', 'coc-bom-1908', 'II Nephi', 9, 96, 'Shall the axe boast itself against him that heweth therewith? Shall the saw magnify itself against him that shaketh it? as if the rod should shake itself against them that lift it up, or as if the staff should lift up itself, as if it were no wood.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-98', 'coc-bom-1908', 'II Nephi', 9, 98, 'And the light of Israel shall be for a fire, and his Holy One for a flame, and it shall burn and shall devour his thorns and his briers in one day,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-100', 'coc-bom-1908', 'II Nephi', 9, 100, 'And the rest of the trees of his forest shall be few, that a child may write them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-101', 'coc-bom-1908', 'II Nephi', 9, 101, 'And it shall come to pass in that day that the remnant of Israel and such as are escaped of the house of Jacob shall no more again stay upon him that smote them, but shall stay upon the Lord, the Holy One of Israel, in truth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-102', 'coc-bom-1908', 'II Nephi', 9, 102, 'The remnant shall return, yea, even the remnant of Jacob, unto the mighty God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-104', 'coc-bom-1908', 'II Nephi', 9, 104, 'For the Lord God of hosts shall make a consumption, even determined, in all the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-106', 'coc-bom-1908', 'II Nephi', 9, 106, 'For yet a very little while, and the indignation shall cease, and mine anger in their destruction.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-108', 'coc-bom-1908', 'II Nephi', 9, 108, 'And it shall come to pass in that day, that his burden shall be taken away from off thy shoulder, and his yoke from off thy neck, and the yoke shall be destroyed because of the anointing.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-115', 'coc-bom-1908', 'II Nephi', 9, 115, 'And he shall cut down the thickets of the forest with iron, and Lebanon shall fall by a mighty one.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-117', 'coc-bom-1908', 'II Nephi', 9, 117, 'And the Spirit of the Lord shall rest upon him, the spirit of wisdom and understanding, the spirit of counsel and might, the spirit of knowledge and of the fear of the Lord,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-120', 'coc-bom-1908', 'II Nephi', 9, 120, 'And righteousness shall be the girdle of his loins, and faithfulness the girdle of his reins.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-123', 'coc-bom-1908', 'II Nephi', 9, 123, 'And the sucking child shall play on the hole of the asp, and the weaned child shall put his hand on the cockatrice den.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-126', 'coc-bom-1908', 'II Nephi', 9, 126, 'And it shall come to pass in that day, that the Lord shall set his hand again the second time to recover the remnant of his people, which shall be left from Assyria, and from Egypt, and from Pathros, and from Cush, and from Elam, and from Shinar, and from Hamath, and from the islands of the sea.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-127', 'coc-bom-1908', 'II Nephi', 9, 127, 'And he shall set up an ensign for the nations, and shall assemble the outcasts of Israel, and gather together the dispersed of Judah from the four corners of the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-131', 'coc-bom-1908', 'II Nephi', 9, 131, 'And there shall be a highway for the remnant of his people which shall be left from Assyria, like as it was to Israel in the day that he came up out of the land of Egypt.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-9-134', 'coc-bom-1908', 'II Nephi', 9, 134, 'Therefore, with joy shall ye draw water out of the wells of salvation.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-1', 'coc-bom-1908', 'II Nephi', 10, 1, 'The burden of Babylon, which Isaiah, the son of Amoz, did see:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-4', 'coc-bom-1908', 'II Nephi', 10, 4, 'The noise of the multitude in the mountains like as of a great people, a tumultuous noise of the kingdoms of nations gathered together--the Lord of hosts mustereth the hosts of the battle.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-5', 'coc-bom-1908', 'II Nephi', 10, 5, 'They come from a far country, from the end of heaven, yea, the Lord and the weapons of his indignation, to destroy the whole land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-12', 'coc-bom-1908', 'II Nephi', 10, 12, 'I will make a man more precious than fine gold, even a man than the golden wedge of Ophir.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-13', 'coc-bom-1908', 'II Nephi', 10, 13, 'Therefore, I will shake the heavens, and the earth shall remove out of her place, in the wrath of the Lord of hosts and in the day of his fierce anger.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-17', 'coc-bom-1908', 'II Nephi', 10, 17, 'Behold, I will stir up the Medes against them, which shall not regard silver and gold, nor they shall not delight in it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-19', 'coc-bom-1908', 'II Nephi', 10, 19, 'And Babylon, the glory of kingdoms, the beauty of the Chaldees'' excellency, shall be as when God overthrew Sodom and Gomorrah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-25', 'coc-bom-1908', 'II Nephi', 10, 25, 'And it shall come to pass in that day, that the Lord shall give thee rest from thy sorrow, and from thy fear, and from the hard bondage wherein thou wast made to serve.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-26', 'coc-bom-1908', 'II Nephi', 10, 26, 'And it shall come to pass in that day, that thou shalt take up this proverb against the king of Babylon and say, How hath the oppressor ceased, the golden city ceased!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-27', 'coc-bom-1908', 'II Nephi', 10, 27, 'The Lord hath broken the staff of the wicked, the scepters of the rulers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-28', 'coc-bom-1908', 'II Nephi', 10, 28, 'He who smote the people in wrath with a continual stroke, he that ruled the nations in anger, is persecuted, and none hindereth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-30', 'coc-bom-1908', 'II Nephi', 10, 30, 'Yea, the fir trees rejoice at thee, and also the cedars of Lebanon, saying, Since thou art laid down, no feller is come up against us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-32', 'coc-bom-1908', 'II Nephi', 10, 32, 'All they shall speak and say unto thee, Art thou also become weak as we? Art thou become like unto us?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-34', 'coc-bom-1908', 'II Nephi', 10, 34, 'How art thou fallen from heaven, O Lucifer, son of the morning! Art thou cut down to the ground, which did weaken the nations!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-37', 'coc-bom-1908', 'II Nephi', 10, 37, 'Yet thou shalt be brought down to hell, to the sides of the pit.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-38', 'coc-bom-1908', 'II Nephi', 10, 38, 'They that see thee shall narrowly look upon thee, and shall consider thee, and shall say, Is this the man that made the earth to tremble, that did shake kingdoms,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-39', 'coc-bom-1908', 'II Nephi', 10, 39, 'And made the world as a wilderness, and destroyed the cities thereof, and opened not the house of his prisoners?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-40', 'coc-bom-1908', 'II Nephi', 10, 40, 'All the kings of the nations, yea, all of them, lie in glory, every one of them in his own house.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-41', 'coc-bom-1908', 'II Nephi', 10, 41, 'But thou art cast out of thy grave like an abominable branch and the remnant of those that are slain, thrust through with a sword, that go down to the stones of the pit as a carcass trodden underfoot.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-43', 'coc-bom-1908', 'II Nephi', 10, 43, 'Prepare slaughter for his children for the iniquities of their fathers, that they do not rise, nor possess the land, nor fill the face of the world with cities.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-44', 'coc-bom-1908', 'II Nephi', 10, 44, 'For I will rise up against them, saith the Lord of hosts, and cut off from Babylon the name, and remnant, and son, and nephew, saith the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-49', 'coc-bom-1908', 'II Nephi', 10, 49, 'For the Lord of hosts hath purposed. And who shall disannul? And his hand stretched out. And who shall turn it back?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-50', 'coc-bom-1908', 'II Nephi', 10, 50, 'In the year that King Ahaz died was this burden.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-10-54', 'coc-bom-1908', 'II Nephi', 10, 54, 'What shall then answer the messengers of the nations? That the Lord hath founded Zion, and the poor of his people shall trust in it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-1', 'coc-bom-1908', 'II Nephi', 11, 1, 'Now I, Nephi, do speak somewhat concerning the words which I have written, which have been spoken by the mouth of Isaiah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-4', 'coc-bom-1908', 'II Nephi', 11, 4, 'Wherefore, I write unto my people, unto all those that shall receive hereafter these things which I write, that they may know the judgments of God--that they come upon all nations, according to the word which he hath spoken.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-16', 'coc-bom-1908', 'II Nephi', 11, 16, 'And never hath any of them been destroyed, save it were foretold them by the prophets of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-19', 'coc-bom-1908', 'II Nephi', 11, 19, 'And now, this I speak because of the spirit which is in me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-26', 'coc-bom-1908', 'II Nephi', 11, 26, 'And after they have been scattered, and the Lord God hath scourged them by other nations for the space of many generations, yea, even down from generation to generation, until they shall be persuaded to believe in Christ, the Son of God, and the atonement, which is infinite for all mankind--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-28', 'coc-bom-1908', 'II Nephi', 11, 28, 'And the Lord will set his hand again the second time to restore his people from their lost and fallen state.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-29', 'coc-bom-1908', 'II Nephi', 11, 29, 'Wherefore, he will proceed to do a marvelous work and a wonder among the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-31', 'coc-bom-1908', 'II Nephi', 11, 31, 'For they shall be given them for the purpose of convincing them of the true Messiah, who was rejected by them,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-32', 'coc-bom-1908', 'II Nephi', 11, 32, 'And unto the convincing of them that they need not look forward any more for a Messiah to come,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-34', 'coc-bom-1908', 'II Nephi', 11, 34, 'For there is save one Messiah spoken of by the prophets, and that Messiah is he who should be rejected of the Jews.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-36', 'coc-bom-1908', 'II Nephi', 11, 36, 'And according to the words of the prophets, and also the word of the angel of God, his name shall be Jesus Christ, the Son of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-37', 'coc-bom-1908', 'II Nephi', 11, 37, 'And now, my brethren, I have spoken plain, that ye cannot err.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-38', 'coc-bom-1908', 'II Nephi', 11, 38, 'And as the Lord God liveth--that brought Israel up out of the land of Egypt, and gave unto Moses power that he should heal the nations, after they had been bitten by the poisonous serpents, if they would cast their eyes unto the serpent which he did raise up before them, and also gave him power that he should smite the rock, and the water should come forth--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-39', 'coc-bom-1908', 'II Nephi', 11, 39, 'Yea, behold, I say unto you that as these things are true. And as the Lord God liveth, there is none other name given under heaven, save it be this Jesus Christ of which I have spoken, whereby man can be saved.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-40', 'coc-bom-1908', 'II Nephi', 11, 40, 'Wherefore, for this cause hath the Lord God promised unto me that these things which I write shall be kept, and preserved, and handed down unto my seed from generation to generation, that the promise may be fulfilled unto Joseph, that his seed should never perish as long as the earth should stand.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-42', 'coc-bom-1908', 'II Nephi', 11, 42, 'And the nations which shall possess them shall be judged of them according to the words which are written.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-44', 'coc-bom-1908', 'II Nephi', 11, 44, 'For we know that it is by grace that we are saved, after all we can do.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-47', 'coc-bom-1908', 'II Nephi', 11, 47, 'Yet we keep the law because of the commandments.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-50', 'coc-bom-1908', 'II Nephi', 11, 50, 'And they, by knowing the deadness of the law, may look forward unto that life which is in Christ and know for what end the law was given,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-51', 'coc-bom-1908', 'II Nephi', 11, 51, 'And after the law is fulfilled in Christ, that they need not harden their hearts against him when the law ought to be done away.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-57', 'coc-bom-1908', 'II Nephi', 11, 57, 'And inasmuch as it shall be expedient, ye must keep the performances and ordinances of God until the law shall be fulfilled which was given unto Moses.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-59', 'coc-bom-1908', 'II Nephi', 11, 59, 'And the words which he shall speak unto you shall be the law which ye shall do.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-60', 'coc-bom-1908', 'II Nephi', 11, 60, 'For behold, I say unto you that I have beheld that many generations shall pass away, and there shall be great wars and contentions among my people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-64', 'coc-bom-1908', 'II Nephi', 11, 64, 'Wherefore, the cry of the blood of the saints shall ascend up to God from the ground against them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-65', 'coc-bom-1908', 'II Nephi', 11, 65, 'Wherefore, all those who are proud and that do wickedly, the day that cometh shall burn them up, saith the Lord of hosts, for they shall be as stubble.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-70', 'coc-bom-1908', 'II Nephi', 11, 70, 'Oh, the pain and the anguish of my soul for the loss of the slain of my people!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-72', 'coc-bom-1908', 'II Nephi', 11, 72, 'But behold, the righteous--that hearken unto the words of the prophets, and destroy them not, but look forward unto Christ with steadfastness for the signs which are given, notwithstanding all persecutions--behold, they are they which shall not perish.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-78', 'coc-bom-1908', 'II Nephi', 11, 78, 'And as I spake concerning the convincing of the Jews that Jesus is the very Christ, it must needs be that the Gentiles be convinced also that Jesus is the Christ, the Eternal God, and that he manifesteth himself unto all those who believe in him, by the power of the Holy Ghost,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-79', 'coc-bom-1908', 'II Nephi', 11, 79, 'Yea, unto every nation, kindred, tongue, and people--working mighty miracles, signs, and wonders among the children of men according to their faith.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-80', 'coc-bom-1908', 'II Nephi', 11, 80, 'But behold, I prophesy unto you concerning the last days, concerning the days when the Lord God shall bring these things forth unto the children of men,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-81', 'coc-bom-1908', 'II Nephi', 11, 81, 'After my seed and the seed of my brethren shall have dwindled in unbelief and shall have been smitten by the Gentiles,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-82', 'coc-bom-1908', 'II Nephi', 11, 82, 'Yea, after the Lord God shall have camped against them round about, and shall have laid siege against them with a mount, and raised forts against them,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-83', 'coc-bom-1908', 'II Nephi', 11, 83, 'And after they shall have been brought down low in the dust, even that they are not. Yet the words of the righteous shall be written, and the prayers of the faithful shall be heard, and all those who have dwindled in unbelief shall not be forgotten.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-87', 'coc-bom-1908', 'II Nephi', 11, 87, 'Wherefore, as those who have been destroyed have been destroyed speedily, and the multitude of their terrible ones shall be as chaff that passeth away,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-88', 'coc-bom-1908', 'II Nephi', 11, 88, 'Yea, thus saith the Lord God, It shall be at an instant, suddenly.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-89', 'coc-bom-1908', 'II Nephi', 11, 89, 'And it shall come to pass, that those who have dwindled in unbelief shall be smitten by the hand of the Gentiles.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-91', 'coc-bom-1908', 'II Nephi', 11, 91, 'Nevertheless, they put down the power and the miracles of God and preach up unto themselves their own wisdom and their own learning, that they may get gain and grind upon the face of the poor.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-94', 'coc-bom-1908', 'II Nephi', 11, 94, 'Yea, and he leadeth them by the neck with a flaxen cord until he bindeth them with his strong cords forever.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-95', 'coc-bom-1908', 'II Nephi', 11, 95, 'For behold, my beloved brethren, I say unto you that the Lord God worketh not in darkness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-97', 'coc-bom-1908', 'II Nephi', 11, 97, 'Wherefore, he commandeth none that they shall not partake of his salvation.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-98', 'coc-bom-1908', 'II Nephi', 11, 98, 'Behold, doth he cry unto any, saying, Depart from me?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-100', 'coc-bom-1908', 'II Nephi', 11, 100, 'Behold, hath he commanded any that they should depart out of the synagogues or out of the houses of worship?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-101', 'coc-bom-1908', 'II Nephi', 11, 101, 'Behold, I say unto you, Nay.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-102', 'coc-bom-1908', 'II Nephi', 11, 102, 'Hath he commanded any that they should not partake of his salvation?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-104', 'coc-bom-1908', 'II Nephi', 11, 104, 'Behold, hath the Lord commanded any that they should not partake of his goodness?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-110', 'coc-bom-1908', 'II Nephi', 11, 110, 'And, again, the Lord God hath commanded that men should not murder, that they should not lie, that they should not steal, that they should not take the name of the Lord, their God, in vain, that they should not envy, that they should not have malice, that they should not contend one with another, that they should not commit whoredoms, and that they should do none of these things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-116', 'coc-bom-1908', 'II Nephi', 11, 116, 'But behold, in the last days, or in the days of the Gentiles, yea, behold, all the nations of the Gentiles and also the Jews, both those who shall come upon this land and those who shall be upon other lands, yea, even upon all the lands of the earth, behold, they will be drunken with iniquity and all manner of abominations.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-117', 'coc-bom-1908', 'II Nephi', 11, 117, 'And when that day shall come, they shall be visited of the Lord of hosts with thunder, and with earthquake, and with a great noise, and with storm, and with tempest, and with the flame of devouring fire.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-121', 'coc-bom-1908', 'II Nephi', 11, 121, 'Yea, even so shall the multitude of all the nations be that fight against Mount Zion.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-125', 'coc-bom-1908', 'II Nephi', 11, 125, 'And it shall come to pass that the Lord God shall bring forth unto you the words of a book, and they shall be the words of them which have slumbered.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-127', 'coc-bom-1908', 'II Nephi', 11, 127, 'Wherefore, because of the things which are sealed up, the things which are sealed shall not be delivered in the day of the wickedness and abominations of the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-128', 'coc-bom-1908', 'II Nephi', 11, 128, 'Wherefore, the book shall be kept from them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-132', 'coc-bom-1908', 'II Nephi', 11, 132, 'And all things shall be revealed unto the children of men which ever have been among the children of men and which ever will be, even unto the end of the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-136', 'coc-bom-1908', 'II Nephi', 11, 136, 'But behold, it shall come to pass that the Lord God shall say unto him to whom he shall deliver the book, Take these words which are not sealed and deliver them to another, that he may show them unto the learned, saying, Read this, I pray thee.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-137', 'coc-bom-1908', 'II Nephi', 11, 137, 'And the learned shall say, Bring hither the book, and I will read them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-138', 'coc-bom-1908', 'II Nephi', 11, 138, 'And now, because of the glory of the world and to get gain, will they say this, and not for the glory of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-139', 'coc-bom-1908', 'II Nephi', 11, 139, 'And the man shall say, I cannot bring the book, for it is sealed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-140', 'coc-bom-1908', 'II Nephi', 11, 140, 'Then shall the learned say, I cannot read it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-144', 'coc-bom-1908', 'II Nephi', 11, 144, 'Wherefore, when thou hast read the words which I have commanded thee and obtained the witnesses which I have promised unto thee, then shalt thou seal up the book again and hide it up unto me, that I may preserve the words which thou hast not read, until I shall see fit in mine own wisdom to reveal all things unto the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-146', 'coc-bom-1908', 'II Nephi', 11, 146, 'And again, it shall come to pass, that the Lord shall say unto him that shall read the words that shall be delivered him, Forasmuch as this people draw near unto me with their mouth and with their lips do honor me, but have removed their hearts far from me, and their fear towards me is taught by the precepts of men, therefore, I will proceed to do a marvelous work among this people,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-147', 'coc-bom-1908', 'II Nephi', 11, 147, 'Yea, a marvelous work and a wonder, for the wisdom of their wise and learned shall perish, and the understanding of their prudent shall be hid.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-148', 'coc-bom-1908', 'II Nephi', 11, 148, 'And wo unto them that seek deep to hide their counsel from the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-149', 'coc-bom-1908', 'II Nephi', 11, 149, 'And their works are in the dark. And they say, Who seeth us, and who knoweth us?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-150', 'coc-bom-1908', 'II Nephi', 11, 150, 'And they also say, Surely, your turning of things upside down shall be esteemed as the potter''s clay.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-151', 'coc-bom-1908', 'II Nephi', 11, 151, 'But behold, I will show unto them, saith the Lord of hosts, that I know all their works.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-152', 'coc-bom-1908', 'II Nephi', 11, 152, 'For shall the work say of him that made it, He made me not?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-153', 'coc-bom-1908', 'II Nephi', 11, 153, 'Or shall the thing framed say of him that framed it, He had no understanding?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-157', 'coc-bom-1908', 'II Nephi', 11, 157, 'For assuredly, as the Lord liveth, they shall see that the terrible one is brought to naught, and the scorner is consumed, and all that watch for iniquity are cut off--and they that make a man an offender for a word, and lay a snare for him that reproveth in the gate, and turn aside the just for a thing of naught.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-158', 'coc-bom-1908', 'II Nephi', 11, 158, 'Therefore, thus saith the Lord, who redeemed Abraham, concerning the house of Jacob: Jacob shall not now be ashamed, neither shall his face now wax pale.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-159', 'coc-bom-1908', 'II Nephi', 11, 159, 'But when he seeth his children, the work of my hands, in the midst of him, they shall sanctify my name, and sanctify the Holy One of Jacob, and shall fear the God of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-11-160', 'coc-bom-1908', 'II Nephi', 11, 160, 'They also that erred in spirit shall come to understanding, and they that murmured shall learn doctrine.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-2', 'coc-bom-1908', 'II Nephi', 12, 2, 'And the things which shall be written out of the book shall be of great worth unto the children of men, and especially unto our seed, which is a remnant of the house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-17', 'coc-bom-1908', 'II Nephi', 12, 17, 'Nevertheless, they are led, that in many instances they do err, because they are taught by the precepts of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-18', 'coc-bom-1908', 'II Nephi', 12, 18, 'Oh, the wise, and the learned, and the rich, that are puffed up in the pride of their hearts, and all those who preach false doctrines, and all those who commit whoredoms and pervert the right way of the Lord--Wo, wo, wo be unto them, saith the Lord God Almighty, for they shall be thrust down to hell.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-21', 'coc-bom-1908', 'II Nephi', 12, 21, 'But behold, if the inhabitants of the earth shall repent of their wickedness and abominations, they shall not be destroyed, saith the Lord of hosts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-23', 'coc-bom-1908', 'II Nephi', 12, 23, 'For the kingdom of the devil must shake, and they which belong to it must needs be stirred up unto repentance, or the devil will grasp them with his everlasting chains, and they be stirred up to anger and perish.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-26', 'coc-bom-1908', 'II Nephi', 12, 26, 'And thus the devil cheateth their souls and leadeth them away carefully down to hell.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-28', 'coc-bom-1908', 'II Nephi', 12, 28, 'And thus he whispereth in their ears until he grasps them with his awful chains from whence there is no deliverance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-30', 'coc-bom-1908', 'II Nephi', 12, 30, 'Therefore, wo be unto him that is at ease in Zion.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-32', 'coc-bom-1908', 'II Nephi', 12, 32, 'Yea, wo be unto him that saith, We have received, and we need no more.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-33', 'coc-bom-1908', 'II Nephi', 12, 33, 'And, in fine, wo unto all those who tremble and are angry because of the truth of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-35', 'coc-bom-1908', 'II Nephi', 12, 35, 'Wo be unto him that shall say, We have received the word of God, and we need no more of the word of God, for we have enough.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-39', 'coc-bom-1908', 'II Nephi', 12, 39, 'Cursed is he that putteth his trust in man, or maketh flesh his arm, or shall hearken unto the precepts of men, save their precepts shall be given by the power of the Holy Ghost.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-43', 'coc-bom-1908', 'II Nephi', 12, 43, 'And also, that I may remember the promises which I have made unto thee, Nephi, and also unto thy father, that I would remember your seed and that the words of your seed should proceed forth out of my mouth unto your seed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-44', 'coc-bom-1908', 'II Nephi', 12, 44, 'And my words shall hiss forth unto the ends of the earth for a standard unto my people which are of the house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-47', 'coc-bom-1908', 'II Nephi', 12, 47, 'And what thank they the Jews for the bible which they received from them?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-48', 'coc-bom-1908', 'II Nephi', 12, 48, 'Yea, what do the Gentiles mean?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-49', 'coc-bom-1908', 'II Nephi', 12, 49, 'Do they remember the travails, and the labors, and the pains of the Jews, and their diligence unto me in bringing forth salvation unto the Gentiles?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-50', 'coc-bom-1908', 'II Nephi', 12, 50, 'O ye Gentiles, have ye remembered the Jews, mine ancient covenant people?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-54', 'coc-bom-1908', 'II Nephi', 12, 54, 'Have ye obtained a bible, save it were by the Jews?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-55', 'coc-bom-1908', 'II Nephi', 12, 55, 'Know ye not that there are more nations than one?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-57', 'coc-bom-1908', 'II Nephi', 12, 57, 'And I bring forth my word unto the children of men, yea, even upon all the nations of the earth?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-58', 'coc-bom-1908', 'II Nephi', 12, 58, 'Wherefore murmur ye because that ye shall receive more of my word?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-59', 'coc-bom-1908', 'II Nephi', 12, 59, 'Know ye not that the testimony of two nations is a witness unto you that I am God, that I remember one nation like unto another?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-60', 'coc-bom-1908', 'II Nephi', 12, 60, 'Wherefore, I speak the same words unto one nation like unto another.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-61', 'coc-bom-1908', 'II Nephi', 12, 61, 'And when the two nations shall run together, the testimony of the two nations shall run together also.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-62', 'coc-bom-1908', 'II Nephi', 12, 62, 'And I do this that I may prove unto many that I am the same yesterday, today, and forever, and that I speak forth my words according to mine own pleasure.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-66', 'coc-bom-1908', 'II Nephi', 12, 66, 'For out of the books which shall be written, I will judge the world--every man according to his works, according to that which is written.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-70', 'coc-bom-1908', 'II Nephi', 12, 70, 'And I shall also speak unto all nations of the earth, and they shall write it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-74', 'coc-bom-1908', 'II Nephi', 12, 74, 'And I will show unto them that fight against my word and against my people, who are of the house of Israel, that I am God and that I covenanted with Abraham that I would remember his seed forever.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-78', 'coc-bom-1908', 'II Nephi', 12, 78, 'For the Lord covenanteth with none, save it be with them that repent and believe in his Son, who is the Holy One of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-79', 'coc-bom-1908', 'II Nephi', 12, 79, 'And now, I would prophesy somewhat more concerning the Jews and the Gentiles.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-81', 'coc-bom-1908', 'II Nephi', 12, 81, 'And then shall the remnant of our seed know concerning us, how that we came out from Jerusalem and that they are descendants of the Jews.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-86', 'coc-bom-1908', 'II Nephi', 12, 86, 'And as many as shall believe in Christ shall also become a delightsome people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-87', 'coc-bom-1908', 'II Nephi', 12, 87, 'And it shall come to pass that the Lord God shall commence his work among all nations, kindreds, tongues, and people, to bring about the restoration of his people upon the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-88', 'coc-bom-1908', 'II Nephi', 12, 88, 'And with righteousness shall the Lord God judge the poor and reprove with equity, for the meek of the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-91', 'coc-bom-1908', 'II Nephi', 12, 91, 'And righteousness shall be the girdle of his loins, and faithfulness the girdle of his reins.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-94', 'coc-bom-1908', 'II Nephi', 12, 94, 'And the sucking child shall play on the hole of the asp, and the weaned child shall put his hand on the cockatrice den.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-99', 'coc-bom-1908', 'II Nephi', 12, 99, 'And Satan shall have power over the hearts of the children of men no more, for a long time.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-12-100', 'coc-bom-1908', 'II Nephi', 12, 100, 'And now, my beloved brethren, I must make an end of my sayings.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-13-1', 'coc-bom-1908', 'II Nephi', 13, 1, 'And now, I, Nephi, make an end of my prophesying unto you, my beloved brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-13-6', 'coc-bom-1908', 'II Nephi', 13, 6, 'Wherefore, I would that ye should remember that I have spoken unto you concerning that prophet, which the Lord showed unto me, that should baptize the Lamb of God, which should take away the sin of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-13-7', 'coc-bom-1908', 'II Nephi', 13, 7, 'And now, if the Lamb of God, he being holy, should have need to be baptized by water to fulfill all righteousness, Oh, then, how much more need have we, being unholy, to be baptized, yea, even by water.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-13-8', 'coc-bom-1908', 'II Nephi', 13, 8, 'And now, I would ask of you, my beloved brethren, wherein the Lamb of God did fulfill all righteousness in being baptized by water. Know ye not that he was holy?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-13-10', 'coc-bom-1908', 'II Nephi', 13, 10, 'Wherefore, after he was baptized with water, the Holy Ghost descended upon him in the form of a dove.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-13-11', 'coc-bom-1908', 'II Nephi', 13, 11, 'And again, it showeth unto the children of men the straightness of the path and the narrowness of the gate by which they should enter, he having set the example before them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-13-12', 'coc-bom-1908', 'II Nephi', 13, 12, 'And he said unto the children of men, Follow thou me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-13-13', 'coc-bom-1908', 'II Nephi', 13, 13, 'Wherefore, my beloved brethren, can we follow Jesus, save we shall be willing to keep the commandments of the Father?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-13-14', 'coc-bom-1908', 'II Nephi', 13, 14, 'And the Father said, Repent ye, repent ye, and be baptized in the name of my beloved Son.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-13-18', 'coc-bom-1908', 'II Nephi', 13, 18, 'But behold, my beloved brethren, thus came the voice of the Son unto me, saying, After ye have repented of your sins, and witnessed unto the Father that ye are willing to keep my commandments, by the baptism of water, and have received the baptism of fire and of the Holy Ghost, and can speak with a new tongue, yea, even with the tongue of angels, and after this should deny me, it would have been better for you that ye had not known me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-13-19', 'coc-bom-1908', 'II Nephi', 13, 19, 'And I heard a voice from the Father, saying, Yea, the words of my beloved are true and faithful.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-13-20', 'coc-bom-1908', 'II Nephi', 13, 20, 'He that endureth to the end, the same shall be saved.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-13-23', 'coc-bom-1908', 'II Nephi', 13, 23, 'For, for this cause have they been shown unto me, that ye might know the gate by which ye should enter.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-13-26', 'coc-bom-1908', 'II Nephi', 13, 26, 'And ye have received the Holy Ghost, which witnesses of the Father and the Son, unto the fulfilling of the promise which he hath made, that if ye enter in by the way, ye should receive.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-13-27', 'coc-bom-1908', 'II Nephi', 13, 27, 'And now, my beloved brethren, after ye have gotten into this straight and narrow path, I would ask if all is done.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-13-29', 'coc-bom-1908', 'II Nephi', 13, 29, 'Wherefore, ye must press forward with a steadfastness in Christ, having a perfect brightness of hope and a love of God and of all men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-13-30', 'coc-bom-1908', 'II Nephi', 13, 30, 'Wherefore, if ye shall press forward, feasting upon the word of Christ, and endure to the end, behold, thus saith the Father, Ye shall have eternal life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-13-32', 'coc-bom-1908', 'II Nephi', 13, 32, 'And now, behold, this is the doctrine of Christ and the only and true doctrine of the Father, and of the Son, and of the Holy Ghost, which is one God, without end. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-14-1', 'coc-bom-1908', 'II Nephi', 14, 1, 'And now, behold, my beloved brethren, I suppose that ye ponder somewhat in your hearts concerning that which ye should do after ye have entered in by the way.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-14-2', 'coc-bom-1908', 'II Nephi', 14, 2, 'But behold, why do ye ponder these things in your hearts? Do ye not remember that I said unto you that after ye had received the Holy Ghost, ye could speak with the tongue of angels?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-14-6', 'coc-bom-1908', 'II Nephi', 14, 6, 'For behold, again I say unto you that if ye will enter in by the way and receive the Holy Ghost, it will show unto you all things what ye should do.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-14-8', 'coc-bom-1908', 'II Nephi', 14, 8, 'And when he shall manifest himself unto you in the flesh, the things which he shall say unto you shall ye observe to do.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-14-12', 'coc-bom-1908', 'II Nephi', 14, 12, 'But behold, I say unto you that ye must pray always and not faint, that ye must not perform anything unto the Lord, save in the first place ye shall pray unto the Father in the name of Christ that he will consecrate thy performance unto thee, that thy performance may be for the welfare of thy soul.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-15-8', 'coc-bom-1908', 'II Nephi', 15, 8, 'I have charity for my people and great faith in Christ, that I shall meet many souls spotless at his judgment seat.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-15-10', 'coc-bom-1908', 'II Nephi', 15, 10, 'But behold, for none of these can I hope, except they shall be reconciled unto Christ, and enter into the narrow gate, and walk in the straight path which leads to life, and continue in the path until the end of the day of probation.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-15-15', 'coc-bom-1908', 'II Nephi', 15, 15, 'And I pray the Father in the name of Christ that many of us, if not all, may be saved in his kingdom at that great and last day.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ii-nephi-15-16', 'coc-bom-1908', 'II Nephi', 15, 16, 'And now, my beloved brethren, all those who are of the house of Israel and all ye ends of the earth, I speak unto you, as the voice of one crying from the dust: Farewell until that great day shall come.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-5', 'coc-bom-1908', 'III Nephi', 1, 5, 'But there were some who began to say that the time was past for the words to be fulfilled which were spoken by Samuel the Lamanite.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-8', 'coc-bom-1908', 'III Nephi', 1, 8, 'But behold, they did watch steadfastly for that day and that night and that day which should be as one day, as if there were no night, that they might know that their faith had not been vain.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-9', 'coc-bom-1908', 'III Nephi', 1, 9, 'Now it came to pass that there was a day set apart by the unbelievers that all those who believed in those traditions should be put to death, except the sign should come to pass which had been given by Samuel the prophet.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-10', 'coc-bom-1908', 'III Nephi', 1, 10, 'Now it came to pass that when Nephi, the son of Nephi, saw this wickedness of his people, his heart was exceeding sorrowful.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-11', 'coc-bom-1908', 'III Nephi', 1, 11, 'And it came to pass that he went out, and bowed himself down upon the earth, and cried mightily to his God in behalf of his people, yea, those who were about to be destroyed because of their faith in the tradition of their fathers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-13', 'coc-bom-1908', 'III Nephi', 1, 13, 'And on the morrow come I into the world to show unto the world that I will fulfill all that which I have caused to be spoken by the mouth of my holy prophets.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-14', 'coc-bom-1908', 'III Nephi', 1, 14, 'Behold, I come unto my own to fulfill all things which I have made known unto the children of men, from the foundation of the world, and to do the will, both of the Father, and of the Son--of the Father because of me, and of the Son because of my flesh.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-15', 'coc-bom-1908', 'III Nephi', 1, 15, 'And behold, the time is at hand, and this night shall the sign be given.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-16', 'coc-bom-1908', 'III Nephi', 1, 16, 'And it came to pass that the words which came unto Nephi were fulfilled according as they had been spoken.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-21', 'coc-bom-1908', 'III Nephi', 1, 21, 'And it came to pass that there was no darkness in all that night, but it was as light as though it was midday.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-23', 'coc-bom-1908', 'III Nephi', 1, 23, 'And it had come to pass, yea, all things, every whit, according to the words of the prophets.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-24', 'coc-bom-1908', 'III Nephi', 1, 24, 'And it came to pass also that a new star did appear, according to the word.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-26', 'coc-bom-1908', 'III Nephi', 1, 26, 'But notwithstanding those lyings and deceivings, the more part of the people did believe and were converted unto the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-27', 'coc-bom-1908', 'III Nephi', 1, 27, 'And it came to pass that Nephi went forth among the people, and also many others, baptizing unto repentance, in the which there was a great remission of sins.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-29', 'coc-bom-1908', 'III Nephi', 1, 29, 'Now in this thing they did err, having not understood the scriptures.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-32', 'coc-bom-1908', 'III Nephi', 1, 32, 'And thus the ninety and second year did pass away, bringing glad tidings unto the people because of the signs which did come to pass, according to the words of the prophecy of all the holy prophets.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-37', 'coc-bom-1908', 'III Nephi', 1, 37, 'And thus were the Lamanites afflicted also and began to decrease as to their faith and righteousness because of the wickedness of the rising generation.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-38', 'coc-bom-1908', 'III Nephi', 1, 38, 'And it came to pass that thus passed away the ninety and fifth year also, and the people began to forget those signs and wonders which they had heard, and began to be less and less astonished at a sign or a wonder from heaven,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-40', 'coc-bom-1908', 'III Nephi', 1, 40, 'And thus did Satan get possession of the hearts of the people again, insomuch that he did blind their eyes and lead them away to believe that the doctrine of Christ was a foolish and a vain thing.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-42', 'coc-bom-1908', 'III Nephi', 1, 42, 'And Satan did go about, leading away the hearts of the people, tempting them, and causing them that they should do great wickedness in the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-46', 'coc-bom-1908', 'III Nephi', 1, 46, 'Therefore, nine years had passed away, and Nephi, who was the father of Nephi who had the charge of the records, did not return to the land of Zarahemla and could nowhere be found in all the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-49', 'coc-bom-1908', 'III Nephi', 1, 49, 'Therefore, all the Lamanites who had become converted unto the Lord did unite with their brethren, the Nephites, and were compelled for the safety of their lives, and their women, and their children to take up arms against those Gadianton robbers,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-50', 'coc-bom-1908', 'III Nephi', 1, 50, 'Yea, and also to maintain their rites, and their privileges of their church, and of their worship, and their freedom, and their liberty.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-51', 'coc-bom-1908', 'III Nephi', 1, 51, 'And it came to pass that before this thirteenth year had passed away, the Nephites were threatened with utter destruction because of this war, which had become exceeding sore.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-53', 'coc-bom-1908', 'III Nephi', 1, 53, 'And their young men and their daughters became exceeding fair, and they were numbered among the Nephites and were called Nephites. And thus ended the thirteenth year.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-1-55', 'coc-bom-1908', 'III Nephi', 1, 55, 'Nevertheless, the people of Nephi did gain some advantage of the robbers, insomuch that they did drive them back out of their lands into the mountains and into their secret places. And thus ended the fourteenth year.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-1', 'coc-bom-1908', 'III Nephi', 2, 1, 'And now, it came to pass that in the sixteenth year from the coming of Christ, Lachoneus, the governor of the land, received an epistle from the leader and the governor of this band of robbers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-3', 'coc-bom-1908', 'III Nephi', 2, 3, 'Yea, ye do stand well, as if ye were supported by the hand of a God in the defense of your liberty, and your property, and your country, or that which ye do call so.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-4', 'coc-bom-1908', 'III Nephi', 2, 4, 'And it seemeth a pity unto me, most noble Lachoneus, that ye should be so foolish and vain as to suppose that ye can stand against so many brave men who are at my command, who do now at this time stand in their arms and do await with great anxiety for the word, Go down upon the Nephites and destroy them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-8', 'coc-bom-1908', 'III Nephi', 2, 8, 'Or, in other words, yield yourselves up unto us, and unite with us, and become acquainted with our secret works, and become our brethren, that ye may be like unto us--not our slaves, but our brethren and partners of all our substance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-10', 'coc-bom-1908', 'III Nephi', 2, 10, 'And they shall not stay their hand and shall spare not, but shall slay you and shall let fall the sword upon you, yea, even until ye shall become extinct.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-13', 'coc-bom-1908', 'III Nephi', 2, 13, 'And now, it came to pass when Lachoneus received this epistle, he was exceedingly astonished because of the boldness of Giddianhi in demanding the possession of the land of the Nephites,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-14', 'coc-bom-1908', 'III Nephi', 2, 14, 'And also of threatening the people, and avenging the wrongs of those that had received no wrong, save it were they had wronged themselves by dissenting away unto those wicked and abominable robbers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-17', 'coc-bom-1908', 'III Nephi', 2, 17, 'Yea, he sent a proclamation among all the people that they should gather together their women and their children, their flocks and their herds, and all their substance, save it were their land, unto one place.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-18', 'coc-bom-1908', 'III Nephi', 2, 18, 'And he caused that fortifications should be built round about them, and the strength thereof should be exceeding great.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-20', 'coc-bom-1908', 'III Nephi', 2, 20, 'Yea, he said unto them, As the Lord liveth, except ye repent of all your iniquities and cry unto the Lord, that ye can in no wise be delivered out of the hands of those Gadianton robbers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-22', 'coc-bom-1908', 'III Nephi', 2, 22, 'And it came to pass that Lachoneus did appoint chief captains over all the armies of the Nephites, to command them at the time that the robbers should come down out of the wilderness against them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-23', 'coc-bom-1908', 'III Nephi', 2, 23, 'Now the chiefest among all the chief captains, and the great commander of all the armies of the Nephites, was appointed, and his name was Gidgiddoni.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-25', 'coc-bom-1908', 'III Nephi', 2, 25, 'Now the people said unto Gidgiddoni, Pray unto the Lord, and let us go up upon the mountains and into the wilderness, that we may fall upon the robbers and destroy them in their own lands.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-28', 'coc-bom-1908', 'III Nephi', 2, 28, 'Therefore, as the Lord liveth, if we do this, he will deliver them into our hands.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-30', 'coc-bom-1908', 'III Nephi', 2, 30, 'And they had taken their horses, and their chariots, and their cattle, and all their flocks, and their herds, and their grain, and all their substance,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-31', 'coc-bom-1908', 'III Nephi', 2, 31, 'And did march forth by thousands and by tens of thousands until they had all gone forth to the place which had been appointed, that they should gather themselves together to defend themselves against their enemies.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-33', 'coc-bom-1908', 'III Nephi', 2, 33, 'And there were a great many thousand people who were called Nephites who did gather themselves together in this land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-36', 'coc-bom-1908', 'III Nephi', 2, 36, 'And they did put up their prayers unto the Lord, their God, that he would deliver them in the time that their enemies should come down against them to battle.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-37', 'coc-bom-1908', 'III Nephi', 2, 37, 'And they were exceeding sorrowful because of their enemy.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-38', 'coc-bom-1908', 'III Nephi', 2, 38, 'And Gidgiddoni did cause that they should make weapons of war of every kind, that they should be strong with armor, and with shields, and with bucklers, after the manner of his instructions.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-39', 'coc-bom-1908', 'III Nephi', 2, 39, 'And it came to pass that in the latter end of the eighteenth year, those armies of robbers had prepared for battle, and began to come down, and to sally forth from the hills, and out of the mountains, and the wilderness, and their strongholds, and their secret places,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-40', 'coc-bom-1908', 'III Nephi', 2, 40, 'And began to take possession of the lands both which were in the land south and which were in the land north, and began to take possession of all the lands which had been deserted by the Nephites and the cities which had been left desolate.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-43', 'coc-bom-1908', 'III Nephi', 2, 43, 'Therefore, there was no chance for the robbers to plunder and to obtain food, save it were to come up in open battle against the Nephites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-44', 'coc-bom-1908', 'III Nephi', 2, 44, 'And the Nephites being in one body, and having so great a number, and having reserved for themselves provisions, and horses, and cattle, and flocks of every kind, that they might subsist for the space of seven years,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-45', 'coc-bom-1908', 'III Nephi', 2, 45, 'In the which time they did hope to destroy the robbers from off the face of the land. And thus the eighteenth year did pass away.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-48', 'coc-bom-1908', 'III Nephi', 2, 48, 'Therefore, Giddianhi gave commandment unto his armies that in this year they should go up to battle against the Nephites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-51', 'coc-bom-1908', 'III Nephi', 2, 51, 'And great and terrible was the appearance of the armies of Giddianhi because of their armor and because of their being dyed in blood.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-52', 'coc-bom-1908', 'III Nephi', 2, 52, 'And it came to pass that the armies of the Nephites, when they saw the appearance of the army of Giddianhi, had all fallen to the earth and did lift their cries to the Lord, their God, that he would spare them and deliver them out of the hands of their enemies.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-57', 'coc-bom-1908', 'III Nephi', 2, 57, 'And notwithstanding the threatenings and the oaths which Giddianhi had made, behold, the Nephites did beat them, insomuch that they did fall back from before them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-59', 'coc-bom-1908', 'III Nephi', 2, 59, 'And thus they did pursue them and did slay them to the borders of the wilderness, even until they had fulfilled the commandment of Gidgiddoni.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-61', 'coc-bom-1908', 'III Nephi', 2, 61, 'And it came to pass that the armies of the Nephites did return again to their place of security.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-64', 'coc-bom-1908', 'III Nephi', 2, 64, 'For they did suppose that if they should cut off the people of Nephi from their lands and should hem them in on every side, and if they should cut them off from all their outward privileges, that they could cause them to yield themselves up according to their wishes.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-67', 'coc-bom-1908', 'III Nephi', 2, 67, 'For behold, they had nothing save it were meat for their subsistence, which meat they did obtain in the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-68', 'coc-bom-1908', 'III Nephi', 2, 68, 'And it came to pass that the wild game became scarce in the wilderness, insomuch that the robbers were about to perish with hunger.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-69', 'coc-bom-1908', 'III Nephi', 2, 69, 'And the Nephites were continually marching out by day and by night, and falling upon their armies, and cutting them off by thousands and by tens of thousands.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-70', 'coc-bom-1908', 'III Nephi', 2, 70, 'And thus it became the desire of the people of Zemnarihah to withdraw from their design because of the great destruction which came upon them by night and by day.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-71', 'coc-bom-1908', 'III Nephi', 2, 71, 'And it came to pass that Zemnarihah did give command unto his people that they should withdraw themselves from the siege and march into the furthermost parts of the land northward.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-73', 'coc-bom-1908', 'III Nephi', 2, 73, 'And this did they do in the nighttime and got on their march beyond the robbers, so that on the morrow when the robbers began their march, they were met by the armies of the Nephites, both in their front and in their rear.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-74', 'coc-bom-1908', 'III Nephi', 2, 74, 'And the robbers who were on the south were also cut off in their places of retreat. And all these things were done by command of Gidgiddoni.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-76', 'coc-bom-1908', 'III Nephi', 2, 76, 'And when they had hanged him until he was dead, they did fell the tree to the earth and did cry with a loud voice, saying, May the Lord preserve his people in righteousness and in holiness of heart, that they may cause to be felled to the earth all who shall seek to slay them because of power and secret combinations, even as this man hath been felled to the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-77', 'coc-bom-1908', 'III Nephi', 2, 77, 'And they did rejoice and cry again with one voice, saying, May the God of Abraham, and the God of Isaac, and the God of Jacob protect this people in righteousness so long as they shall call on the name of their God for protection.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-81', 'coc-bom-1908', 'III Nephi', 2, 81, 'And they knew it was because of their repentance and their humility that they had been delivered from an everlasting destruction.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-85', 'coc-bom-1908', 'III Nephi', 2, 85, 'Therefore, they did forsake all their sins, and their abominations, and their whoredoms, and did serve God with all diligence day and night.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-87', 'coc-bom-1908', 'III Nephi', 2, 87, 'And as many as would repent of their sins and enter into a covenant, that they would murder no more, were set at liberty.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-88', 'coc-bom-1908', 'III Nephi', 2, 88, 'But as many as there were who did not enter into a covenant, and who did still continue to have those secret murders in their hearts, yea, as many as were found breathing out threatenings against their brethren, were condemned and punished according to the law.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-89', 'coc-bom-1908', 'III Nephi', 2, 89, 'And thus they did put an end to all those wicked, and secret, and abominable combinations, in the which there was so much wickedness and so many murders committed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-94', 'coc-bom-1908', 'III Nephi', 2, 94, 'Therefore, I have made my record of these things according to the record of Nephi, which was engraven on the plates which were called the plates of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-95', 'coc-bom-1908', 'III Nephi', 2, 95, 'And behold, I do make this record on plates which I have made with mine own hands.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-96', 'coc-bom-1908', 'III Nephi', 2, 96, 'And behold, I am called Mormon, being called after the land of Mormon, the land in the which Alma did establish the church among this people, yea, the first church which was established among them after their transgression.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-97', 'coc-bom-1908', 'III Nephi', 2, 97, 'Behold, I am a disciple of Jesus Christ, the Son of God. I have been called of him to declare his word among his people, that they might have everlasting life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-98', 'coc-bom-1908', 'III Nephi', 2, 98, 'And it hath become expedient that I--according to the will of God, that the prayers of those who have gone hence, who were the holy ones, should be fulfilled according to their faith--should make a record of these things which have been done,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-99', 'coc-bom-1908', 'III Nephi', 2, 99, 'Yea, a small record of that which hath taken place from the time that Lehi left Jerusalem, even down until the present time.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-102', 'coc-bom-1908', 'III Nephi', 2, 102, 'And now, I make an end of my saying which is of myself and proceed to give my account of the things which have been before me. I am Mormon and a pure descendant of Lehi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-103', 'coc-bom-1908', 'III Nephi', 2, 103, 'I have reason to bless my God and my Savior Jesus Christ that he brought our fathers out of the land of Jerusalem (and no one knew it save it were himself and those whom he brought out of that land) and that he hath given me and my people so much knowledge, unto the salvation of our souls.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-104', 'coc-bom-1908', 'III Nephi', 2, 104, 'Surely he hath blessed the house of Jacob and hath been merciful unto the seed of Joseph.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-2-106', 'coc-bom-1908', 'III Nephi', 2, 106, 'Yea, and surely shall he again bring a remnant of the seed of Joseph to the knowledge of the Lord, their God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-1', 'coc-bom-1908', 'III Nephi', 3, 1, 'And now, it came to pass that the people of the Nephites did all return to their own lands in the twenty and sixth year--every man with his family, his flocks and his herds, his horses and his cattle, and all things whatsoever did belong unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-3', 'coc-bom-1908', 'III Nephi', 3, 3, 'And they did return to their own lands and their possessions, both on the north and on the south, both on the land northward and on the land southward.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-6', 'coc-bom-1908', 'III Nephi', 3, 6, 'And now, there was nothing in all the land to hinder the people from prospering continually, except they should fall into transgressions.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-7', 'coc-bom-1908', 'III Nephi', 3, 7, 'And now, it was Gidgiddoni, and the judge Lachoneus, and those who had been appointed leaders who had established this great peace in the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-9', 'coc-bom-1908', 'III Nephi', 3, 9, 'And thus passed away the twenty and eighth year, and the people had continual peace.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-13', 'coc-bom-1908', 'III Nephi', 3, 13, 'Yea, some were ignorant because of their poverty, and others did receive great learning because of their riches.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-16', 'coc-bom-1908', 'III Nephi', 3, 16, 'And they would not depart from it, for they were firm, and steadfast, and immovable--willing with all diligence to keep the commandments of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-17', 'coc-bom-1908', 'III Nephi', 3, 17, 'Now the cause of this iniquity of the people was this: Satan had great power, unto the stirring up of the people to do all manner of iniquity and to the puffing them up with pride, tempting them to seek for power, and authority, and riches, and the vain things of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-21', 'coc-bom-1908', 'III Nephi', 3, 21, 'And now, it was in the days of Lachoneus, the son of Lachoneus, for Lachoneus did fill the seat of his father and did govern the people that year.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-22', 'coc-bom-1908', 'III Nephi', 3, 22, 'And there began to be men inspired from heaven and sent forth, standing among the people in all the land, preaching and testifying boldly of the sins and iniquities of the people,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-26', 'coc-bom-1908', 'III Nephi', 3, 26, 'Yea, all those who were lawyers were angry with those who testified of these things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-27', 'coc-bom-1908', 'III Nephi', 3, 27, 'Now there was no lawyer, nor judge, nor high priest that could have power to condemn anyone to death, save their condemnation was signed by the governor of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-30', 'coc-bom-1908', 'III Nephi', 3, 30, 'Therefore, a complaint came unto the land of Zarahemla, to the governor of the land, against these judges who had condemned the prophets of the Lord unto death, not according to the law.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-31', 'coc-bom-1908', 'III Nephi', 3, 31, 'Now it came to pass that they were taken and brought up before the judge, to be judged of the crime which they had done according to the law which had been given by the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-34', 'coc-bom-1908', 'III Nephi', 3, 34, 'Therefore, they did combine against the people of the Lord, and enter into a covenant to destroy them, and to deliver those who were guilty of murder from the grasp of justice, which was about to be administered according to the law.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-41', 'coc-bom-1908', 'III Nephi', 3, 41, 'And the regulations of the government were destroyed because of the secret combination of the friends and kindreds of those who murdered the prophets.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-42', 'coc-bom-1908', 'III Nephi', 3, 42, 'And they did cause a great contention in the land, insomuch that the more righteous part of the people--although they had nearly all become wicked--yea, there were but few righteous men among them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-43', 'coc-bom-1908', 'III Nephi', 3, 43, 'And thus six years had not passed away since the more part of the people had turned from their righteousness, like the dog to his vomit or like the sow to her wallowing in the mire.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-48', 'coc-bom-1908', 'III Nephi', 3, 48, 'Therefore, Jacob, seeing that their enemies were more numerous than they, he being the king of the band, therefore, he commanded his people that they should take their flight into the northernmost part of the land,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-49', 'coc-bom-1908', 'III Nephi', 3, 49, 'And there build up unto themselves a kingdom, until they were joined by dissenters (for he flattered them that there would be many dissenters) and they become sufficiently strong to contend with the tribes of the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-55', 'coc-bom-1908', 'III Nephi', 3, 55, 'Nevertheless, their hearts were turned from the Lord, their God, and they did stone the prophets and did cast them out from among them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-57', 'coc-bom-1908', 'III Nephi', 3, 57, 'Therefore, being grieved for the hardness of their hearts and the blindness of their minds--went forth among them in that same year and began to testify boldly: repentance and remission of sins through faith on the Lord Jesus Christ.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-63', 'coc-bom-1908', 'III Nephi', 3, 63, 'But as many as were converted did truly signify unto the people that they had been visited by the power and Spirit of God, which was in Jesus Christ in whom they believed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-65', 'coc-bom-1908', 'III Nephi', 3, 65, 'And they did show forth signs also and did do some miracles among the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-66', 'coc-bom-1908', 'III Nephi', 3, 66, 'Thus passed away the thirty and second year also.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-3-69', 'coc-bom-1908', 'III Nephi', 3, 69, 'Therefore, there were ordained of Nephi, men unto this ministry, that all such as should come unto them should be baptized with water--and this as a witness and a testimony before God and unto the people that they had repented and received a remission of their sins.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-2', 'coc-bom-1908', 'III Nephi', 4, 2, 'And there was not any man who could do a miracle in the name of Jesus save he were cleansed, every whit, from his iniquity.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-4', 'coc-bom-1908', 'III Nephi', 4, 4, 'Yea, for the time that there should be darkness for the space of three days over the face of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-5', 'coc-bom-1908', 'III Nephi', 4, 5, 'And there began to be great doubtings and disputations among the people, notwithstanding so many signs had been given.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-14', 'coc-bom-1908', 'III Nephi', 4, 14, 'And thus the face of the whole earth became deformed because of the tempests, and the thunderings, and the lightnings, and the quaking of the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-17', 'coc-bom-1908', 'III Nephi', 4, 17, 'Nevertheless, all these great and terrible things were done in about the space of three hours--and then behold, there was darkness upon the face of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-20', 'coc-bom-1908', 'III Nephi', 4, 20, 'And there was not any light seen, neither fire, nor glimmer, neither the sun, nor the moon, nor the stars, for so great were the mists of darkness which were upon the face of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-22', 'coc-bom-1908', 'III Nephi', 4, 22, 'Yea, great were the groanings of the people because of the darkness and the great destruction which had come upon them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-23', 'coc-bom-1908', 'III Nephi', 4, 23, 'And in one place they were heard to cry, saying, Oh, that we had repented before this great and terrible day, and then would our brethren have been spared, and they would not have been burned in that great city Zarahemla.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-28', 'coc-bom-1908', 'III Nephi', 4, 28, 'Behold, that great city Zarahemla have I burned with fire, and the inhabitants thereof.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-29', 'coc-bom-1908', 'III Nephi', 4, 29, 'And behold, that great city Moroni have I caused to be sunk in the depths of the sea, and the inhabitants thereof to be drowned.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-30', 'coc-bom-1908', 'III Nephi', 4, 30, 'And behold, that great city Moronihah have I covered with earth, and the inhabitants thereof, to hide their iniquities and their abominations from before my face, that the blood of the prophets and of the saints shall not come up any more unto me against them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-33', 'coc-bom-1908', 'III Nephi', 4, 33, 'To hide their wickedness and abominations from before my face, that the blood of the prophets and the saints shall not come up any more unto me against them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-35', 'coc-bom-1908', 'III Nephi', 4, 35, 'And the inhabitants thereof have I buried up in the depths of the earth, to hide their wickedness and abominations from before my face, that the blood of the prophets and the saints should not come up any more unto me against them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-40', 'coc-bom-1908', 'III Nephi', 4, 40, 'And many great destructions have I caused to come upon this land and upon this people because of their wickedness and their abominations.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-41', 'coc-bom-1908', 'III Nephi', 4, 41, 'O all ye that are spared because ye were more righteous than they, will ye not now return unto me, and repent of your sins, and be converted, that I may heal you?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-42', 'coc-bom-1908', 'III Nephi', 4, 42, 'Yea, verily, I say unto you, If ye will come unto me, ye shall have eternal life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-44', 'coc-bom-1908', 'III Nephi', 4, 44, 'Behold, I am Jesus Christ, the Son of God. I created the heavens, and the earth, and all things that in them are.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-46', 'coc-bom-1908', 'III Nephi', 4, 46, 'I came unto my own, and my own received me not. And the scriptures concerning my coming are fulfilled.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-48', 'coc-bom-1908', 'III Nephi', 4, 48, 'I am the light and the life of the world. I am Alpha and Omega, the beginning and the end.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-50', 'coc-bom-1908', 'III Nephi', 4, 50, 'And whoso cometh unto me with a broken heart and a contrite spirit, him will I baptize with fire and with the Holy Ghost, even as the Lamanites, because of their faith in me at the time of their conversion, were baptized with fire and with the Holy Ghost, and they knew it not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-53', 'coc-bom-1908', 'III Nephi', 4, 53, 'And now, behold, it came to pass that all the people of the land did hear these sayings and did witness of it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-55', 'coc-bom-1908', 'III Nephi', 4, 55, 'And it came to pass that there came a voice again unto the people--and all the people did hear and did witness of it--saying, O ye people of these great cities which have fallen, who are descendants of Jacob, yea, who are of the house of Israel, O ye people of the house of Israel, how oft have I gathered you as a hen gathereth her chickens under her wings and have nourished you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-57', 'coc-bom-1908', 'III Nephi', 4, 57, 'Yea, O ye people of the house of Israel, ye that dwell at Jerusalem, as ye that have fallen, yea, how oft would I have gathered you as a hen gathereth her chickens, and ye would not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-58', 'coc-bom-1908', 'III Nephi', 4, 58, 'O ye house of Israel, whom I have spared, how oft will I gather you as a hen gathereth her chickens under her wings if ye will repent and return unto me with full purpose of heart.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-59', 'coc-bom-1908', 'III Nephi', 4, 59, 'But if not, O house of Israel, the places of your dwellings shall become desolate until the time of the fulfilling of the covenant to your fathers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-60', 'coc-bom-1908', 'III Nephi', 4, 60, 'And now, it came to pass that after the people had heard these words, behold, they began to weep and howl again because of the loss of their kindred and friends.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-61', 'coc-bom-1908', 'III Nephi', 4, 61, 'And it came to pass that thus did the three days pass away.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-64', 'coc-bom-1908', 'III Nephi', 4, 64, 'And their mourning was turned into joy and their lamentations into the praise and thanksgiving unto the Lord Jesus Christ, their Redeemer.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-65', 'coc-bom-1908', 'III Nephi', 4, 65, 'And thus far were the scriptures fulfilled which had been spoken by the prophets.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-71', 'coc-bom-1908', 'III Nephi', 4, 71, 'Yea, the prophet Zenos did testify of these things, and also Zenock spake concerning these things because they testified particularly concerning us, who are the remnant of their seed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-72', 'coc-bom-1908', 'III Nephi', 4, 72, 'Behold, our father Jacob also testified concerning a remnant of the seed of Joseph. And behold, are not we a remnant of the seed of Joseph?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-73', 'coc-bom-1908', 'III Nephi', 4, 73, 'And these things which testify of us, are they not written upon the plates of brass which our father Lehi brought out of Jerusalem?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-74', 'coc-bom-1908', 'III Nephi', 4, 74, 'And it came to pass that in the ending of the thirty and fourth year, behold, I will show unto you that the people of Nephi who were spared, and also those who had been called Lamanites, who had been spared, did have great favors shown unto them and great blessings poured out upon their heads, insomuch that soon after the ascension of Christ into heaven, he did truly manifest himself unto them, showing his body unto them, and ministering unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-4-75', 'coc-bom-1908', 'III Nephi', 4, 75, 'And an account of his ministry shall be given hereafter. Therefore, for this time I make an end of my sayings.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-3', 'coc-bom-1908', 'III Nephi', 5, 3, 'And they were also conversing about this Jesus Christ, of whom the sign had been given concerning his death.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-8', 'coc-bom-1908', 'III Nephi', 5, 8, 'And it said unto them, Behold, my beloved Son, in whom I am well pleased, in whom I have glorified my name, hear ye him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-13', 'coc-bom-1908', 'III Nephi', 5, 13, 'And it came to pass that when Jesus had spoken these words, the whole multitude fell to the earth, for they remembered that it had been prophesied among them that Christ should show himself unto them after his ascension into heaven.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-14', 'coc-bom-1908', 'III Nephi', 5, 14, 'And it came to pass that the Lord spake unto them, saying, Arise and come forth unto me, that ye may thrust your hands into my side and also that ye may feel the prints of the nails in my hands and in my feet, that ye may know that I am the God of Israel, and the God of the whole earth, and have been slain for the sins of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-16', 'coc-bom-1908', 'III Nephi', 5, 16, 'And this they did do, going forth one by one until they had all gone forth, and did see with their eyes, and did feel with their hands, and did know of a surety, and did bear record that it was he of whom it was written by the prophets should come.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-17', 'coc-bom-1908', 'III Nephi', 5, 17, 'And when they had all gone forth and had witnessed for themselves, they did cry out with one accord, saying, Hosanna! Blessed be the name of the Most High God! And they did fall down at the feet of Jesus and did worship him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-18', 'coc-bom-1908', 'III Nephi', 5, 18, 'And it came to pass that he spake unto Nephi (for Nephi was among the multitude), and he commanded him that he should come forth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-19', 'coc-bom-1908', 'III Nephi', 5, 19, 'And Nephi arose and went forth, and bowed himself before the Lord, and he did kiss his feet.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-20', 'coc-bom-1908', 'III Nephi', 5, 20, 'And the Lord commanded him that he should arise. And he arose and stood before him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-21', 'coc-bom-1908', 'III Nephi', 5, 21, 'And the Lord said unto him, I give unto you power that ye shall baptize this people when I am again ascended into heaven.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-24', 'coc-bom-1908', 'III Nephi', 5, 24, 'Verily, I say unto you that whoso repenteth of his sins through your words and desireth to be baptized in my name, on this wise shall ye baptize them: Behold, ye shall go down and stand in the water, and in my name shall ye baptize them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-25', 'coc-bom-1908', 'III Nephi', 5, 25, 'And now, behold, these are the words which ye shall say, calling them by name, saying, Having authority given me of Jesus Christ, I baptize you in the name of the Father, and of the Son, and of the Holy Ghost. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-26', 'coc-bom-1908', 'III Nephi', 5, 26, 'And then shall ye immerse them in the water and come forth again out of the water.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-28', 'coc-bom-1908', 'III Nephi', 5, 28, 'And according as I have commanded you, thus shall ye baptize.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-35', 'coc-bom-1908', 'III Nephi', 5, 35, 'And whoso believeth not in me and is not baptized shall be damned.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-39', 'coc-bom-1908', 'III Nephi', 5, 39, 'And again, I say unto you, Ye must repent, and become as a little child, and be baptized in my name, or ye can in no wise receive these things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-40', 'coc-bom-1908', 'III Nephi', 5, 40, 'And again, I say unto you, Ye must repent, and be baptized in my name, and become as a little child, or ye can in no wise inherit the kingdom of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-43', 'coc-bom-1908', 'III Nephi', 5, 43, 'Therefore, go forth unto this people, and declare the words which I have spoken unto the ends of the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-44', 'coc-bom-1908', 'III Nephi', 5, 44, 'And it came to pass that when Jesus had spoken these words unto Nephi and to those who had been called (now the number of them who had been called and received power and authority to baptize was twelve),', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-47', 'coc-bom-1908', 'III Nephi', 5, 47, 'Therefore, blessed are ye if ye shall believe in me and be baptized after that ye have seen me and know that I am.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-48', 'coc-bom-1908', 'III Nephi', 5, 48, 'And again, more blessed are they who shall believe in your words because that ye shall testify that ye have seen me and that ye know that I am.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-50', 'coc-bom-1908', 'III Nephi', 5, 50, 'Yea, blessed are the poor in spirit who come unto me, for theirs is the kingdom of heaven.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-51', 'coc-bom-1908', 'III Nephi', 5, 51, 'And again, blessed are all they that mourn, for they shall be comforted.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-52', 'coc-bom-1908', 'III Nephi', 5, 52, 'And blessed are the meek, for they shall inherit the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-53', 'coc-bom-1908', 'III Nephi', 5, 53, 'And blessed are all they who do hunger and thirst after righteousness, for they shall be filled with the Holy Ghost.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-54', 'coc-bom-1908', 'III Nephi', 5, 54, 'And blessed are the merciful, for they shall obtain mercy.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-55', 'coc-bom-1908', 'III Nephi', 5, 55, 'And blessed are all the pure in heart, for they shall see God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-56', 'coc-bom-1908', 'III Nephi', 5, 56, 'And blessed are all the peacemakers, for they shall be called the children of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-57', 'coc-bom-1908', 'III Nephi', 5, 57, 'And blessed are all they who are persecuted for my name''s sake, for theirs is the kingdom of heaven.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-58', 'coc-bom-1908', 'III Nephi', 5, 58, 'And blessed are ye when men shall revile you, and persecute, and shall say all manner of evil against you falsely, for my sake,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-60', 'coc-bom-1908', 'III Nephi', 5, 60, 'Verily, verily, I say unto you, I give unto you to be the salt of the earth. But if the salt shall lose its savor, wherewith shall the earth be salted? The salt shall be thenceforth good for nothing but to be cast out and to be trodden underfoot of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-61', 'coc-bom-1908', 'III Nephi', 5, 61, 'Verily, verily, I say unto you, I give unto you to be the light of this people. A city that is set on a hill cannot be hid.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-63', 'coc-bom-1908', 'III Nephi', 5, 63, 'Therefore, let your light so shine before this people, that they may see your good works and glorify your Father who is in heaven.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-65', 'coc-bom-1908', 'III Nephi', 5, 65, 'For verily, I say unto you, One jot nor one tittle hath not passed away from the law, but in me it hath all been fulfilled.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-66', 'coc-bom-1908', 'III Nephi', 5, 66, 'And behold, I have given you the law and the commandments of my Father, that ye shall believe in me and that ye shall repent of your sins and come unto me with a broken heart and a contrite spirit.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-68', 'coc-bom-1908', 'III Nephi', 5, 68, 'For verily, I say unto you that except ye shall keep my commandments which I have commanded you at this time, ye shall in no case enter into the kingdom of heaven.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-71', 'coc-bom-1908', 'III Nephi', 5, 71, 'Therefore, if ye shall come unto me, or shall desire to come unto me, and rememberest that thy brother hath aught against thee,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-73', 'coc-bom-1908', 'III Nephi', 5, 73, 'Agree with thine adversary quickly while thou art in the way with him, lest at any time he shall get thee, and thou shalt be cast into prison.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-74', 'coc-bom-1908', 'III Nephi', 5, 74, 'Verily, verily, I say unto thee, Thou shalt by no means come out thence until thou hast paid the uttermost senine.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-75', 'coc-bom-1908', 'III Nephi', 5, 75, 'And while ye are in prison, can ye pay even one senine? Verily, verily, I say unto you, Nay.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-77', 'coc-bom-1908', 'III Nephi', 5, 77, 'But I say unto you that whosoever looketh on a woman to lust after her hath committed adultery already in his heart.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-79', 'coc-bom-1908', 'III Nephi', 5, 79, 'It hath been written that whosoever shall put away his wife, let him give her a writing of divorcement.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-81', 'coc-bom-1908', 'III Nephi', 5, 81, 'And again, it is written, Thou shalt not forswear thyself but shalt perform unto the Lord thine oaths.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-84', 'coc-bom-1908', 'III Nephi', 5, 84, 'And behold, it is written, An eye for an eye, and a tooth for a tooth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-86', 'coc-bom-1908', 'III Nephi', 5, 86, 'And if any man will sue thee at the law and take away thy coat, let him have thy cloak also.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-87', 'coc-bom-1908', 'III Nephi', 5, 87, 'And whosoever shall compel thee to go a mile, go with him twain.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-88', 'coc-bom-1908', 'III Nephi', 5, 88, 'Give to him that asketh thee, and to him that would borrow of thee, turn thou not away.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-94', 'coc-bom-1908', 'III Nephi', 5, 94, 'Therefore, when ye shall do your alms, do not sound a trumpet before you, as will hypocrites do in the synagogues and in the streets, that they may have glory of men. Verily, I say unto you, They have their reward.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-95', 'coc-bom-1908', 'III Nephi', 5, 95, 'But when thou doest alms, let not thy left hand know what thy right hand doeth,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-97', 'coc-bom-1908', 'III Nephi', 5, 97, 'And when thou prayest, thou shalt not do as the hypocrites, for they love to pray standing in the synagogues and in the corners of the streets, that they may be seen of men. Verily, I say unto you, They have their reward.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-99', 'coc-bom-1908', 'III Nephi', 5, 99, 'But when ye pray, use not vain repetitions as the heathen, for they think that they shall be heard for their much speaking.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-100', 'coc-bom-1908', 'III Nephi', 5, 100, 'Be not ye, therefore, like unto them, for your Father knoweth what things ye have need of before ye ask him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-101', 'coc-bom-1908', 'III Nephi', 5, 101, 'After this manner therefore, pray ye:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-102', 'coc-bom-1908', 'III Nephi', 5, 102, 'Our Father who art in heaven, hallowed be thy name.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-103', 'coc-bom-1908', 'III Nephi', 5, 103, 'Thy will be done on earth as it is in heaven.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-104', 'coc-bom-1908', 'III Nephi', 5, 104, 'And forgive us our debts, as we forgive our debtors.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-105', 'coc-bom-1908', 'III Nephi', 5, 105, 'And lead us not into temptation, but deliver us from evil.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-106', 'coc-bom-1908', 'III Nephi', 5, 106, 'For thine is the kingdom, and the power, and the glory forever. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-108', 'coc-bom-1908', 'III Nephi', 5, 108, 'Moreover, when ye fast, be not as the hypocrites, of a sad countenance--for they disfigure their faces that they may appear unto men to fast. Verily, I say unto you, They have their reward.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-111', 'coc-bom-1908', 'III Nephi', 5, 111, 'But lay up for yourselves treasures in heaven, where neither moth nor rust doth corrupt and where thieves do not break through nor steal.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-112', 'coc-bom-1908', 'III Nephi', 5, 112, 'For where your treasure is, there will your heart be also.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-5-114', 'coc-bom-1908', 'III Nephi', 5, 114, 'But if thine eye be evil, thy whole body shall be full of darkness. If, therefore, the light that is in thee be darkness, how great is that darkness!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-1', 'coc-bom-1908', 'III Nephi', 6, 1, 'And now, it came to pass that when Jesus had spoken these words, he looked upon the twelve whom he had chosen and said unto them, Remember the words which I have spoken.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-2', 'coc-bom-1908', 'III Nephi', 6, 2, 'For behold, ye are they whom I have chosen to minister unto this people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-3', 'coc-bom-1908', 'III Nephi', 6, 3, 'Therefore, I say unto you, Take no thought for your life, what ye shall eat or what ye shall drink--nor yet for your body, what ye shall put on. Is not the life more than meat and the body than raiment?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-5', 'coc-bom-1908', 'III Nephi', 6, 5, 'Which of you by taking thought can add one cubit unto his stature?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-7', 'coc-bom-1908', 'III Nephi', 6, 7, 'And yet I say unto you that even Solomon in all his glory was not arrayed like one of these.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-8', 'coc-bom-1908', 'III Nephi', 6, 8, 'Wherefore, if God so clothe the grass of the field, which today is and tomorrow is cast into the oven, even so will he clothe you if ye are not of little faith.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-9', 'coc-bom-1908', 'III Nephi', 6, 9, 'Therefore, take no thought, saying, What shall we eat? or, What shall we drink? or, Wherewithal shall we be clothed?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-10', 'coc-bom-1908', 'III Nephi', 6, 10, 'For your heavenly Father knoweth that ye have need of all these things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-11', 'coc-bom-1908', 'III Nephi', 6, 11, 'But seek ye first the kingdom of God and his righteousness, and all these things shall be added unto you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-12', 'coc-bom-1908', 'III Nephi', 6, 12, 'Take, therefore, no thought for the morrow, for the morrow shall take thought for the things of itself. Sufficient is the day unto the evil thereof.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-13', 'coc-bom-1908', 'III Nephi', 6, 13, 'And now, it came to pass that when Jesus had spoken these words, he turned again to the multitude and did open his mouth unto them again, saying, Verily, verily, I say unto you, Judge not, that ye be not judged.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-15', 'coc-bom-1908', 'III Nephi', 6, 15, 'And why beholdest thou the mote that is in thy brother''s eye, but considerest not the beam that is in thine own eye?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-21', 'coc-bom-1908', 'III Nephi', 6, 21, 'Or what man is there of you, who, if his son ask bread, will he give him a stone?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-22', 'coc-bom-1908', 'III Nephi', 6, 22, 'Or if he ask a fish, will he give him a serpent?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-23', 'coc-bom-1908', 'III Nephi', 6, 23, 'If ye then, being evil, know how to give good gifts unto your children, how much more shall your Father who is in heaven give good things to them that ask him?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-26', 'coc-bom-1908', 'III Nephi', 6, 26, 'Because strait is the gate, and narrow is the way which leadeth unto life, and few there be that find it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-27', 'coc-bom-1908', 'III Nephi', 6, 27, 'Beware of false prophets, who come to you in sheep''s clothing, but inwardly they are ravening wolves.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-28', 'coc-bom-1908', 'III Nephi', 6, 28, 'Ye shall know them by their fruits. Do men gather grapes of thorns or figs of thistles?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-30', 'coc-bom-1908', 'III Nephi', 6, 30, 'A good tree cannot bring forth evil fruit, neither a corrupt tree bring forth good fruit.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-31', 'coc-bom-1908', 'III Nephi', 6, 31, 'Every tree that bringeth not forth good fruit is hewn down and cast into the fire.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-32', 'coc-bom-1908', 'III Nephi', 6, 32, 'Wherefore, by their fruits ye shall know them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-33', 'coc-bom-1908', 'III Nephi', 6, 33, 'Not everyone that saith unto me, Lord, Lord, shall enter into the kingdom of heaven, but he that doeth the will of my Father who is in heaven.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-6-34', 'coc-bom-1908', 'III Nephi', 6, 34, 'Many will say to me in that day, Lord, Lord, have we not prophesied in thy name? and in thy name have cast out devils? and in thy name done many wonderful works?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-7-2', 'coc-bom-1908', 'III Nephi', 7, 2, 'Therefore, whoso remembereth these sayings of mine and doeth them, him will I raise up at the last day.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-7-4', 'coc-bom-1908', 'III Nephi', 7, 4, 'And he said unto them, Marvel not that I said unto you that old things had passed away and that all things had become new.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-7-5', 'coc-bom-1908', 'III Nephi', 7, 5, 'Behold, I say unto you that the law is fulfilled that was given unto Moses.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-7-7', 'coc-bom-1908', 'III Nephi', 7, 7, 'Behold, I do not destroy the prophets, for as many as have not been fulfilled in me, verily, I say unto you, shall all be fulfilled.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-7-8', 'coc-bom-1908', 'III Nephi', 7, 8, 'And because I said unto you that old things hath passed away, I do not destroy that which hath been spoken concerning things which are to come.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-7-12', 'coc-bom-1908', 'III Nephi', 7, 12, 'And this is the law and the prophets, for they truly testified of me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-7-24', 'coc-bom-1908', 'III Nephi', 7, 24, 'And verily, verily, I say unto you that I have other sheep, which are not of this land, neither of the land of Jerusalem, neither in any parts of that land round about whither I have been to minister.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-7-27', 'coc-bom-1908', 'III Nephi', 7, 27, 'And I command you that ye shall write these sayings after I am gone, that if it so be that my people at Jerusalem, they who have seen me and been with me in my ministry, do not ask the Father in my name, that they may receive a knowledge of you by the Holy Ghost and also of the other tribes whom they know not of,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-7-28', 'coc-bom-1908', 'III Nephi', 7, 28, 'That these sayings which ye shall write shall be kept and shall be manifested unto the Gentiles, that through the fullness of the Gentiles, the remnant of their seed--who shall be scattered forth upon the face of the earth because of their unbelief--may be brought in, or may be brought to a knowledge of me, their Redeemer.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-7-30', 'coc-bom-1908', 'III Nephi', 7, 30, 'And blessed are the Gentiles because of their belief in me, in and of the Holy Ghost, which witnesseth unto them of me and of the Father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-7-31', 'coc-bom-1908', 'III Nephi', 7, 31, 'Behold, because of their belief in me, saith the Father, and because of the unbelief of you, O house of Israel, in the latter day shall the truth come unto the Gentiles, that the fullness of these things shall be made known unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-7-33', 'coc-bom-1908', 'III Nephi', 7, 33, 'And because of the mercies of the Father unto the Gentiles, and also the judgments of the Father upon my people who are of the house of Israel, verily, verily, I say unto you that after all this, and I have caused my people who are of the house of Israel to be smitten, and to be afflicted, and to be slain, and to be cast out from among them, and to become hated by them, and to become a hiss and a byword among them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-7-34', 'coc-bom-1908', 'III Nephi', 7, 34, 'And thus commandeth the Father that I should say unto you, At that day when the Gentiles shall sin against my gospel, and shall reject the fullness of my gospel, and shall be lifted up in the pride of their hearts above all nations and above all the people of the whole earth, and shall be filled with all manner of lyings, and of deceits, and of mischiefs, and all manner of hypocrisy, and murders, and priestcrafts, and whoredoms, and of secret abominations--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-7-35', 'coc-bom-1908', 'III Nephi', 7, 35, 'And if they shall do all these things and shall reject the fullness of my gospel, behold, saith the Father, I will bring the fullness of my gospel from among them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-7-39', 'coc-bom-1908', 'III Nephi', 7, 39, 'And I will not suffer my people who are of the house of Israel to go through among them and tread them down, saith the Father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-7-40', 'coc-bom-1908', 'III Nephi', 7, 40, 'But if they will not turn unto me and hearken unto my voice, I will suffer them, yea, I will suffer my people, O house of Israel, that they shall go through among them and shall tread them down,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-7-41', 'coc-bom-1908', 'III Nephi', 7, 41, 'And they shall be as salt that hath lost its savor, which is thenceforth good for nothing but to be cast out and to be trodden underfoot of my people, O house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-7-42', 'coc-bom-1908', 'III Nephi', 7, 42, 'Verily, verily, I say unto you, Thus hath the Father commanded me, that I should give unto this people this land for their inheritance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-1', 'coc-bom-1908', 'III Nephi', 8, 1, 'Behold, now it came to pass that when Jesus had spoken these words, he looked round about again on the multitude, and he said unto them, Behold, my time is at hand.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-5', 'coc-bom-1908', 'III Nephi', 8, 5, 'And it came to pass that when Jesus had thus spoken, he cast his eyes round about again on the multitude and beheld they were in tears and did look steadfastly upon him as if they would ask him to tarry a little longer with them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-6', 'coc-bom-1908', 'III Nephi', 8, 6, 'And he said unto them, Behold, my bowels are filled with compassion towards you. Have ye any that are sick among you? Bring them hither.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-7', 'coc-bom-1908', 'III Nephi', 8, 7, 'Have ye any that are lame, or blind, or halt, or maimed, or leprous, or that are withered, or that are deaf, or that are afflicted in any manner? Bring them hither, and I will heal them, for I have compassion upon you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-11', 'coc-bom-1908', 'III Nephi', 8, 11, 'And as many as could come, for the multitude, did kiss his feet, insomuch that they did bathe his feet with their tears.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-12', 'coc-bom-1908', 'III Nephi', 8, 12, 'And it came to pass that he commanded that their little children should be brought.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-14', 'coc-bom-1908', 'III Nephi', 8, 14, 'And it came to pass that when they had all been brought and Jesus stood in the midst, he commanded the multitude that they should kneel down upon the ground.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-15', 'coc-bom-1908', 'III Nephi', 8, 15, 'And it came to pass that when they had knelt upon the ground, Jesus groaned within himself and saith, Father, I am troubled because of the wickedness of the people of the house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-19', 'coc-bom-1908', 'III Nephi', 8, 19, 'And no one can conceive of the joy which filled our souls at the time we heard him pray for us unto the Father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-21', 'coc-bom-1908', 'III Nephi', 8, 21, 'And it came to pass that Jesus spake unto them and bade them arise.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-22', 'coc-bom-1908', 'III Nephi', 8, 22, 'And they arose from the earth. And he said unto them, Blessed are ye because of your faith. And now, behold, my joy is full.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-28', 'coc-bom-1908', 'III Nephi', 8, 28, 'And it came to pass that Jesus commanded his disciples that they should bring forth some bread and wine unto him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-29', 'coc-bom-1908', 'III Nephi', 8, 29, 'And while they were gone for bread and wine, he commanded the multitude that they should sit themselves down upon the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-31', 'coc-bom-1908', 'III Nephi', 8, 31, 'And when they had eaten and were filled, he commanded that they should give unto the multitude.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-33', 'coc-bom-1908', 'III Nephi', 8, 33, 'And this shall ye always observe to do, even as I have done, even as I have broken bread, and blessed it, and given it unto you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-34', 'coc-bom-1908', 'III Nephi', 8, 34, 'And this shall ye do in remembrance of my body, which I have shown unto you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-35', 'coc-bom-1908', 'III Nephi', 8, 35, 'And it shall be a testimony unto the Father that ye do always remember me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-36', 'coc-bom-1908', 'III Nephi', 8, 36, 'And if ye do always remember me, ye shall have my Spirit to be with you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-37', 'coc-bom-1908', 'III Nephi', 8, 37, 'And it came to pass that when he had said these words, he commanded his disciples that they should take of the wine of the cup and drink of it and that they should also give unto the multitude, that they might drink of it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-41', 'coc-bom-1908', 'III Nephi', 8, 41, 'And if ye do always remember me, ye shall have my Spirit to be with you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-42', 'coc-bom-1908', 'III Nephi', 8, 42, 'And I give unto you a commandment that ye shall do these things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-43', 'coc-bom-1908', 'III Nephi', 8, 43, 'And if ye shall always do these things, blessed are ye, for ye are built upon my rock.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-46', 'coc-bom-1908', 'III Nephi', 8, 46, 'Therefore, blessed are ye if ye shall keep my commandments, which the Father hath commanded me that I should give unto you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-47', 'coc-bom-1908', 'III Nephi', 8, 47, 'Verily, verily, I say unto you, Ye must watch and pray always, lest ye be tempted by the devil and ye are led away captive by him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-48', 'coc-bom-1908', 'III Nephi', 8, 48, 'And as I have prayed among you, even so shall ye pray in my church, among my people who do repent and are baptized in my name.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-52', 'coc-bom-1908', 'III Nephi', 8, 52, 'Pray in your families unto the Father, always in my name, that your wives and your children may be blessed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-55', 'coc-bom-1908', 'III Nephi', 8, 55, 'Behold, I am the light which ye shall hold up--that which ye have seen me do.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-58', 'coc-bom-1908', 'III Nephi', 8, 58, 'And now, it came to pass that when Jesus had spoken these words, he turned his eyes again upon the disciples whom he had chosen and said unto them,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-59', 'coc-bom-1908', 'III Nephi', 8, 59, 'Behold, verily, verily, I say unto you, I give unto you another commandment, and then I must go unto my Father, that I may fulfill other commandments which he hath given me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-67', 'coc-bom-1908', 'III Nephi', 8, 67, 'And I give you these commandments because of the disputations which have been among you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-68', 'coc-bom-1908', 'III Nephi', 8, 68, 'And blessed are ye if ye have no disputations among you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-69', 'coc-bom-1908', 'III Nephi', 8, 69, 'And now, I go unto the Father because it is expedient that I should go unto the Father for your sakes.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-72', 'coc-bom-1908', 'III Nephi', 8, 72, 'And I will show unto you hereafter that this record is true.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-73', 'coc-bom-1908', 'III Nephi', 8, 73, 'And it came to pass that when Jesus had touched them all, there came a cloud and overshadowed the multitude, that they could not see Jesus.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-74', 'coc-bom-1908', 'III Nephi', 8, 74, 'And while they were overshadowed, he departed from them and ascended into heaven.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-8-75', 'coc-bom-1908', 'III Nephi', 8, 75, 'And the disciples saw and did bear record that he ascended again into heaven.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-1', 'coc-bom-1908', 'III Nephi', 9, 1, 'And now, it came to pass that when Jesus had ascended into heaven, the multitude did disperse, and every man did take his wife and his children and did return to his own home.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-4', 'coc-bom-1908', 'III Nephi', 9, 4, 'And it came to pass that on the morrow, when the multitude was gathered together, behold, Nephi and his brother whom he had raised from the dead, whose name was Timothy, and also his son, whose name was Jonas, and also Mathoni, and Mathonihah, his brother, and Kumen, and Kumenonhi, and Jeremiah, and Shemnon, and Jonas, and Zedekiah, and Isaiah--now these were the names of the disciples whom Jesus had chosen--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-5', 'coc-bom-1908', 'III Nephi', 9, 5, 'And it came to pass that they went forth and stood in the midst of the multitude.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-6', 'coc-bom-1908', 'III Nephi', 9, 6, 'And behold, the multitude was so great that they did cause that they should be separated into twelve bodies.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-8', 'coc-bom-1908', 'III Nephi', 9, 8, 'And the disciples did pray unto the Father also in the name of Jesus.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-9', 'coc-bom-1908', 'III Nephi', 9, 9, 'And it came to pass that they arose and ministered unto the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-11', 'coc-bom-1908', 'III Nephi', 9, 11, 'And when they had thus prayed, they went down unto the water''s edge, and the multitude followed them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-12', 'coc-bom-1908', 'III Nephi', 9, 12, 'And it came to pass that Nephi went down into the water and was baptized.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-13', 'coc-bom-1908', 'III Nephi', 9, 13, 'And he came up out of the water and began to baptize. And he baptized all those whom Jesus had chosen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-14', 'coc-bom-1908', 'III Nephi', 9, 14, 'And it came to pass when they were all baptized and had come up out of the water, the Holy Ghost did fall upon them, and they were filled with the Holy Ghost and with fire.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-16', 'coc-bom-1908', 'III Nephi', 9, 16, 'And it came to pass that while the angels were ministering unto the disciples, behold, Jesus came and stood in the midst and ministered unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-17', 'coc-bom-1908', 'III Nephi', 9, 17, 'And it came to pass that he spake unto the multitude and commanded them that they should kneel down again upon the earth, and also that his disciples should kneel down upon the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-18', 'coc-bom-1908', 'III Nephi', 9, 18, 'And it came to pass that when they had all knelt down upon the earth, he commanded his disciples that they should pray.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-21', 'coc-bom-1908', 'III Nephi', 9, 21, 'Father, I pray thee that thou wilt give the Holy Ghost unto all them that shall believe in their words.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-23', 'coc-bom-1908', 'III Nephi', 9, 23, 'And now, Father, I pray unto thee for them and also for all those who shall believe on their words, that they may believe in me, that I may be in them as thou, Father, art in me, that we may be one.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-26', 'coc-bom-1908', 'III Nephi', 9, 26, 'And behold, the whiteness thereof did exceed all the whiteness, yea, even there could be nothing upon earth so white as the whiteness thereof.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-29', 'coc-bom-1908', 'III Nephi', 9, 29, 'And I pray for them and also for them who shall believe on their words, that they may be purified in me through faith on their words, even as they are purified in me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-30', 'coc-bom-1908', 'III Nephi', 9, 30, 'Father, I pray not for the world, but for those whom thou hast given me out of the world because of their faith, that they may be purified in me--that I may be in them as thou, Father, art in me, that we may be one, that I may be glorified in them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-37', 'coc-bom-1908', 'III Nephi', 9, 37, 'And it came to pass that he commanded the multitude that they should cease to pray, and also his disciples.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-38', 'coc-bom-1908', 'III Nephi', 9, 38, 'And he commanded them that they should not cease to pray in their hearts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-39', 'coc-bom-1908', 'III Nephi', 9, 39, 'And he commanded them that they should arise and stand upon their feet. And they arose up and stood upon their feet.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-40', 'coc-bom-1908', 'III Nephi', 9, 40, 'And it came to pass that he brake bread again, and blessed it, and gave to the disciples to eat.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-41', 'coc-bom-1908', 'III Nephi', 9, 41, 'And when they had eaten, he commanded them that they should break bread and give it unto the multitude.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-42', 'coc-bom-1908', 'III Nephi', 9, 42, 'And when they had given unto the multitude, he also gave them wine to drink and commanded them that they should give unto the multitude.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-45', 'coc-bom-1908', 'III Nephi', 9, 45, 'Now when the multitude had all eaten and drunk, behold, they were filled with the Spirit, and they did cry out with one voice and gave glory to Jesus, whom they both saw and heard.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-46', 'coc-bom-1908', 'III Nephi', 9, 46, 'And it came to pass that when they had all given glory unto Jesus, he said unto them, Behold, now I finish the commandment which the Father hath commanded me concerning this people who are a remnant of the house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-48', 'coc-bom-1908', 'III Nephi', 9, 48, 'And verily, verily, I say unto you that when they shall be fulfilled, then is the fulfilling of the covenant which the Father hath made unto his people,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-50', 'coc-bom-1908', 'III Nephi', 9, 50, 'And the Father hath commanded me that I should give unto you this land for your inheritance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-53', 'coc-bom-1908', 'III Nephi', 9, 53, 'Thy hand shall be lifted up upon thine adversaries, and all thine enemies shall be cut off.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-57', 'coc-bom-1908', 'III Nephi', 9, 57, 'And it shall come to pass that I will establish my people, O house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-61', 'coc-bom-1908', 'III Nephi', 9, 61, 'And it shall come to pass that every soul who will not hear that prophet shall be cut off from among the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-62', 'coc-bom-1908', 'III Nephi', 9, 62, 'Verily, I say unto you, Yea, and all the prophets from Samuel, and those that follow after, as many as have spoken, have testified of me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-64', 'coc-bom-1908', 'III Nephi', 9, 64, 'The Father having raised me up unto you first and sent me to bless you, in turning away every one of you from his iniquities--and this because ye are the children of the covenant.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-66', 'coc-bom-1908', 'III Nephi', 9, 66, 'Nevertheless, when they shall have received the fullness of my gospel, then if they shall harden their hearts against me, I will return their iniquities upon their own heads, saith the Father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-68', 'coc-bom-1908', 'III Nephi', 9, 68, 'That I would give unto them again the land of their fathers for their inheritance, which is the land of Jerusalem, which is the promised land unto them forever, saith the Father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-71', 'coc-bom-1908', 'III Nephi', 9, 71, 'Then will the Father gather them together again and give unto them Jerusalem for the land of their inheritance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-78', 'coc-bom-1908', 'III Nephi', 9, 78, 'And then shall they say, How beautiful upon the mountains are the feet of him that bringeth good tidings unto them, that publisheth peace, that bringeth good tidings unto them of good, that publisheth salvation, that saith unto Zion, Thy God reigneth!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-82', 'coc-bom-1908', 'III Nephi', 9, 82, 'As many were astonished at thee (his visage was so marred, more than any man, and his form, more than the sons of men),', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-84', 'coc-bom-1908', 'III Nephi', 9, 84, 'Verily, verily, I say unto you, All these things shall surely come, even as the Father hath commanded me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-86', 'coc-bom-1908', 'III Nephi', 9, 86, 'And verily, I say unto you, I give unto you a sign, that ye may know the time when these things shall be about to take place, that I shall gather in from their long dispersion, my people, O house of Israel, and shall establish again among them my Zion.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-87', 'coc-bom-1908', 'III Nephi', 9, 87, 'And behold, this is the thing which I will give unto you for a sign: For verily, I say unto you that when these things which I declare unto you--and which I shall declare unto you hereafter of myself and by the power of the Holy Ghost, which shall be given unto you of the Father--shall be made known unto the Gentiles,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-88', 'coc-bom-1908', 'III Nephi', 9, 88, 'That they may know concerning this people who are a remnant of the house of Jacob and concerning this, my people who shall be scattered by them,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-89', 'coc-bom-1908', 'III Nephi', 9, 89, 'Verily, verily, I say unto you, When these things shall be made known unto them of the Father and shall come forth of the Father from them unto you--for it is wisdom in the Father that they should be established in this land,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-90', 'coc-bom-1908', 'III Nephi', 9, 90, 'And be set up as a free people by the power of the Father, that these things might come forth from them unto a remnant of your seed, that the covenant of the Father may be fulfilled which he hath covenanted with his people, O house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-91', 'coc-bom-1908', 'III Nephi', 9, 91, 'Therefore, when these works and the work which shall be wrought among you hereafter shall come forth from the Gentiles unto your seed, which shall dwindle in unbelief because of iniquity--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-92', 'coc-bom-1908', 'III Nephi', 9, 92, 'For thus it behooveth the Father that it should come forth from the Gentiles, that he may show forth his power unto the Gentiles, for this cause, that the Gentiles, if they will not harden their hearts, that they may repent, and come unto me, and be baptized in my name, and know of the true points of my doctrine, that they may be numbered among my people, O house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-93', 'coc-bom-1908', 'III Nephi', 9, 93, 'And when these things come to pass--that thy seed shall begin to know these things--it shall be a sign unto them, that they may know that the work of the Father hath already commenced unto the fulfilling of the covenant which he hath made unto the people who are of the house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-97', 'coc-bom-1908', 'III Nephi', 9, 97, 'Yet I will heal him, for I will show unto them that my wisdom is greater than the cunning of the devil.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-98', 'coc-bom-1908', 'III Nephi', 9, 98, 'Therefore, it shall come to pass that whosoever will not believe in my words, who am Jesus Christ, whom the Father shall cause him to bring forth unto the Gentiles, and shall give unto him power that he shall bring them forth unto the Gentiles (it shall be done even as Moses said), they shall be cut off from among my people who are of the covenant.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-99', 'coc-bom-1908', 'III Nephi', 9, 99, 'And my people who are a remnant of Jacob shall be among the Gentiles, yea, in the midst of them as a lion among the beasts of the forest, as a young lion among the flocks of sheep, who, if he go through both treadeth down and teareth in pieces, and none can deliver.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-100', 'coc-bom-1908', 'III Nephi', 9, 100, 'Their hand shall be lifted up upon their adversaries, and all their enemies shall be cut off.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-102', 'coc-bom-1908', 'III Nephi', 9, 102, 'And I will cut off witchcrafts out of thy hand, and thou shalt have no more soothsayers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-9-105', 'coc-bom-1908', 'III Nephi', 9, 105, 'And it shall come to pass that all lyings, and deceivings, and envyings, and strifes, and priestcrafts, and whoredoms shall be done away.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-10-3', 'coc-bom-1908', 'III Nephi', 10, 3, 'And then shall they assist my people that they may be gathered in--who are scattered upon all the face of the land--in unto the New Jerusalem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-10-5', 'coc-bom-1908', 'III Nephi', 10, 5, 'Verily, I say unto you, At that day shall the work of the Father commence among all the dispersed of my people, yea, even the tribes which have been lost, which the Father hath led away out of Jerusalem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-10-7', 'coc-bom-1908', 'III Nephi', 10, 7, 'Yea, and then shall the work commence, with the Father, among all nations, in preparing the way whereby his people may be gathered home to the land of their inheritance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-10-14', 'coc-bom-1908', 'III Nephi', 10, 14, 'For the Lord hath called thee as a woman forsaken, and grieved in spirit, and a wife of youth when thou wast refused, saith thy God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-10-17', 'coc-bom-1908', 'III Nephi', 10, 17, 'For this is as the waters of Noah unto me, for as I have sworn that the waters of Noah should no more go over the earth, so have I sworn that I would not be wroth with thee.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-10-19', 'coc-bom-1908', 'III Nephi', 10, 19, 'O thou afflicted, tossed with tempest and not comforted, behold, I will lay thy stones with fair colors and lay thy foundations with sapphires.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-10-20', 'coc-bom-1908', 'III Nephi', 10, 20, 'And I will make thy windows of agates, and thy gates of carbuncles, and all thy borders of pleasant stones.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-10-26', 'coc-bom-1908', 'III Nephi', 10, 26, 'And now, behold, I say unto you that ye ought to search these things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-10-29', 'coc-bom-1908', 'III Nephi', 10, 29, 'And all things that he spake hath been and shall be, even according to the words which he spake.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-10-31', 'coc-bom-1908', 'III Nephi', 10, 31, 'And whosoever will hearken unto my words, and repenteth, and is baptized, the same shall be saved.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-10-32', 'coc-bom-1908', 'III Nephi', 10, 32, 'Search the prophets, for many there be that testify of these things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-10-33', 'coc-bom-1908', 'III Nephi', 10, 33, 'And now, it came to pass that when Jesus had said these words, he said unto them again, after he had expounded all the scriptures unto them which they had received, he said unto them, Behold, other scriptures I would that ye should write, that ye have not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-10-34', 'coc-bom-1908', 'III Nephi', 10, 34, 'And it came to pass that he said unto Nephi, Bring forth the record which ye have kept.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-10-35', 'coc-bom-1908', 'III Nephi', 10, 35, 'And when Nephi had brought forth the records and laid them before him, he cast his eyes upon them and said,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-10-36', 'coc-bom-1908', 'III Nephi', 10, 36, 'Verily, I say unto you, I commanded my servant Samuel, the Lamanite, that he should testify unto this people, that at the day that the Father should glorify his name in me, that there were many saints who should arise from the dead, and should appear unto many, and should minister unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-10-37', 'coc-bom-1908', 'III Nephi', 10, 37, 'And he said unto them, Were it not so?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-10-38', 'coc-bom-1908', 'III Nephi', 10, 38, 'And his disciples answered him and said, Yea, Lord, Samuel did prophesy according to thy words, and they were all fulfilled.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-10-39', 'coc-bom-1908', 'III Nephi', 10, 39, 'And Jesus said unto them, How be it that ye have not written this thing--that many saints did arise, and appear unto many, and did minister unto them?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-10-40', 'coc-bom-1908', 'III Nephi', 10, 40, 'And it came to pass that Nephi remembered that this thing had not been written.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-11-1', 'coc-bom-1908', 'III Nephi', 11, 1, 'And now, it came to pass that when Jesus had expounded all the scriptures in one, which they had written, he commanded them that they should teach the things which he had expounded unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-11-2', 'coc-bom-1908', 'III Nephi', 11, 2, 'And it came to pass that he commanded them that they should write the words which the Father had given unto Malachi, which he should tell unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-11-3', 'coc-bom-1908', 'III Nephi', 11, 3, 'And it came to pass that after they were written, he expounded them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-11-5', 'coc-bom-1908', 'III Nephi', 11, 5, 'But who may abide the day of his coming? And who shall stand when he appeareth? For he is like a refiner''s fire, and like fullers'' soap.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-11-7', 'coc-bom-1908', 'III Nephi', 11, 7, 'Then shall the offering of Judah and Jerusalem be pleasant unto the Lord, as in the days of old and as in former years.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-11-10', 'coc-bom-1908', 'III Nephi', 11, 10, 'Even from the days of your fathers ye are gone away from mine ordinances and have not kept them. Return unto me, and I will return unto you, saith the Lord of hosts. But ye said, Wherein shall we return?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-11-11', 'coc-bom-1908', 'III Nephi', 11, 11, 'Will a man rob God? Yet ye have robbed me. But ye say, Wherein have we robbed thee? In tithes and offerings.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-11-12', 'coc-bom-1908', 'III Nephi', 11, 12, 'Ye are cursed with a curse, for ye have robbed me, even this whole nation.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-11-15', 'coc-bom-1908', 'III Nephi', 11, 15, 'And all nations shall call you blessed, for ye shall be a delightsome land, saith the Lord of hosts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-11-16', 'coc-bom-1908', 'III Nephi', 11, 16, 'Your words have been stout against me, saith the Lord. Yet ye say, What have we spoken against thee?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-11-17', 'coc-bom-1908', 'III Nephi', 11, 17, 'Ye have said, It is vain to serve God, and, What doth it profit that we have kept his ordinances and that we have walked mournfully before the Lord of hosts?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-11-21', 'coc-bom-1908', 'III Nephi', 11, 21, 'Then shall ye return and discern between the righteous and the wicked, between him that serveth God and him that serveth him not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-11-25', 'coc-bom-1908', 'III Nephi', 11, 25, 'Remember ye the law of Moses, my servant, which I commanded unto him in Horeb for all Israel, with the statutes and judgments.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-11-27', 'coc-bom-1908', 'III Nephi', 11, 27, 'And he shall turn the heart of the fathers to the children and the heart of the children to their fathers, lest I come and smite the earth with a curse.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-11-28', 'coc-bom-1908', 'III Nephi', 11, 28, 'And now, it came to pass that when Jesus had told these things, he expounded them unto the multitude, and he did expound all things unto them, both great and small.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-11-29', 'coc-bom-1908', 'III Nephi', 11, 29, 'And he saith, These scriptures which ye had not with you, the Father commanded that I should give unto you, for it was wisdom in him that they should be given unto future generations.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-11-30', 'coc-bom-1908', 'III Nephi', 11, 30, 'And he did expound all things, even from the beginning until the time that he should come in his glory--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-12-3', 'coc-bom-1908', 'III Nephi', 12, 3, 'And when they shall have received this--which is expedient that they should have first to try their faith--and if it shall so be that they shall believe these things, then shall the greater things be made manifest unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-12-4', 'coc-bom-1908', 'III Nephi', 12, 4, 'And if it so be that they will not believe these things, then shall the greater things be withheld from them unto their condemnation.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-12-8', 'coc-bom-1908', 'III Nephi', 12, 8, 'And it came to pass that after he had ascended into heaven the second time that he showed himself unto them, and had gone unto the Father--after having healed all their sick, and their lame, and opened the eyes of their blind, and unstopped the ears of the deaf, and even had done all manner of cures among them, and raised a man from the dead, and had shown forth his power unto them, and had ascended unto the Father--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-12-12', 'coc-bom-1908', 'III Nephi', 12, 12, 'And it came to pass that they did do all things even as Jesus had commanded them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-12-13', 'coc-bom-1908', 'III Nephi', 12, 13, 'And they who were baptized in the name of Jesus were called the church of Christ.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-12-14', 'coc-bom-1908', 'III Nephi', 12, 14, 'And it came to pass that as the disciples of Jesus were journeying, and were preaching the things which they had both heard and seen, and were baptizing in the name of Jesus, it came to pass that the disciples were gathered together and were united in mighty prayer and fasting.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-12-17', 'coc-bom-1908', 'III Nephi', 12, 17, 'And the Lord said unto them, Verily, verily, I say unto you, Why is it that the people should murmur and dispute because of this thing?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-12-22', 'coc-bom-1908', 'III Nephi', 12, 22, 'And if it so be that the church is built upon my gospel, then will the Father show forth his own works in it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-12-27', 'coc-bom-1908', 'III Nephi', 12, 27, 'That as I have been lifted up by men, even so should men be lifted up by the Father to stand before me to be judged of their works, whether they be good or whether they be evil.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-12-32', 'coc-bom-1908', 'III Nephi', 12, 32, 'Therefore, nothing entereth into his rest, save it be those who have washed their garments in my blood because of their faith, and the repentance of all their sins, and their faithfulness unto the end.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-12-33', 'coc-bom-1908', 'III Nephi', 12, 33, 'Now this is the commandment: Repent, all ye ends of the earth, and come unto me, and be baptized in my name, that ye may be sanctified by the reception of the Holy Ghost, that ye may stand spotless before me at the last day.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-13-5', 'coc-bom-1908', 'III Nephi', 13, 5, 'Therefore, what manner of men ought ye to be? Verily, I say unto you, Even as I am. And now, I go unto the Father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-13-10', 'coc-bom-1908', 'III Nephi', 13, 10, 'And in that day will I visit them, even in turning their works upon their own heads.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-13-12', 'coc-bom-1908', 'III Nephi', 13, 12, 'And it came to pass when Jesus had said these words, he spake unto his disciples, one by one, saying unto them, What is it that ye desire of me after that I am gone to the Father?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-13-13', 'coc-bom-1908', 'III Nephi', 13, 13, 'And they all spake, save it were three, saying, We desire that after we have lived unto the age of man, that our ministry, wherein thou hast called us, may have an end, that we may speedily come unto thee in thy kingdom.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-13-15', 'coc-bom-1908', 'III Nephi', 13, 15, 'And when he had spoken unto them, he turned himself unto the three and said unto them, What will ye that I should do unto you when I am gone unto the Father?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-13-16', 'coc-bom-1908', 'III Nephi', 13, 16, 'And they sorrowed in their hearts, for they durst not speak unto him the thing which they desired.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-13-18', 'coc-bom-1908', 'III Nephi', 13, 18, 'Therefore, more blessed are ye, for ye shall never taste of death, but ye shall live to behold all the doings of the Father unto the children of men, even until all things shall be fulfilled according to the will of the Father, when I shall come in my glory with the powers of heaven.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-13-25', 'coc-bom-1908', 'III Nephi', 13, 25, 'And behold, the heavens were opened, and they were caught up into heaven and saw and heard unspeakable things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-13-33', 'coc-bom-1908', 'III Nephi', 13, 33, 'And thrice they were cast into a furnace and received no harm.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-13-37', 'coc-bom-1908', 'III Nephi', 13, 37, 'And now, I, Mormon, make an end of speaking concerning these things for a time.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-13-40', 'coc-bom-1908', 'III Nephi', 13, 40, 'They will also be among the Jews, and the Jews shall know them not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-13-44', 'coc-bom-1908', 'III Nephi', 13, 44, 'Yea, even among the Gentiles shall there be a great and marvelous work wrought by them before that judgment day.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-13-45', 'coc-bom-1908', 'III Nephi', 13, 45, 'And if ye had all the scriptures which give an account of all the marvelous works of Christ, ye would, according to the words of Christ, know that these things must surely come.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-13-46', 'coc-bom-1908', 'III Nephi', 13, 46, 'And wo be unto him that will not hearken unto the words of Jesus and also to them whom he hath chosen and sent among them,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-13-48', 'coc-bom-1908', 'III Nephi', 13, 48, 'For do ye suppose that ye can get rid of the justice of an offended God, who hath been trampled under feet of men, that thereby salvation might come?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-13-49', 'coc-bom-1908', 'III Nephi', 13, 49, 'And now, behold, as I spake concerning those whom the Lord had chosen, yea, even three who were caught up into the heavens, that I knew not whether they were cleansed from mortality to immortality.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-13-51', 'coc-bom-1908', 'III Nephi', 13, 51, 'Therefore, that they might not taste of death, there was a change wrought upon their bodies, that they might not suffer pain nor sorrow, save it were for the sins of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-13-62', 'coc-bom-1908', 'III Nephi', 13, 62, 'Therefore, ye need not suppose that ye can turn the right hand of the Lord unto the left, that he may not execute judgment unto the fulfilling of the covenant which he hath made unto the house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-14-2', 'coc-bom-1908', 'III Nephi', 14, 2, 'Turn, all ye Gentiles, from your wicked ways, and repent of your evil doings--of your lyings and deceivings, and of your whoredoms, and of your secret abominations and your idolatries, and of your murders and your priestcrafts, and your envyings and your strifes, and from all your wickedness and abominations--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:iii-nephi-14-3', 'coc-bom-1908', 'III Nephi', 14, 3, 'And come unto me, and be baptized in my name, that ye may receive a remission of your sins and be filled with the Holy Ghost, that ye may be numbered with my people who are of the house of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-4', 'coc-bom-1908', 'Alma', 1, 4, 'And he had gone about among the people, preaching to them that which he termed to be the word of God, bearing down against the church,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-5', 'coc-bom-1908', 'Alma', 1, 5, 'Declaring unto the people that every priest and teacher ought to become popular, and they ought not to labor with their own hands, but that they ought to be supported by the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-6', 'coc-bom-1908', 'Alma', 1, 6, 'And he also testified unto the people that all mankind should be saved at the last day, and that they need not fear nor tremble, but that they might lift up their heads and rejoice,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-9', 'coc-bom-1908', 'Alma', 1, 9, 'And he began to be lifted up in the pride of his heart, and to wear very costly apparel, yea, and even began to establish a church after the manner of his preaching.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-13', 'coc-bom-1908', 'Alma', 1, 13, 'Now because Gideon withstood him with the words of God, he was wroth with Gideon, and drew his sword, and began to smite him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-15', 'coc-bom-1908', 'Alma', 1, 15, 'And the man who slew him was taken by the people of the church and was brought before Alma to be judged according to the crime which he had committed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-16', 'coc-bom-1908', 'Alma', 1, 16, 'And it came to pass that he stood before Alma and pled for himself with much boldness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-17', 'coc-bom-1908', 'Alma', 1, 17, 'But Alma said unto him, Behold, this is the first time that priestcraft has been introduced among this people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-26', 'coc-bom-1908', 'Alma', 1, 26, 'And now, the law could have no power on any man for his belief.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-29', 'coc-bom-1908', 'Alma', 1, 29, 'Yea, they did persecute them and afflict them with all manner of words, and this because of their humility--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-30', 'coc-bom-1908', 'Alma', 1, 30, 'Because they were not proud in their own eyes and because they did impart the word of God, one with another, without money and without price.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-31', 'coc-bom-1908', 'Alma', 1, 31, 'Now there was a strict law among the people of the church that there should not any man belonging to the church arise and persecute those that did not belong to the church, and that there should be no persecution among themselves.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-34', 'coc-bom-1908', 'Alma', 1, 34, 'For the hearts of many were hardened, and their names were blotted out, that they were remembered no more among the people of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-35', 'coc-bom-1908', 'Alma', 1, 35, 'And also many withdrew themselves from among them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-37', 'coc-bom-1908', 'Alma', 1, 37, 'And when the priests left their labor to impart the word of God unto the people, the people also left their labors to hear the word of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-43', 'coc-bom-1908', 'Alma', 1, 43, 'And now, because of the steadiness of the church, they began to be exceeding rich, having abundance of all things whatsoever they stood in need--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-44', 'coc-bom-1908', 'Alma', 1, 44, 'An abundance of flocks, and herds, and fatlings of every kind, and also abundance of grain, and of gold, and of silver, and of precious things, and abundance of silk and fine twined linen, and all manner of good homely cloth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-47', 'coc-bom-1908', 'Alma', 1, 47, 'And thus they did prosper and become far more wealthy than those who did not belong to their church.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-48', 'coc-bom-1908', 'Alma', 1, 48, 'For those who did not belong to their church did indulge themselves in sorceries, and in idolatry or idleness, and in babblings, and in envyings and strife,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-49', 'coc-bom-1908', 'Alma', 1, 49, 'And wearing costly apparel, being lifted up in the pride of their own eyes--persecuting, lying, thieving, robbing, committing whoredoms, and murdering, and all manner of wickedness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-50', 'coc-bom-1908', 'Alma', 1, 50, 'Nevertheless, the law was put in force upon all those who did transgress it, inasmuch as it were possible.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-52', 'coc-bom-1908', 'Alma', 1, 52, 'Therefore, there was much peace among the people of Nephi until the fifth year of the reign of the judges.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-53', 'coc-bom-1908', 'Alma', 1, 53, 'And it came to pass in the commencement of the fifth year of their reign, there began to be a contention among the people, for a certain man, being called Amlici--he being a very cunning man, yea, a wise man, as to the wisdom of the world, he being after the order of the man that slew Gideon by the sword, who was executed according to the law--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-55', 'coc-bom-1908', 'Alma', 1, 55, 'Now this was alarming to the people of the church and also to all those who had not been drawn away after the persuasions of Amlici,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-56', 'coc-bom-1908', 'Alma', 1, 56, 'For they knew that according to their law that such things must be established by the voice of the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-60', 'coc-bom-1908', 'Alma', 1, 60, 'And it came to pass that the voice of the people came against Amlici, that he was not made king over the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-62', 'coc-bom-1908', 'Alma', 1, 62, 'And it came to pass that they gathered themselves together and did consecrate Amlici to be their king.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-67', 'coc-bom-1908', 'Alma', 1, 67, 'And thus they were prepared to meet the Amlicites at the time of their coming.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-68', 'coc-bom-1908', 'Alma', 1, 68, 'And there were appointed captains, and higher captains, and chief captains, according to their numbers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-73', 'coc-bom-1908', 'Alma', 1, 73, 'Nevertheless, the Lord did strengthen the hand of the Nephites, that they slew the Amlicites with a great slaughter, that they began to flee before them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-75', 'coc-bom-1908', 'Alma', 1, 75, 'And there was slain of the Nephites six thousand five hundred sixty and two souls.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-77', 'coc-bom-1908', 'Alma', 1, 77, 'And Alma sent spies to follow the remnant of the Amlicites, that he might know of their plans and their plots, whereby he might guard himself against them, that he might preserve his people from being destroyed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-79', 'coc-bom-1908', 'Alma', 1, 79, 'And it came to pass that on the morrow they returned into the camp of the Nephites in great haste, being greatly astonished and struck with much fear, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-83', 'coc-bom-1908', 'Alma', 1, 83, 'And it came to pass that the people of Nephi took their tents and departed out of the valley of Gideon towards their city, which was the city of Zarahemla.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-85', 'coc-bom-1908', 'Alma', 1, 85, 'Nevertheless, the Nephites, being strengthened by the hand of the Lord, having prayed mightily to him that he would deliver them out of the hands of their enemies--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-88', 'coc-bom-1908', 'Alma', 1, 88, 'And it came to pass that Alma, being a man of God, being exercised with much faith, cried, saying, O Lord, have mercy and spare my life, that I may be an instrument in thy hands to save and protect this people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-92', 'coc-bom-1908', 'Alma', 1, 92, 'And thus he cleared the ground, or rather the bank, which was on the west of the river Sidon, throwing the bodies of the Lamanites who had been slain into the waters of Sidon, that thereby his people might have room to cross and contend with the Lamanites and the Amlicites on the west side of the river Sidon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-96', 'coc-bom-1908', 'Alma', 1, 96, 'And it was that part of the wilderness which was infested by wild and ravenous beasts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-98', 'coc-bom-1908', 'Alma', 1, 98, 'And it came to pass that the Nephites who were not slain by the weapons of war, after having buried those who had been slain (now the number of the slain were not numbered because of the greatness of their number), after they had finished burying their dead, they all returned to their lands, and to their houses, and their wives, and their children.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-100', 'coc-bom-1908', 'Alma', 1, 100, 'And also many of their fields of grain were destroyed, for they were trodden down by the hosts of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-104', 'coc-bom-1908', 'Alma', 1, 104, 'And the skins of the Lamanites were dark, according to the mark which was set upon their fathers, which was a curse upon them because of their transgression and their rebellion against their brethren, who consisted of Nephi, Jacob, and Joseph, and Sam, who were just and holy men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-106', 'coc-bom-1908', 'Alma', 1, 106, 'And this was done that their seed might be distinguished from the seed of their brethren, that thereby the Lord God might preserve his people, that they might not mix and believe in incorrect traditions which would prove their destruction.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-107', 'coc-bom-1908', 'Alma', 1, 107, 'And it came to pass that whosoever did mingle his seed with that of the Lamanites did bring the same curse upon his seed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-108', 'coc-bom-1908', 'Alma', 1, 108, 'Therefore, whosoever suffered himself to be led away by the Lamanites was called under that head, and there was a mark set upon him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-110', 'coc-bom-1908', 'Alma', 1, 110, 'And it is they who have kept the records, which are true of their people and also of the people of the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-112', 'coc-bom-1908', 'Alma', 1, 112, 'Thus the word of God is fulfilled, for these are the words which he said to Nephi:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-114', 'coc-bom-1908', 'Alma', 1, 114, 'And again, I will set a mark upon him that mingleth his seed with thy brethren, that they may be cursed also.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-115', 'coc-bom-1908', 'Alma', 1, 115, 'And again, I will set a mark upon him that fighteth against thee and thy seed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-120', 'coc-bom-1908', 'Alma', 1, 120, 'And even so doth every man that is cursed bring upon himself his own condemnation.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-121', 'coc-bom-1908', 'Alma', 1, 121, 'Now it came to pass that not many days after the battle which was fought in the land of Zarahemla by the Lamanites and the Amlicites, that there was another army of the Lamanites came in upon the people of Nephi in the same place where the first army met the Amlicites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-122', 'coc-bom-1908', 'Alma', 1, 122, 'And it came to pass that there was an army sent to drive them out of their land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-125', 'coc-bom-1908', 'Alma', 1, 125, 'And then they returned again and began to establish peace in the land, being troubled no more for a time with their enemies.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-127', 'coc-bom-1908', 'Alma', 1, 127, 'And in one year were thousands and tens of thousands of souls sent to the eternal world,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-128', 'coc-bom-1908', 'Alma', 1, 128, 'That they might reap their rewards according to their works, whether they were good or whether they were bad--to reap eternal happiness or eternal misery according to the spirit which they listed to obey, whether it be a good spirit or a bad one.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-1-130', 'coc-bom-1908', 'Alma', 1, 130, 'And thus ended the fifth year of the reign of the judges.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-2-5', 'coc-bom-1908', 'Alma', 2, 5, 'Yea, they were baptized by the hand of Alma, who had been consecrated the high priest over the people of the church by the hand of his father Alma.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-2-6', 'coc-bom-1908', 'Alma', 2, 6, 'And it came to pass in the seventh year of the reign of the judges, there were about three thousand five hundred souls that united themselves to the church of God and were baptized.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-2-8', 'coc-bom-1908', 'Alma', 2, 8, 'And it came to pass in the eighth year of the reign of the judges, that the people of the church began to wax proud because of their exceeding riches, and their fine silks, and their fine twined linen,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-2-10', 'coc-bom-1908', 'Alma', 2, 10, 'And in all these things were they lifted up in the pride of their eyes, for they began to wear very costly apparel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-2-12', 'coc-bom-1908', 'Alma', 2, 12, 'Yea, many of them were sorely grieved, for the wickedness which they saw had begun to be among their people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-2-13', 'coc-bom-1908', 'Alma', 2, 13, 'For they saw and beheld with great sorrow that the people of the church began to be lifted up in the pride of their eyes and to set their hearts upon riches and upon the vain things of the world,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-2-16', 'coc-bom-1908', 'Alma', 2, 16, 'Yea, there were envyings, and strifes, and malice, and persecutions, and pride, even to exceed the pride of those who did not belong to the church of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-2-19', 'coc-bom-1908', 'Alma', 2, 19, 'Yea, he saw great inequality among the people, some lifting themselves up with their pride, despising others, turning their backs upon the needy, and the naked, and those who were hungry, and those who were athirst, and those who were sick and afflicted.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-2-20', 'coc-bom-1908', 'Alma', 2, 20, 'Now this was a great cause for lamentations among the people, while others were abasing themselves, succoring those who stood in need of their succor, such as imparting their substance to the poor and the needy, feeding the hungry, and suffering all manner of afflictions for Christ''s sake, who should come according to the spirit of prophecy, looking forward to that day, thus retaining a remission of their sins,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-2-21', 'coc-bom-1908', 'Alma', 2, 21, 'Being filled with great joy because of the resurrection of the dead, according to the will, and power, and deliverance of Jesus Christ from the bands of death.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-2-23', 'coc-bom-1908', 'Alma', 2, 23, 'And he selected a wise man who was among the elders of the church and gave him power according to the voice of the people, that he might have power to enact laws according to the laws which had been given and to put them in force according to the wickedness and the crimes of the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-2-26', 'coc-bom-1908', 'Alma', 2, 26, 'And this he did, that he himself might go forth among his people, or among the people of Nephi, that he might preach the word of God unto them, to stir them up in remembrance of their duty,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-2-27', 'coc-bom-1908', 'Alma', 2, 27, 'And that he might pull down, by the word of God, all the pride, and craftiness, and all the contentions which were among his people--seeing no way that he might reclaim them, save it were in bearing down in pure testimony against them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-2-28', 'coc-bom-1908', 'Alma', 2, 28, 'And thus in the commencement of the ninth year of the reign of the judges over the people of Nephi, Alma delivered up the judgment seat to Nephihah and confined himself wholly to the high priesthood of the holy order of God, to the testimony of the word, according to the spirit of revelation and prophecy.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-1', 'coc-bom-1908', 'Alma', 3, 1, 'Now it came to pass that Alma began to deliver the word of God unto the people, first in the land of Zarahemla and from thence throughout all the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-2', 'coc-bom-1908', 'Alma', 3, 2, 'And these are the words which he spake to the people in the church which was established in the city of Zarahemla, according to his own record, saying:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-3', 'coc-bom-1908', 'Alma', 3, 3, 'I, Alma, having been consecrated by my father, Alma, to be a high priest over the church of God, he having power and authority from God to do these things, behold, I say unto you that he began to establish a church in the land which was in the borders of Nephi,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-5', 'coc-bom-1908', 'Alma', 3, 5, 'And behold, I say unto you, They were delivered out of the hands of the people of King Noah by the mercy and power of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-7', 'coc-bom-1908', 'Alma', 3, 7, 'And we were brought into this land, and here we began to establish the church of God throughout this land also.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-8', 'coc-bom-1908', 'Alma', 3, 8, 'And now, behold, I say unto you, my brethren, you that belong to this church, Have you sufficiently retained in remembrance the captivity of your fathers?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-9', 'coc-bom-1908', 'Alma', 3, 9, 'Yea, and have you sufficiently retained in remembrance his mercy and long-suffering towards them?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-10', 'coc-bom-1908', 'Alma', 3, 10, 'And moreover, have ye sufficiently retained in remembrance that he has delivered their souls from hell?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-13', 'coc-bom-1908', 'Alma', 3, 13, 'Yea, they were encircled about by the bands of death and the chains of hell, and an everlasting destruction did await them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-14', 'coc-bom-1908', 'Alma', 3, 14, 'And now, I ask of you, my brethren, Were they destroyed?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-15', 'coc-bom-1908', 'Alma', 3, 15, 'Behold, I say unto you, Nay, they were not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-16', 'coc-bom-1908', 'Alma', 3, 16, 'And again I ask, Were the bands of death broken? And the chains of hell which encircled them about, were they loosed?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-18', 'coc-bom-1908', 'Alma', 3, 18, 'And I say unto you that they are saved.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-19', 'coc-bom-1908', 'Alma', 3, 19, 'And now, I ask of you, On what conditions are they saved? Yea, what grounds had they to hope for salvation?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-20', 'coc-bom-1908', 'Alma', 3, 20, 'What is the cause of their being loosed from the bands of death, yea, and also the chains of hell?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-21', 'coc-bom-1908', 'Alma', 3, 21, 'Behold, I can tell you: Did not my father Alma believe in the words which were delivered by the mouth of Abinadi? And was he not a holy prophet?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-22', 'coc-bom-1908', 'Alma', 3, 22, 'Did he not speak the words of God, and my father Alma believe them?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-23', 'coc-bom-1908', 'Alma', 3, 23, 'And according to his faith there was a mighty change wrought in his heart.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-24', 'coc-bom-1908', 'Alma', 3, 24, 'Behold, I say unto you that this is all true.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-27', 'coc-bom-1908', 'Alma', 3, 27, 'And now, behold, I ask of you, my brethren of the church, Have ye spiritually been born of God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-28', 'coc-bom-1908', 'Alma', 3, 28, 'Have ye received his image in your countenances?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-29', 'coc-bom-1908', 'Alma', 3, 29, 'Have ye experienced this mighty change in your hearts?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-30', 'coc-bom-1908', 'Alma', 3, 30, 'Do ye exercise faith in the redemption of him who created you?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-31', 'coc-bom-1908', 'Alma', 3, 31, 'Do you look forward with an eye of faith and view this mortal body raised in immortality and this corruption raised in incorruption, to stand before God to be judged according to the deeds which have been done in the mortal body?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-32', 'coc-bom-1908', 'Alma', 3, 32, 'I say unto you, Can you imagine to yourselves that ye hear the voice of the Lord saying unto you in that day, Come unto me, ye blessed, for behold, your works have been the works of righteousness upon the face of the earth?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-33', 'coc-bom-1908', 'Alma', 3, 33, 'Or do ye imagine to yourselves that ye can lie unto the Lord in that day and say, Lord, our works have been righteous works upon the face of the earth--and that he will save you?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-34', 'coc-bom-1908', 'Alma', 3, 34, 'Or otherwise, can ye imagine yourselves brought before the tribunal of God, with your souls filled with guilt and remorse, having a remembrance of all your guilt,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-35', 'coc-bom-1908', 'Alma', 3, 35, 'Yea, a perfect remembrance of all your wickedness--yea, a remembrance that ye have set at defiance the commandments of God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-36', 'coc-bom-1908', 'Alma', 3, 36, 'I say unto you, Can ye look up to God at that day with a pure heart and clean hands?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-37', 'coc-bom-1908', 'Alma', 3, 37, 'I say unto you, Can you look up, having the image of God engraven upon your countenances?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-38', 'coc-bom-1908', 'Alma', 3, 38, 'I say unto you, Can ye think of being saved when you have yielded yourselves to become subjects to the devil?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-40', 'coc-bom-1908', 'Alma', 3, 40, 'Yea, his garments must be purified until they are cleansed from all stain, through the blood of him of whom it has been spoken by our fathers who should come to redeem his people from their sins.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-41', 'coc-bom-1908', 'Alma', 3, 41, 'And now, I ask of you, my brethren, How will any of you feel if ye shall stand before the bar of God, having your garments stained with blood and all manner of filthiness?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-42', 'coc-bom-1908', 'Alma', 3, 42, 'Behold, what will these things testify against you?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-43', 'coc-bom-1908', 'Alma', 3, 43, 'Behold, will they not testify that ye are murderers, yea, and also that ye are guilty of all manner of wickedness?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-44', 'coc-bom-1908', 'Alma', 3, 44, 'Behold, my brethren, do ye suppose that such an one can have a place to sit down in the kingdom of God, with Abraham, with Isaac, and with Jacob, and also all the holy prophets, whose garments are cleansed and are spotless, pure, and white?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-46', 'coc-bom-1908', 'Alma', 3, 46, 'And now, behold, I say unto you, my brethren, If ye have experienced a change of heart, and if ye have felt to sing the song of redeeming love, I would ask, Can ye feel so now?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-47', 'coc-bom-1908', 'Alma', 3, 47, 'Have ye walked, keeping yourselves blameless before God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-48', 'coc-bom-1908', 'Alma', 3, 48, 'Could ye say, if ye were called to die at this time, within yourselves, that ye have been sufficiently humble--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-49', 'coc-bom-1908', 'Alma', 3, 49, 'That your garments have been cleansed and made white, through the blood of Christ, who will come to redeem his people from their sins?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-50', 'coc-bom-1908', 'Alma', 3, 50, 'Behold, are ye stripped of pride? I say unto you, If ye are not, ye are not prepared to meet God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-51', 'coc-bom-1908', 'Alma', 3, 51, 'Behold, ye must prepare quickly, for the kingdom of heaven is soon at hand, and such an one hath not eternal life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-52', 'coc-bom-1908', 'Alma', 3, 52, 'Behold, I say, Is there one among you who is not stripped of envy?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-54', 'coc-bom-1908', 'Alma', 3, 54, 'And again I say unto you, Is there one among you that doth make a mock of his brother or that heapeth upon him persecutions?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-60', 'coc-bom-1908', 'Alma', 3, 60, 'For behold, the time is at hand that whosoever bringeth forth not good fruit, or whosoever doeth not the works of righteousness, the same have cause to wail and mourn.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-61', 'coc-bom-1908', 'Alma', 3, 61, 'O ye workers of iniquity, ye that are puffed up in the vain things of the world, ye that have professed to have known the ways of righteousness, nevertheless, have gone astray, as sheep having no shepherd--notwithstanding a shepherd hath called after you and is still calling after you, but ye will not hearken unto his voice--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-63', 'coc-bom-1908', 'Alma', 3, 63, 'And if ye will not hearken unto the voice of the good shepherd, to the name by which ye are called, behold, ye are not the sheep of the good shepherd.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-64', 'coc-bom-1908', 'Alma', 3, 64, 'And now, if ye are not the sheep of the good shepherd, of what fold are ye?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-67', 'coc-bom-1908', 'Alma', 3, 67, 'For I say unto you that whatsoever is good cometh from God, and whatsoever is evil cometh from the devil.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-72', 'coc-bom-1908', 'Alma', 3, 72, 'For behold, I have spoken unto you plain, that ye cannot err, or have spoken according to the commandments of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-74', 'coc-bom-1908', 'Alma', 3, 74, 'Yea, I am commanded to stand and testify unto this people the things which have been spoken by our fathers concerning the things which are to come.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-75', 'coc-bom-1908', 'Alma', 3, 75, 'And this is not all. Do ye not suppose that I know of these things myself?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-76', 'coc-bom-1908', 'Alma', 3, 76, 'Behold, I testify unto you that I do know that these things whereof I have spoken are true.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-77', 'coc-bom-1908', 'Alma', 3, 77, 'And how do ye suppose that I know of their surety?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-78', 'coc-bom-1908', 'Alma', 3, 78, 'Behold, I say unto you, They are made known unto me by the Holy Spirit of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-79', 'coc-bom-1908', 'Alma', 3, 79, 'Behold, I have fasted and prayed many days that I might know these things of myself.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-81', 'coc-bom-1908', 'Alma', 3, 81, 'And moreover, I say unto you that, as it has thus been revealed unto me, that the words which have been spoken by our fathers are true,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-82', 'coc-bom-1908', 'Alma', 3, 82, 'Even so, according to the spirit of prophecy which is in me, which is also by the manifestation of the Spirit of God, I say unto you that I know of myself that whatsoever I shall say unto you concerning that which is to come is true,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-83', 'coc-bom-1908', 'Alma', 3, 83, 'And I say unto you that I know that Jesus Christ shall come, yea, the Son, the Only Begotten of the Father, full of grace, and mercy, and truth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-84', 'coc-bom-1908', 'Alma', 3, 84, 'And behold, it is he that cometh to take away the sins of the world, yea, the sins of every man who steadfastly believeth on his name.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-91', 'coc-bom-1908', 'Alma', 3, 91, 'Behold, and remember, the Holy One hath spoken it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-92', 'coc-bom-1908', 'Alma', 3, 92, 'And now, my beloved brethren, I say unto you, Can ye withstand these sayings? Yea, can ye lay aside these things and trample the Holy One under your feet?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-93', 'coc-bom-1908', 'Alma', 3, 93, 'Yea, can ye be puffed up in the pride of your hearts? Yea, will ye still persist in the wearing of costly apparel and setting your hearts upon the vain things of the world, upon your riches?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-94', 'coc-bom-1908', 'Alma', 3, 94, 'Yea, will ye persist in supposing that ye are better one than another?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-95', 'coc-bom-1908', 'Alma', 3, 95, 'Yea, will ye persist in the persecutions of your brethren--who humble themselves and do walk after the holy order of God, wherewith they have been brought into this church, having been sanctified by the Holy Spirit? And they do bring forth works which are meet for repentance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-96', 'coc-bom-1908', 'Alma', 3, 96, 'Yea, and will you persist in turning your backs upon the poor and the needy and in withholding your substance from them?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-97', 'coc-bom-1908', 'Alma', 3, 97, 'And finally, all ye that will persist in your wickedness, I say unto you that these are they who shall be hewn down and cast into the fire, except they speedily repent.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-99', 'coc-bom-1908', 'Alma', 3, 99, 'And behold, their names shall be blotted out, that the names of the wicked shall not be numbered among the names of the righteous, that the word of God may be fulfilled, which saith, The names of the wicked shall not be mingled with the names of my people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-101', 'coc-bom-1908', 'Alma', 3, 101, 'And now, my brethren, What have ye to say against this?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-102', 'coc-bom-1908', 'Alma', 3, 102, 'I say unto you, If ye speak against it, it matters not, for the word of God must be fulfilled.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-103', 'coc-bom-1908', 'Alma', 3, 103, 'For what shepherd is there among you, having many sheep, doth not watch over them, that the wolves enter not and devour his flock?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-104', 'coc-bom-1908', 'Alma', 3, 104, 'And behold, if a wolf enter his flock, doth he not drive him out? Yea, and at the last, if he can, he will destroy him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-106', 'coc-bom-1908', 'Alma', 3, 106, 'And he commandeth you that ye suffer no ravenous wolf to enter among you, that ye may not be destroyed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-3-107', 'coc-bom-1908', 'Alma', 3, 107, 'And now, I, Alma, do command you in the language of him who hath commanded me, that ye observe to do the words which I have spoken unto you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-4-1', 'coc-bom-1908', 'Alma', 4, 1, 'And now, it came to pass that after Alma had made an end of speaking unto the people of the church which was established in the city of Zarahemla, he ordained priests and elders, by laying on his hands according to the order of God, to preside and watch over the church.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-4-2', 'coc-bom-1908', 'Alma', 4, 2, 'And it came to pass that whosoever did not belong to the church, who repented of their sins, were baptized unto repentance and were received into the church.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-4-3', 'coc-bom-1908', 'Alma', 4, 3, 'And it also came to pass that whosoever did belong to the church, that did not repent of their wickedness and humble themselves before God--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-4-6', 'coc-bom-1908', 'Alma', 4, 6, 'Nevertheless, the children of God were commanded that they should gather themselves together oft and join in fasting and mighty prayer in behalf of the welfare of the souls of those who knew not God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-4-7', 'coc-bom-1908', 'Alma', 4, 7, 'And now, it came to pass that when Alma had made these regulations, he departed from them, yea, from the church which was in the city of Zarahemla,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-4-8', 'coc-bom-1908', 'Alma', 4, 8, 'And went over upon the east of the river Sidon, into the valley of Gideon, there having been a city built which was called the city of Gideon, which was in the valley that was called Gideon, being called after the man who was slain by the hand of Nehor with the sword.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-4-9', 'coc-bom-1908', 'Alma', 4, 9, 'And Alma went and began to declare the word of God unto the church which was established in the valley of Gideon, according to the revelation of the truth of the word which had been spoken by his fathers,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-4-10', 'coc-bom-1908', 'Alma', 4, 10, 'And according to the spirit of prophecy which was in him--according to the testimony of Jesus Christ, the Son of God, who should come to redeem his people from their sins--and the holy order by which he was called. And thus it is written. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-5-1', 'coc-bom-1908', 'Alma', 5, 1, 'Behold, my beloved brethren, seeing that I have been permitted to come unto you, therefore, I attempt to address you in my language,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-5-4', 'coc-bom-1908', 'Alma', 5, 4, 'And behold, I have come, having great hopes and much desire that I should find that ye had humbled yourselves before God and that ye had continued in the supplicating of his grace, that I should find that ye were blameless before him,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-5-5', 'coc-bom-1908', 'Alma', 5, 5, 'That I should find that ye were not in the awful dilemma that our brethren were in at Zarahemla.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-5-6', 'coc-bom-1908', 'Alma', 5, 6, 'But blessed be the name of God, that he hath given me to know--yea, hath given unto me the exceeding great joy of knowing--that they are established again in the way of his righteousness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-5-9', 'coc-bom-1908', 'Alma', 5, 9, 'For behold, my joy cometh over them after wading through much afflictions and sorrow.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-5-12', 'coc-bom-1908', 'Alma', 5, 12, 'Yea, I trust that you do not worship idols, but that ye do worship the true and the living God and that ye look forward for the remission of your sins with an everlasting faith which is to come.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-5-14', 'coc-bom-1908', 'Alma', 5, 14, 'For behold, the time is not far distant that the Redeemer liveth and cometh among his people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-5-18', 'coc-bom-1908', 'Alma', 5, 18, 'For behold, the kingdom of heaven is at hand, and the Son of God cometh upon the face of the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-5-22', 'coc-bom-1908', 'Alma', 5, 22, 'And he will take upon him their infirmities, that his bowels may be filled with mercy, according to the flesh, that he may know according to the flesh how to succor his people according to their infirmities.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-5-27', 'coc-bom-1908', 'Alma', 5, 27, 'Yea, come, and go forth, and show unto your God that ye are willing to repent of your sins, and enter into a covenant with him to keep his commandments, and witness it unto him this day by going into the waters of baptism.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-5-28', 'coc-bom-1908', 'Alma', 5, 28, 'And whosoever doeth this and keepeth the commandments of God from thenceforth, the same will remember that I say unto him, yea, he will remember that I have said unto him, he shall have eternal life, according to the testimony of the Holy Spirit, which testifieth in me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-5-29', 'coc-bom-1908', 'Alma', 5, 29, 'And now, my beloved brethren, do you believe these things?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-5-31', 'coc-bom-1908', 'Alma', 5, 31, 'And now, because your faith is strong concerning that, yea, concerning the things which I have spoken, great is my joy.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-5-32', 'coc-bom-1908', 'Alma', 5, 32, 'For as I said unto you from the beginning, that I had much desire that ye were not in the state of dilemma like your brethren, even so I have found that my desires have been gratified.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-5-37', 'coc-bom-1908', 'Alma', 5, 37, 'Therefore, I say unto you, The time shall come, yea, and it shall be at the last day, that he who is filthy shall remain in his filthiness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-5-38', 'coc-bom-1908', 'Alma', 5, 38, 'And now, my beloved brethren, I have said these things unto you that I might awaken you to a sense of your duty to God, that ye may walk blameless before him, that ye may walk after the holy order of God, after which ye have been received.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-5-39', 'coc-bom-1908', 'Alma', 5, 39, 'And now, I would that ye should be humble, and be submissive, and gentle, easy to be entreated, full of patience and long-suffering, being temperate in all things, being diligent in keeping the commandments of God at all times,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-5-40', 'coc-bom-1908', 'Alma', 5, 40, 'Asking for whatsoever things ye stand in need, both spiritual and temporal, always returning thanks unto God for whatsoever things ye do receive.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-5-42', 'coc-bom-1908', 'Alma', 5, 42, 'And may the Lord bless you and keep your garments spotless, that ye may at last be brought to sit down with Abraham, Isaac, and Jacob, and the holy prophets who have been ever since the world began, having your garments spotless, even as their garments are spotless in the kingdom of heaven, to go no more out.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-5-44', 'coc-bom-1908', 'Alma', 5, 44, 'And now, may the peace of God rest upon you, and upon your houses and lands, and upon your flocks and herds, and all that you possess, your women and your children, according to your faith and good works, from this time forth and forever. And thus I have spoken. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-6-2', 'coc-bom-1908', 'Alma', 6, 2, 'Yea, he returned to his own house at Zarahemla to rest himself from the labors which he had performed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-6-3', 'coc-bom-1908', 'Alma', 6, 3, 'And thus ended the ninth year of the reign of the judges over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-6-6', 'coc-bom-1908', 'Alma', 6, 6, 'And it came to pass that the people came to him throughout all the borders of the land which was by the wilderness side.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-6-9', 'coc-bom-1908', 'Alma', 6, 9, 'And it came to pass that when Alma had come to the city of Ammonihah, he began to preach the word of God unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-6-13', 'coc-bom-1908', 'Alma', 6, 13, 'And we are not of thy church, and we do not believe in such foolish traditions.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-6-16', 'coc-bom-1908', 'Alma', 6, 16, 'Now when the people had said this, and had withstood all his words, and reviled him, and spit upon him, and caused that he should be cast out of their city, he departed thence and took his journey towards the city which was called Aaron.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-6-17', 'coc-bom-1908', 'Alma', 6, 17, 'And it came to pass that while he was journeying thither, being weighed down with sorrow, wading through much tribulation and anguish of soul because of the wickedness of the people who were in the city of Ammonihah,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-6-19', 'coc-bom-1908', 'Alma', 6, 19, 'For thou hast been faithful in keeping the commandments of God from the time which thou received thy first message from him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-6-21', 'coc-bom-1908', 'Alma', 6, 21, 'Yea, say unto them, except they repent, the Lord God will destroy them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-6-22', 'coc-bom-1908', 'Alma', 6, 22, 'For behold, they do study at this time that they may destroy the liberty of thy people (for thus saith the Lord) which is contrary to the statutes, and judgments, and commandments which he has given unto his people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-6-23', 'coc-bom-1908', 'Alma', 6, 23, 'Now it came to pass that after Alma had received his message from the angel of the Lord, he returned speedily to the land of Ammonihah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-6-24', 'coc-bom-1908', 'Alma', 6, 24, 'And he entered the city by another way, yea, by the way which is on the south of the city of Ammonihah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-6-25', 'coc-bom-1908', 'Alma', 6, 25, 'And as he entered the city, he was an hungered, and he said to a man, Will ye give to a humble servant of God something to eat?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-6-30', 'coc-bom-1908', 'Alma', 6, 30, 'And after he had eaten and was filled, he said unto Amulek, I am Alma and am the high priest over the church of God throughout the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-6-33', 'coc-bom-1908', 'Alma', 6, 33, 'But behold, I have been commanded that I should turn again and prophesy unto this people, yea, and to testify against them concerning their iniquities.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-6-35', 'coc-bom-1908', 'Alma', 6, 35, 'And Alma tarried many days with Amulek before he began to preach unto the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-6-36', 'coc-bom-1908', 'Alma', 6, 36, 'And it came to pass that the people did wax more gross in their iniquities.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-6-40', 'coc-bom-1908', 'Alma', 6, 40, 'Nevertheless, they did not exercise their power until they were bound in bands and cast into prison.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-6-41', 'coc-bom-1908', 'Alma', 6, 41, 'Now this was done that the Lord might show forth his power in them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-6-42', 'coc-bom-1908', 'Alma', 6, 42, 'And it came to pass that they went forth and began to preach and to prophesy unto the people according to the spirit and power which the Lord had given them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-1', 'coc-bom-1908', 'Alma', 7, 1, 'And again, I, Alma, having been commanded of God that I should take Amulek and go forth and preach again unto this people, or the people who were in the city of Ammonihah, it came to pass as I began to preach unto them, they began to contend with me, saying, Who art thou?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-2', 'coc-bom-1908', 'Alma', 7, 2, 'Suppose ye that we shall believe the testimony of one man although he should preach unto us that the earth should pass away?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-3', 'coc-bom-1908', 'Alma', 7, 3, 'Now they understood not the words which they spake, for they knew not that the earth should pass away.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-4', 'coc-bom-1908', 'Alma', 7, 4, 'And they said also, We will not believe thy words if thou shouldest prophesy that this great city should be destroyed in one day.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-5', 'coc-bom-1908', 'Alma', 7, 5, 'Now they knew not that God could do such marvelous works, for they were a hard-hearted and stiff-necked people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-6', 'coc-bom-1908', 'Alma', 7, 6, 'And they said, Who is God, that sendeth no more authority than one man among this people to declare unto them the truth of such great and marvelous things?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-9', 'coc-bom-1908', 'Alma', 7, 9, 'Do ye not remember that our father Lehi was brought out of Jerusalem by the hand of God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-10', 'coc-bom-1908', 'Alma', 7, 10, 'Do ye not remember that they were all led by him through the wilderness?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-11', 'coc-bom-1908', 'Alma', 7, 11, 'And have ye forgotten so soon how many times he delivered our fathers out of the hands of their enemies, and preserved them from being destroyed, even by the hands of their own brethren?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-12', 'coc-bom-1908', 'Alma', 7, 12, 'Yea, and if it had not been for his matchless power, and his mercy, and his long-suffering towards us, we should unavoidably have been cut off from the face of the earth long before this period of time and perhaps been consigned to a state of endless misery and wo.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-15', 'coc-bom-1908', 'Alma', 7, 15, 'Behold, do ye not remember the words which he spake unto Lehi, saying that, Inasmuch as ye shall keep my commandments, ye shall prosper in the land?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-16', 'coc-bom-1908', 'Alma', 7, 16, 'And again it is said that, Inasmuch as ye will not keep my commandments, ye shall be cut off from the presence of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-17', 'coc-bom-1908', 'Alma', 7, 17, 'Now I would that ye should remember that inasmuch as the Lamanites have not kept the commandments of God, they have been cut off from the presence of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-18', 'coc-bom-1908', 'Alma', 7, 18, 'Now we see that the word of the Lord has been verified in this thing, and the Lamanites have been cut off from his presence from the beginning of their transgressions in the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-19', 'coc-bom-1908', 'Alma', 7, 19, 'Nevertheless, I say unto you that it shall be more tolerable for them in the day of judgment than for you if ye remain in your sins,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-23', 'coc-bom-1908', 'Alma', 7, 23, 'And many of them will be saved, for the Lord will be merciful unto all who call on his name.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-35', 'coc-bom-1908', 'Alma', 7, 35, 'And now, behold, I say unto you that if this people, who have received so many blessings from the hand of the Lord, should transgress, contrary to the light and knowledge which they do have,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-36', 'coc-bom-1908', 'Alma', 7, 36, 'I say unto you that if this be the case, that if they should fall into transgression, that it would be far more tolerable for the Lamanites than for them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-37', 'coc-bom-1908', 'Alma', 7, 37, 'For behold, the promises of the Lord are extended to the Lamanites, but they are not unto you if ye transgress.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-38', 'coc-bom-1908', 'Alma', 7, 38, 'For has not the Lord expressly promised and firmly decreed that if ye will rebel against him, that ye shall utterly be destroyed from off the face of the earth?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-41', 'coc-bom-1908', 'Alma', 7, 41, 'And behold, he cometh to redeem those who will be baptized unto repentance through faith on his name.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-42', 'coc-bom-1908', 'Alma', 7, 42, 'Therefore, prepare ye the way of the Lord, for the time is at hand that all men shall reap a reward of their works according to that which they have been.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-44', 'coc-bom-1908', 'Alma', 7, 44, 'And if they have been evil, they shall reap the damnation of their souls according to the power and captivation of the devil.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-45', 'coc-bom-1908', 'Alma', 7, 45, 'Now behold, this is the voice of the angel crying unto the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-46', 'coc-bom-1908', 'Alma', 7, 46, 'And now, my beloved brethren, for ye are my brethren, and ye had ought to be beloved, and ye had ought to bring forth works which are meet for repentance, seeing that your hearts have been grossly hardened against the word of God and seeing that ye are a lost and a fallen people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-49', 'coc-bom-1908', 'Alma', 7, 49, 'But it came to pass that the Lord did not suffer them that they should take me at that time and cast me into prison.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-7-50', 'coc-bom-1908', 'Alma', 7, 50, 'And it came to pass that Amulek went, and stood forth, and began to preach unto them also.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-2', 'coc-bom-1908', 'Alma', 8, 2, 'And it was that same Aminadi who interpreted the writing which was upon the wall of the temple, which was written by the finger of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-3', 'coc-bom-1908', 'Alma', 8, 3, 'And Aminadi was a descendant of Nephi, who was the son of Lehi, who came out of the land of Jerusalem, who was a descendant of Manasseh, who was the son of Joseph, who was sold into Egypt by the hands of his brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-6', 'coc-bom-1908', 'Alma', 8, 6, 'Nevertheless, after all this, I never have known much of the ways of the Lord and his mysteries and marvelous power.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-9', 'coc-bom-1908', 'Alma', 8, 9, 'Therefore, I went on rebelling against God in the wickedness of my heart, even until the fourth day of this seventh month, which is in the tenth year of the reign of the judges.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-12', 'coc-bom-1908', 'Alma', 8, 12, 'And it came to pass that I obeyed the voice of the angel and returned towards my house.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-17', 'coc-bom-1908', 'Alma', 8, 17, 'Yea, even all my kindred hath he blessed, and the blessing of the Lord hath rested upon us according to the words which he spake.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-19', 'coc-bom-1908', 'Alma', 8, 19, 'Nevertheless, there were some among them who thought to question them, that by their cunning devices they might catch them in their words, that they might find witness against them, that they might deliver them to the judges,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-20', 'coc-bom-1908', 'Alma', 8, 20, 'That they might be judged according to the law, and that they might be slain or cast into prison according to the crime which they could make appear or witness against them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-21', 'coc-bom-1908', 'Alma', 8, 21, 'Now it was those men who sought to destroy them who were lawyers, who were hired or appointed by the people to administer the law at their times of trials, or at the trials of the crimes of the people before the judges.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-23', 'coc-bom-1908', 'Alma', 8, 23, 'And it came to pass that they began to question Amulek, that thereby they might make him cross his words, or contradict the words which he should speak.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-24', 'coc-bom-1908', 'Alma', 8, 24, 'Now they knew not that Amulek could know of their designs.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-27', 'coc-bom-1908', 'Alma', 8, 27, 'Yea, well did Mosiah say--who was our last king, when he was about to deliver up the kingdom, having no one to confer it upon, causing that this people should be governed by their own voices--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-28', 'coc-bom-1908', 'Alma', 8, 28, 'Yea, well did he say, that if the time should come that the voice of this people should choose iniquity, that is, if the time should come that this people should fall into transgression, they would be ripe for destruction.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-30', 'coc-bom-1908', 'Alma', 8, 30, 'Yea, well doth he cry by the voice of his angels that, I will come down among my people with equity and justice in my hands.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-35', 'coc-bom-1908', 'Alma', 8, 35, 'And now, it came to pass that the people were more angry with Amulek, and they cried out, saying, This man doth revile against our laws, which are just, and our wise lawyers whom we have selected.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-36', 'coc-bom-1908', 'Alma', 8, 36, 'But Amulek stretched forth his hand and cried the mightier unto them, saying, O ye wicked and perverse generation! Why hath Satan got such great hold upon your hearts?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-37', 'coc-bom-1908', 'Alma', 8, 37, 'Why will ye yield yourselves unto him that he may have power over you, to blind your eyes, that ye will not understand the words which are spoken according to their truth?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-38', 'coc-bom-1908', 'Alma', 8, 38, 'For behold, have I testified against your law?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-40', 'coc-bom-1908', 'Alma', 8, 40, 'And now, behold, I say unto you that the foundation of the destruction of this people is beginning to be laid by the unrighteousness of your lawyers and your judges.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-42', 'coc-bom-1908', 'Alma', 8, 42, 'And now, he says that he has not spoken against it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-43', 'coc-bom-1908', 'Alma', 8, 43, 'And again, he has reviled against our lawyers, and our judges, etc.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-44', 'coc-bom-1908', 'Alma', 8, 44, 'And it came to pass that the lawyers put it into their hearts that they should remember these things against him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-45', 'coc-bom-1908', 'Alma', 8, 45, 'And there was one among them whose name was Zeezrom.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-46', 'coc-bom-1908', 'Alma', 8, 46, 'Now he was the foremost to accuse Amulek and Alma, he being one of the most expert among them, having much business to do among the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-48', 'coc-bom-1908', 'Alma', 8, 48, 'Now it was in the law of Mosiah that every man who was a judge of the law, or those who were appointed to be judges, should receive wages according to the time which they labored to judge those who were brought before them to be judged.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-51', 'coc-bom-1908', 'Alma', 8, 51, 'And he judged the man according to the law and the evidences which were brought against him, and thus the man was compelled to pay that which he owed, or be striped, or be cast out from among the people as a thief and a robber.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-53', 'coc-bom-1908', 'Alma', 8, 53, 'Now these are the names of the different pieces of their gold, and of their silver, according to their value.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-55', 'coc-bom-1908', 'Alma', 8, 55, 'But they altered their reckoning and their measure according to the minds and the circumstances of the people in every generation until the reign of the judges, they having been established by King Mosiah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-56', 'coc-bom-1908', 'Alma', 8, 56, 'Now the reckoning is thus: a senine of gold, a seon of gold, a shum of gold, and a limnah of gold.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-57', 'coc-bom-1908', 'Alma', 8, 57, 'A senum of silver, an amnor of silver, an ezrom of silver, and an onti of silver.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-62', 'coc-bom-1908', 'Alma', 8, 62, 'Now an antion of gold is equal to three shiblons.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-63', 'coc-bom-1908', 'Alma', 8, 63, 'Now this is their number according to their reckoning.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-65', 'coc-bom-1908', 'Alma', 8, 65, 'Therefore, they did stir up the people to riotings, and all manner of disturbances, and wickedness, that they might have more employ,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-67', 'coc-bom-1908', 'Alma', 8, 67, 'And this Zeezrom began to question Amulek, saying, Will ye answer me a few questions which I shall ask you?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-68', 'coc-bom-1908', 'Alma', 8, 68, 'Now Zeezrom was a man who was expert in the devices of the devil, that he might destroy that which was good. Therefore, he said unto Amulek, Will ye answer the questions which I shall put unto you?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-70', 'coc-bom-1908', 'Alma', 8, 70, 'And Zeezrom said unto him, Behold, here are six onties of silver, and all these will I give thee if thou wilt deny the existence of a supreme being.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-71', 'coc-bom-1908', 'Alma', 8, 71, 'Now Amulek said, O thou child of hell, why tempt ye me?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-72', 'coc-bom-1908', 'Alma', 8, 72, 'Knowest thou that the righteous yieldeth to no such temptations?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-73', 'coc-bom-1908', 'Alma', 8, 73, 'Believest thou that there is no God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-75', 'coc-bom-1908', 'Alma', 8, 75, 'And now, thou hast lied before God unto me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-77', 'coc-bom-1908', 'Alma', 8, 77, 'And it was only thy desire that I should deny the true and living God, that thou mightest have cause to destroy me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-78', 'coc-bom-1908', 'Alma', 8, 78, 'And now, behold, for this great evil thou shalt have thy reward.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-79', 'coc-bom-1908', 'Alma', 8, 79, 'And Zeezrom said unto him, Thou sayest there is a true and living God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-80', 'coc-bom-1908', 'Alma', 8, 80, 'And Amulek said, Yea, there is a true and a living God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-81', 'coc-bom-1908', 'Alma', 8, 81, 'Now Zeezrom said, Is there more than one God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-82', 'coc-bom-1908', 'Alma', 8, 82, 'And he answereth, No.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-83', 'coc-bom-1908', 'Alma', 8, 83, 'Now Zeezrom said unto him again, How knowest thou these things?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-84', 'coc-bom-1908', 'Alma', 8, 84, 'And he said, An angel hath made them known unto me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-85', 'coc-bom-1908', 'Alma', 8, 85, 'And Zeezrom said again, Who is he that shall come? Is it the Son of God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-86', 'coc-bom-1908', 'Alma', 8, 86, 'And he said unto him, Yea.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-87', 'coc-bom-1908', 'Alma', 8, 87, 'And Zeezrom said again, Shall he save his people in their sins?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-88', 'coc-bom-1908', 'Alma', 8, 88, 'And Amulek answered and said unto him, I say unto you, He shall not, for it is impossible for him to deny his word.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-90', 'coc-bom-1908', 'Alma', 8, 90, 'Now Amulek saith again unto him, Behold, thou hast lied, for thou sayest that I spake as though I had authority to command God, because I said he shall not save his people in their sins.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-92', 'coc-bom-1908', 'Alma', 8, 92, 'Therefore, how can ye be saved, except ye inherit the kingdom of heaven? Therefore, ye cannot be saved in your sins.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-93', 'coc-bom-1908', 'Alma', 8, 93, 'Now Zeezrom saith again unto him, Is the Son of God the very eternal Father?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-95', 'coc-bom-1908', 'Alma', 8, 95, 'He is the beginning and the end, the first and the last.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-98', 'coc-bom-1908', 'Alma', 8, 98, 'For behold, the day cometh that all shall rise from the dead, and stand before God, and be judged according to their works.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-101', 'coc-bom-1908', 'Alma', 8, 101, 'And we shall be brought to stand before God, knowing even as we know now, and have a bright recollection of all our guilt.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-104', 'coc-bom-1908', 'Alma', 8, 104, 'And shall be brought and be arraigned before the bar of Christ, the Son, and God, the Father, and the Holy Spirit, which is one eternal God, to be judged according to their works, whether they be good or whether they be evil.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-105', 'coc-bom-1908', 'Alma', 8, 105, 'Now behold, I have spoken unto you concerning the death of the mortal body and also concerning the resurrection of the mortal body.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-107', 'coc-bom-1908', 'Alma', 8, 107, 'Thus the whole becoming spiritual and immortal, that they can no more see corruption.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-8-109', 'coc-bom-1908', 'Alma', 8, 109, 'And thus ended the words of Amulek, or this is all that I have written.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-1', 'coc-bom-1908', 'Alma', 9, 1, 'Now Alma, seeing that the words of Amulek had silenced Zeezrom--for he beheld that Amulek had caught him in his lying and deceiving to destroy him--and seeing that he began to tremble under a consciousness of his guilt, he opened his mouth and began to speak unto him, and to establish the words of Amulek, and to explain things beyond, or to unfold the scriptures beyond that which Amulek had done.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-2', 'coc-bom-1908', 'Alma', 9, 2, 'Now the words that Alma spake unto Zeezrom were heard by the people round about, for the multitude was great. And he spake on this wise:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-5', 'coc-bom-1908', 'Alma', 9, 5, 'And thou seest that we know that thy plan was a very subtle plan, as to the subtlety of the devil, for to lie and to deceive this people, that thou mightest set them against us, to revile us and to cast us out.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-6', 'coc-bom-1908', 'Alma', 9, 6, 'Now this was a plan of thine adversary, and he hath exercised his power in thee.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-7', 'coc-bom-1908', 'Alma', 9, 7, 'Now I would that ye should remember that what I say unto thee, I say unto all.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-8', 'coc-bom-1908', 'Alma', 9, 8, 'And behold, I say unto you all that this was a snare of the adversary, which he has laid to catch this people,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-9', 'coc-bom-1908', 'Alma', 9, 9, 'That he might bring you into subjection unto him, that he might encircle you about with his chains, that he might chain you down to everlasting destruction, according to the power of his captivity.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-11', 'coc-bom-1908', 'Alma', 9, 11, 'And he was also convinced that Alma and Amulek had a knowledge of him, for he was convinced that they knew the thoughts and intents of his heart.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-12', 'coc-bom-1908', 'Alma', 9, 12, 'For power was given unto them that they might know of these things according to the spirit of prophecy.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-13', 'coc-bom-1908', 'Alma', 9, 13, 'And Zeezrom began to inquire of them diligently, that he might know more concerning the kingdom of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-14', 'coc-bom-1908', 'Alma', 9, 14, 'And he said unto Alma, What does this mean which Amulek hath spoken concerning the resurrection of the dead, that all shall rise from the dead, both the just and the unjust, and are brought to stand before God to be judged according to their works?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-16', 'coc-bom-1908', 'Alma', 9, 16, 'Nevertheless, they are laid under a strict command that they shall not impart, only according to the portion of his word which he doth grant unto the children of men, according to the heed and diligence which they give unto him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-20', 'coc-bom-1908', 'Alma', 9, 20, 'And then they are taken captive by the devil and led by his will down to destruction.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-25', 'coc-bom-1908', 'Alma', 9, 25, 'And we would fain be glad if we could command the rocks and the mountains to fall upon us, to hide us from his presence.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-27', 'coc-bom-1908', 'Alma', 9, 27, 'That he is just in all his works, and that he is merciful unto the children of men, and that he has all power to save every man that believeth on his name and bringeth forth fruit meet for repentance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-28', 'coc-bom-1908', 'Alma', 9, 28, 'And now, behold, I say unto you, Then cometh a death, even a second death, which is a spiritual death.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-31', 'coc-bom-1908', 'Alma', 9, 31, 'And then is the time that they shall be chained down to an everlasting destruction, according to the power and captivity of Satan, he having subjected them according to his will.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-34', 'coc-bom-1908', 'Alma', 9, 34, 'But there was one Antionah, who was a chief ruler among them, came forth and said unto him, What is this that thou hast said, that man should rise from the dead and be changed from this mortal to an immortal state, that the soul can never die?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-35', 'coc-bom-1908', 'Alma', 9, 35, 'What does the scripture mean which saith that God placed cherubim and a flaming sword on the east of the garden of Eden, lest our first parents should enter and partake of the fruit of the tree of life and live forever?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-36', 'coc-bom-1908', 'Alma', 9, 36, 'And thus we see that there was no possible chance that they should live forever.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-37', 'coc-bom-1908', 'Alma', 9, 37, 'Now Alma said unto him, This is the thing which I was about to explain.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-41', 'coc-bom-1908', 'Alma', 9, 41, 'Therefore, this life became a probationary state--a time to prepare to meet God, a time to prepare for that endless state, which has been spoken of by us, which is after the resurrection of the dead.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-43', 'coc-bom-1908', 'Alma', 9, 43, 'But there was a plan of redemption laid, which shall bring to pass the resurrection of the dead, of which has been spoken.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-45', 'coc-bom-1908', 'Alma', 9, 45, 'And thus the plan of redemption would have been frustrated, and the word of God would have been void, taking none effect.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-48', 'coc-bom-1908', 'Alma', 9, 48, 'Therefore, he sent angels to converse with them, who caused men to behold of his glory.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-54', 'coc-bom-1908', 'Alma', 9, 54, 'But God did call on men, in the name of his Son (this being the plan of redemption which was laid), saying, If ye will repent and harden not your hearts, then will I have mercy upon you through mine Only Begotten Son.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-56', 'coc-bom-1908', 'Alma', 9, 56, 'And whosoever will harden his heart and will do iniquity, behold, I swear in my wrath that he shall not enter into my rest.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-58', 'coc-bom-1908', 'Alma', 9, 58, 'Therefore, your iniquity provoketh him, that he sendeth down his wrath upon you as in the first provocation,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-61', 'coc-bom-1908', 'Alma', 9, 61, 'But let us enter into the rest of God, which is prepared according to his word.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-64', 'coc-bom-1908', 'Alma', 9, 64, 'And those priests were ordained after the order of his Son, in a manner that thereby the people might know in what manner to look forward to his Son for redemption.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-67', 'coc-bom-1908', 'Alma', 9, 67, 'And thus they have been called to this holy calling on account of their faith, while others would reject the Spirit of God on account of the hardness of their hearts and blindness of their minds, while, if it had not been for this, they might have had as great privilege as their brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-69', 'coc-bom-1908', 'Alma', 9, 69, 'And thus being called by his holy calling and ordained unto the high priesthood of the holy order of God, to teach his commandments unto the children of men, that they also might enter into his rest,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-70', 'coc-bom-1908', 'Alma', 9, 70, 'This high priesthood being after the order of his Son, which order was from the foundation of the world,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-71', 'coc-bom-1908', 'Alma', 9, 71, 'Or, in other words, being without beginning of days or end of years, being prepared from eternity to all eternity, according to his foreknowledge of all things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-9-73', 'coc-bom-1908', 'Alma', 9, 73, 'Thus they become high priests forever, after the order of the Son, the Only Begotten of the Father, who is without beginning of days or end of years, who is full of grace, equity, and truth. And thus it is. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-5', 'coc-bom-1908', 'Alma', 10, 5, 'And there were many, exceeding great many, who were made pure and entered into the rest of the Lord, their God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-7', 'coc-bom-1908', 'Alma', 10, 7, 'Yea, humble yourselves even as the people in the days of Melchisedec, who was also a high priest after this same order which I have spoken, who also took upon him the high priesthood forever.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-10', 'coc-bom-1908', 'Alma', 10, 10, 'And this, that they might look forward to him for a remission of their sins, that they might enter into the rest of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-12', 'coc-bom-1908', 'Alma', 10, 12, 'But Melchisedec, having exercised mighty faith and received the office of the high priesthood, according to the holy order of God, did preach repentance unto his people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-22', 'coc-bom-1908', 'Alma', 10, 22, 'Therefore, we are thus highly favored, for we have these glad tidings declared unto us in all parts of our vineyard.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-26', 'coc-bom-1908', 'Alma', 10, 26, 'And it shall be made known unto just and holy men, by the mouth of angels at the time of his coming, that the words of our fathers may be fulfilled according to that which they have spoken concerning him, which was according to the spirit of prophecy which was in them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-30', 'coc-bom-1908', 'Alma', 10, 30, 'And may the Lord grant unto you repentance, that ye may not bring down his wrath upon you, that ye may not be bound down by the chains of hell, that ye may not suffer the second death.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-31', 'coc-bom-1908', 'Alma', 10, 31, 'And Alma spake many more words unto the people, which are not written in this book.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-34', 'coc-bom-1908', 'Alma', 10, 34, 'And they also said that Amulek had lied unto them and had reviled against their law and also against their lawyers and judges.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-37', 'coc-bom-1908', 'Alma', 10, 37, 'And the people went forth and witnessed against them, testifying that they had reviled against the law, and their lawyers, and judges of the land, and also all the people that were in the land,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-38', 'coc-bom-1908', 'Alma', 10, 38, 'And also testified that there was but one God, and that he should send his Son among the people, but he should not save them. And many such things did the people testify against Alma and Amulek.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-39', 'coc-bom-1908', 'Alma', 10, 39, 'Now this was done before the chief judge of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-42', 'coc-bom-1908', 'Alma', 10, 42, 'And it came to pass that he began to cry unto the people, saying, Behold, I am guilty, and these men are spotless before God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-46', 'coc-bom-1908', 'Alma', 10, 46, 'And they also brought forth their records which contained the holy scriptures and cast them into the fire also, that they might be burned and destroyed by fire.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-47', 'coc-bom-1908', 'Alma', 10, 47, 'And it came to pass that they took Alma and Amulek and carried them forth to the place of martyrdom, that they might witness the destruction of those who were consumed by fire.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-48', 'coc-bom-1908', 'Alma', 10, 48, 'And when Amulek saw the pains of the women and children who were consuming in the fire, he was also pained. And he said unto Alma, How can we witness this awful scene?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-49', 'coc-bom-1908', 'Alma', 10, 49, 'Therefore, let us stretch forth our hands, and exercise the power of God which is in us, and save them from the flames.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-52', 'coc-bom-1908', 'Alma', 10, 52, 'And the blood of the innocent shall stand as a witness against them, yea, and cry mightily against them at the last day.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-53', 'coc-bom-1908', 'Alma', 10, 53, 'Now Amulek said unto Alma, Behold, perhaps they will burn us also.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-56', 'coc-bom-1908', 'Alma', 10, 56, 'And he smote them with his hand upon their cheeks and said unto them, After what ye have seen, will ye preach again unto this people that they shall be cast into a lake of fire and brimstone?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-58', 'coc-bom-1908', 'Alma', 10, 58, 'And the judge smote them upon their cheeks and asked, What say ye for yourselves?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-59', 'coc-bom-1908', 'Alma', 10, 59, 'Now this judge was after the order and faith of Nehor, who slew Gideon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-63', 'coc-bom-1908', 'Alma', 10, 63, 'And it came to pass that the judge stood before them and said, Why do ye not answer the words of this people?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-64', 'coc-bom-1908', 'Alma', 10, 64, 'Know ye not that I have power to deliver ye up unto the flames?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-67', 'coc-bom-1908', 'Alma', 10, 67, 'And many came forth also and smote them, saying, Will ye stand again, and judge this people, and condemn our law?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-68', 'coc-bom-1908', 'Alma', 10, 68, 'If ye have such great power, why do ye not deliver yourselves?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-69', 'coc-bom-1908', 'Alma', 10, 69, 'And many such things did they say unto them, gnashing their teeth upon them, and spitting upon them, and saying, How shall we look when we are damned?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-73', 'coc-bom-1908', 'Alma', 10, 73, 'And it came to pass after they had thus suffered for many days (and it was on the twelfth day, in the tenth month, in the tenth year of the reign of the judges over the people of Nephi), that the chief judge over the land of Ammonihah, and many of their teachers and their lawyers, went in unto the prison where Alma and Amulek were bound with cords.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-75', 'coc-bom-1908', 'Alma', 10, 75, 'And it came to pass that they all went forth and smote them, saying the same words, even until the last.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-80', 'coc-bom-1908', 'Alma', 10, 80, 'And the chief judge, and the lawyers, and priests, and teachers who smote upon Alma and Amulek were slain by the fall thereof.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-87', 'coc-bom-1908', 'Alma', 10, 87, 'And behold, there they found all the people who had departed out of the land of Ammonihah, who had been cast out and stoned because they believed in the words of Alma.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-88', 'coc-bom-1908', 'Alma', 10, 88, 'And they related unto them all that had happened unto their wives and children, and also concerning themselves, and of their power of deliverance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-94', 'coc-bom-1908', 'Alma', 10, 94, 'And when he saw them, he stretched forth his hand and besought them that they would heal him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-95', 'coc-bom-1908', 'Alma', 10, 95, 'And it came to pass that Alma said unto him, taking him by the hand, Believest thou in the power of Christ unto salvation?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-96', 'coc-bom-1908', 'Alma', 10, 96, 'And he answered and said, Yea, I believe all the words that thou hast taught.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-97', 'coc-bom-1908', 'Alma', 10, 97, 'And Alma said, If thou believest in the redemption of Christ, thou canst be healed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-98', 'coc-bom-1908', 'Alma', 10, 98, 'And he said, Yea, I believe according to thy words.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-99', 'coc-bom-1908', 'Alma', 10, 99, 'And then Alma cried unto the Lord, saying, O Lord, our God, have mercy on this man, and heal him according to his faith which is in Christ.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-103', 'coc-bom-1908', 'Alma', 10, 103, 'And Alma established a church in the land of Sidom and consecrated priests and teachers in the land to baptize unto the Lord whosoever were desirous to be baptized.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-106', 'coc-bom-1908', 'Alma', 10, 106, 'And they repented not of their sins, ascribing all the power of Alma and Amulek to the devil--for they were of the profession of Nehor and did not believe in the repentance of their sins.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-107', 'coc-bom-1908', 'Alma', 10, 107, 'And it came to pass that Alma and Amulek--Amulek having forsaken all his gold, and silver, and his precious things which were in the land of Ammonihah for the word of God, he being rejected by those who were once his friends and also by his father and his kindred,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-108', 'coc-bom-1908', 'Alma', 10, 108, 'Therefore, after Alma, having established the church at Sidom, seeing a great check, yea, seeing that the people were checked as to the pride of their hearts, and began to humble themselves before God,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-109', 'coc-bom-1908', 'Alma', 10, 109, 'And began to assemble themselves together at their sanctuaries to worship God before the altar, watching and praying continually, that they might be delivered from Satan, and from death, and from destruction--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-110', 'coc-bom-1908', 'Alma', 10, 110, 'Now as I said, Alma, having seen all these things, therefore, he took Amulek and came over to the land of Zarahemla, and took him to his own house, and did administer unto him in his tribulations, and strengthened him in the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-10-111', 'coc-bom-1908', 'Alma', 10, 111, 'And thus ended the tenth year of the reign of the judges over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-2', 'coc-bom-1908', 'Alma', 11, 2, 'For behold, the armies of the Lamanites had come in upon the wilderness side, into the borders of the land, even into the city of Ammonihah, and began to slay the people and to destroy the city.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-3', 'coc-bom-1908', 'Alma', 11, 3, 'And now, it came to pass before the Nephites could raise a sufficient army to drive them out of the land, they had destroyed the people who were in the city of Ammonihah, and also some around the borders of Noah, and taking others captive into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-5', 'coc-bom-1908', 'Alma', 11, 5, 'Therefore, he that had been appointed chief captain over the armies of the Nephites (and his name was Zoram, and he had two sons, Lehi and Aha),', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-6', 'coc-bom-1908', 'Alma', 11, 6, 'Now Zoram and his two sons, knowing that Alma was high priest over the church, and having heard that he had the spirit of prophecy,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-7', 'coc-bom-1908', 'Alma', 11, 7, 'Therefore, they went unto him and desired of him to know whither the Lord would that they should go into the wilderness in search of their brethren who had been taken captive by the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-8', 'coc-bom-1908', 'Alma', 11, 8, 'And it came to pass that Alma inquired of the Lord concerning the matter.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-9', 'coc-bom-1908', 'Alma', 11, 9, 'And Alma returned and said unto them, Behold, the Lamanites will cross the river Sidon, in the south wilderness, away up beyond the borders of the land of Manti.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-11', 'coc-bom-1908', 'Alma', 11, 11, 'And it came to pass that Zoram and his sons crossed over the river Sidon with their armies and marched away beyond the borders of Manti, into the south wilderness, which was on the east side of the river Sidon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-13', 'coc-bom-1908', 'Alma', 11, 13, 'And they were brought by their brethren to possess their own lands.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-15', 'coc-bom-1908', 'Alma', 11, 15, 'Yea, every living soul of the Ammonihahites was destroyed, and also their great city, which they said God could not destroy because of its greatness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-17', 'coc-bom-1908', 'Alma', 11, 17, 'Nevertheless, after many days, their dead bodies were heaped up upon the face of the earth, and they were covered with a shallow covering.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-18', 'coc-bom-1908', 'Alma', 11, 18, 'And now, so great was the scent thereof that the people did not go in to possess the land of Ammonihah for many years.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-20', 'coc-bom-1908', 'Alma', 11, 20, 'And the Lamanites did not come again to war against the Nephites until the fourteenth year of the reign of the judges over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-21', 'coc-bom-1908', 'Alma', 11, 21, 'And thus for three years did the people of Nephi have continual peace in all the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-22', 'coc-bom-1908', 'Alma', 11, 22, 'And Alma and Amulek went forth, preaching repentance to the people in their temples, and in their sanctuaries, and also in their synagogues, which were built after the manner of the Jews.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-23', 'coc-bom-1908', 'Alma', 11, 23, 'And as many as would hear their words, unto them they did impart the word of God, without any respect of persons, continually.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-24', 'coc-bom-1908', 'Alma', 11, 24, 'And thus did Alma and Amulek go forth, and also many more who had been chosen for the work, to preach the word throughout all the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-25', 'coc-bom-1908', 'Alma', 11, 25, 'And the establishment of the church became general throughout the land, in all the region round about, among all the people of the Nephites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-26', 'coc-bom-1908', 'Alma', 11, 26, 'And there was no inequality among them, for the Lord did pour out his Spirit on all the face of the land, to prepare the minds of the children of men, or to prepare their hearts, to receive the word which should be taught among them at the time of his coming,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-27', 'coc-bom-1908', 'Alma', 11, 27, 'That they might not be hardened against the word, that they might not be unbelieving and go on to destruction,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-28', 'coc-bom-1908', 'Alma', 11, 28, 'But that they might receive the word with joy, and as a branch be grafted into the true vine, that they might enter into the rest of the Lord, their God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-29', 'coc-bom-1908', 'Alma', 11, 29, 'Now those priests who did go forth among the people did preach against all lyings, and deceivings, and envyings, and strifes, and malice, and revilings, and stealing, robbing, plundering, murdering, committing adultery, and all manner of lasciviousness, crying that these things ought not so to be,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-30', 'coc-bom-1908', 'Alma', 11, 30, 'Holding forth things which must shortly come, yea, holding forth the coming of the Son of God, his sufferings and death, and also the resurrection of the dead.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-32', 'coc-bom-1908', 'Alma', 11, 32, 'And now, after the church having been established throughout all the land, having got the victory over the devil, and the word of God being preached in its purity in all the land, and the Lord pouring out his blessings upon the people,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-11-33', 'coc-bom-1908', 'Alma', 11, 33, 'Thus ended the fourteenth year of the reign of the judges over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-1', 'coc-bom-1908', 'Alma', 12, 1, 'And now, it came to pass that as Alma was journeying from the land of Gideon southward, away to the land of Manti, behold, to his astonishment, he met the sons of Mosiah journeying towards the land of Zarahemla.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-4', 'coc-bom-1908', 'Alma', 12, 4, 'For they were men of a sound understanding, and they had searched the scriptures diligently, that they might know the word of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-7', 'coc-bom-1908', 'Alma', 12, 7, 'Yea, by the power of their words, many were brought before the altar of God, to call on his name and confess their sins before him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-9', 'coc-bom-1908', 'Alma', 12, 9, 'They did suffer much, both in body and in mind, such as hunger, thirst, and fatigue, and also much labor in the spirit.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-12', 'coc-bom-1908', 'Alma', 12, 12, 'And this they did that they might provide food for themselves while in the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-13', 'coc-bom-1908', 'Alma', 12, 13, 'And thus they departed into the wilderness with their numbers which they had selected, to go up to the land of Nephi to preach the word of God unto the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-15', 'coc-bom-1908', 'Alma', 12, 15, 'That they might be an instrument in the hands of God, to bring, if it were possible, their brethren, the Lamanites, to the knowledge of the truth,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-16', 'coc-bom-1908', 'Alma', 12, 16, 'To the knowledge of the baseness of the traditions of their fathers, which were not correct.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-19', 'coc-bom-1908', 'Alma', 12, 19, 'Yet ye shall be patient in long-suffering and afflictions, that ye may show forth good examples unto them in me. And I will make an instrument of thee in my hands, unto the salvation of many souls.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-20', 'coc-bom-1908', 'Alma', 12, 20, 'And it came to pass that the hearts of the sons of Mosiah, and also those who were with them, took courage to go forth unto the Lamanites to declare unto them the word of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-23', 'coc-bom-1908', 'Alma', 12, 23, 'And their hearts were set upon riches, or upon gold, and silver, and precious stones.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-24', 'coc-bom-1908', 'Alma', 12, 24, 'Yet they sought to obtain these things by murdering and plundering, that they might not labor for them with their own hands.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-26', 'coc-bom-1908', 'Alma', 12, 26, 'Therefore, this was the cause for which the sons of Mosiah had undertaken the work, that perhaps they might bring them unto repentance, that perhaps they might bring them to know of the plan of redemption.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-27', 'coc-bom-1908', 'Alma', 12, 27, 'Therefore, they separated themselves one from another and went forth among them, every man alone, according to the word and power of God which was given unto him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-29', 'coc-bom-1908', 'Alma', 12, 29, 'And Ammon went to the land of Ishmael, the land being called after the sons of Ishmael, who also became Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-31', 'coc-bom-1908', 'Alma', 12, 31, 'And thus it was left to the pleasure of the king to slay them, or to retain them in captivity, or to cast them into prison, or to cast them out of his land according to his will and pleasure.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-33', 'coc-bom-1908', 'Alma', 12, 33, 'And the king inquired of Ammon if it were his desire to dwell in the land among the Lamanites, or among his people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-34', 'coc-bom-1908', 'Alma', 12, 34, 'And Ammon said unto him, Yea, I desire to dwell among this people for a time, yea, and perhaps until the day I die.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-37', 'coc-bom-1908', 'Alma', 12, 37, 'And it came to pass that he was set, among other servants, to watch the flocks of Lamoni according to the custom of the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-38', 'coc-bom-1908', 'Alma', 12, 38, 'And after he had been in the service of the king three days, as he was with the Lamanitish servants, going forth with their flocks to the place of water, which was called the water of Sebus (and all the Lamanites drive their flocks hither, that they may have water),', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-40', 'coc-bom-1908', 'Alma', 12, 40, 'Now the servants of the king began to murmur, saying, Now the king will slay us, as he has our brethren, because their flocks were scattered by the wickedness of these men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-41', 'coc-bom-1908', 'Alma', 12, 41, 'And they began to weep exceedingly, saying, Behold, our flocks are scattered already.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-42', 'coc-bom-1908', 'Alma', 12, 42, 'Now they wept because of the fear of being slain.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-44', 'coc-bom-1908', 'Alma', 12, 44, 'Now these were the thoughts of Ammon when he saw the afflictions of those whom he termed to be his brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-46', 'coc-bom-1908', 'Alma', 12, 46, 'And thus we will reserve the flocks unto the king, and he will not slay us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-49', 'coc-bom-1908', 'Alma', 12, 49, 'Therefore, they did as Ammon commanded them, and he went forth and stood to contend with those who stood by the waters of Sebus.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-53', 'coc-bom-1908', 'Alma', 12, 53, 'And thus he slew a certain number of them, insomuch that they began to be astonished at his power.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-55', 'coc-bom-1908', 'Alma', 12, 55, 'Therefore, seeing that they could not hit him with their stones, they came forth with clubs to slay him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-61', 'coc-bom-1908', 'Alma', 12, 61, 'And they were carried in unto the king for a testimony of the things which they had done.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-62', 'coc-bom-1908', 'Alma', 12, 62, 'And it came to pass that King Lamoni caused that his servants should stand forth and testify to all the things which they had seen concerning the matter.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-63', 'coc-bom-1908', 'Alma', 12, 63, 'And when they had all testified to the things which they had seen, and he had learned of the faithfulness of Ammon in preserving his flocks, and also of his great power in contending against those who sought to slay him, he was astonished exceedingly and said, Surely this is more than a man.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-64', 'coc-bom-1908', 'Alma', 12, 64, 'Behold, is not this the Great Spirit who doth send such great punishments upon this people because of their murders?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-67', 'coc-bom-1908', 'Alma', 12, 67, 'And now, O King, we do not believe that a man has such great power, for we know that he cannot be slain.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-69', 'coc-bom-1908', 'Alma', 12, 69, 'Now this is the Great Spirit of whom our fathers have spoken.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-70', 'coc-bom-1908', 'Alma', 12, 70, 'Now this was the tradition of Lamoni, which he had received from his father, that there was a Great Spirit.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-71', 'coc-bom-1908', 'Alma', 12, 71, 'Notwithstanding they believed in a Great Spirit, they supposed that whatsoever they did was right.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-74', 'coc-bom-1908', 'Alma', 12, 74, 'Now it was the practice of the Lamanites to stand by the waters of Sebus to scatter the flocks of the people, that thereby they might drive away many that were scattered unto their own land, it being a practice of plunder among them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-75', 'coc-bom-1908', 'Alma', 12, 75, 'And it came to pass that King Lamoni inquired of his servants, saying, Where is this man that has such great power?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-76', 'coc-bom-1908', 'Alma', 12, 76, 'And they said unto him, Behold, he is feeding thy horses.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-78', 'coc-bom-1908', 'Alma', 12, 78, 'For there had been a great feast appointed at the land of Nephi by the father of Lamoni, who was king over all the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-79', 'coc-bom-1908', 'Alma', 12, 79, 'Now when King Lamoni heard that Ammon was preparing his horses and his chariots, he was more astonished because of the faithfulness of Ammon, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-83', 'coc-bom-1908', 'Alma', 12, 83, 'And one of the king''s servants said unto him, Rabbanah, which is, being interpreted, powerful or great king (considering their kings to be powerful).', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-84', 'coc-bom-1908', 'Alma', 12, 84, 'And thus he said unto him, Rabbanah, the king desireth thee to stay.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-85', 'coc-bom-1908', 'Alma', 12, 85, 'Therefore, Ammon turned himself unto the king and said unto him, What wilt thou that I should do for thee, O King?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-86', 'coc-bom-1908', 'Alma', 12, 86, 'And the king answered him not for the space of an hour, according to their time, for he knew not what he should say unto him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-87', 'coc-bom-1908', 'Alma', 12, 87, 'And it came to pass that Ammon said unto him again, What desireth thou of me? But the king answered him not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-88', 'coc-bom-1908', 'Alma', 12, 88, 'And it came to pass that Ammon, being filled with the Spirit of God, therefore, he perceived the thoughts of the king.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-89', 'coc-bom-1908', 'Alma', 12, 89, 'And he said unto him, Is it because thou hast heard that I defended thy servants and thy flocks, and slew seven of their brethren with the sling and with the sword, and smote off the arms of others in order to defend thy flocks and thy servants? Behold, is it this that causeth thy marvelings?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-90', 'coc-bom-1908', 'Alma', 12, 90, 'I say unto you, What is it, that thy marvelings are so great?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-93', 'coc-bom-1908', 'Alma', 12, 93, 'But notwithstanding this, King Lamoni did open his mouth and said unto him, Who art thou? Art thou that Great Spirit who knows all things?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-94', 'coc-bom-1908', 'Alma', 12, 94, 'Ammon answered and said unto him, I am not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-95', 'coc-bom-1908', 'Alma', 12, 95, 'And the king said, How knowest thou the thoughts of my heart?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-97', 'coc-bom-1908', 'Alma', 12, 97, 'And now, if thou wilt tell me concerning these things, whatsoever thou desirest, I will give unto thee.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-99', 'coc-bom-1908', 'Alma', 12, 99, 'Now Ammon, being wise yet harmless, he said unto Lamoni, Wilt thou hearken unto my words if I tell thee by what power I do these things? And this is the thing that I desire of thee.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-101', 'coc-bom-1908', 'Alma', 12, 101, 'And Ammon began to speak unto him with boldness and said unto him, Believest thou that there is a God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-102', 'coc-bom-1908', 'Alma', 12, 102, 'And he answered and said unto him, I do not know what that meaneth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-103', 'coc-bom-1908', 'Alma', 12, 103, 'And then Ammon said, Believest thou that there is a Great Spirit?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-104', 'coc-bom-1908', 'Alma', 12, 104, 'And he said, Yea.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-105', 'coc-bom-1908', 'Alma', 12, 105, 'And Ammon said, This is God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-106', 'coc-bom-1908', 'Alma', 12, 106, 'And Ammon said unto him again, Believest thou that this Great Spirit, who is God, created all things which are in heaven and in the earth?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-108', 'coc-bom-1908', 'Alma', 12, 108, 'And Ammon said unto him, The heavens is a place where God dwells, and all his holy angels.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-109', 'coc-bom-1908', 'Alma', 12, 109, 'And King Lamoni said, Is it above the earth?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-111', 'coc-bom-1908', 'Alma', 12, 111, 'And King Lamoni said, I believe all these things which thou hast spoken. Art thou sent from God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-113', 'coc-bom-1908', 'Alma', 12, 113, 'And a portion of that Spirit dwelleth in me, which giveth me knowledge and also power, according to my faith and desires which are in God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-114', 'coc-bom-1908', 'Alma', 12, 114, 'Now when Ammon had said these words, he began at the creation of the world, and also the creation of Adam, and told him all the things concerning the fall of man,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-116', 'coc-bom-1908', 'Alma', 12, 116, 'And he also rehearsed unto them (for it was unto the king and to his servants) all the journeyings of their fathers in the wilderness, and all their sufferings with hunger and thirst, and their travel, etc.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-118', 'coc-bom-1908', 'Alma', 12, 118, 'And he expounded unto them all the records and scriptures, from the time that Lehi left Jerusalem down to the present time.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-121', 'coc-bom-1908', 'Alma', 12, 121, 'And it came to pass that after he had said all these things and expounded them to the king, that the king believed all his words.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-123', 'coc-bom-1908', 'Alma', 12, 123, 'And now, when he had said this, he fell unto the earth as if he were dead.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-125', 'coc-bom-1908', 'Alma', 12, 125, 'And his wife, and his sons, and his daughters mourned over him after the manner of the Lamanites, greatly lamenting his loss.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-126', 'coc-bom-1908', 'Alma', 12, 126, 'And it came to pass that after two days and two nights, they were about to take his body and lay it in a sepulcher which they had made for the purpose of burying their dead.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-127', 'coc-bom-1908', 'Alma', 12, 127, 'Now the queen, having heard of the fame of Ammon, therefore, she sent and desired that he should come in unto her.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-128', 'coc-bom-1908', 'Alma', 12, 128, 'And it came to pass that Ammon did as he was commanded, and went in unto the queen, and desired to know what she would that he should do.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-132', 'coc-bom-1908', 'Alma', 12, 132, 'Now this was what Ammon desired, for he knew that King Lamoni was under the power of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-133', 'coc-bom-1908', 'Alma', 12, 133, 'He knew that the dark veil of unbelief being cast away from his mind and the light which did light up his mind--which was the light of the glory of God, which was a marvelous light of his goodness--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-134', 'coc-bom-1908', 'Alma', 12, 134, 'Yea, this light had infused such joy into his soul, the cloud of darkness having been dispelled, and that the light of everlasting light was lit up in his soul.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-138', 'coc-bom-1908', 'Alma', 12, 138, 'And Ammon said unto her, Believest thou this?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-141', 'coc-bom-1908', 'Alma', 12, 141, 'And it came to pass that she watched over the bed of her husband from that time even until that time on the morrow which Ammon had appointed that he should rise.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-145', 'coc-bom-1908', 'Alma', 12, 145, 'Now Ammon, seeing the Spirit of the Lord poured out according to his prayers upon the Lamanites, his brethren, who had been the cause of so much mourning among the Nephites, or among all the people of God, because of their iniquities and their traditions,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-146', 'coc-bom-1908', 'Alma', 12, 146, 'He fell upon his knees and began to pour out his soul in prayer and thanksgiving to God for what he had done for his brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-149', 'coc-bom-1908', 'Alma', 12, 149, 'For it was they who had stood before the king and testified unto him concerning the great power of Ammon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-151', 'coc-bom-1908', 'Alma', 12, 151, 'Therefore, when she saw that all the servants of Lamoni had fallen to the earth, and also her mistress, the queen, and the king, and Ammon lay prostrate upon the earth, she knew that it was the power of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-152', 'coc-bom-1908', 'Alma', 12, 152, 'And supposing that this opportunity, by making known unto the people what had happened among them, that by beholding this scene, it would cause them to believe in the power of God,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-155', 'coc-bom-1908', 'Alma', 12, 155, 'And they also saw Ammon, and behold, he was a Nephite.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-156', 'coc-bom-1908', 'Alma', 12, 156, 'And now, the people began to murmur among themselves, some saying that it was a great evil that had come upon them, or upon the king and his house, because he had suffered that the Nephite should remain in the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-157', 'coc-bom-1908', 'Alma', 12, 157, 'But others rebuked them, saying, The king hath brought this evil upon his house because he slew his servants who had had their flocks scattered at the waters of Sebus.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-158', 'coc-bom-1908', 'Alma', 12, 158, 'And they were also rebuked by those men who had stood at the waters of Sebus and scattered the flocks which belonged to the king,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-159', 'coc-bom-1908', 'Alma', 12, 159, 'For they were angry with Ammon because of the number which he had slain of their brethren at the waters of Sebus while defending the flocks of the king.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-163', 'coc-bom-1908', 'Alma', 12, 163, 'And they began to marvel again among themselves what could be the cause of this great power, or what all these things could mean.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-165', 'coc-bom-1908', 'Alma', 12, 165, 'But others rebuked them all, saying that he was a monster, who had been sent from the Nephites to torment them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-169', 'coc-bom-1908', 'Alma', 12, 169, 'And it came to pass that she went and took the queen by the hand, that perhaps she might raise her from the ground. And as soon as she touched her hand, she arose, and stood upon her feet, and cried with a loud voice, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-170', 'coc-bom-1908', 'Alma', 12, 170, 'O blessed Jesus, who has saved me from an awful hell! O blessed God, have mercy upon this people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-176', 'coc-bom-1908', 'Alma', 12, 176, 'And they did all declare unto the people the selfsame thing--that their hearts had been changed, that they had no more desire to do evil.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-180', 'coc-bom-1908', 'Alma', 12, 180, 'And we see that his arm is extended to all people who will repent and believe on his name.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-181', 'coc-bom-1908', 'Alma', 12, 181, 'And it came to pass that when they had established a church in that land, that King Lamoni desired that Ammon should go with him to the land of Nephi, that he might show him unto his father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-183', 'coc-bom-1908', 'Alma', 12, 183, 'Now it came to pass that when Ammon had heard this, he said unto Lamoni, Behold, my brother and brethren are in prison at Middoni, and I go that I may deliver them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-186', 'coc-bom-1908', 'Alma', 12, 186, 'Now Lamoni said unto him, Who told thee that thy brethren were in prison?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-188', 'coc-bom-1908', 'Alma', 12, 188, 'Now when Lamoni had heard this, he caused that his servants should make ready his horses and his chariots.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-190', 'coc-bom-1908', 'Alma', 12, 190, 'And it came to pass that as Ammon and Lamoni were journeying thither, that they met the father of Lamoni, who was king over all the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-191', 'coc-bom-1908', 'Alma', 12, 191, 'And behold, the father of Lamoni said unto him, Why did ye not come to the feast on that great day when I made a feast unto my sons and unto my people?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-192', 'coc-bom-1908', 'Alma', 12, 192, 'And he also said, Whither art thou going with this Nephite, who is one of the children of a liar?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-193', 'coc-bom-1908', 'Alma', 12, 193, 'And it came to pass that Lamoni rehearsed unto him whither he was going, for he feared to offend him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-194', 'coc-bom-1908', 'Alma', 12, 194, 'And he also told him all the cause of his tarrying in his own kingdom, that he did not go unto his father to the feast which he had prepared.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-195', 'coc-bom-1908', 'Alma', 12, 195, 'And now, when Lamoni had rehearsed unto him all these things, behold, to his astonishment his father was angry with him and said, Lamoni, thou art going to deliver these Nephites, who are sons of a liar.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-197', 'coc-bom-1908', 'Alma', 12, 197, 'Now the father of Lamoni commanded him that he should slay Ammon with the sword.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-198', 'coc-bom-1908', 'Alma', 12, 198, 'And he also commanded him that he should not go to the land of Middoni, but that he should return with him to the land of Ishmael.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-205', 'coc-bom-1908', 'Alma', 12, 205, 'But Ammon withstood his blows and also smote his arm that he could not use it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-206', 'coc-bom-1908', 'Alma', 12, 206, 'Now when the king saw that Ammon could slay him, he began to plead with Ammon that he would spare his life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-207', 'coc-bom-1908', 'Alma', 12, 207, 'But Ammon raised his sword and said unto him, Behold, I will smite thee, except thou wilt grant unto me that my brethren may be cast out of prison.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-208', 'coc-bom-1908', 'Alma', 12, 208, 'Now the king, fearing that he should lose his life, said, If thou wilt spare me, I will grant unto thee whatsoever thou wilt ask, even to the half of the kingdom.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-210', 'coc-bom-1908', 'Alma', 12, 210, 'Now when Ammon had said these words, the king began to rejoice because of his life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-211', 'coc-bom-1908', 'Alma', 12, 211, 'And when he saw that Ammon had no desire to destroy him, and when he also saw the great love he had for his son Lamoni, he was astonished exceedingly and said,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-215', 'coc-bom-1908', 'Alma', 12, 215, 'And it came to pass that Ammon and Lamoni proceeded on their journey towards the land of Middoni.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-12-221', 'coc-bom-1908', 'Alma', 12, 221, 'And there they were taken and cast into prison, and bound with strong cords, and kept in prison for many days, and were delivered by Lamoni and Ammon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-2', 'coc-bom-1908', 'Alma', 13, 2, 'Now the Lamanites, and the Amalekites, and the people of Amulon had built a great city, which was called Jerusalem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-4', 'coc-bom-1908', 'Alma', 13, 4, 'And it came to pass that Aaron came to the city of Jerusalem and firstly began to preach to the Amalekites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-6', 'coc-bom-1908', 'Alma', 13, 6, 'Therefore, as Aaron entered into one of their synagogues to preach unto the people, and as he was speaking unto them, behold, there arose an Amalekite and began to contend with him, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-7', 'coc-bom-1908', 'Alma', 13, 7, 'What is that thou hast testified? Hast thou seen an angel? Why do not angels appear unto us? Behold, are not this people as good as thy people? Thou also sayest, except we repent, we shall perish.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-8', 'coc-bom-1908', 'Alma', 13, 8, 'How knowest thou the thought and intent of our heart? How knowest thou that we have cause to repent? How knowest thou that we are not a righteous people?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-9', 'coc-bom-1908', 'Alma', 13, 9, 'Behold, we have built sanctuaries, and we do assemble ourselves together to worship God. We do believe that God will save all men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-10', 'coc-bom-1908', 'Alma', 13, 10, 'Now Aaron said unto him, Believest thou that the Son of God shall come to redeem mankind from their sins?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-11', 'coc-bom-1908', 'Alma', 13, 11, 'And the man said unto him, We do not believe that thou knowest any such thing. We do not believe in these foolish traditions.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-13', 'coc-bom-1908', 'Alma', 13, 13, 'Now Aaron began to open the scriptures unto them, concerning the coming of Christ, and also concerning the resurrection of the dead, and that there could be no redemption for mankind, save it were through the death and sufferings of Christ and the atonement of his blood.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-17', 'coc-bom-1908', 'Alma', 13, 17, 'And they did preach the word unto many, and few believed on the words which they taught.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-18', 'coc-bom-1908', 'Alma', 13, 18, 'Nevertheless, Aaron and a certain number of his brethren were taken and cast into prison, and the remainder of them fled out of the land of Middoni, unto the regions round about.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-21', 'coc-bom-1908', 'Alma', 13, 21, 'And they went forth whithersoever they were led by the Spirit of the Lord, preaching the word of God in every synagogue of the Amalekites, or in every assembly of the Lamanites where they could be admitted.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-23', 'coc-bom-1908', 'Alma', 13, 23, 'And it came to pass that Ammon and Lamoni returned from the land of Middoni to the land of Ishmael, which was the land of their inheritance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-25', 'coc-bom-1908', 'Alma', 13, 25, 'And he did rejoice over them, and he did teach them many things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-26', 'coc-bom-1908', 'Alma', 13, 26, 'And he did also declare unto them that they were a people who were under him, and that they were a free people, that they were free from the oppressions of the king, his father, for that his father had granted unto him that he might reign over the people who were in the land of Ishmael and in all the land round about.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-27', 'coc-bom-1908', 'Alma', 13, 27, 'And he also declared unto them that they might have the liberty of worshiping the Lord, their God, according to their desires, in whatsoever place they were in, if it were in the land which was under the reign of King Lamoni.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-28', 'coc-bom-1908', 'Alma', 13, 28, 'And Ammon did preach unto the people of King Lamoni. And it came to pass that he did teach them all things concerning things pertaining to righteousness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-32', 'coc-bom-1908', 'Alma', 13, 32, 'And it came to pass that he went in unto him into the king''s palace with his brethren, and bowed himself before the king, and said unto him, Behold, O King, we are the brethren of Ammon, whom thou hast delivered out of prison. And now, O King, if thou wilt spare our lives, we will be thy servants.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-36', 'coc-bom-1908', 'Alma', 13, 36, 'Now the king said unto them, What is this that ye have said concerning the Spirit of the Lord? Behold, this is the thing which doth trouble me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-38', 'coc-bom-1908', 'Alma', 13, 38, 'And Aaron answered him and said unto him, Believest thou that there is a God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-41', 'coc-bom-1908', 'Alma', 13, 41, 'And the king said, Is God that Great Spirit that brought our fathers out of the land of Jerusalem?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-42', 'coc-bom-1908', 'Alma', 13, 42, 'And Aaron said unto him, Yea, he is that Great Spirit, and he created all things, both in heaven and in earth. Believest thou this?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-44', 'coc-bom-1908', 'Alma', 13, 44, 'And it came to pass that when Aaron saw that the king would believe his words, he began from the creation of Adam, reading the scriptures unto the king--how God created man after his own image, and that God gave him commandments, and that because of transgression, man had fallen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-45', 'coc-bom-1908', 'Alma', 13, 45, 'And Aaron did expound unto him the scriptures from the creation of Adam, laying the fall of man before him, and their carnal state, and also the plan of redemption, which was prepared from the foundation of the world, through Christ, for all whosoever would believe on his name.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-47', 'coc-bom-1908', 'Alma', 13, 47, 'And that he breaketh the bands of death, that the grave shall have no victory, and that the sting of death should be swallowed up in the hopes of glory. And Aaron did expound all these things unto the king.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-48', 'coc-bom-1908', 'Alma', 13, 48, 'And it came to pass that after Aaron had expounded these things unto him, the king said, What shall I do that I may have this eternal life of which thou hast spoken?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-49', 'coc-bom-1908', 'Alma', 13, 49, 'Yea, what shall I do that I may be born of God, having this wicked spirit rooted out of my breast, and receive his Spirit, that I may be filled with joy, that I may not be cast off at the last day?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-51', 'coc-bom-1908', 'Alma', 13, 51, 'But Aaron said unto him, If thou desirest this thing, if thou wilt bow down before God, yea, if thou wilt repent of all thy sins, and will bow down before God, and call on his name in faith, believing that ye shall receive, then shalt thou receive the hope which thou desirest.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-53', 'coc-bom-1908', 'Alma', 13, 53, 'And if there is a God, and if thou art God, wilt thou make thyself known unto me? And I will give away all my sins to know thee and that I may be raised from the dead and be saved at the last day.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-54', 'coc-bom-1908', 'Alma', 13, 54, 'And now, when the king had said these words, he was struck as if he were dead.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-55', 'coc-bom-1908', 'Alma', 13, 55, 'And it came to pass that his servants ran and told the queen all that had happened unto the king.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-58', 'coc-bom-1908', 'Alma', 13, 58, 'And they pled with the queen, saying, Why commandest thou that we should slay these men, when behold, one of them is mightier than us all? Therefore, we shall fall before them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-59', 'coc-bom-1908', 'Alma', 13, 59, 'Now when the queen saw the fear of the servants, she also began to fear exceedingly, lest there should some evil come upon her.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-60', 'coc-bom-1908', 'Alma', 13, 60, 'And she commanded her servants that they should go and call the people, that they might slay Aaron and his brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-61', 'coc-bom-1908', 'Alma', 13, 61, 'Now when Aaron saw the determination of the queen, and he--also knowing the hardness of the hearts of the people--feared, lest a multitude should assemble themselves together and there should be a great contention and a disturbance among them,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-62', 'coc-bom-1908', 'Alma', 13, 62, 'Therefore, he put forth his hand, and raised the king from the earth, and said unto him, Stand. And he stood upon his feet, receiving his strength.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-63', 'coc-bom-1908', 'Alma', 13, 63, 'Now this was done in the presence of the queen and many of the servants. And when they saw it, they greatly marveled and began to fear.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-64', 'coc-bom-1908', 'Alma', 13, 64, 'And the king stood forth and began to minister unto them. And he did minister unto them insomuch that his whole household were converted unto the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-65', 'coc-bom-1908', 'Alma', 13, 65, 'Now there was a multitude gathered together because of the commandment of the queen, and there began to be great murmurings among them because of Aaron and his brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-66', 'coc-bom-1908', 'Alma', 13, 66, 'But the king stood forth among them and administered unto them. And they were pacified towards Aaron and those who were with him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-67', 'coc-bom-1908', 'Alma', 13, 67, 'And it came to pass that when the king saw that the people were pacified, he caused that Aaron and his brethren should stand forth in the midst of the multitude and that they should preach the word unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-68', 'coc-bom-1908', 'Alma', 13, 68, 'And it came to pass that the king sent a proclamation throughout all the land, amongst all his people who were in all his land, who were in all the regions round about which was bordering even to the sea, on the east and on the west, and which was divided from the land of Zarahemla by a narrow strip of wilderness,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-69', 'coc-bom-1908', 'Alma', 13, 69, 'Which ran from the sea east, even to the sea west, and round about on the borders of the seashore, and the borders of the wilderness which was on the north, by the land of Zarahemla, through the borders of Manti, by the head of the river Sidon, running from the east towards the west. And thus were the Lamanites and the Nephites divided.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-71', 'coc-bom-1908', 'Alma', 13, 71, 'Yea, and also on the west of the land of Zarahemla, in the borders by the seashore, and on the west in the land of Nephi, in the place of their fathers'' first inheritance, and thus bordering along by the seashore.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-73', 'coc-bom-1908', 'Alma', 13, 73, 'Nevertheless, the Nephites had taken possession of all the northern parts of the land bordering on the wilderness, at the head of the river Sidon, from the east to the west, round about on the wilderness side, on the north, even until they came to the land which they called Bountiful.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-74', 'coc-bom-1908', 'Alma', 13, 74, 'And it bordered upon the land which they called Desolation, it being so far northward that it came into the land which had been peopled and been destroyed, of whose bones we have spoken, which was discovered by the people of Zarahemla, it being the place of their first landing. And they came from there up into the south wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-75', 'coc-bom-1908', 'Alma', 13, 75, 'Thus the land on the northward was called Desolation, and the land on the southward was called Bountiful, it being the wilderness which is filled with all manner of wild animals of every kind, a part of which had come from the land northward for food.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-77', 'coc-bom-1908', 'Alma', 13, 77, 'And thus the land of Nephi and the land of Zarahemla were nearly surrounded by water, there being a small neck of land between the land northward and the land southward.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-78', 'coc-bom-1908', 'Alma', 13, 78, 'And it came to pass that the Nephites had inhabited the land Bountiful, even from the east unto the west sea,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-80', 'coc-bom-1908', 'Alma', 13, 80, 'Therefore, the Lamanites could have no more possessions, only in the land of Nephi and the wilderness round about.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-81', 'coc-bom-1908', 'Alma', 13, 81, 'Now this was wisdom in the Nephites. As the Lamanites were an enemy to them, they would not suffer their afflictions on every hand, and also that they might have a country whither they might flee according to their desires.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-13-82', 'coc-bom-1908', 'Alma', 13, 82, 'And now, I, having said this, return again to the account of Ammon, and Aaron, Omner, and Himni, and their brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-4', 'coc-bom-1908', 'Alma', 14, 4, 'And thus they might go forth and preach the word according to their desires, for the king had been converted unto the Lord, and all his household.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-5', 'coc-bom-1908', 'Alma', 14, 5, 'Therefore, he sent this proclamation throughout the land unto his people, that the word of God might have no obstruction, but that it might go forth throughout all the land, that his people might be convinced concerning the wicked traditions of their fathers,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-6', 'coc-bom-1908', 'Alma', 14, 6, 'And that they might be convinced that they were all brethren and that they ought not to murder, nor to plunder, nor to steal, nor to commit adultery, nor to commit any manner of wickedness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-7', 'coc-bom-1908', 'Alma', 14, 7, 'And now, it came to pass that when the king had sent forth this proclamation, that Aaron and his brethren went forth from city to city and from one house of worship to another,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-10', 'coc-bom-1908', 'Alma', 14, 10, 'And as sure as the Lord liveth--so sure as many as believed, or as many as were brought to the knowledge of the truth through the preaching of Ammon and his brethren, according to the spirit of revelation, and of prophecy, and the power of God working miracles in them--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-11', 'coc-bom-1908', 'Alma', 14, 11, 'Yea, I say unto you, As the Lord liveth, as many of the Lamanites as believed in their preaching and were converted unto the Lord never did fall away, for they became a righteous people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-12', 'coc-bom-1908', 'Alma', 14, 12, 'They did lay down the weapons of their rebellion, that they did not fight against God any more, neither against any of their brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-13', 'coc-bom-1908', 'Alma', 14, 13, 'Now these are they who were converted unto the Lord: the people of the Lamanites who were in the land of Ishmael, and also of the people of the Lamanites who were in the land of Middoni, and also of the people of the Lamanites who were in the city of Nephi, and also of the people of the Lamanites who were in the land of Shilom, and who were in the land of Shemlon, and in the city of Lemuel, and in the city of Shimnilon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-16', 'coc-bom-1908', 'Alma', 14, 16, 'Therefore, we have named all the cities of the Lamanites in which they did repent and come to the knowledge of the truth and were converted.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-18', 'coc-bom-1908', 'Alma', 14, 18, 'Therefore, the king consulted with Aaron and many of their priests concerning the name that they should take upon them, that they might be distinguished.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-23', 'coc-bom-1908', 'Alma', 14, 23, 'Now the king conferred the kingdom upon his son, and he called his name Anti-Nephi-Lehi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-24', 'coc-bom-1908', 'Alma', 14, 24, 'And the king died in that selfsame year that the Lamanites began to make preparations for war against the people of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-26', 'coc-bom-1908', 'Alma', 14, 26, 'And from thence they came to the land of Ishmael, that they might hold a council with Lamoni, and also with his brother Anti-Nephi-Lehi, what they should do to defend themselves against the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-29', 'coc-bom-1908', 'Alma', 14, 29, 'Now these are the words which he said unto the people concerning the matter: I thank my God, my beloved people, that our great God has in goodness sent these our brethren, the Nephites, unto us to preach unto us and to convince us of the traditions of our wicked fathers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-32', 'coc-bom-1908', 'Alma', 14, 32, 'And I also thank my God, yea, my great God, that he hath granted unto us that we might repent of these things, and also that he hath forgiven us of those our many sins and murders which we have committed, and took away the guilt from our hearts through the merits of his Son.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-33', 'coc-bom-1908', 'Alma', 14, 33, 'And now, behold, my brethren, since it has been all that we could do (as we were the most lost of all mankind) to repent of all our sins and the many murders which we have committed, and to get God to take them away from our hearts--for it was all we could do to repent sufficiently before God, that he would take away our stain--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-34', 'coc-bom-1908', 'Alma', 14, 34, 'Now, my best beloved brethren, since God hath taken away our stains and our swords have become bright, then let us stain our swords no more with the blood of our brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-36', 'coc-bom-1908', 'Alma', 14, 36, 'For perhaps if we should stain our swords again, they can no more be washed bright through the blood of the Son of our great God, which shall be shed for the atonement of our sins.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-37', 'coc-bom-1908', 'Alma', 14, 37, 'And the great God has had mercy on us and made these things known unto us, that we might not perish.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-39', 'coc-bom-1908', 'Alma', 14, 39, 'And now, behold, since it has been as much as we could do to get our stains taken away from us, and our swords are made bright,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-40', 'coc-bom-1908', 'Alma', 14, 40, 'Let us hide them away that they may be kept bright, as a testimony to our God at the last day, or at the day that we shall be brought to stand before him to be judged, that we have not stained our swords in the blood of our brethren since he imparted his word unto us and has made us clean thereby.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-46', 'coc-bom-1908', 'Alma', 14, 46, 'And thus we see that when these Lamanites were brought to believe and to know the truth, they were firm and would suffer, even unto death, rather than commit sin.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-47', 'coc-bom-1908', 'Alma', 14, 47, 'And thus we see that they buried the weapons of peace, or they buried the weapons of war for peace.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-48', 'coc-bom-1908', 'Alma', 14, 48, 'And it came to pass that their brethren, the Lamanites, made preparations for war and came up to the land of Nephi for the purpose of destroying the king, and to place another in his stead, and also of destroying the people of Anti-Nephi-Lehi out of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-52', 'coc-bom-1908', 'Alma', 14, 52, 'And there were many whose hearts had swollen in them for those of their brethren who had fallen under the sword, for they repented of the things which they had done.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-56', 'coc-bom-1908', 'Alma', 14, 56, 'Now the greatest number of those of the Lamanites who slew so many of their brethren were Amalekites and Amulonites, the greatest number of whom were after the order of the Nehors.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-63', 'coc-bom-1908', 'Alma', 14, 63, 'And the remainder, having fled into the east wilderness and having usurped the power and authority over the Lamanites, caused that many of the Lamanites should perish by fire because of their belief.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-66', 'coc-bom-1908', 'Alma', 14, 66, 'And it came to pass that those rulers who were the remnant of the children of Amulon caused that they should be put to death, yea, all those that believed in these things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-69', 'coc-bom-1908', 'Alma', 14, 69, 'For he said unto them, What ye shall do unto me shall be a type of things to come.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-75', 'coc-bom-1908', 'Alma', 14, 75, 'But notwithstanding the law of Moses, they did look forward to the coming of Christ, considering that the law of Moses was a type of his coming, and believing that they must keep those outward performances until the time that he should be revealed unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-77', 'coc-bom-1908', 'Alma', 14, 77, 'And thus they did retain a hope through faith unto eternal salvation, relying upon the spirit of prophecy, which spake of those things to come.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-78', 'coc-bom-1908', 'Alma', 14, 78, 'And now, behold, Ammon, and Aaron, and Omner, and Himni, and their brethren did rejoice exceedingly for the success which they had had among the Lamanites, seeing that the Lord had granted unto them according to their prayers, and that he had also verified his word unto them in every particular.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-79', 'coc-bom-1908', 'Alma', 14, 79, 'And now, these are the words of Ammon to his brethren, which say thus: My brothers and my brethren, behold, I say unto you, How great reason have we to rejoice! For could we have supposed, when we started from the land of Zarahemla, that God would have granted unto us such great blessings?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-80', 'coc-bom-1908', 'Alma', 14, 80, 'And now, I ask, What great blessings has he bestowed upon us? Can ye tell?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-82', 'coc-bom-1908', 'Alma', 14, 82, 'And this is the blessing which hath been bestowed upon us--that we have been made instruments in the hands of God to bring about this great work.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-83', 'coc-bom-1908', 'Alma', 14, 83, 'Behold, thousands of them do rejoice and have been brought into the fold of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-90', 'coc-bom-1908', 'Alma', 14, 90, 'And it came to pass that when Ammon had said these words, his brother Aaron rebuked him, saying, Ammon, I fear that thy joy doth carry thee away unto boasting.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-97', 'coc-bom-1908', 'Alma', 14, 97, 'Behold, who can glory too much in the Lord? Yea, who can say too much of his great power, and of his mercy, and of his long-suffering towards the children of men? Behold, I say unto you, I cannot say the smallest part which I feel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-98', 'coc-bom-1908', 'Alma', 14, 98, 'Who could have supposed that our God would have been so merciful as to have snatched us from our awful, sinful, and polluted state?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-100', 'coc-bom-1908', 'Alma', 14, 100, 'Oh, my soul almost, as it were, fleeth at the thought.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-101', 'coc-bom-1908', 'Alma', 14, 101, 'Behold, he did not exercise his justice upon us, but in his great mercy hath brought us over that everlasting gulf of death and misery, even to the salvation of our souls.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-104', 'coc-bom-1908', 'Alma', 14, 104, 'Yea, and it shall be given unto such to bring thousands of souls to repentance, even as it has been given unto us to bring these our brethren to repentance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-105', 'coc-bom-1908', 'Alma', 14, 105, 'Now do ye remember, my brethren, that we said unto our brethren in the land of Zarahemla, We go up to the land of Nephi to preach unto our brethren, the Lamanites, and they laughed us to scorn?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-106', 'coc-bom-1908', 'Alma', 14, 106, 'For they said unto us, Do ye suppose that ye can bring the Lamanites to the knowledge of the truth?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-107', 'coc-bom-1908', 'Alma', 14, 107, 'Do ye suppose that ye can convince the Lamanites of the incorrectness of the traditions of their fathers, as stiff-necked a people as they are--whose hearts delight in the shedding of blood, whose days have been spent in the grossest iniquity, whose ways have been the ways of a transgressor from the beginning?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-108', 'coc-bom-1908', 'Alma', 14, 108, 'Now, my brethren, ye remember that this was their language.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-109', 'coc-bom-1908', 'Alma', 14, 109, 'And moreover, they did say, Let us take up arms against them, that we destroy them and their iniquity out of the land, lest they overrun us and destroy us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-110', 'coc-bom-1908', 'Alma', 14, 110, 'But behold, my beloved brethren, we came into the wilderness, not with the intent to destroy our brethren, but with the intent that perhaps we might save some few of their souls.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-116', 'coc-bom-1908', 'Alma', 14, 116, 'Now behold, we can look forth and see the fruits of our labors. And are they few?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-119', 'coc-bom-1908', 'Alma', 14, 119, 'And now, behold, I say unto you, Has there been so great love in all the land?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-120', 'coc-bom-1908', 'Alma', 14, 120, 'Behold, I say unto you, Nay, there has not, even among the Nephites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-14-123', 'coc-bom-1908', 'Alma', 14, 123, 'Now have we not reason to rejoice? Yea, I say unto you, There never were men that had so great reason to rejoice as we since the world began.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-1', 'coc-bom-1908', 'Alma', 15, 1, 'Now it came to pass that when those Lamanites who had gone to war against the Nephites had found, after their many struggles to destroy them, that it was in vain to seek their destruction, they returned again to the land of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-2', 'coc-bom-1908', 'Alma', 15, 2, 'And it came to pass that the Amalekites, because of their loss, were exceeding angry.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-4', 'coc-bom-1908', 'Alma', 15, 4, 'Now this people again refused to take their arms, and they suffered themselves to be slain according to the desires of their enemies.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-5', 'coc-bom-1908', 'Alma', 15, 5, 'Now when Ammon and his brethren saw this work of destruction among those whom they so dearly beloved, and among those who had so dearly beloved them--for they were treated as though they were angels sent from God to save them from everlasting destruction--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-7', 'coc-bom-1908', 'Alma', 15, 7, 'But the king said unto them, Behold, the Nephites will destroy us because of the many murders and sins we have committed against them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-13', 'coc-bom-1908', 'Alma', 15, 13, 'And now, it came to pass that Ammon went and told the king all the words which the Lord had said unto him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-14', 'coc-bom-1908', 'Alma', 15, 14, 'And they gathered together all their people, yea, all the people of the Lord, and did gather together all their flocks and herds, and departed out of the land, and came into the wilderness which divided the land of Nephi from the land of Zarahemla, and came over near the borders of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-18', 'coc-bom-1908', 'Alma', 15, 18, 'Now was not this exceeding joy? Behold, this is joy which none receiveth save it be the truly penitent and humble seeker of happiness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-20', 'coc-bom-1908', 'Alma', 15, 20, 'And now, it came to pass that Alma conducted his brethren back to the land of Zarahemla, even to his own house.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-21', 'coc-bom-1908', 'Alma', 15, 21, 'And they went and told the chief judge all the things that had happened unto them in the land of Nephi among their brethren, the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-22', 'coc-bom-1908', 'Alma', 15, 22, 'And it came to pass that the chief judge sent a proclamation throughout all the land, desiring the voice of the people concerning the admitting their brethren, who were the people of Anti-Nephi-Lehi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-27', 'coc-bom-1908', 'Alma', 15, 27, 'Now it came to pass that when Ammon had heard this, he returned to the people of Anti-Nephi-Lehi, and also Alma with him, into the wilderness where they had pitched their tents, and made known unto them all these things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-28', 'coc-bom-1908', 'Alma', 15, 28, 'And Alma also related unto them his conversion with Ammon, and Aaron, and his brethren. And it came to pass that it did cause great joy among them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-34', 'coc-bom-1908', 'Alma', 15, 34, 'Therefore, they would suffer death in the most aggravating and distressing manner which could be inflicted by their brethren before they would take the sword or the cimeter to smite them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-35', 'coc-bom-1908', 'Alma', 15, 35, 'And thus they were a zealous and beloved people, a highly favored people of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-36', 'coc-bom-1908', 'Alma', 15, 36, 'And now, it came to pass that after the people of Ammon were established in the land of Jershon, and a church also established in the land of Jershon, and the armies of the Nephites were set round about the land of Jershon--yea, in all the borders round about the land of Zarahemla--behold, the armies of the Lamanites had followed their brethren into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-39', 'coc-bom-1908', 'Alma', 15, 39, 'And now, this was a time that there was a great mourning and lamentation heard throughout all the land among all the people of Nephi,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-41', 'coc-bom-1908', 'Alma', 15, 41, 'And thus the cry of mourning was heard among every one of them, mourning for their kindred who had been slain.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-43', 'coc-bom-1908', 'Alma', 15, 43, 'And this is the account of Ammon and his brethren, their journeyings in the land of Nephi, their sufferings in the land, their sorrows, and their afflictions, and their incomprehensible joy, and the reception and safety of the brethren in the land of Jershon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-44', 'coc-bom-1908', 'Alma', 15, 44, 'And now, may the Lord, the Redeemer of all men, bless their souls forever.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-47', 'coc-bom-1908', 'Alma', 15, 47, 'And the bodies of many thousands are laid low in the earth, while the bodies of many thousands are mouldering in heaps upon the face of the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-53', 'coc-bom-1908', 'Alma', 15, 53, 'Yea, I would declare unto every soul, as with the voice of thunder, repentance and the plan of redemption--that they should repent and come unto our God, that there might be no more sorrow upon all the face of the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-57', 'coc-bom-1908', 'Alma', 15, 57, 'Now, seeing that I know these things, why should I desire more than to perform the work to which I have been called?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-58', 'coc-bom-1908', 'Alma', 15, 58, 'Why should I desire that I was an angel, that I could speak unto all the ends of the earth?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-67', 'coc-bom-1908', 'Alma', 15, 67, 'Now when I think of the success of these, my brethren, my soul is carried away, even to the separation of it from the body, as it were, so great is my joy.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-68', 'coc-bom-1908', 'Alma', 15, 68, 'And now, may God grant unto these, my brethren, that they may sit down in the kingdom of God, yea, and also all those who are the fruit of their labors, that they may go no more out, but that they may praise him forever.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-15-69', 'coc-bom-1908', 'Alma', 15, 69, 'And may God grant that it may be done according to my words, even as I have spoken. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-1', 'coc-bom-1908', 'Alma', 16, 1, 'Behold, now it came to pass that after the people of Ammon were established in the land of Jershon, yea, and also after the Lamanites were driven out of the land and their dead were buried by the people of the land--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-3', 'coc-bom-1908', 'Alma', 16, 3, 'But it came to pass after they had buried their dead and also after the days of fasting, and mourning, and prayer (and it was in the sixteenth year of the reign of the judges over the people of Nephi), there began to be continual peace throughout all the land, yea, and the people did observe to keep the commandments of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-5', 'coc-bom-1908', 'Alma', 16, 5, 'And thus the people did have no disturbance in all the sixteenth year of the reign of the judges over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-6', 'coc-bom-1908', 'Alma', 16, 6, 'And it came to pass in the seventeenth year of the reign of the judges there was continual peace.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-9', 'coc-bom-1908', 'Alma', 16, 9, 'For thus saith the scripture, Choose ye this day whom ye will serve.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-13', 'coc-bom-1908', 'Alma', 16, 13, 'And this antichrist, whose name was Korihor (and the law could have no hold upon him), began to preach unto the people that there should be no Christ.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-14', 'coc-bom-1908', 'Alma', 16, 14, 'And after this manner did he preach, saying, O ye that are bound down under a foolish and a vain hope, why do ye yoke yourselves with such foolish things? Why do ye look for a Christ? For no man can know of anything which is to come.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-15', 'coc-bom-1908', 'Alma', 16, 15, 'Behold, these things which ye call prophecies, which ye say are handed down by holy prophets, behold, they are foolish traditions of your fathers. How do ye know of their surety?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-19', 'coc-bom-1908', 'Alma', 16, 19, 'And thus he did preach unto them, leading away the hearts of many, causing them to lift up their heads in their wickedness, yea, leading away many women and also men to commit whoredoms, telling them that when a man was dead, that was the end thereof.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-20', 'coc-bom-1908', 'Alma', 16, 20, 'Now this man went over to the land of Jershon also, to preach these things among the people of Ammon, who were once the people of the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-22', 'coc-bom-1908', 'Alma', 16, 22, 'And it came to pass that he caused that he should be carried out of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-24', 'coc-bom-1908', 'Alma', 16, 24, 'And it came to pass that the high priest said unto him, Why do ye go about perverting the ways of the Lord?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-25', 'coc-bom-1908', 'Alma', 16, 25, 'Why do ye teach this people that there shall be no Christ, to interrupt their rejoicings?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-26', 'coc-bom-1908', 'Alma', 16, 26, 'Why do ye speak against all the prophecies of the holy prophets?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-27', 'coc-bom-1908', 'Alma', 16, 27, 'Now the high priest''s name was Giddonah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-28', 'coc-bom-1908', 'Alma', 16, 28, 'And Korihor said unto him, Because I do not teach the foolish traditions of your fathers, and because I do not teach this people to bind themselves down under the foolish ordinances and performances which are laid down by ancient priests to usurp power and authority over them, to keep them in ignorance, that they may not lift up their heads, but be brought down according to thy words.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-29', 'coc-bom-1908', 'Alma', 16, 29, 'Ye say that this people is a free people. Behold, I say they are in bondage.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-30', 'coc-bom-1908', 'Alma', 16, 30, 'Ye say that those ancient prophecies are true. Behold, I say that ye do not know that they are true.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-31', 'coc-bom-1908', 'Alma', 16, 31, 'Ye say that this people is a guilty and a fallen people because of the transgression of a parent. Behold, I say that a child is not guilty because of its parents.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-32', 'coc-bom-1908', 'Alma', 16, 32, 'And ye also say that Christ shall come. But behold, I say that ye do not know that there shall be a Christ.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-35', 'coc-bom-1908', 'Alma', 16, 35, 'Yea, they durst not make use of that which is their own, lest they should offend their priests, who do yoke them according to their desires and have brought them to believe by their traditions, and their dreams, and their whims, and their visions, and their pretended mysteries, that they should--if they did not do according to their words--offend some unknown being, who they say is God, a being who never has been seen nor known, who never was nor ever will be.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-39', 'coc-bom-1908', 'Alma', 16, 39, 'And he did rise up in great swelling words before Alma and did revile against the priests and teachers, accusing them of leading away the people after the silly traditions of their fathers for the sake of glutting in the labors of the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-42', 'coc-bom-1908', 'Alma', 16, 42, 'And now, if we do not receive anything for our labors in the church, what doth it profit us to labor in the church, save it were to declare the truth, that we may have rejoicings in the joy of our brethren?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-43', 'coc-bom-1908', 'Alma', 16, 43, 'Then why sayest thou that we preach unto this people to get gain, when thou of thyself knowest that we receive no gain?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-44', 'coc-bom-1908', 'Alma', 16, 44, 'And now, believest thou that we deceive this people, that causes such joy in their hearts?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-45', 'coc-bom-1908', 'Alma', 16, 45, 'And Korihor answered him, Yea.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-46', 'coc-bom-1908', 'Alma', 16, 46, 'And then Alma said unto him, Believest thou that there is a God? And he answered, Nay.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-47', 'coc-bom-1908', 'Alma', 16, 47, 'Now Alma said unto him, Will ye deny again that there is a God and also deny the Christ? For behold, I say unto you, I know there is a God and also that Christ shall come.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-48', 'coc-bom-1908', 'Alma', 16, 48, 'And now, what evidence have ye that there is no God, or that Christ cometh not? I say unto you that ye have none, save it be your word only.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-50', 'coc-bom-1908', 'Alma', 16, 50, 'Believest thou that these things are true?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-52', 'coc-bom-1908', 'Alma', 16, 52, 'And now, Korihor said unto Alma, If thou wilt show me a sign, that I may be convinced that there is a God, yea, show unto me that he hath power, and then will I be convinced of the truth of thy words.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-53', 'coc-bom-1908', 'Alma', 16, 53, 'But Alma said unto him, Thou hast had signs enough. Will ye tempt your God? Will ye say, Show unto me a sign, when ye have the testimony of all these, thy brethren and also all the holy prophets?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-55', 'coc-bom-1908', 'Alma', 16, 55, 'Yea, and also all the planets which move in their regular form do witness that there is a Supreme Creator. And yet do ye go about, leading away the hearts of this people, testifying unto them there is no God? And yet will ye deny against all these witnesses?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-56', 'coc-bom-1908', 'Alma', 16, 56, 'And he said, Yea, I will deny, except ye shall show me a sign.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-57', 'coc-bom-1908', 'Alma', 16, 57, 'And now, it came to pass that Alma said unto him, Behold, I am grieved because of the hardness of your heart, yea, that ye will still resist the spirit of the truth, that thy soul may be destroyed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-59', 'coc-bom-1908', 'Alma', 16, 59, 'Therefore, if thou shalt deny again, behold, God shall smite thee, that thou shalt become dumb, that thou shalt never open thy mouth any more, that thou shalt not deceive this people any more.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-62', 'coc-bom-1908', 'Alma', 16, 62, 'Now when Alma had said these words, Korihor was struck dumb, that he could not have utterance, according to the words of Alma.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-63', 'coc-bom-1908', 'Alma', 16, 63, 'And now, when the chief judge saw this, he put forth his hand and wrote unto Korihor, saying, Art thou convinced of the power of God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-64', 'coc-bom-1908', 'Alma', 16, 64, 'In whom did ye desire that Alma should show forth his sign? Would ye that he should afflict others to show unto thee a sign?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-65', 'coc-bom-1908', 'Alma', 16, 65, 'Behold, he has showed unto you a sign. And now, will ye dispute more?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-70', 'coc-bom-1908', 'Alma', 16, 70, 'Now when he had said this, he besought that Alma should pray unto God that the curse might be taken from him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-75', 'coc-bom-1908', 'Alma', 16, 75, 'And Korihor did go about from house to house, begging food for his support.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-76', 'coc-bom-1908', 'Alma', 16, 76, 'And it came to pass that as he went forth among the people--yea, among a people who had separated themselves from the Nephites and called themselves Zoramites, being led by a man whose name was Zoram--and as he went forth amongst them, behold, he was run upon and trodden down, even until he was dead.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-80', 'coc-bom-1908', 'Alma', 16, 80, 'Now the Zoramites had gathered themselves together in a land which they called Antionum, which was east of the land of Zarahemla, which lay nearly bordering upon the seashore, which was south of the land of Jershon, which also bordered upon the wilderness south, which wilderness was full of the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-81', 'coc-bom-1908', 'Alma', 16, 81, 'Now the Nephites greatly feared that the Zoramites would enter into a correspondence with the Lamanites and that it would be the means of great loss on the part of the Nephites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-82', 'coc-bom-1908', 'Alma', 16, 82, 'And now, as the preaching of the word had had a greater tendency to lead the people to do that which was just--yea, it had had more powerful effect upon the minds of the people than the sword, or anything else, which had happened unto them--therefore, Alma thought it was expedient that they should try the virtue of the word of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-93', 'coc-bom-1908', 'Alma', 16, 93, 'And we also thank thee that thou hast elected us, that we may not be led away after the foolish traditions of our brethren, which doth bind them down to a belief of Christ, which doth lead their hearts to wander far from thee, our God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-94', 'coc-bom-1908', 'Alma', 16, 94, 'And again, we thank thee, O God, that we are a chosen and a holy people. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-95', 'coc-bom-1908', 'Alma', 16, 95, 'Now it came to pass that after Alma, and his brethren, and his sons had heard these prayers, they were astonished beyond all measure.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-96', 'coc-bom-1908', 'Alma', 16, 96, 'For behold, every man did go forth and offer up the same prayers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-97', 'coc-bom-1908', 'Alma', 16, 97, 'Now the place was called by them Rameumptom, which, being interpreted, is the holy stand.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-98', 'coc-bom-1908', 'Alma', 16, 98, 'Now from this stand, they did offer up, every man, the selfsame prayer unto God, thanking their God that they were chosen of him, and that he did not lead them away after the tradition of their brethren, and that their hearts were not stolen away to believe in things to come, which they knew nothing about.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-99', 'coc-bom-1908', 'Alma', 16, 99, 'Now after the people had all offered up thanks after this manner, they returned to their homes, never speaking of their God again until they had assembled themselves together again to the holy stand to offer up thanks after their manner.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-101', 'coc-bom-1908', 'Alma', 16, 101, 'Yea, and he also saw that their hearts were lifted up unto great boasting in their pride.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-102', 'coc-bom-1908', 'Alma', 16, 102, 'And he lifted up his voice to heaven and cried, saying, Oh, how long, O Lord, wilt thou suffer that thy servants shall dwell here below in the flesh to behold such gross wickedness among the children of men?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-103', 'coc-bom-1908', 'Alma', 16, 103, 'Behold, O God, they cry unto thee, and yet their hearts are swallowed up in their pride.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-104', 'coc-bom-1908', 'Alma', 16, 104, 'Behold, O God, they cry unto thee with their mouths, while they are puffed up, even to greatness, with the vain things of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-107', 'coc-bom-1908', 'Alma', 16, 107, 'Yea, and they say that thou hast made it known unto them that there shall be no Christ.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-108', 'coc-bom-1908', 'Alma', 16, 108, 'O Lord God, how long wilt thou suffer that such wickedness and iniquity shall be among this people?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-109', 'coc-bom-1908', 'Alma', 16, 109, 'O Lord, wilt thou give me strength, that I may bear with mine infirmities? For I am infirm, and such wickedness among this people doth pain my soul.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-110', 'coc-bom-1908', 'Alma', 16, 110, 'O Lord, my heart is exceeding sorrowful. Wilt thou comfort my soul in Christ?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-111', 'coc-bom-1908', 'Alma', 16, 111, 'O Lord, wilt thou grant unto me that I may have strength, that I may suffer with patience these afflictions which shall come upon me because of the iniquity of this people?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-112', 'coc-bom-1908', 'Alma', 16, 112, 'O Lord, wilt thou comfort my soul and give unto me success, and also my fellow laborers who are with me, yea, Ammon, and Aaron, and Omner, and also Amulek, and Zeezrom, and also my two sons? Yea, even all these wilt thou comfort, O Lord? Yea, wilt thou comfort their souls in Christ?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-113', 'coc-bom-1908', 'Alma', 16, 113, 'Wilt thou grant unto them that they may have strength, that they may bear their afflictions which shall come upon them because of the iniquities of this people?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-114', 'coc-bom-1908', 'Alma', 16, 114, 'O Lord, wilt thou grant unto us that we may have success in bringing them again unto thee in Christ?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-116', 'coc-bom-1908', 'Alma', 16, 116, 'Now it came to pass that when Alma had said these words, that he clapped his hands upon all them who were with him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-117', 'coc-bom-1908', 'Alma', 16, 117, 'And behold, as he clapped his hands upon them, they were filled with the Holy Spirit.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-118', 'coc-bom-1908', 'Alma', 16, 118, 'And after that, they did separate themselves one from another, taking no thought for themselves, what they should eat, or what they should drink, or what they should put on.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-124', 'coc-bom-1908', 'Alma', 16, 124, 'Now as Alma was teaching and speaking unto the people upon the hill Onidah, there came a great multitude unto him, who were those of whom we have been speaking, who were poor in heart because of their poverty as to the things of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-129', 'coc-bom-1908', 'Alma', 16, 129, 'Behold, thy brother hath said, What shall we do? For we are cast out of our synagogues, that we cannot worship our God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-130', 'coc-bom-1908', 'Alma', 16, 130, 'Behold, I say unto you, Do ye suppose that ye cannot worship God, save it be in your synagogues only?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-131', 'coc-bom-1908', 'Alma', 16, 131, 'And moreover, I would ask, Do ye suppose that ye must not worship God only once in a week?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-136', 'coc-bom-1908', 'Alma', 16, 136, 'And now, as I said unto you, that because ye were compelled to be humble, ye were blessed, do ye not suppose that they are more blessed who truly humble themselves because of the word?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-138', 'coc-bom-1908', 'Alma', 16, 138, 'Or rather, in other words, Blessed is he that believeth in the word of God and is baptized without stubbornness of heart, yea, without being brought to know the word or even compelled to know before they will believe.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-139', 'coc-bom-1908', 'Alma', 16, 139, 'Yea, there are many who do say, If thou wilt show unto us a sign from heaven, then we shall know of a surety, then we shall believe.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-141', 'coc-bom-1908', 'Alma', 16, 141, 'And now, how much more cursed is he that knoweth the will of God and doeth it not, than he that only believeth, or only hath cause to believe, and falleth into transgression? Now of this thing ye must judge.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-144', 'coc-bom-1908', 'Alma', 16, 144, 'And now, behold, I say unto you--and I would that ye should remember that God is merciful unto all who believe on his name--therefore, he desireth, in the first place, that ye should believe, yea, even on his word.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-145', 'coc-bom-1908', 'Alma', 16, 145, 'And now, he imparteth his word by angels unto men--yea, not only men, but women also.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-146', 'coc-bom-1908', 'Alma', 16, 146, 'Now this is not all. Little children do have words given unto them many times, which confound the wise and the learned.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-149', 'coc-bom-1908', 'Alma', 16, 149, 'Now as I said concerning faith, that it was not a perfect knowledge, even so it is with my words.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-150', 'coc-bom-1908', 'Alma', 16, 150, 'Ye cannot know of their surety at first, unto perfection, any more than faith is a perfect knowledge.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-151', 'coc-bom-1908', 'Alma', 16, 151, 'But behold, if ye will awake, and arouse your faculties, even to an experiment upon my words, and exercise a particle of faith, yea, even if ye can no more than desire to believe, let this desire work in you, even until ye believe in a manner that ye can give place for a portion of my words.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-152', 'coc-bom-1908', 'Alma', 16, 152, 'Now we will compare the word unto a seed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-157', 'coc-bom-1908', 'Alma', 16, 157, 'And now, behold, will not this strengthen your faith? Yea, it will strengthen your faith, for ye will say, I know that this is a good seed, for behold, it sprouteth and beginneth to grow.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-159', 'coc-bom-1908', 'Alma', 16, 159, 'And now, behold, because ye have tried the experiment and planted the seed, and it swelleth, and sprouteth, and beginneth to grow, ye must needs know that the seed is good.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-164', 'coc-bom-1908', 'Alma', 16, 164, 'And behold, as the tree beginneth to grow, ye will say, Let us nourish it with great care, that it may get root, that it may grow up and bring forth fruit unto us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-165', 'coc-bom-1908', 'Alma', 16, 165, 'And now, behold, if ye nourish it with much care, it will get root, and grow up, and bring forth fruit.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-169', 'coc-bom-1908', 'Alma', 16, 169, 'And thus it is if ye will not nourish the word, looking forward with an eye of faith to the fruit thereof, ye can never pluck of the fruit of the tree of life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-171', 'coc-bom-1908', 'Alma', 16, 171, 'And because of your diligence, and your faith, and your patience with the word, in nourishing it, that it may take root in you, behold, by and by ye shall pluck the fruit thereof, which is most precious, which is sweet above all that is sweet, and which is white above all that is white, yea, and pure above all that is pure.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-173', 'coc-bom-1908', 'Alma', 16, 173, 'Then, my brethren, ye shall reap the rewards of your faith, and your diligence, and patience, and long-suffering, waiting for the tree to bring forth fruit unto you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-174', 'coc-bom-1908', 'Alma', 16, 174, 'Now after Alma had spoken these words, they sent forth unto him desiring to know whether they should believe in one God, that they might obtain this fruit of which he had spoken, or how they should plant the seed, or the word of which he had spoken, which he said must be planted in their hearts, or in what manner they should begin to exercise their faith.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-175', 'coc-bom-1908', 'Alma', 16, 175, 'And Alma said unto them, Behold, ye have said that ye could not worship your God because ye are cast out of your synagogues.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-177', 'coc-bom-1908', 'Alma', 16, 177, 'Do ye remember to have read what Zenos, the prophet of old, has said concerning prayer or worship?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-180', 'coc-bom-1908', 'Alma', 16, 180, 'And again, O God, when I did turn to my house, thou didst hear me in my prayer.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-185', 'coc-bom-1908', 'Alma', 16, 185, 'And now, Alma said unto them, Do ye believe those scriptures which have been written by them of old?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-187', 'coc-bom-1908', 'Alma', 16, 187, 'Now, behold, my brethren, I would ask, if ye have read the scriptures? If ye have, how can ye disbelieve on the Son of God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-188', 'coc-bom-1908', 'Alma', 16, 188, 'For it is not written that Zenos alone spake of these things, but Zenock also spake of these things. For behold, he said, Thou art angry, O Lord, with this people because they will not understand of thy mercies which thou hast bestowed upon them because of thy Son.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-192', 'coc-bom-1908', 'Alma', 16, 192, 'But few understood the meaning of those things, and this because of the hardness of their hearts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-194', 'coc-bom-1908', 'Alma', 16, 194, 'Now the reason they would not look was because they did not believe that it would heal them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-195', 'coc-bom-1908', 'Alma', 16, 195, 'O my brethren, if ye could be healed by merely casting about your eyes, that ye might be healed, would ye not behold quickly? Or would ye rather harden your hearts in unbelief and be slothful, that ye would not cast about your eyes, that ye might perish?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-197', 'coc-bom-1908', 'Alma', 16, 197, 'And that he shall rise again from the dead, which shall bring to pass the resurrection, that all men shall stand before him to be judged at the last and judgment day according to their works.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-199', 'coc-bom-1908', 'Alma', 16, 199, 'And behold, it will become a tree, springing up in you unto everlasting life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-200', 'coc-bom-1908', 'Alma', 16, 200, 'And then may God grant unto you that your burdens may be light, through the joy of his Son. And even all this can ye do, if ye will. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-202', 'coc-bom-1908', 'Alma', 16, 202, 'Yea, I know that these things were taught unto you bountifully before your dissension from among us. And as ye have desired of my beloved brother that he should make known unto you what ye should do because of your afflictions, and he hath spoken somewhat unto you to prepare your minds, yea, and he hath exhorted you unto faith and to patience,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-203', 'coc-bom-1908', 'Alma', 16, 203, 'Yea, even that ye would have so much faith as even to plant the word in your hearts, that ye may try the experiment of its goodness. And we have beheld that the great question which is in your minds is whether the word be in the Son of God or whether there shall be no Christ.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-204', 'coc-bom-1908', 'Alma', 16, 204, 'And ye also beheld that my brother has proven unto you, in many instances, that the word is in Christ unto salvation.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-206', 'coc-bom-1908', 'Alma', 16, 206, 'And now, behold, I will testify unto you of myself that these things are true.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-211', 'coc-bom-1908', 'Alma', 16, 211, 'Now there is not any man that can sacrifice his own blood, which will atone for the sins of another.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-212', 'coc-bom-1908', 'Alma', 16, 212, 'Now if a man murdereth, behold, will our law, which is just, take the life of his brother? I say unto you, Nay.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-216', 'coc-bom-1908', 'Alma', 16, 216, 'This being the intent of this last sacrifice, to bring about the bowels of mercy, which overpowereth justice and bringeth about means unto men, that they may have faith unto repentance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-222', 'coc-bom-1908', 'Alma', 16, 222, 'Yea, and when you do not cry unto the Lord, let your hearts be full, drawn out in prayer unto him continually for your welfare and also for the welfare of those who are around you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-223', 'coc-bom-1908', 'Alma', 16, 223, 'And now, behold, my brethren, I say unto you, Do not suppose that this is all. For after ye have done all these things, if ye turn away the needy and the naked, and visit not the sick and afflicted, and impart not of your substance, if ye have, to those who stand in need--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-225', 'coc-bom-1908', 'Alma', 16, 225, 'Therefore, if ye do not remember to be charitable, ye are as dross, which the refiners do cast out (it being of no worth) and is trodden underfoot of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-230', 'coc-bom-1908', 'Alma', 16, 230, 'For after this day of life, which is given us to prepare for eternity, behold, if we do not improve our time while in this life, then cometh the night of darkness, wherein there can be no labor performed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-231', 'coc-bom-1908', 'Alma', 16, 231, 'Ye cannot say, when ye are brought to that awful crisis, that I will repent, that I will return to my God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-241', 'coc-bom-1908', 'Alma', 16, 241, 'Yea, and the rest of the brethren, after they had preached the word unto the Zoramites, also came over into the land of Jershon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-243', 'coc-bom-1908', 'Alma', 16, 243, 'And they sent, and gathered together--throughout all the land--all the people, and consulted with them concerning the words which had been spoken.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-246', 'coc-bom-1908', 'Alma', 16, 246, 'And it came to pass that Alma and his brethren did minister unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-248', 'coc-bom-1908', 'Alma', 16, 248, 'And he breathed out many threatenings against them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-252', 'coc-bom-1908', 'Alma', 16, 252, 'And thus the Zoramites and the Lamanites began to make preparations for war against the people of Ammon and also against the Nephites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-253', 'coc-bom-1908', 'Alma', 16, 253, 'And thus ended the seventeenth year of the reign of the judges over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-257', 'coc-bom-1908', 'Alma', 16, 257, 'But they have lands for their inheritance in the land of Jershon, and they have taken up arms to defend themselves, and their wives, and children, and their lands.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-260', 'coc-bom-1908', 'Alma', 16, 260, 'Therefore, he caused that his sons should be gathered together that he might give unto them every one his charge, separately, concerning the things pertaining unto righteousness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-16-261', 'coc-bom-1908', 'Alma', 16, 261, 'And we have an account of his commandments, which he gave unto them according to his own record.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-4', 'coc-bom-1908', 'Alma', 17, 4, 'And I would not that ye think that I know of myself--not of the temporal, but of the spiritual, not of the carnal mind, but of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-7', 'coc-bom-1908', 'Alma', 17, 7, 'But behold, the voice said unto me, Arise. And I arose, and stood up, and beheld the angel. And he said unto me, If thou wilt not of thyself be destroyed, seek no more to destroy the church of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-12', 'coc-bom-1908', 'Alma', 17, 12, 'Yea, and, in fine, so great had been my iniquities that the very thoughts of coming into the presence of my God did rack my soul with inexpressible horror.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-13', 'coc-bom-1908', 'Alma', 17, 13, 'Oh, thought I, that I could be banished and become extinct, both soul and body, that I might not be brought to stand in the presence of my God to be judged of my deeds.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-14', 'coc-bom-1908', 'Alma', 17, 14, 'And now, for three days and for three nights was I racked, even with the pains of a damned soul.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-15', 'coc-bom-1908', 'Alma', 17, 15, 'And it came to pass that as I was thus racked with torment, while I was harrowed up by the memory of my many sins, behold, I remembered also to have heard my father prophesy unto the people concerning the coming of one Jesus Christ, a Son of God, to atone for the sins of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-16', 'coc-bom-1908', 'Alma', 17, 16, 'Now as my mind caught hold upon this thought, I cried within my heart, O Jesus, thou Son of God, have mercy on me, who am in the gall of bitterness and am encircled about by the everlasting chains of death.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-22', 'coc-bom-1908', 'Alma', 17, 22, 'Yea, and from that time even until now, I have labored without ceasing, that I might bring souls unto repentance, that I might bring them to taste of the exceeding joy of which I did taste, that they might also be born of God and be filled with the Holy Ghost.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-30', 'coc-bom-1908', 'Alma', 17, 30, 'And ye ought to know also, that inasmuch as ye will not keep the commandments of God, ye shall be cut off from his presence. Now this is according to his word.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-32', 'coc-bom-1908', 'Alma', 17, 32, 'And these plates of brass which contain these engravings, which have the records of the holy scriptures upon them, which have the genealogy of our forefathers, even from the beginning.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-33', 'coc-bom-1908', 'Alma', 17, 33, 'And behold, it has been prophesied by our fathers that they should be kept, and handed down from one generation to another, and be kept and preserved by the hand of the Lord until they should go forth unto every nation, kindred, tongue, and people, that they shall know of the mysteries contained thereon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-40', 'coc-bom-1908', 'Alma', 17, 40, 'And who knoweth but what they will be the means of bringing many thousands of them, yea, and also many thousands of our stiff-necked brethren, the Nephites, who are now hardening their hearts in sins and iniquities, to the knowledge of their Redeemer.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-43', 'coc-bom-1908', 'Alma', 17, 43, 'Oh, remember, remember, my son Helaman, how strict are the commandments of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-45', 'coc-bom-1908', 'Alma', 17, 45, 'And now, remember, my son, that God has entrusted you with these things which are sacred, which he has kept sacred, and also which he will keep and preserve for a wise purpose in him, that he may show forth his power unto future generations.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-46', 'coc-bom-1908', 'Alma', 17, 46, 'And now, behold, I tell you by the spirit of prophecy that if ye transgress the commandments of God, behold, these things which are sacred shall be taken away from you by the power of God, and ye shall be delivered up unto Satan, that he may sift you as chaff before the wind.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-47', 'coc-bom-1908', 'Alma', 17, 47, 'But if ye keep the commandments of God and do with these things which are sacred according to that which the Lord doth command you (for you must appeal unto the Lord for all things whatsoever ye must do with them), behold, no power of earth or hell can take them from you, for God is powerful to the fulfilling of all his words.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-48', 'coc-bom-1908', 'Alma', 17, 48, 'For he will fulfill all his promises which he shall make unto you, for he has fulfilled his promises which he has made unto our fathers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-49', 'coc-bom-1908', 'Alma', 17, 49, 'For he promised unto them that he would reserve these things for a wise purpose in him, that he might show forth his power unto future generations.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-51', 'coc-bom-1908', 'Alma', 17, 51, 'Therefore, I command you, my son Helaman, that ye be diligent in fulfilling all my words and that ye be diligent in keeping the commandments of God as they are written.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-55', 'coc-bom-1908', 'Alma', 17, 55, 'And the Lord said, I will prepare unto my servant Gazelem, a stone, which shall shine forth in darkness unto light, that I may discover unto my people who serve me, that I may discover unto them the works of their brethren, yea, their secret works, their works of darkness, and their wickedness and abominations.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-72', 'coc-bom-1908', 'Alma', 17, 72, 'And behold, there cannot any man work after the manner of so curious a workmanship.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-75', 'coc-bom-1908', 'Alma', 17, 75, 'Nevertheless, because those miracles were worked by small means, it did show unto them marvelous works.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-77', 'coc-bom-1908', 'Alma', 17, 77, 'Therefore, they tarried in the wilderness, or did not travel a direct course, and were afflicted with hunger and thirst because of their transgressions.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-79', 'coc-bom-1908', 'Alma', 17, 79, 'For behold, it is as easy to give heed to the word of Christ, which will point to you a straight course to eternal bliss, as it was for our fathers to give heed to this compass, which would point unto them a straight course to the promised land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-80', 'coc-bom-1908', 'Alma', 17, 80, 'And now, I say, Is there not a type in this thing? For just as surely as this director did bring our fathers, by following its course, to the promised land, shall the words of Christ, if we follow their course, carry us beyond this vale of sorrow into a far better land of promise.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-17-84', 'coc-bom-1908', 'Alma', 17, 84, 'Go unto this people, and declare the word, and be sober. My son, farewell.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-18-3', 'coc-bom-1908', 'Alma', 18, 3, 'I say unto you, my son, that I have had great joy in thee already because of thy faithfulness, and thy diligence, and thy patience, and thy long-suffering among the people of the Zoramites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-18-10', 'coc-bom-1908', 'Alma', 18, 10, 'But behold, I did cry unto him, and I did find peace to my soul.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-18-11', 'coc-bom-1908', 'Alma', 18, 11, 'And now, my son, I have told you this that ye may learn wisdom, that ye may learn of me that there is no other way nor means whereby man can be saved, only in and through Christ.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-18-12', 'coc-bom-1908', 'Alma', 18, 12, 'Behold, he is the life and the light of the world. Behold, he is the word of truth and righteousness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-18-17', 'coc-bom-1908', 'Alma', 18, 17, 'And may the Lord bless your soul and receive you at the last day into his kingdom, to sit down in peace.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-18-18', 'coc-bom-1908', 'Alma', 18, 18, 'Now go, my son, and teach the word unto this people. Be sober. My son, farewell.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-1', 'coc-bom-1908', 'Alma', 19, 1, 'And now, my son, I have somewhat more to say unto thee than what I said unto thy brother. For behold, have ye not observed the steadiness of thy brother, his faithfulness, and his diligence in keeping the commandments of God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-2', 'coc-bom-1908', 'Alma', 19, 2, 'Behold, has he not set a good example for thee?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-3', 'coc-bom-1908', 'Alma', 19, 3, 'For thou didst not give so much heed unto my words as did thy brother among the people of the Zoramites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-4', 'coc-bom-1908', 'Alma', 19, 4, 'Now this is what I have against thee: Thou didst go on unto boasting in thy strength and thy wisdom.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-6', 'coc-bom-1908', 'Alma', 19, 6, 'Thou shouldest have tended to the ministry wherewith thou wast entrusted.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-7', 'coc-bom-1908', 'Alma', 19, 7, 'Know ye not, my son, that these things are an abomination in the sight of the Lord--yea, most abominable above all sins, save it be the shedding of innocent blood or denying the Holy Ghost?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-10', 'coc-bom-1908', 'Alma', 19, 10, 'And now, my son, I would to God that ye had not been guilty of so great a crime.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-11', 'coc-bom-1908', 'Alma', 19, 11, 'I would not dwell upon your crimes, to harrow up your soul, if it were not for your good.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-14', 'coc-bom-1908', 'Alma', 19, 14, 'Oh, remember, and take it upon you, and cross yourself in these things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-21', 'coc-bom-1908', 'Alma', 19, 21, 'And now, my son, I would say somewhat unto you concerning the coming of Christ.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-23', 'coc-bom-1908', 'Alma', 19, 23, 'And now, my son, this was the ministry unto which ye were called: to declare these glad tidings unto this people, to prepare their minds, or rather that salvation might come unto them, that they may prepare the minds of their children to hear the word at the time of his coming.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-24', 'coc-bom-1908', 'Alma', 19, 24, 'And now, I will ease your mind somewhat on this subject. Behold, you marvel why these things should be known so long beforehand.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-25', 'coc-bom-1908', 'Alma', 19, 25, 'Behold, I say unto you, Is not a soul at this time as precious unto God as a soul will be at the time of his coming?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-26', 'coc-bom-1908', 'Alma', 19, 26, 'Is it not as necessary that the plan of redemption should be made known unto this people, as well as unto their children?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-27', 'coc-bom-1908', 'Alma', 19, 27, 'Is it not as easy at this time for the Lord to send his angel to declare these glad tidings unto us, as unto our children, or as after the time of his coming?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-29', 'coc-bom-1908', 'Alma', 19, 29, 'Behold, I say unto you that there is no resurrection--or I would say, in other words, that this mortal does not put on immortality, this corruption does not put on incorruption--until after the coming of Christ.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-30', 'coc-bom-1908', 'Alma', 19, 30, 'Behold, he bringeth to pass the resurrection of the dead. But behold, my son, the resurrection is not yet.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-32', 'coc-bom-1908', 'Alma', 19, 32, 'But I show unto you one thing which I have inquired diligently of God that I might know--that is, concerning the resurrection.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-33', 'coc-bom-1908', 'Alma', 19, 33, 'Behold, there is a time appointed that all shall come forth from the dead.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-36', 'coc-bom-1908', 'Alma', 19, 36, 'Now there must needs be a space betwixt the time of death and the time of the resurrection.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-37', 'coc-bom-1908', 'Alma', 19, 37, 'And now, I would inquire, What becometh of the souls of men from this time of death to the time appointed for the resurrection?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-41', 'coc-bom-1908', 'Alma', 19, 41, 'And when the time cometh when all shall rise, then shall they know that God knoweth all the times which are appointed unto man.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-42', 'coc-bom-1908', 'Alma', 19, 42, 'Now concerning the state of the soul between death and the resurrection:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-43', 'coc-bom-1908', 'Alma', 19, 43, 'Behold, it has been made known unto me by an angel that the spirits of all men, as soon as they are departed from this mortal body--yea, the spirits of all men, whether they be good or evil--are taken home to that God who gave them life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-44', 'coc-bom-1908', 'Alma', 19, 44, 'And then shall it come to pass that the spirits of those who are righteous are received into a state of happiness, which is called paradise, a state of rest, a state of peace, where they shall rest from all their troubles, and from all care, and sorrow, etc.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-48', 'coc-bom-1908', 'Alma', 19, 48, 'Now there are some that have understood that this state of happiness and this state of misery of the soul, before the resurrection, was a first resurrection.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-49', 'coc-bom-1908', 'Alma', 19, 49, 'Yea, I admit it may be termed a resurrection--the raising of the spirit or the soul and their consignation to happiness or misery according to the words which have been spoken.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-50', 'coc-bom-1908', 'Alma', 19, 50, 'And behold, again it hath been spoken that there is a first resurrection, a resurrection of all those who have been, or who are, or who shall be, down to the resurrection of Christ from the dead.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-51', 'coc-bom-1908', 'Alma', 19, 51, 'Now we do not suppose that this first resurrection, which is spoken of in this manner, can be the resurrection of the souls and their consignation to happiness or misery. Ye cannot suppose that this is what it meaneth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-57', 'coc-bom-1908', 'Alma', 19, 57, 'Yea, this bringeth about the restoration of those things of which have been spoken by the mouths of the prophets.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-59', 'coc-bom-1908', 'Alma', 19, 59, 'And now, my son, this is the restoration of which has been spoken by the mouths of the prophets. And then shall the righteous shine forth in the kingdom of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-63', 'coc-bom-1908', 'Alma', 19, 63, 'And I perceive that thy mind has been worried also concerning this thing. But behold, I will explain it unto thee.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-65', 'coc-bom-1908', 'Alma', 19, 65, 'Behold, it is requisite and just, according to the power and resurrection of Christ, that the soul of man should be restored to its body and that every part of the body should be restored to itself.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-68', 'coc-bom-1908', 'Alma', 19, 68, 'The one on the one hand, the other on the other--the one raised to happiness according to his desires of happiness, or good according to his desires of good, and the other to evil according to his desires of evil. For as he has desired to do evil all the day long, even so shall he have his reward of evil when the night cometh.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-69', 'coc-bom-1908', 'Alma', 19, 69, 'And so it is on the other hand. If he hath repented of his sins and desired righteousness until the end of his days, even so shall he be rewarded unto righteousness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-72', 'coc-bom-1908', 'Alma', 19, 72, 'And now, behold, my son, do not risk one more offense against your God upon those points of doctrine which ye have hitherto risked to commit sin.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-73', 'coc-bom-1908', 'Alma', 19, 73, 'Do not suppose, because it has been spoken concerning restoration, that ye shall be restored from sin to happiness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-74', 'coc-bom-1908', 'Alma', 19, 74, 'Behold, I say unto you, Wickedness never was happiness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-76', 'coc-bom-1908', 'Alma', 19, 76, 'And now, behold, is the meaning of the word restoration to take a thing of a natural state and place it in an unnatural state, or to place it in a state opposite to its nature?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-82', 'coc-bom-1908', 'Alma', 19, 82, 'Now behold, my son, I will explain this thing unto thee: For behold, after the Lord God sent our first parents forth from the garden of Eden to till the ground, from whence they were taken, yea, he drove out the man, and he placed at the east end of the garden of Eden, cherubim and a flaming sword, which turned every way, to keep the tree of life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-84', 'coc-bom-1908', 'Alma', 19, 84, 'And thus we see that there was a time granted unto man to repent, yea, a probationary time, a time to repent and serve God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-86', 'coc-bom-1908', 'Alma', 19, 86, 'Yea, and also the word of God would have been void, and the great plan of salvation would have been frustrated.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-92', 'coc-bom-1908', 'Alma', 19, 92, 'And now, remember, my son, if it were not for the plan of redemption (laying it aside), as soon as they were dead, their souls were miserable, being cut off from the presence of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-96', 'coc-bom-1908', 'Alma', 19, 96, 'And thus we see that all mankind were fallen, and they were in the grasp of justice, yea, the justice of God, which consigned them forever to be cut off from his presence.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-98', 'coc-bom-1908', 'Alma', 19, 98, 'Now repentance could not come unto men, except there were a punishment, which also was as eternal as the life of the soul should be, affixed opposite to the plan of happiness, which was as eternal also as the life of the soul.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-99', 'coc-bom-1908', 'Alma', 19, 99, 'Now, how could a man repent, except he should sin? How could he sin if there was no law? How could there be a law save there was a punishment?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-100', 'coc-bom-1908', 'Alma', 19, 100, 'Now there was a punishment affixed and a just law given, which brought remorse of conscience unto man.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-101', 'coc-bom-1908', 'Alma', 19, 101, 'Now if there was no law given if a man murdered he should die, would he be afraid he should die if he should murder?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-102', 'coc-bom-1908', 'Alma', 19, 102, 'And also, if there was no law given against sin, men would not be afraid to sin.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-103', 'coc-bom-1908', 'Alma', 19, 103, 'And if there was no law given if men sinned, what could justice do, or mercy either? For they would have no claim upon the creature.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-107', 'coc-bom-1908', 'Alma', 19, 107, 'What? Do ye suppose that mercy can rob justice? I say unto you, Nay, not one whit. If so, God would cease to be God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-108', 'coc-bom-1908', 'Alma', 19, 108, 'And thus God bringeth about his great and eternal purposes, which were prepared from the foundation of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-111', 'coc-bom-1908', 'Alma', 19, 111, 'If he has desired to do evil and has not repented in his days, behold, evil shall be done unto him according to the restoration of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-113', 'coc-bom-1908', 'Alma', 19, 113, 'O my son, I desire that ye should deny the justice of God no more.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-115', 'coc-bom-1908', 'Alma', 19, 115, 'And now, O my son, ye are called of God to preach the word unto this people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-19-117', 'coc-bom-1908', 'Alma', 19, 117, 'And may God grant unto you even according to my words. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-3', 'coc-bom-1908', 'Alma', 20, 3, 'And now, I return to an account of the wars between the Nephites and the Lamanites in the eighteenth year of the reign of the judges.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-6', 'coc-bom-1908', 'Alma', 20, 6, 'And now, as the Amalekites were of a more wicked and murderous disposition than the Lamanites were, in and of themselves, therefore, Zerahemnah appointed chief captains over the Lamanites, and they were all the Amalekites and the Zoramites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-9', 'coc-bom-1908', 'Alma', 20, 9, 'And now, the design of the Nephites was to support their lands, and their houses, and their wives, and their children, that they might preserve them from the hands of their enemies and also that they might preserve their rights and their privileges,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-15', 'coc-bom-1908', 'Alma', 20, 15, 'And thus the Nephites were compelled, alone, to withstand against the Lamanites, who were a compound of Laman, and Lemuel, and the sons of Ishmael, and all those who had dissented from the Nephites, who were Amalekites, and Zoramites, and the descendants of the priests of Noah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-17', 'coc-bom-1908', 'Alma', 20, 17, 'And it came to pass as the armies of the Lamanites had gathered together in the land of Antionum, behold, the armies of the Nephites were prepared to meet them in the land of Jershon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-19', 'coc-bom-1908', 'Alma', 20, 19, 'And Moroni took all the command and the governments of their wars. And he was only twenty and five years old when he was appointed chief captain over the armies of the Nephites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-21', 'coc-bom-1908', 'Alma', 20, 21, 'And when the armies of the Lamanites saw that the people of Nephi, or that Moroni had prepared his people with breastplates, and with armshields, yea, and also shields to defend their heads, and also they were dressed with thick clothing,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-22', 'coc-bom-1908', 'Alma', 20, 22, 'Now the army of Zerahemnah was not prepared with any such thing.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-28', 'coc-bom-1908', 'Alma', 20, 28, 'And those messengers went and delivered the message unto Moroni.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-29', 'coc-bom-1908', 'Alma', 20, 29, 'Now Moroni, leaving a part of his army in the land of Jershon, lest by any means a part of the Lamanites should come into that land and take possession of the city, took the remainder part of his army and marched over into the land of Manti.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-31', 'coc-bom-1908', 'Alma', 20, 31, 'And it came to pass that Moroni caused that his army should be secreted in the valley which was near the bank of the river Sidon, which was on the west of the river Sidon in the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-32', 'coc-bom-1908', 'Alma', 20, 32, 'And Moroni placed spies round about, that he might know when the camp of the Lamanites should come.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-33', 'coc-bom-1908', 'Alma', 20, 33, 'And now, as Moroni knew the intention of the Lamanites, that it was their intention to destroy their brethren, or to subject them and bring them into bondage, that they might establish a kingdom unto themselves over all the land,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-36', 'coc-bom-1908', 'Alma', 20, 36, 'And thus having placed his army according to his desire, he was prepared to meet them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-37', 'coc-bom-1908', 'Alma', 20, 37, 'And it came to pass that the Lamanites came up on the north of the hill, where a part of the army of Moroni was concealed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-42', 'coc-bom-1908', 'Alma', 20, 42, 'And it came to pass that the Lamanites became frightened because of the great destruction among them, even until they began to flee towards the river Sidon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-44', 'coc-bom-1908', 'Alma', 20, 44, 'And Lehi retained his armies upon the bank of the river Sidon, that they should not cross.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-45', 'coc-bom-1908', 'Alma', 20, 45, 'And it came to pass that Moroni and his army met the Lamanites in the valley, on the other side of the river Sidon, and began to fall upon them and to slay them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-53', 'coc-bom-1908', 'Alma', 20, 53, 'And it came to pass that when the men of Moroni saw the fierceness and the anger of the Lamanites, they were about to shrink and flee from them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-54', 'coc-bom-1908', 'Alma', 20, 54, 'And Moroni, perceiving their intent, sent forth and inspired their hearts with these thoughts: yea, the thoughts of their lands, their liberty, yea, their freedom from bondage.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-55', 'coc-bom-1908', 'Alma', 20, 55, 'And it came to pass that they turned upon the Lamanites, and they cried with one voice unto the Lord, their God, for their liberty and their freedom from bondage.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-59', 'coc-bom-1908', 'Alma', 20, 59, 'Therefore, when Zerahemnah saw the men of Lehi on the east of the river Sidon and the armies of Moroni on the west of the river Sidon, that they were encircled about by the Nephites, they were struck with terror.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-60', 'coc-bom-1908', 'Alma', 20, 60, 'Now Moroni, when he saw their terror, commanded his men that they should stop shedding their blood.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-61', 'coc-bom-1908', 'Alma', 20, 61, 'And it came to pass that they did stop and withdrew a pace from them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-62', 'coc-bom-1908', 'Alma', 20, 62, 'And Moroni said unto Zerahemnah, Behold, Zerahemnah, that we do not desire to be men of blood.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-63', 'coc-bom-1908', 'Alma', 20, 63, 'Ye know that ye are in our hands, yet we do not desire to slay you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-67', 'coc-bom-1908', 'Alma', 20, 67, 'And now, I would that ye should understand that this is done unto us because of our religion and our faith in Christ. And now, ye see that ye cannot destroy this our faith.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-69', 'coc-bom-1908', 'Alma', 20, 69, 'And never will the Lord suffer that we shall be destroyed, except we should fall into transgression and deny our faith.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-70', 'coc-bom-1908', 'Alma', 20, 70, 'And now, Zerahemnah, I command you, in the name of that all-powerful God, who has strengthened our arms, that we have gained power over you by our faith, by our religion, and by our rites of worship, and by our church, and by the sacred support which we owe to our wives and our children, by that liberty which binds us to our lands and our country, yea, and also by the maintenance of the sacred word of God, to which we owe all our happiness,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-74', 'coc-bom-1908', 'Alma', 20, 74, 'And now, it came to pass that when Zerahemnah had heard these sayings, he came forth, and delivered up his sword, and his cimeter, and his bow into the hands of Moroni, and said unto him,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-77', 'coc-bom-1908', 'Alma', 20, 77, 'Behold, it is your breastplates and your shields that have preserved you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-78', 'coc-bom-1908', 'Alma', 20, 78, 'And now, when Zerahemnah had made an end of speaking these words, Moroni returned the sword and the weapons of war which he had received unto Zerahemnah, saying, Behold, we will end the conflict.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-80', 'coc-bom-1908', 'Alma', 20, 80, 'Now as ye are in our hands, we will spill your blood upon the ground, or ye shall submit to the conditions to which I have proposed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-83', 'coc-bom-1908', 'Alma', 20, 83, 'And Zerahemnah withdrew from before them into the midst of his soldiers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-85', 'coc-bom-1908', 'Alma', 20, 85, 'Even as this scalp has fallen to the earth, which is the scalp of your chief, so shall ye fall to the earth, except ye will deliver up your weapons of war and depart with a covenant of peace.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-87', 'coc-bom-1908', 'Alma', 20, 87, 'And as many as entered into a covenant, they suffered to depart into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-93', 'coc-bom-1908', 'Alma', 20, 93, 'Now Zerahemnah, when he saw that they were all about to be destroyed, cried mightily unto Moroni, promising that he would covenant, and also his people with them, if they would spare the remainder of their lives, that they never would come to war against them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-94', 'coc-bom-1908', 'Alma', 20, 94, 'And it came to pass that Moroni caused that the work of death should cease again among the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-98', 'coc-bom-1908', 'Alma', 20, 98, 'And the armies of the Nephites, or of Moroni, returned and came to their houses and their lands.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-99', 'coc-bom-1908', 'Alma', 20, 99, 'And thus ended the eighteenth year of the reign of the judges over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-20-100', 'coc-bom-1908', 'Alma', 20, 100, 'And thus ended the record of Alma, which was written upon the plates of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-3', 'coc-bom-1908', 'Alma', 21, 3, 'And it came to pass in the nineteenth year of the reign of the judges over the people of Nephi, that Alma came unto his son Helaman and said unto him, Believest thou the words which I spake unto thee concerning those records which have been kept?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-4', 'coc-bom-1908', 'Alma', 21, 4, 'And Helaman said unto him, Yea, I believe.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-5', 'coc-bom-1908', 'Alma', 21, 5, 'And Alma said again, Believest thou in Jesus Christ, who shall come? And he said, Yea, I believe all the words which thou hast spoken.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-6', 'coc-bom-1908', 'Alma', 21, 6, 'And Alma said unto him again, Will ye keep my commandments? And he said, Yea, I will keep thy commandments with all my heart.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-15', 'coc-bom-1908', 'Alma', 21, 15, 'And them shall the Lamanites pursue, even until they shall become extinct. And now, because of iniquity, this prophecy shall be fulfilled.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-25', 'coc-bom-1908', 'Alma', 21, 25, 'Therefore, Helaman and his brethren went forth to establish the church again in all the land, yea, in every city throughout all the land which was possessed by the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-26', 'coc-bom-1908', 'Alma', 21, 26, 'And it came to pass that they did appoint priests and teachers throughout all the land, over all the churches.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-29', 'coc-bom-1908', 'Alma', 21, 29, 'And it came to pass that as many as would not hearken to the words of Helaman and his brethren were gathered together against their brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-30', 'coc-bom-1908', 'Alma', 21, 30, 'And now, behold, they were exceeding wroth, insomuch that they were determined to slay them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-33', 'coc-bom-1908', 'Alma', 21, 33, 'And they had been led by the flatteries of Amalickiah, that if they would support him and establish him to be their king, that he would make them rulers over the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-34', 'coc-bom-1908', 'Alma', 21, 34, 'Thus they were led away by Amalickiah to dissensions, notwithstanding the preaching of Helaman and his brethren, yea, notwithstanding their exceeding great care over the church, for they were high priests over the church.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-36', 'coc-bom-1908', 'Alma', 21, 36, 'And thus were the affairs of the people of Nephi exceeding precarious and dangerous, notwithstanding their great victory which they had had over the Lamanites and their great rejoicings which they had had because of their deliverance by the hands of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-38', 'coc-bom-1908', 'Alma', 21, 38, 'Yea, we see that Amalickiah, because he was a man of cunning devices and a man of many flattering words, that he led away the hearts of many people to do wickedly,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-39', 'coc-bom-1908', 'Alma', 21, 39, 'Yea, and to seek to destroy the church of God and to destroy the foundation of liberty which God had granted unto them, or which blessing God had sent upon the face of the land for the righteous'' sake.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-40', 'coc-bom-1908', 'Alma', 21, 40, 'And now, it came to pass that when Moroni, who was the chief commander of the armies of the Nephites, had heard of these dissensions, he was angry with Amalickiah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-45', 'coc-bom-1908', 'Alma', 21, 45, 'Yea, all those who were true believers in Christ took upon them gladly the name of Christ, or Christians as they were called, because of their belief in Christ who should come. And therefore, at this time, Moroni prayed that the cause of the Christians and the freedom of the land might be favored.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-46', 'coc-bom-1908', 'Alma', 21, 46, 'And it came to pass that when he had poured out his soul to God, he gave all the land which was south of the land Desolation, yea, and, in fine, all the land, both on the north and south, a chosen land, and the land of liberty.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-47', 'coc-bom-1908', 'Alma', 21, 47, 'And he said, Surely God shall not suffer that we, who are despised because we take upon us the name of Christ, shall be trodden down and destroyed--until we bring it upon us by our own transgressions.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-48', 'coc-bom-1908', 'Alma', 21, 48, 'And when Moroni had said these words, he went forth among the people, waving the rent of his garment in the air, that all might see the writing which he had written upon the rent, and crying with a loud voice, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-49', 'coc-bom-1908', 'Alma', 21, 49, 'Behold, whosoever will maintain this title upon the land, let them come forth in the strength of the Lord and enter into a covenant that they will maintain their rights and their religion, that the Lord God may bless them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-51', 'coc-bom-1908', 'Alma', 21, 51, 'Or, in other words, if they should transgress the commandments of God, or fall into transgression and be ashamed to take upon them the name of Christ, the Lord should rend them even as they had rent their garments.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-53', 'coc-bom-1908', 'Alma', 21, 53, 'Yea, he may cast us at the feet of our enemies, even as we have cast our garments at thy feet, to be trodden underfoot if we shall fall into transgression.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-57', 'coc-bom-1908', 'Alma', 21, 57, 'And he said, Even as this remnant of the garment of my son hath been preserved, so shall a remnant of the seed of my sons be preserved by the hand of God and be taken unto himself, while the remainder of the seed of Joseph shall perish, even as the remnant of his garment.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-59', 'coc-bom-1908', 'Alma', 21, 59, 'Now behold, this was the language of Jacob.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-61', 'coc-bom-1908', 'Alma', 21, 61, 'And now, it came to pass that when Moroni had said these words, he went forth, and also sent forth, in all the parts of the land where there were dissensions, and gathered together all the people who were desirous to maintain their liberty--to stand against Amalickiah and those who had dissented, who were called Amalickiahites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-62', 'coc-bom-1908', 'Alma', 21, 62, 'And it came to pass that when Amalickiah saw that the people of Moroni were more numerous than the Amalickiahites, and he also saw that his people were doubtful concerning the justice of the cause in which they had undertaken, therefore, fearing that he should not gain the point, he took those of his people who would and departed into the land of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-64', 'coc-bom-1908', 'Alma', 21, 64, 'Yea, for he knew that they would stir up the Lamanites to anger against them and cause them to come to battle against them. And this he knew that Amalickiah would do, that he might obtain his purposes.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-65', 'coc-bom-1908', 'Alma', 21, 65, 'Therefore, Moroni thought it was expedient that he should take his armies, who had gathered themselves together, and armed themselves, and entered into a covenant to keep the peace.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-66', 'coc-bom-1908', 'Alma', 21, 66, 'And it came to pass that he took his army and marched out into the wilderness to cut off the course of Amalickiah in the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-67', 'coc-bom-1908', 'Alma', 21, 67, 'And it came to pass that he did according to his desires, and marched forth into the wilderness, and headed the armies of Amalickiah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-69', 'coc-bom-1908', 'Alma', 21, 69, 'Now Moroni, being a man who was appointed by the chief judges and the voice of the people, therefore, he had power according to his will, with the armies of the Nephites, to establish and to exercise authority over them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-75', 'coc-bom-1908', 'Alma', 21, 75, 'And there were some who died with fevers, which at some seasons of the year were very frequent in the land--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-76', 'coc-bom-1908', 'Alma', 21, 76, 'But not so much so with fevers because of the excellent qualities of the many plants and roots, which God had prepared to remove the cause of diseases to which man was subject by the nature of the climate.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-80', 'coc-bom-1908', 'Alma', 21, 80, 'And it came to pass that they would not, or the more part of them would not, obey the commandments of the king.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-85', 'coc-bom-1908', 'Alma', 21, 85, 'And they had appointed a man to be a king and a leader over them, being fixed in their minds with a determined resolution that they would not be subjected to go against the Nephites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-86', 'coc-bom-1908', 'Alma', 21, 86, 'And it came to pass that they had gathered themselves together upon the top of the mount which was called Antipas, in preparation to battle.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-88', 'coc-bom-1908', 'Alma', 21, 88, 'And behold, it came to pass that he caused his army to pitch their tents in the valley which was near the Mount Antipas.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-90', 'coc-bom-1908', 'Alma', 21, 90, 'And it came to pass that when Lehonti received the message, he durst not go down to the foot of the mount.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-93', 'coc-bom-1908', 'Alma', 21, 93, 'And it came to pass that when Lehonti had come down with his guards to Amalickiah, that Amalickiah desired him to come down with his army in the nighttime and surround those men in their camp over whom the king had given him command, and that he would deliver them up into Lehonti''s hands, if he would make him (Amalickiah) a second leader over the whole army.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-94', 'coc-bom-1908', 'Alma', 21, 94, 'And it came to pass that Lehonti came down with his men and surrounded the men of Amalickiah, so that before they awoke at the dawn of the day, they were surrounded by the armies of Lehonti.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-95', 'coc-bom-1908', 'Alma', 21, 95, 'And it came to pass that when they saw they were surrounded, they pled with Amalickiah that he would suffer them to fall in with their brethren, that they might not be destroyed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-96', 'coc-bom-1908', 'Alma', 21, 96, 'Now this was the very thing which Amalickiah desired. And it came to pass that he delivered his men, contrary to the commands of the king.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-97', 'coc-bom-1908', 'Alma', 21, 97, 'Now this was the thing that Amalickiah desired, that he might accomplish his designs in dethroning the king.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-98', 'coc-bom-1908', 'Alma', 21, 98, 'Now it was the custom among the Lamanites, if their chief leader was killed, to appoint the second leader to be their chief leader.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-99', 'coc-bom-1908', 'Alma', 21, 99, 'Now it came to pass that Amalickiah caused that one of his servants should administer poison by degrees to Lehonti, that he died.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-100', 'coc-bom-1908', 'Alma', 21, 100, 'Now when Lehonti was dead, the Lamanites appointed Amalickiah to be their leader and chief commander.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-101', 'coc-bom-1908', 'Alma', 21, 101, 'And it came to pass that Amalickiah marched with his armies (for he had gained his desires) to the land of Nephi, to the city of Nephi, which was the chief city.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-103', 'coc-bom-1908', 'Alma', 21, 103, 'But behold, as the king came out to meet him, Amalickiah caused that his servants should go forth to meet the king.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-104', 'coc-bom-1908', 'Alma', 21, 104, 'And they went and bowed themselves before the king, as if to reverence him because of his greatness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-105', 'coc-bom-1908', 'Alma', 21, 105, 'And it came to pass that the king put forth his hand to raise them, as was the custom with the Lamanites as a token of peace, which custom they had taken from the Nephites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-108', 'coc-bom-1908', 'Alma', 21, 108, 'And it came to pass that Amalickiah commanded that his armies should march forth and see what had happened to the king.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-109', 'coc-bom-1908', 'Alma', 21, 109, 'And when they had come to the spot and found the king lying in his gore, Amalickiah pretended to be wroth and said, Whosoever loved the king, let him go forth and pursue his servants, that they may be slain.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-110', 'coc-bom-1908', 'Alma', 21, 110, 'And it came to pass that all they who loved the king, when they heard these words, came forth and pursued after the servants of the king.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-111', 'coc-bom-1908', 'Alma', 21, 111, 'Now when the servants of the king saw an army pursuing after them, they were frightened again, and fled into the wilderness, and came over in the land of Zarahemla, and joined the people of Ammon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-113', 'coc-bom-1908', 'Alma', 21, 113, 'And it came to pass on the morrow, he entered the city Nephi with his armies and took possession of the city.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-114', 'coc-bom-1908', 'Alma', 21, 114, 'And now, it came to pass that the queen, when she had heard that the king was slain (for Amalickiah had sent an embassy to the queen, informing her that the king had been slain by his servants, that he had pursued them with his army, but it was in vain, and they had made their escape),', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-118', 'coc-bom-1908', 'Alma', 21, 118, 'And thus they satisfied the queen concerning the death of the king.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-120', 'coc-bom-1908', 'Alma', 21, 120, 'Yea, he was acknowledged king throughout all the land, among all the people of the Lamanites, who were composed of the Lamanites, and the Lemuelites, and the Ishmaelites, and all the dissenters of the Nephites from the reign of Nephi down to the present time.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-121', 'coc-bom-1908', 'Alma', 21, 121, 'Now these dissenters, having the same instruction and the same information as the Nephites, yea, having been instructed in the same knowledge of the Lord--nevertheless, it is strange to relate, not long after their dissensions they became more hardened, and impenitent, and more wild, wicked, and ferocious than the Lamanites,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-122', 'coc-bom-1908', 'Alma', 21, 122, 'Drinking in with the traditions of the Lamanites, giving way to indolence and all manner of lasciviousness, yea, entirely forgetting the Lord, their God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-124', 'coc-bom-1908', 'Alma', 21, 124, 'And thus he did inspire their hearts against the Nephites, insomuch that in the latter end of the nineteenth year of the reign of the judges, he, having accomplished his designs thus far, yea, having been made king over the Lamanites, he sought also to reign over all the land,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-127', 'coc-bom-1908', 'Alma', 21, 127, 'And it came to pass that they took their camp and moved forth towards the land of Zarahemla in the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-128', 'coc-bom-1908', 'Alma', 21, 128, 'Now it came to pass that while Amalickiah had thus been obtaining power by fraud and deceit, Moroni, on the other hand, had been preparing the minds of the people to be faithful unto the Lord, their God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-131', 'coc-bom-1908', 'Alma', 21, 131, 'And thus he was preparing to support their liberty, their lands, their wives, and their children, and their peace, and that they might live unto the Lord, their God, and that they might maintain that which was called by their enemies the cause of Christians.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-133', 'coc-bom-1908', 'Alma', 21, 133, 'Yea, a man whose heart did swell with thanksgiving to his God for the many privileges and blessings which he bestowed upon his people, a man who did labor exceedingly for the welfare and safety of his people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-136', 'coc-bom-1908', 'Alma', 21, 136, 'Yea, and they were also taught never to give an offense, yea, and never to raise the sword, except it were against an enemy, except it were to preserve their lives.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-139', 'coc-bom-1908', 'Alma', 21, 139, 'And his heart did glory in it--not in the shedding of blood but in doing good, in preserving his people, yea, in keeping the commandments of God, yea, and resisting iniquity.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-141', 'coc-bom-1908', 'Alma', 21, 141, 'Behold, he was a man like unto Ammon, the son of Mosiah, yea, and even the other sons of Mosiah, yea, and also Alma and his sons, for they were all men of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-145', 'coc-bom-1908', 'Alma', 21, 145, 'Yea, and, in fine, their wars never did cease for the space of many years with the Lamanites, notwithstanding their much reluctance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-147', 'coc-bom-1908', 'Alma', 21, 147, 'Nevertheless, they could not suffer to lay down their lives, that their wives and their children should be massacred by the barbarous cruelty of those who were once their brethren, yea, and had dissented from their church, and had left them, and had gone to destroy them by joining the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-149', 'coc-bom-1908', 'Alma', 21, 149, 'And now, it came to pass in the eleventh month of the nineteenth year, on the tenth day of the month, the armies of the Lamanites were seen approaching towards the land of Ammonihah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-153', 'coc-bom-1908', 'Alma', 21, 153, 'Now at this time, the chief captains of the Lamanites were astonished exceedingly because of the wisdom of the Nephites in preparing their places of security.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-156', 'coc-bom-1908', 'Alma', 21, 156, 'And being thus prepared, they supposed that they should easily overpower and subject their brethren to the yoke of bondage or slay and massacre them according to their pleasure.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-157', 'coc-bom-1908', 'Alma', 21, 157, 'But behold, to their uttermost astonishment, they were prepared for them in a manner which never had been known among all the children of Lehi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-158', 'coc-bom-1908', 'Alma', 21, 158, 'Now they were prepared for the Lamanites, to battle after the manner of the instructions of Moroni.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-159', 'coc-bom-1908', 'Alma', 21, 159, 'And it came to pass that the Lamanites, or the Amalickiahites, were exceedingly astonished at their manner of preparation for war.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-161', 'coc-bom-1908', 'Alma', 21, 161, 'But behold, Amalickiah did not come down himself to battle.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-162', 'coc-bom-1908', 'Alma', 21, 162, 'And behold, his chief captains durst not attack the Nephites at the city of Ammonihah, for Moroni had altered the management of affairs among the Nephites, insomuch that the Lamanites were disappointed in their places of retreat, and they could not come upon them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-166', 'coc-bom-1908', 'Alma', 21, 166, 'But behold, to their astonishment, the city of Noah, which had hitherto been a weak place, had now, by the means of Moroni, become strong, yea, even to exceed the strength of the city Ammonihah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-170', 'coc-bom-1908', 'Alma', 21, 170, 'Now behold, the Lamanites could not get into their forts of security by any other way save by the entrance, because of the highness of the bank which had been thrown up and the depth of the ditch which had been dug round about, save it were by the entrance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-171', 'coc-bom-1908', 'Alma', 21, 171, 'And thus were the Nephites prepared to destroy all such as should attempt to climb up to enter the fort by any other way, by casting over stones and arrows at them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-174', 'coc-bom-1908', 'Alma', 21, 174, 'But behold, they were driven back from time to time, insomuch that they were slain with an immense slaughter.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-180', 'coc-bom-1908', 'Alma', 21, 180, 'And it came to pass that when the Lamanites saw that their chief captains were all slain, they fled into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-181', 'coc-bom-1908', 'Alma', 21, 181, 'And it came to pass that they returned to the land of Nephi to inform their king, Amalickiah, who was a Nephite by birth, concerning their great loss.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-184', 'coc-bom-1908', 'Alma', 21, 184, 'And it came to pass that, on the other hand, the people of Nephi did thank the Lord, their God, because of his matchless power in delivering them from the hands of their enemies.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-21-186', 'coc-bom-1908', 'Alma', 21, 186, 'Yea, and by all those who had been ordained by the holy order of God, being baptized unto repentance and sent forth to preach among the people, etc.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-2', 'coc-bom-1908', 'Alma', 22, 2, 'And upon the top of these ridges of earth he caused that there should be timbers, yea, works of timbers built up to the height of a man, round about the cities.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-4', 'coc-bom-1908', 'Alma', 22, 4, 'And he caused places of security to be built upon those towers, that the stones and the arrows of the Lamanites could not hurt them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-5', 'coc-bom-1908', 'Alma', 22, 5, 'And they were prepared, that they could cast stones from the top thereof, according to their pleasure and their strength, and slay him who should attempt to approach near the walls of the city.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-6', 'coc-bom-1908', 'Alma', 22, 6, 'Thus Moroni did prepare strongholds against the coming of their enemies round about every city in all the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-8', 'coc-bom-1908', 'Alma', 22, 8, 'And the land of Nephi did run in a straight course from the east sea to the west.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-9', 'coc-bom-1908', 'Alma', 22, 9, 'And it came to pass that when Moroni had driven all the Lamanites out of the east wilderness, which was north of the lands of their own possessions, he caused that the inhabitants who were in the land of Zarahemla and in the land round about should go forth into the east wilderness, even to the borders by the seashore, and possess the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-10', 'coc-bom-1908', 'Alma', 22, 10, 'And he also placed armies on the south, in the borders of their possessions, and caused them to erect fortifications, that they might secure their armies and their people from the hands of their enemies.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-11', 'coc-bom-1908', 'Alma', 22, 11, 'And thus he cut off all the strongholds of the Lamanites in the east wilderness, yea, and also on the west, fortifying the line between the Nephites and the Lamanites between the land of Zarahemla and the land of Nephi, from the west sea, running by the head of the river Sidon--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-12', 'coc-bom-1908', 'Alma', 22, 12, 'The Nephites possessing all the land northward, yea, even all the land which was northward of the land Bountiful, according to their pleasure.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-13', 'coc-bom-1908', 'Alma', 22, 13, 'Thus Moroni with his armies--which did increase daily because of the assurance of protection which his works did bring forth unto them--therefore, they did seek to cut off the strength and the power of the Lamanites from off the lands of their possessions, that they should have no power upon the lands of their possessions.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-16', 'coc-bom-1908', 'Alma', 22, 16, 'And they also began in that same year to build many cities on the north--one in a particular manner, which they called Lehi, which was in the north by the borders of the seashore. And thus ended the twentieth year.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-17', 'coc-bom-1908', 'Alma', 22, 17, 'And in these prosperous circumstances were the people of Nephi in the commencement of the twenty and first year of the reign of the judges over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-19', 'coc-bom-1908', 'Alma', 22, 19, 'And thus we see how merciful and just are all the dealings of the Lord, to the fulfilling of all his words unto the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-21', 'coc-bom-1908', 'Alma', 22, 21, 'But remember, inasmuch as they will not keep my commandments, they shall be cut off from the presence of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-23', 'coc-bom-1908', 'Alma', 22, 23, 'And those who were faithful in keeping the commandments of the Lord were delivered at all times, whilst thousands of their wicked brethren have been consigned to bondage, or to perish by the sword, or to dwindle in unbelief and mingle with the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-24', 'coc-bom-1908', 'Alma', 22, 24, 'But behold, there never was a happier time among the people of Nephi, since the days of Nephi, than in the days of Moroni, yea, even at this time, in the twenty and first year of the reign of the judges.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-25', 'coc-bom-1908', 'Alma', 22, 25, 'And it came to pass that the twenty and second year of the reign of the judges also ended in peace, yea, and also the twenty and third year.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-26', 'coc-bom-1908', 'Alma', 22, 26, 'And it came to pass that in the commencement of the twenty and fourth year of the reign of the judges, there would also have been peace among the people of Nephi had it not been for a contention which took place among them concerning the land of Lehi and the land of Morianton, which joined upon the borders of Lehi, both of which were on the borders by the seashore.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-30', 'coc-bom-1908', 'Alma', 22, 30, 'Therefore, Morianton put it into their hearts that they should flee to the land which was northward, which was covered with large bodies of water, and take possession of the land which was northward.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-32', 'coc-bom-1908', 'Alma', 22, 32, 'And it came to pass that she fled, and came over to the camp of Moroni, and told Moroni all things concerning the matter and also concerning their intentions to flee into the land northward.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-34', 'coc-bom-1908', 'Alma', 22, 34, 'Therefore, Moroni sent an army with their camp to head the people of Morianton, to stop their flight into the land northward.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-37', 'coc-bom-1908', 'Alma', 22, 37, 'And so stubborn were the people of Morianton (being inspired by his wickedness and his flattering words) that a battle commenced between them, in the which Teancum did slay Morianton, and defeat his army, and took them prisoners, and returned to the camp of Moroni.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-38', 'coc-bom-1908', 'Alma', 22, 38, 'And thus ended the twenty and fourth year of the reign of the judges over the people of Nephi. And thus were the people of Morianton brought back.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-40', 'coc-bom-1908', 'Alma', 22, 40, 'And it came to pass that in the same year that the people of Nephi had peace restored unto them, that Nephihah, the second chief judge, died, having filled the judgment seat with perfect uprightness before God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-43', 'coc-bom-1908', 'Alma', 22, 43, 'Yea, to support and maintain the cause of God all his days, and to bring the wicked to justice according to their crime. Now behold, his name was Pahoran.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-22-44', 'coc-bom-1908', 'Alma', 22, 44, 'And Pahoran did fill the seat of his father and did commence his reign in the end of the twenty and fourth year over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-23-1', 'coc-bom-1908', 'Alma', 23, 1, 'And now, it came to pass in the commencement of the twenty and fifth year of the reign of the judges over the people of Nephi, they, having established peace between the people of Lehi and the people of Morianton concerning their lands and having commenced the twenty and fifth year in peace,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-23-5', 'coc-bom-1908', 'Alma', 23, 5, 'And it came to pass that those who were desirous that Pahoran should be dethroned from the judgment seat were called kingmen, for they were desirous that the law should be altered in a manner to overthrow the free government and to establish a king over the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-23-7', 'coc-bom-1908', 'Alma', 23, 7, 'And it came to pass that this matter of their contention was settled by the voice of the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-23-8', 'coc-bom-1908', 'Alma', 23, 8, 'And it came to pass that the voice of the people came in favor of the freemen, and Pahoran retained the judgment seat, which caused much rejoicing among the brethren of Pahoran and also many of the people of liberty, who also put the kingmen to silence, that they durst not oppose but were obliged to maintain the cause of freedom.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-23-13', 'coc-bom-1908', 'Alma', 23, 13, 'But notwithstanding their great loss, Amalickiah had gathered together a wonderful great army, insomuch that he feared not to come down to the land of Zarahemla.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-23-14', 'coc-bom-1908', 'Alma', 23, 14, 'Yea, even Amalickiah did himself come down at the head of the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-23-20', 'coc-bom-1908', 'Alma', 23, 20, 'And it came to pass that it was granted according to the voice of the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-23-21', 'coc-bom-1908', 'Alma', 23, 21, 'And it came to pass that Moroni commanded that his army should go against those kingmen, to pull down their pride and their nobility and level them with the earth, or they should take up arms and support the cause of liberty.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-23-24', 'coc-bom-1908', 'Alma', 23, 24, 'And the remainder of those dissenters, rather than to be smitten down to the earth by the sword, yielded to the standard of liberty, and were compelled to hoist the title of liberty upon their towers and in their cities and to take up arms in defense of their country.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-23-26', 'coc-bom-1908', 'Alma', 23, 26, 'But they were brought down to humble themselves like unto their brethren and to fight valiantly for their freedom from bondage.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-23-27', 'coc-bom-1908', 'Alma', 23, 27, 'Behold, it came to pass that while Moroni was thus breaking down the wars and contentions among his own people, and subjecting them to peace and civilization, and making regulations to prepare for war against the Lamanites, behold, the Lamanites had come into the land of Moroni, which was in the borders by the seashore.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-23-29', 'coc-bom-1908', 'Alma', 23, 29, 'And it came to pass that Amalickiah took possession of the city, yea, possession of all their fortifications.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-23-32', 'coc-bom-1908', 'Alma', 23, 32, 'And thus he went on, taking possession of many cities--the city of Nephihah, and the city of Lehi, and the city of Morianton, and the city of Omner, and the city of Gid, and the city of Mulek, all of which were on the east borders by the seashore.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-23-33', 'coc-bom-1908', 'Alma', 23, 33, 'And thus had the Lamanites obtained, by the cunning of Amalickiah, so many cities by their numberless hosts, all of which were strongly fortified after the manner of the fortifications of Moroni--all of which afforded strongholds for the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-23-34', 'coc-bom-1908', 'Alma', 23, 34, 'And it came to pass that they marched to the borders of the land Bountiful, driving the Nephites before them and slaying many.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-23-35', 'coc-bom-1908', 'Alma', 23, 35, 'But it came to pass that they were met by Teancum, who had slain Morianton and had headed his people in his flight.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-23-36', 'coc-bom-1908', 'Alma', 23, 36, 'And it came to pass that he headed Amalickiah also, as he was marching forth with his numerous army, that he might take possession of the land Bountiful and also the land northward.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-23-38', 'coc-bom-1908', 'Alma', 23, 38, 'And it came to pass that they did harass them, insomuch that they did slay them even until it was dark.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-23-43', 'coc-bom-1908', 'Alma', 23, 43, 'And he caused that his armies should stand in readiness, lest the Lamanites had awakened and should come upon them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-7', 'coc-bom-1908', 'Alma', 24, 7, 'Yea, and truly he was preparing to defend himself against them by casting up walls round about and preparing places of resort.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-10', 'coc-bom-1908', 'Alma', 24, 10, 'And he also sent orders unto him, that he should fortify the land Bountiful and secure the narrow pass which led into the land northward, lest the Lamanites should obtain that point and should have power to harass them on every side.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-11', 'coc-bom-1908', 'Alma', 24, 11, 'And Moroni also sent unto him, desiring him that he would be faithful in maintaining that quarter of the land and that he would seek every opportunity to scourge the Lamanites in that quarter, as much as was in his power,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-12', 'coc-bom-1908', 'Alma', 24, 12, 'That perhaps he might take again, by stratagem or some other way, those cities which had been taken out of their hands, and that he also would fortify and strengthen the cities round about, which had not fallen into the hands of the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-15', 'coc-bom-1908', 'Alma', 24, 15, 'And thus he was endeavoring to harass the Nephites and to draw away a part of their forces to that part of the land, while he had commanded those whom he had left to possess the cities which he had taken, that they should also harass the Nephites on the borders by the east sea, and should take possession of their lands as much as it was in their power, according to the power of their armies.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-16', 'coc-bom-1908', 'Alma', 24, 16, 'And thus were the Nephites in those dangerous circumstances in the ending of the twenty and sixth year of the reign of the judges over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-18', 'coc-bom-1908', 'Alma', 24, 18, 'And it came to pass that Teancum had received orders to make an attack upon the city of Mulek and retake it, if it were possible.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-20', 'coc-bom-1908', 'Alma', 24, 20, 'Therefore, he abandoned his designs and returned again to the city Bountiful to wait for the coming of Moroni, that he might receive strength to his army.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-21', 'coc-bom-1908', 'Alma', 24, 21, 'And it came to pass that Moroni did arrive with his army to the land of Bountiful in the latter end of the twenty and seventh year of the reign of the judges over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-22', 'coc-bom-1908', 'Alma', 24, 22, 'And in the commencement of the twenty and eighth year, Moroni, and Teancum, and many of the chief captains held a council of war, what they should do to cause the Lamanites to come out against them to battle,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-23', 'coc-bom-1908', 'Alma', 24, 23, 'Or that they might by some means flatter them out of their strongholds, that they might gain advantage over them and take again the city of Mulek.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-24', 'coc-bom-1908', 'Alma', 24, 24, 'And it came to pass that they sent embassies to the army of the Lamanites, which protected the city of Mulek, to their leader, whose name was Jacob, desiring him that he would come out with his armies to meet them upon the plains between the two cities.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-25', 'coc-bom-1908', 'Alma', 24, 25, 'But behold, Jacob, who was a Zoramite, would not come out with his army to meet them upon the plains.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-26', 'coc-bom-1908', 'Alma', 24, 26, 'And it came to pass that Moroni, having no hopes of meeting them upon fair grounds, therefore, he resolved upon a plan that he might decoy the Lamanites out of their strongholds.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-28', 'coc-bom-1908', 'Alma', 24, 28, 'And thus, on the morrow when the guards of the Lamanites had discovered Teancum, they ran and told it unto Jacob, their leader.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-29', 'coc-bom-1908', 'Alma', 24, 29, 'And it came to pass that the armies of the Lamanites did march forth against Teancum, supposing by their numbers to overpower Teancum because of the smallness of his numbers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-30', 'coc-bom-1908', 'Alma', 24, 30, 'And as Teancum saw the armies of the Lamanites coming out against him, he began to retreat down by the seashore northward.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-31', 'coc-bom-1908', 'Alma', 24, 31, 'And it came to pass that when the Lamanites saw that he began to flee, they took courage and pursued them with vigor.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-32', 'coc-bom-1908', 'Alma', 24, 32, 'And while Teancum was thus leading away the Lamanites who were pursuing them in vain, behold, Moroni commanded that a part of his army who were with him should march forth into the city and take possession of it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-33', 'coc-bom-1908', 'Alma', 24, 33, 'And thus they did and slew all those who had been left to protect the city, yea, all those who would not yield up their weapons of war.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-34', 'coc-bom-1908', 'Alma', 24, 34, 'And thus Moroni had obtained possession of the city Mulek with a part of his army, while he marched with the remainder to meet the Lamanites when they should return from the pursuit of Teancum.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-38', 'coc-bom-1908', 'Alma', 24, 38, 'Now Lehi was not desirous to overtake them till they should meet Moroni and his army.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-40', 'coc-bom-1908', 'Alma', 24, 40, 'And Moroni commanded his men that they should fall upon them until they had given up their weapons of war.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-41', 'coc-bom-1908', 'Alma', 24, 41, 'And it came to pass that Jacob, being their leader, being also a Zoramite and having an unconquerable spirit, he led the Lamanites forth to battle with exceeding fury against Moroni--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-46', 'coc-bom-1908', 'Alma', 24, 46, 'Now Moroni, seeing their confusion, he said unto them, If ye will bring forth your weapons of war and deliver them up, behold, we will forbear shedding your blood.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-49', 'coc-bom-1908', 'Alma', 24, 49, 'And now, the number of prisoners who were taken exceeded more than the number of those who had been slain, yea, more than those who had been slain on both sides.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-51', 'coc-bom-1908', 'Alma', 24, 51, 'And Moroni went to the city of Mulek with Lehi, and took command of the city, and gave it unto Lehi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-54', 'coc-bom-1908', 'Alma', 24, 54, 'And Teancum, by the orders of Moroni, caused that they should commence laboring in digging a ditch round about the land, or the city Bountiful.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-56', 'coc-bom-1908', 'Alma', 24, 56, 'And thus they did cause the Lamanites to labor until they had encircled the city of Bountiful round about with a strong wall of timbers and earth to an exceeding height.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-62', 'coc-bom-1908', 'Alma', 24, 62, 'And thus, because of iniquity amongst themselves, yea, because of dissension and intrigue among themselves, they were placed in the most dangerous circumstances.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-67', 'coc-bom-1908', 'Alma', 24, 67, 'But it came to pass that when they saw the danger and the many afflictions and tribulations which the Nephites bore for them, they were moved with compassion and were desirous to take up arms in defense of their country.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-73', 'coc-bom-1908', 'Alma', 24, 73, 'Yea, even they covenanted that they never would give up their liberty, but they would fight in all cases to protect the Nephites and themselves from bondage.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-74', 'coc-bom-1908', 'Alma', 24, 74, 'Now behold, there were two thousand of those young men who entered into this covenant and took their weapons of war to defend their country.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-77', 'coc-bom-1908', 'Alma', 24, 77, 'Yea, they were men of truth and soberness, for they had been taught to keep the commandments of God and to walk uprightly before him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-78', 'coc-bom-1908', 'Alma', 24, 78, 'And now, it came to pass that Helaman did march at the head of his two thousand stripling soldiers, to the support of the people in the borders of the land on the south by the west sea.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-24-79', 'coc-bom-1908', 'Alma', 24, 79, 'And thus ended the twenty and eighth year of the reign of the judges over the people of Nephi, etc.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-1', 'coc-bom-1908', 'Alma', 25, 1, 'And now, it came to pass in the twenty and ninth year of the judges, that Ammoron sent unto Moroni, desiring that he would exchange prisoners.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-5', 'coc-bom-1908', 'Alma', 25, 5, 'Now these are the words which he wrote unto Ammoron, saying, Behold, Ammoron, I have written unto you somewhat concerning this war which ye have waged against my people, or rather which thy brother hath waged against them, and which ye are still determined to carry on after his death.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-8', 'coc-bom-1908', 'Alma', 25, 8, 'But as ye have once rejected these things and have fought against the people of the Lord, even so I may expect you will do it again.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-18', 'coc-bom-1908', 'Alma', 25, 18, 'For behold, your fathers did wrong their brethren, insomuch that they did rob them of their right to the government when it rightly belonged to them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-19', 'coc-bom-1908', 'Alma', 25, 19, 'And now, behold, if ye will lay down your arms and subject yourselves to be governed by those to whom the government doth rightly belong, then will I cause that my people shall lay down their weapons and shall be at war no more.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-22', 'coc-bom-1908', 'Alma', 25, 22, 'And we will wage a war which shall be eternal, either to the subjecting the Nephites to our authority or to their eternal extinction.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-24', 'coc-bom-1908', 'Alma', 25, 24, 'And if it so be that there is a devil and a hell, behold, will he not send you there to dwell with my brother, whom ye have murdered, whom ye have hinted that he hath gone to such a place? But behold, these things mattereth not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-25', 'coc-bom-1908', 'Alma', 25, 25, 'I am Ammoron and a descendant of Zoram, whom your fathers pressed and brought out of Jerusalem. And behold, now, I am a bold Lamanite.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-30', 'coc-bom-1908', 'Alma', 25, 30, 'And now, it came to pass that when Moroni had said these words, he caused that a search should be made among his men, that perhaps he might find a man who was a descendant of Laman among them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-32', 'coc-bom-1908', 'Alma', 25, 32, 'Now Moroni caused that Laman and a small number of his men should go forth unto the guards who were over the Nephites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-37', 'coc-bom-1908', 'Alma', 25, 37, 'But Laman said unto them, Let us keep of our wine till we go against the Nephites to battle. But this saying only made them more desirous to drink of the wine.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-38', 'coc-bom-1908', 'Alma', 25, 38, 'For, said they, We are weary, therefore, let us take of the wine, and by and by we shall receive wine for our rations, which will strengthen us to go against the Nephites. And Laman said unto them, You may do according to your desires.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-40', 'coc-bom-1908', 'Alma', 25, 40, 'And it came to pass that they did drink and were merry, and by and by they were all drunken.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-41', 'coc-bom-1908', 'Alma', 25, 41, 'And now, when Laman and his men saw that they were all drunken and were in a deep sleep, they returned to Moroni and told him all the things that had happened. And now, this was according to the design of Moroni.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-43', 'coc-bom-1908', 'Alma', 25, 43, 'And all those things were done in a profound silence. But had they awakened the Lamanites, behold, they were drunken, and the Nephites could have slain them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-46', 'coc-bom-1908', 'Alma', 25, 46, 'And then he caused the men who were with him to withdraw a pace from them and surround the armies of the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-47', 'coc-bom-1908', 'Alma', 25, 47, 'Now behold, this was done in the nighttime, so that when the Lamanites awoke in the morning, they beheld that they were surrounded by the Nephites without and that their prisoners were armed within.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-49', 'coc-bom-1908', 'Alma', 25, 49, 'Therefore, their chief captains demanded their weapons of war, and they brought them forth and cast them at the feet of the Nephites, pleading for mercy. Now behold, this was the desire of Moroni.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-51', 'coc-bom-1908', 'Alma', 25, 51, 'And it came to pass that he did cause the Lamanites, whom he had taken prisoners, that they should commence a labor in strengthening the fortifications round about the city Gid.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-52', 'coc-bom-1908', 'Alma', 25, 52, 'And it came to pass that when he had fortified the city Gid according to his desires, he caused that his prisoners should be taken to the city Bountiful.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-53', 'coc-bom-1908', 'Alma', 25, 53, 'And he also guarded that city with an exceeding strong force.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-54', 'coc-bom-1908', 'Alma', 25, 54, 'And it came to pass that they did, notwithstanding all the intrigues of the Lamanites, keep and protect all the prisoners whom they had taken and also maintain all the ground and the advantage which they had retaken.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-55', 'coc-bom-1908', 'Alma', 25, 55, 'And it came to pass that the Nephites began again to be victorious and to reclaim their rights and their privileges.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-56', 'coc-bom-1908', 'Alma', 25, 56, 'Many times did the Lamanites attempt to encircle them about by night, but in these attempts they did lose many prisoners.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-57', 'coc-bom-1908', 'Alma', 25, 57, 'And many times did they attempt to administer of their wine to the Nephites, that they might destroy them with poison or with drunkenness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-58', 'coc-bom-1908', 'Alma', 25, 58, 'But behold, the Nephites were not slow to remember the Lord, their God, in this their times of affliction.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-61', 'coc-bom-1908', 'Alma', 25, 61, 'And now, it came to pass that it was expedient for Moroni to make preparations to attack the city Morianton.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-25-63', 'coc-bom-1908', 'Alma', 25, 63, 'And thus ended the twenty and ninth year of the reign of the judges over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-1', 'coc-bom-1908', 'Alma', 26, 1, 'And now, it came to pass in the commencement of the thirtieth year of the reign of the judges, in the second day, on the first month, Moroni received an epistle from Helaman, stating the affairs of the people in that quarter of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-2', 'coc-bom-1908', 'Alma', 26, 2, 'And these are the words which he wrote, saying, My dearly beloved brother, Moroni--as well in the Lord as in the tribulations of our warfare--behold, my beloved brother, I have somewhat to tell you concerning our warfare in this part of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-3', 'coc-bom-1908', 'Alma', 26, 3, 'Behold two thousand of the sons of those men whom Ammon brought down out of the land of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-4', 'coc-bom-1908', 'Alma', 26, 4, 'Now ye have known that these were a descendant of Laman, who was the eldest son of our father Lehi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-6', 'coc-bom-1908', 'Alma', 26, 6, 'And now, ye also know concerning the covenant which their fathers made, that they would not take up their weapons of war against their brethren to shed blood.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-7', 'coc-bom-1908', 'Alma', 26, 7, 'But in the twenty and sixth year, when they saw our afflictions and our tribulations for them, they were about to break the covenant which they had made and take up their weapons of war in our defense.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-8', 'coc-bom-1908', 'Alma', 26, 8, 'But I would not suffer them that they should break this covenant which they had made, supposing that God would strengthen us, insomuch that we should not suffer more because of the fulfilling the oath which they had taken.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-9', 'coc-bom-1908', 'Alma', 26, 9, 'But behold, here is one thing in which we may have great joy.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-10', 'coc-bom-1908', 'Alma', 26, 10, 'For behold, in the twenty and sixth year, I, Helaman, did march at the head of these two thousand young men to the city of Judea to assist Antipus, whom ye had appointed a leader over the people of that part of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-12', 'coc-bom-1908', 'Alma', 26, 12, 'Nevertheless, we may console ourselves in this point: that they have died in the cause of their country and of their God, yea, and they are happy.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-15', 'coc-bom-1908', 'Alma', 26, 15, 'And now, these are the cities which the Lamanites have obtained possession by the shedding of the blood of so many of our valiant men: the land of Manti, or the city of Manti, and the city of Zeezrom, and the city of Cumeni, and the city of Antiparah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-19', 'coc-bom-1908', 'Alma', 26, 19, 'And now, it came to pass that when the Lamanites saw that Antipus had received a greater strength to his army, they were compelled by the orders of Ammoron to not come against the city of Judea, or against us, to battle.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-21', 'coc-bom-1908', 'Alma', 26, 21, 'They were commanded by Ammoron to maintain those cities which they had taken. And thus ended the twenty and sixth year.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-22', 'coc-bom-1908', 'Alma', 26, 22, 'And in the commencement of the twenty and seventh year, we had prepared our city and ourselves for defense.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-29', 'coc-bom-1908', 'Alma', 26, 29, 'And thus with their forces they were determined to maintain those cities which they had taken.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-30', 'coc-bom-1908', 'Alma', 26, 30, 'And now, it came to pass in the second month of this year, there was brought unto us many provisions from the fathers of those my two thousand sons.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-31', 'coc-bom-1908', 'Alma', 26, 31, 'And also there was sent two thousand men unto us from the land of Zarahemla.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-32', 'coc-bom-1908', 'Alma', 26, 32, 'And thus we were prepared with ten thousand men and provisions for them and also for their wives and their children.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-33', 'coc-bom-1908', 'Alma', 26, 33, 'And the Lamanites, thus seeing our forces increase daily and provisions arrive for our support, they began to be fearful and began to sally forth, if it were possible, to put an end to our receiving provisions and strength.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-34', 'coc-bom-1908', 'Alma', 26, 34, 'Now when we saw that the Lamanites began to grow uneasy on this wise, we were desirous to bring a stratagem into effect upon them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-35', 'coc-bom-1908', 'Alma', 26, 35, 'Therefore, Antipus ordered that I should march forth with my little sons to a neighboring city, as if we were carrying provisions to a neighboring city.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-36', 'coc-bom-1908', 'Alma', 26, 36, 'And we were to march near the city of Antiparah, as if we were going to the city beyond in the borders by the seashore.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-37', 'coc-bom-1908', 'Alma', 26, 37, 'And it came to pass that we did march forth, as if with our provisions to go to that city.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-38', 'coc-bom-1908', 'Alma', 26, 38, 'And it came to pass that Antipus did march forth with a part of his army, leaving the remainder to maintain the city.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-39', 'coc-bom-1908', 'Alma', 26, 39, 'But he did not march forth until I had gone forth with my little army and came near the city Antiparah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-40', 'coc-bom-1908', 'Alma', 26, 40, 'And now, in the city Antiparah were stationed the strongest army of the Lamanites, yea, the most numerous.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-41', 'coc-bom-1908', 'Alma', 26, 41, 'And it came to pass that when they had been informed by their spies, they came forth with their army and marched against us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-42', 'coc-bom-1908', 'Alma', 26, 42, 'And it came to pass that we did flee before them northward.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-45', 'coc-bom-1908', 'Alma', 26, 45, 'And now, Antipus, beholding our danger, did speed the march of his army.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-47', 'coc-bom-1908', 'Alma', 26, 47, 'And it came to pass that before the dawn of the morning, behold, the Lamanites were pursuing us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-53', 'coc-bom-1908', 'Alma', 26, 53, 'And now, I say unto you, my beloved brother Moroni, that never had I seen so great courage, nay, not amongst all the Nephites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-57', 'coc-bom-1908', 'Alma', 26, 57, 'And they rehearsed unto me the words of their mothers, saying, We do not doubt our mothers knew.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-58', 'coc-bom-1908', 'Alma', 26, 58, 'And it came to pass that I did return with my two thousand against these Lamanites who had pursued us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-59', 'coc-bom-1908', 'Alma', 26, 59, 'And now, behold, the armies of Antipus had overtaken them, and a terrible battle had commenced.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-63', 'coc-bom-1908', 'Alma', 26, 63, 'Now when the people of Antipus saw that the Lamanites had turned them about, they gathered together their men and came again upon the rear of the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-65', 'coc-bom-1908', 'Alma', 26, 65, 'And now, it came to pass that when they had surrendered themselves up unto us, behold, I numbered those young men who had fought with me, fearing lest there were many of them slain.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-69', 'coc-bom-1908', 'Alma', 26, 69, 'And the remainder I took, and joined them to my stripling Ammonites, and took our march back to the city of Judea.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-70', 'coc-bom-1908', 'Alma', 26, 70, 'And now, it came to pass that I received an epistle from Ammoron, the king, stating that if I would deliver up those prisoners of war whom we had taken, that he would deliver up the city of Antiparah unto us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-74', 'coc-bom-1908', 'Alma', 26, 74, 'And thus ended the twenty and eighth year of the reign of the judges.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-75', 'coc-bom-1908', 'Alma', 26, 75, 'And it came to pass that in the commencement of the twenty and ninth year, we received a supply of provisions and also an addition to our army from the land of Zarahemla and from the land round about--to the number of six thousand men, besides sixty of the sons of the Ammonites, who had come to join their brethren, my little band of two thousand.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-77', 'coc-bom-1908', 'Alma', 26, 77, 'And it came to pass that it was our desire to wage a battle with the army which was placed to protect the city of Cumeni.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-80', 'coc-bom-1908', 'Alma', 26, 80, 'At length their provisions did arrive, and they were about to enter the city by night.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-83', 'coc-bom-1908', 'Alma', 26, 83, 'Therefore, it became expedient that we should take those provisions and send them to Judea, and our prisoners to the land of Zarahemla.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-85', 'coc-bom-1908', 'Alma', 26, 85, 'But it came to pass that our prisoners were so numerous that, notwithstanding the enormity of our numbers, we were obliged to employ all our force to keep them or to put them to death.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-86', 'coc-bom-1908', 'Alma', 26, 86, 'For behold, they would break out in great numbers and would fight with stones, and with clubs, or whatsoever things they could get into their hands, insomuch that we did slay upwards of two thousand of them after they had surrendered themselves prisoners of war.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-88', 'coc-bom-1908', 'Alma', 26, 88, 'And also our provisions were not any more than sufficient for our own people, notwithstanding that which we had taken from the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-90', 'coc-bom-1908', 'Alma', 26, 90, 'Therefore, we selected a part of our men and gave them charge over our prisoners, to go down to the land of Zarahemla. But it came to pass that on the morrow they did return.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-92', 'coc-bom-1908', 'Alma', 26, 92, 'For behold, Ammoron had sent to their support a new supply of provisions and also a numerous army of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-93', 'coc-bom-1908', 'Alma', 26, 93, 'And it came to pass that those men whom we sent with the prisoners did arrive in season to check them as they were about to overpower us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-99', 'coc-bom-1908', 'Alma', 26, 99, 'And it came to pass that after the Lamanites had fled, I immediately gave orders that my men who had been wounded should be taken from among the dead and caused that their wounds should be dressed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-102', 'coc-bom-1908', 'Alma', 26, 102, 'And now, their preservation was astonishing to our whole army--yea, that they should be spared while there was a thousand of our brethren who were slain.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-103', 'coc-bom-1908', 'Alma', 26, 103, 'And we do justly ascribe it to the miraculous power of God because of their exceeding faith in that which they had been taught to believe--that there was a just God, and whosoever did not doubt, that they should be preserved by his marvelous power.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-105', 'coc-bom-1908', 'Alma', 26, 105, 'And now, it came to pass that after we had thus taken care of our wounded men and had buried our dead and also the dead of the Lamanites, who were many, behold, we did inquire of Gid concerning the prisoners whom they had started to go down to the land of Zarahemla with.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-106', 'coc-bom-1908', 'Alma', 26, 106, 'Now Gid was the chief captain over the band which was appointed to guard them down to the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-107', 'coc-bom-1908', 'Alma', 26, 107, 'And now, these are the words which Gid said unto me: Behold, we did start to go down to the land of Zarahemla with our prisoners.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-108', 'coc-bom-1908', 'Alma', 26, 108, 'And it came to pass that we did meet the spies of our armies, who had been sent out to watch the camp of the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-111', 'coc-bom-1908', 'Alma', 26, 111, 'And it came to pass because of their rebellion, we did cause that our swords should come upon them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-114', 'coc-bom-1908', 'Alma', 26, 114, 'And behold, we are again delivered out of the hands of our enemies.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-117', 'coc-bom-1908', 'Alma', 26, 117, 'Yea, and I trust that the souls of them who have been slain have entered into the rest of their God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-120', 'coc-bom-1908', 'Alma', 26, 120, 'And they were so much more numerous than was our army that we durst not go forth and attack them in their strongholds.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-122', 'coc-bom-1908', 'Alma', 26, 122, 'Therefore, it became expedient that we should wait, that we might receive more strength from the land of Zarahemla and also a new supply of provisions.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-123', 'coc-bom-1908', 'Alma', 26, 123, 'And it came to pass that I thus did send an embassy to the governor of our land to acquaint him concerning the affairs of our people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-124', 'coc-bom-1908', 'Alma', 26, 124, 'And it came to pass that we did wait to receive provisions and strength from the land of Zarahemla.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-127', 'coc-bom-1908', 'Alma', 26, 127, 'And it came to pass that we did wait in these difficult circumstances for the space of many months, even until we were about to perish for the want of food.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-129', 'coc-bom-1908', 'Alma', 26, 129, 'And this is all the assistance which we did receive to defend ourselves and our country from falling into the hands of our enemies, yea, to contend with an enemy which was innumerable.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-131', 'coc-bom-1908', 'Alma', 26, 131, 'Therefore, we did pour out our souls in prayer to God, that he would strengthen us and deliver us out of the hands of our enemies, yea, and also give us strength, that we might retain our cities, and our lands, and our possessions, for the support of our people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-132', 'coc-bom-1908', 'Alma', 26, 132, 'Yea, and it came to pass that the Lord, our God, did visit us with assurances that he would deliver us, yea, insomuch that he did speak peace to our souls, and did grant unto us great faith, and did cause us that we should hope for our deliverance in him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-133', 'coc-bom-1908', 'Alma', 26, 133, 'And we did take courage with our small force which we had received and were fixed with a determination to conquer our enemies and to maintain our lands, and our possessions, and our wives, and our children, and the cause of our liberty.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-135', 'coc-bom-1908', 'Alma', 26, 135, 'And it came to pass that on the morrow, that when the Lamanites saw that we were in the borders by the wilderness which was near the city, that they sent out their spies round about us, that they might discover the number and the strength of our army.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-136', 'coc-bom-1908', 'Alma', 26, 136, 'And it came to pass that when they saw that we were not strong according to our numbers, and fearing that we should cut them off from their support, except they should come out to battle against us and kill us,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-137', 'coc-bom-1908', 'Alma', 26, 137, 'And also supposing that they could easily destroy us with their numerous hosts, therefore, they began to make preparations to come out against us to battle.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-138', 'coc-bom-1908', 'Alma', 26, 138, 'And when we saw that they were making preparations to come out against us, behold, I caused that Gid, with a small number of men, should secrete himself in the wilderness, and also that Teomner should, with a small number of men, secrete themselves also in the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-140', 'coc-bom-1908', 'Alma', 26, 140, 'And it came to pass that the Lamanites did come out with their numerous army against us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-141', 'coc-bom-1908', 'Alma', 26, 141, 'And when they had come and were about to fall upon us with the sword, I caused that my men, those who were with me, should retreat into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-143', 'coc-bom-1908', 'Alma', 26, 143, 'And we did pass by in the midst of Gid and Teomner, insomuch that they were not discovered by the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-144', 'coc-bom-1908', 'Alma', 26, 144, 'And it came to pass that when the Lamanites had passed by, or when the army had passed by, Gid and Teomner did rise up from their secret places and did cut off the spies of the Lamanites, that they should not return to the city.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-145', 'coc-bom-1908', 'Alma', 26, 145, 'And it came to pass that when they had cut them off, they ran to the city and fell upon the guards who were left to guard the city, insomuch that they did destroy them and did take possession of the city.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-146', 'coc-bom-1908', 'Alma', 26, 146, 'Now this was done because the Lamanites did suffer their whole army, save a few guards only, to be led away into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-147', 'coc-bom-1908', 'Alma', 26, 147, 'And it came to pass that Gid and Teomner by this means had obtained possession of their strongholds.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-148', 'coc-bom-1908', 'Alma', 26, 148, 'And it came to pass that we took our course, after having traveled much in the wilderness, towards the land of Zarahemla.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-151', 'coc-bom-1908', 'Alma', 26, 151, 'Now it came to pass that when it was night, that I caused that my men should not sleep but that they should march forward by another way towards the land of Manti.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-152', 'coc-bom-1908', 'Alma', 26, 152, 'And because of this our march in the nighttime, behold, on the morrow we were beyond the Lamanites, insomuch that we did arrive before them to the city of Manti.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-153', 'coc-bom-1908', 'Alma', 26, 153, 'And thus it came to pass that by this stratagem we did take possession of the city of Manti without the shedding of blood.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-154', 'coc-bom-1908', 'Alma', 26, 154, 'And it came to pass that when the armies of the Lamanites did arrive near the city and saw that we were prepared to meet them, they were astonished exceedingly and struck with great fear, insomuch that they did flee into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-155', 'coc-bom-1908', 'Alma', 26, 155, 'Yea, and it came to pass that the armies of the Lamanites did flee out of all this quarter of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-156', 'coc-bom-1908', 'Alma', 26, 156, 'But behold, they have carried with them many women and children out of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-158', 'coc-bom-1908', 'Alma', 26, 158, 'But behold, our armies are small to maintain so great a number of cities and so great possessions.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-159', 'coc-bom-1908', 'Alma', 26, 159, 'But behold, we trust our God, who has given us victory over those lands, insomuch that we have obtained those cities and those lands which were our own.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-169', 'coc-bom-1908', 'Alma', 26, 169, 'Yea, and that he may favor this people, even that ye may have success in obtaining the possession of all that which the Lamanites have taken from us which was for our support.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-26-170', 'coc-bom-1908', 'Alma', 26, 170, 'And now, behold, I close mine epistle. I am Helaman, the son of Alma.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-2', 'coc-bom-1908', 'Alma', 27, 2, 'Yea, and he did make it known unto all his people in all the land round about in that part where he was, that they might rejoice also.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-3', 'coc-bom-1908', 'Alma', 27, 3, 'And it came to pass that he immediately sent an epistle to Pahoran, desiring that he should cause men to be gathered together to strengthen Helaman, or the armies of Helaman, insomuch that he might with ease maintain that part of the land which he had been so miraculously prospered in retaining.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-4', 'coc-bom-1908', 'Alma', 27, 4, 'And it came to pass when Moroni had sent this epistle to the land of Zarahemla, he began again to lay a plan that he might obtain the remainder of those possessions and cities which the Lamanites had taken from them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-6', 'coc-bom-1908', 'Alma', 27, 6, 'Yea, even those who had been compelled to flee from the land of Manti, and from the land round about, had come over and joined the Lamanites in this part of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-10', 'coc-bom-1908', 'Alma', 27, 10, 'Therefore, he retained all his force to maintain those places which he had recovered.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-11', 'coc-bom-1908', 'Alma', 27, 11, 'And now, when Moroni saw that the city of Nephihah was lost, he was exceeding sorrowful and began to doubt, because of the wickedness of the people, whether they should not fall into the hands of their brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-12', 'coc-bom-1908', 'Alma', 27, 12, 'Now this was the case with all his chief captains. They doubted and marveled also because of the wickedness of the people--and this because of the success of the Lamanites over them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-13', 'coc-bom-1908', 'Alma', 27, 13, 'And it came to pass that Moroni was angry with the government because of their indifference concerning the freedom of their country.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-15', 'coc-bom-1908', 'Alma', 27, 15, 'For behold, I have somewhat to say unto them by the way of condemnation. For behold, ye yourselves know that ye have been appointed to gather together men, and arm them with swords, and with cimeters, and all manner of weapons of war of every kind, and send forth against the Lamanites in whatsoever parts they should come into our land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-16', 'coc-bom-1908', 'Alma', 27, 16, 'And now, behold, I say unto you that myself, and also my men, and also Helaman and his men have suffered exceeding great sufferings, yea, even hunger, thirst, and fatigue, and all manner of afflictions of every kind.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-18', 'coc-bom-1908', 'Alma', 27, 18, 'Yea, thousands have fallen by the sword, while it might have otherwise been if ye had rendered unto our armies sufficient strength and succor for them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-20', 'coc-bom-1908', 'Alma', 27, 20, 'Can you think to sit upon your thrones in a state of thoughtless stupor while your enemies are spreading the work of death around you,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-22', 'coc-bom-1908', 'Alma', 27, 22, 'Yea, ye might have sent armies unto them to have strengthened them and have saved thousands of them from falling by the sword.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-24', 'coc-bom-1908', 'Alma', 27, 24, 'Yea, and this they have done, when they were about to perish with hunger because of your exceeding great neglect towards them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-27', 'coc-bom-1908', 'Alma', 27, 27, 'Behold, could ye suppose that ye could sit upon your thrones and, because of the exceeding goodness of God, ye could do nothing, and he would deliver you? Behold, if ye have supposed this, ye have supposed in vain.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-30', 'coc-bom-1908', 'Alma', 27, 30, 'And now, behold, I say unto you, I fear exceedingly that the judgments of God will come upon this people because of their exceeding slothfulness, yea, even the slothfulness of our government, and their exceeding great neglect towards their brethren, yea, towards those who have been slain.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-36', 'coc-bom-1908', 'Alma', 27, 36, 'But why should I say much concerning this matter, for we know not but what ye yourselves are seeking for authority. We know not but what ye are also traitors to your country.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-37', 'coc-bom-1908', 'Alma', 27, 37, 'Or is it that ye have neglected us because ye are in the heart of our country, and ye are surrounded by security, that ye do not cause food to be sent unto us and also men to strengthen our armies?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-38', 'coc-bom-1908', 'Alma', 27, 38, 'Have ye forgot the commandments of the Lord, your God? Yea, have ye forgot the captivity of our fathers?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-39', 'coc-bom-1908', 'Alma', 27, 39, 'Have ye forgot the many times we have been delivered out of the hands of our enemies?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-40', 'coc-bom-1908', 'Alma', 27, 40, 'Or do ye suppose that the Lord will still deliver us, while we sit upon our thrones and do not make use of the means which the Lord has provided for us?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-41', 'coc-bom-1908', 'Alma', 27, 41, 'Yea, will ye sit in idleness while ye are surrounded with thousands of those, yea, and tens of thousands, who do also sit in idleness--while there are thousands round about in the borders of the land who are falling by the sword, yea, wounded and bleeding?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-42', 'coc-bom-1908', 'Alma', 27, 42, 'Do ye suppose that God will look upon you as guiltless while ye sit still and behold these things? Behold, I say unto you, Nay.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-43', 'coc-bom-1908', 'Alma', 27, 43, 'Now I would that ye should remember that God has said that the inward vessel shall be cleansed first, and then shall the outer vessel be cleansed also.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-44', 'coc-bom-1908', 'Alma', 27, 44, 'And now, except ye do repent of that which ye have done, and begin to be up and doing, and send forth food and men unto us and also unto Helaman, that he may support those parts of our country which he has retained, and that we may also recover the remainder of our possessions in these parts, behold, it will be expedient that we contend no more with the Lamanites until we have first cleansed our inward vessel, yea, even the great head of our government.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-50', 'coc-bom-1908', 'Alma', 27, 50, 'For behold, the Lord will not suffer that ye shall live and wax strong in your iniquities to destroy his righteous people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-51', 'coc-bom-1908', 'Alma', 27, 51, 'Behold, can you suppose that the Lord will spare you and come out in judgment against the Lamanites, when it is the tradition of their fathers that has caused their hatred?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-52', 'coc-bom-1908', 'Alma', 27, 52, 'Yea, and it has been redoubled by those who have dissented from us, while your iniquity is for the cause of your love of glory and the vain things of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-53', 'coc-bom-1908', 'Alma', 27, 53, 'Ye know that ye do transgress the laws of God, and ye do know that ye do trample them under your feet.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-54', 'coc-bom-1908', 'Alma', 27, 54, 'Behold, the Lord saith unto me, If those whom ye have appointed your governors do not repent of their sins and iniquities, ye shall go up to battle against them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-57', 'coc-bom-1908', 'Alma', 27, 57, 'Now see that ye fulfill the word of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-58', 'coc-bom-1908', 'Alma', 27, 58, 'Behold, I am Moroni, your chief captain. I seek not for power but to pull it down.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-27-59', 'coc-bom-1908', 'Alma', 27, 59, 'I seek not for honor of the world, but for the glory of my God and the freedom and welfare of my country. And thus I close mine epistle.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-28-1', 'coc-bom-1908', 'Alma', 28, 1, 'Behold, now it came to pass that soon after Moroni had sent his epistle unto the chief governor, he received an epistle from Pahoran, the chief governor.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-28-6', 'coc-bom-1908', 'Alma', 28, 6, 'And behold, they have driven me out before them, and I have fled to the land of Gideon with as many men as it were possible that I could get.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-28-8', 'coc-bom-1908', 'Alma', 28, 8, 'And they have come unto us, insomuch that those who have risen up in rebellion against us are set at defiance, yea, insomuch that they do fear us and durst not come out against us to battle.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-28-10', 'coc-bom-1908', 'Alma', 28, 10, 'In the which alliance he hath agreed to maintain the city of Zarahemla, which maintenance he supposeth will enable the Lamanites to conquer the remainder of the land, and he shall be placed king over this people when they shall be conquered under the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-28-12', 'coc-bom-1908', 'Alma', 28, 12, 'I, Pahoran, do not seek for power, save only to retain my judgment seat, that I may preserve the rights and the liberty of my people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-28-13', 'coc-bom-1908', 'Alma', 28, 13, 'My soul standeth fast in that liberty in the which God hath made us free.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-28-14', 'coc-bom-1908', 'Alma', 28, 14, 'And now, behold, we will resist wickedness, even unto bloodshed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-28-15', 'coc-bom-1908', 'Alma', 28, 15, 'We would not shed the blood of the Lamanites if they would stay in their own land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-28-16', 'coc-bom-1908', 'Alma', 28, 16, 'We would not shed the blood of our brethren if they would not rise up in rebellion and take the sword against us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-28-17', 'coc-bom-1908', 'Alma', 28, 17, 'We would subject ourselves to the yoke of bondage if it were requisite with the justice of God, or if he should command us so to do.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-28-18', 'coc-bom-1908', 'Alma', 28, 18, 'But behold, he doth not command us that we shall subject ourselves to our enemies, but that we should put our trust in him and he will deliver us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-28-21', 'coc-bom-1908', 'Alma', 28, 21, 'Behold, I have sent a few provisions unto them, that they may not perish until ye can come unto me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-28-22', 'coc-bom-1908', 'Alma', 28, 22, 'Gather together whatsoever force ye can upon your march hither, and we will go speedily against those dissenters in the strength of our God, according to the faith which is in us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-28-25', 'coc-bom-1908', 'Alma', 28, 25, 'But ye have said, Except they repent, the Lord hath commanded you that ye should go against them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-28-27', 'coc-bom-1908', 'Alma', 28, 27, 'And now, I close mine epistle to my beloved brother Moroni.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-1', 'coc-bom-1908', 'Alma', 29, 1, 'And now, it came to pass that when Moroni had received this epistle, his heart did take courage and was filled with exceeding great joy because of the faithfulness of Pahoran--that he was not also a traitor to the freedom and cause of his country.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-2', 'coc-bom-1908', 'Alma', 29, 2, 'But he did also mourn exceedingly because of the iniquity of those who had driven Pahoran from the judgment seat, yea, in fine, because of those who had rebelled against their country and also their God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-3', 'coc-bom-1908', 'Alma', 29, 3, 'And it came to pass that Moroni took a small number of men, according to the desire of Pahoran, and gave Lehi and Teancum command over the remainder of his army, and took his march towards the land of Gideon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-4', 'coc-bom-1908', 'Alma', 29, 4, 'And he did raise the standard of liberty in whatsoever place he did enter and gained whatsoever force he could in all his march towards the land of Gideon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-5', 'coc-bom-1908', 'Alma', 29, 5, 'And it came to pass that thousands did flock unto his standard and did take up their swords in the defense of their freedom, that they might not come into bondage.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-7', 'coc-bom-1908', 'Alma', 29, 7, 'And it came to pass that Moroni and Pahoran went down with their armies into the land of Zarahemla, and went forth against the city, and did meet the men of Pachus, insomuch that they did come to battle.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-12', 'coc-bom-1908', 'Alma', 29, 12, 'And thus ended the thirtieth year of the reign of the judges over the people of Nephi--Moroni and Pahoran having restored peace to the land of Zarahemla among their own people, having inflicted death upon all those who were not true to the cause of freedom.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-14', 'coc-bom-1908', 'Alma', 29, 14, 'And he also caused that an army of six thousand men, with a sufficient quantity of food, should be sent to the armies of Lehi and Teancum.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-15', 'coc-bom-1908', 'Alma', 29, 15, 'And it came to pass that this was done to fortify the land against the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-16', 'coc-bom-1908', 'Alma', 29, 16, 'And it came to pass that Moroni and Pahoran, leaving a large body of men in the land of Zarahemla, took their march with a large body of men towards the land of Nephihah, being determined to overthrow the Lamanites in that city.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-17', 'coc-bom-1908', 'Alma', 29, 17, 'And it came to pass that as they were marching towards the land, they took a large body of men of the Lamanites, and slew many of them, and took their provisions and their weapons of war.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-18', 'coc-bom-1908', 'Alma', 29, 18, 'And it came to pass after they had taken them, they caused them to enter into a covenant that they would no more take up their weapons of war against the Nephites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-20', 'coc-bom-1908', 'Alma', 29, 20, 'And it came to pass that when they had sent them away, they pursued their march towards the land of Nephihah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-21', 'coc-bom-1908', 'Alma', 29, 21, 'And it came to pass that when they had come to the city Nephihah, they did pitch their tents in the plains of Nephihah, which is near the city Nephihah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-23', 'coc-bom-1908', 'Alma', 29, 23, 'And when the night came, Moroni went forth in the darkness of the night and came upon the top of the wall to spy out in what part of the city the Lamanites did camp with their army.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-25', 'coc-bom-1908', 'Alma', 29, 25, 'And now, Moroni returned to his army and caused that they should prepare in haste strong cords and ladders to be let down from the top of the wall into the inner part of the wall.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-26', 'coc-bom-1908', 'Alma', 29, 26, 'And it came to pass that Moroni caused that his men should march forth, and come upon the top of the wall, and let themselves down into that part of the city, yea, even on the west, where the Lamanites did not camp with their armies.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-28', 'coc-bom-1908', 'Alma', 29, 28, 'And now, when the Lamanites awoke and saw that the armies of Moroni were within the walls, they were affrighted exceedingly, insomuch that they did flee out by the pass.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-31', 'coc-bom-1908', 'Alma', 29, 31, 'Now it came to pass that many of the Lamanites who were prisoners were desirous to join the people of Ammon and become a free people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-33', 'coc-bom-1908', 'Alma', 29, 33, 'And thus were the Nephites relieved from a great burden, yea, insomuch that they were relieved from all the prisoners of the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-34', 'coc-bom-1908', 'Alma', 29, 34, 'Now it came to pass that Moroni, after he had obtained possession of the city of Nephihah--having taken many prisoners, which did reduce the armies of the Lamanites exceedingly, and having retained many of the Nephites who had been taken prisoners, which did strengthen the army of Moroni exceedingly--therefore, Moroni went forth from the land of Nephihah to the land of Lehi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-35', 'coc-bom-1908', 'Alma', 29, 35, 'And it came to pass that when the Lamanites saw that Moroni was coming against them, they were again frightened and fled before the army of Moroni.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-37', 'coc-bom-1908', 'Alma', 29, 37, 'And the armies of the Lamanites were all gathered together, insomuch that they were all in one body in the land of Moroni.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-38', 'coc-bom-1908', 'Alma', 29, 38, 'Now Ammoron, the king of the Lamanites, was also with them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-41', 'coc-bom-1908', 'Alma', 29, 41, 'For he was exceeding angry with Ammoron, insomuch that he considered that Ammoron and Amalickiah, his brother, had been the cause of this great and lasting war between them and the Lamanites, which had been the cause of so much war and bloodshed, yea, and so much famine.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-42', 'coc-bom-1908', 'Alma', 29, 42, 'And it came to pass that Teancum in his anger did go forth into the camp of the Lamanites and did let himself down over the walls of the city.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-44', 'coc-bom-1908', 'Alma', 29, 44, 'But behold, the king did awake his servant before he died, insomuch that they did pursue Teancum and slew him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-46', 'coc-bom-1908', 'Alma', 29, 46, 'But behold, he was dead and had gone the way of all the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-51', 'coc-bom-1908', 'Alma', 29, 51, 'And many were softened because of their afflictions, insomuch that they did humble themselves before God, even in the depth of humility.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-55', 'coc-bom-1908', 'Alma', 29, 55, 'Therefore, Helaman and his brethren went forth and did declare the word of God with much power, unto the convincing of many people of their wickedness, which did cause them to repent of their sins and to be baptized unto the Lord, their God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-57', 'coc-bom-1908', 'Alma', 29, 57, 'And their judges and their chief judges were chosen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-58', 'coc-bom-1908', 'Alma', 29, 58, 'And the people of Nephi began to prosper again in the land and began to multiply and to wax exceeding strong again in the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-61', 'coc-bom-1908', 'Alma', 29, 61, 'And they did pray unto the Lord, their God, continually, insomuch that the Lord did bless them according to his word, so that they did wax strong and prosper in the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-62', 'coc-bom-1908', 'Alma', 29, 62, 'And it came to pass that all these things were done.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-29-63', 'coc-bom-1908', 'Alma', 29, 63, 'And Helaman died in the thirty and fifth year of the reign of the judges over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-30-3', 'coc-bom-1908', 'Alma', 30, 3, 'And it came to pass that Moroni died also.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-30-4', 'coc-bom-1908', 'Alma', 30, 4, 'And thus ended the thirty and sixth year of the reign of the judges.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-30-5', 'coc-bom-1908', 'Alma', 30, 5, 'And it came to pass that in the thirty and seventh year of the reign of the judges, there was a large company of men, even to the amount of five thousand and four hundred men with their wives and their children, departed out of the land of Zarahemla into the land which was northward.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-30-6', 'coc-bom-1908', 'Alma', 30, 6, 'And it came to pass that Hagoth--he being an exceeding curious man--therefore, he went forth, and built him an exceeding large ship on the borders of the land Bountiful by the land Desolation, and launched it forth into the west sea, by the narrow neck which led into the land northward.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-30-8', 'coc-bom-1908', 'Alma', 30, 8, 'And thus ended the thirty and seventh year.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-30-9', 'coc-bom-1908', 'Alma', 30, 9, 'And in the thirty and eighth year this man built other ships.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-30-11', 'coc-bom-1908', 'Alma', 30, 11, 'And it came to pass that they were never heard of more. And we suppose that they were drowned up in the depths of the sea.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-30-13', 'coc-bom-1908', 'Alma', 30, 13, 'And it came to pass that in this year, there were many people who went forth into the land northward. And thus ended the thirty and eighth year.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-30-15', 'coc-bom-1908', 'Alma', 30, 15, 'Therefore, it became expedient for Shiblon to confer those sacred things, before his death, upon the son of Helaman, who was called Helaman, being called after the name of his father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-30-16', 'coc-bom-1908', 'Alma', 30, 16, 'Now behold, all those engravings which were in the possession of Helaman were written and sent forth among the children of men throughout all the land, save it were those parts which had been commanded by Alma should not go forth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-30-19', 'coc-bom-1908', 'Alma', 30, 19, 'And also in this same year, they came down with a numerous army to war against the people of Moronihah, or against the army of Moronihah, in the which they were beaten and driven back again to their own lands, suffering great loss.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-30-20', 'coc-bom-1908', 'Alma', 30, 20, 'And thus ended the thirty and ninth year of the reign of the judges over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:alma-30-21', 'coc-bom-1908', 'Alma', 30, 21, 'And thus ended the account of Alma, and Helaman his son, and also Shiblon, who was his son.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-1-1', 'coc-bom-1908', 'Helaman', 1, 1, 'And now, behold, it came to pass in the commencement of the fortieth year of the reign of the judges over the people of Nephi, there began to be a serious difficulty among the people of the Nephites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-1-3', 'coc-bom-1908', 'Helaman', 1, 3, 'Now these are their names who did contend for the judgment seat, who did also cause the people to contend: Pahoran, Paanchi, and Pacumeni.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-1-5', 'coc-bom-1908', 'Helaman', 1, 5, 'Nevertheless, it came to pass that Pahoran was appointed by the voice of the people to be chief judge and a governor over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-1-6', 'coc-bom-1908', 'Helaman', 1, 6, 'And it came to pass that Pacumeni, when he saw that he could not obtain the judgment seat, he did unite with the voice of the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-1-18', 'coc-bom-1908', 'Helaman', 1, 18, 'Therefore, he did stir them up to anger, and he did gather together his armies, and he did appoint Coriantumr to be their leader, and did cause that they should march down to the land of Zarahemla to battle against the Nephites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-1-21', 'coc-bom-1908', 'Helaman', 1, 21, 'Therefore, Coriantumr did cut down the watch by the entrance of the city, and did march forth with his whole army into the city, and they did slay everyone who did oppose them, insomuch that they did take possession of the whole city.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-1-22', 'coc-bom-1908', 'Helaman', 1, 22, 'And it came to pass that Pacumeni, who was the chief judge, did flee before Coriantumr, even to the walls of the city.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-1-23', 'coc-bom-1908', 'Helaman', 1, 23, 'And it came to pass that Coriantumr did smite him against the wall, insomuch that he died. And thus ended the days of Pacumeni.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-1-24', 'coc-bom-1908', 'Helaman', 1, 24, 'And now, when Coriantumr saw that he was in possession of the city of Zarahemla and saw that the Nephites had fled before them, and were slain, and were taken, and were cast into prison, and that he had obtained the possession of the strongest hold in all the land, his heart took courage, insomuch that he was about to go forth against all the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-1-29', 'coc-bom-1908', 'Helaman', 1, 29, 'But behold, the Lamanites were not frightened according to his desire, but they had come into the center of the land, and had taken the capital city, which was the city of Zarahemla, and were marching through the most capital parts of the land, slaying the people with a great slaughter--both men, women and children--taking possession of many cities and of many strongholds.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-1-30', 'coc-bom-1908', 'Helaman', 1, 30, 'But when Moronihah had discovered this, he immediately sent forth Lehi with an army round about to head them before they should come to the land Bountiful.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-1-33', 'coc-bom-1908', 'Helaman', 1, 33, 'And now, behold, the Lamanites could not retreat either way--neither on the north, nor on the south, nor on the east, nor on the west--for they were surrounded on every hand by the Nephites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-1-35', 'coc-bom-1908', 'Helaman', 1, 35, 'And it came to pass that Moronihah took possession of the city of Zarahemla again and caused that the Lamanites who had been taken prisoners should depart out of the land in peace.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-1-36', 'coc-bom-1908', 'Helaman', 1, 36, 'And thus ended the forty and first year of the reign of the judges.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-1-42', 'coc-bom-1908', 'Helaman', 1, 42, 'And it came to pass as he went forth towards the judgment seat to destroy Helaman, behold, one of the servants of Helaman--having been out by night and having obtained, through disguise, a knowledge of those plans which had been laid by his band to destroy Helaman--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-1-44', 'coc-bom-1908', 'Helaman', 1, 44, 'And when the servant of Helaman had known all the heart of Kishkumen, and how that it was his object to murder, and also that it was the object of all those who belonged to his band to murder, and to rob, and to gain power (and this was their secret plan and their combination), the servant of Helaman saith unto Kishkumen, Let us go forth unto the judgment seat.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-1-46', 'coc-bom-1908', 'Helaman', 1, 46, 'And he ran and told Helaman all the things which he had seen, and heard, and done.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-1-47', 'coc-bom-1908', 'Helaman', 1, 47, 'And it came to pass that Helaman did send forth to take this band of robbers and secret murderers, that they might be executed according to the law.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-1-50', 'coc-bom-1908', 'Helaman', 1, 50, 'And thus ended the forty and second year of the reign of the judges over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-1-51', 'coc-bom-1908', 'Helaman', 1, 51, 'And behold, in the end of this book, ye shall see that this Gadianton did prove the overthrow, yea, almost the entire destruction of the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-1-52', 'coc-bom-1908', 'Helaman', 1, 52, 'Behold, I do not mean the end of the book of Helaman, but I mean the end of the book of Nephi, from which I have taken all the account which I have written.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-1', 'coc-bom-1908', 'Helaman', 2, 1, 'And now, it came to pass in the forty and third year of the reign of the judges, there was no contention among the people of Nephi, save it were a little pride which was in the church, which did cause some little dissensions among the people, which affairs were settled in the ending of the forty and third year.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-5', 'coc-bom-1908', 'Helaman', 2, 5, 'Yea, and even they did spread forth into all parts of the land, into whatever parts it had not been rendered desolate and without timber because of the many inhabitants who had before inherited the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-8', 'coc-bom-1908', 'Helaman', 2, 8, 'And it came to pass that they did multiply, and spread, and did go forth from the land southward to the land northward, and did spread insomuch that they began to cover the face of the whole earth, from the sea south to the sea north, from the sea west to the sea east.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-11', 'coc-bom-1908', 'Helaman', 2, 11, 'And it came to pass that there were many of the people of Ammon, who were Lamanites by birth, did also go forth into this land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-16', 'coc-bom-1908', 'Helaman', 2, 16, 'The forty and sixth year of the reign of the judges ended.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-19', 'coc-bom-1908', 'Helaman', 2, 19, 'And it came to pass that he had two sons. He gave unto the eldest the name of Nephi and unto the youngest the name of Lehi. And they began to grow up unto the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-20', 'coc-bom-1908', 'Helaman', 2, 20, 'And it came to pass that the wars and contentions began to cease, in a small degree, among the people of the Nephites in the latter end of the forty and eighth year of the reign of the judges over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-23', 'coc-bom-1908', 'Helaman', 2, 23, 'And so great was the prosperity of the church and so many the blessings which were poured out upon the people that even the high priests and the teachers were themselves astonished beyond measure.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-24', 'coc-bom-1908', 'Helaman', 2, 24, 'And it came to pass that the work of the Lord did prosper unto the baptizing and uniting to the church of God many souls, yea, even tens of thousands.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-26', 'coc-bom-1908', 'Helaman', 2, 26, 'Yea, we see that whosoever will lay hold upon the word of God, which is quick and powerful, which shall divide asunder all the cunning, and the snares, and the wiles of the devil, and lead the man of Christ in a straight and narrow course across that everlasting gulf of misery which is prepared to engulf the wicked, and land their souls, yea, their immortal souls, at the right hand of God in the kingdom of heaven, to sit down with Abraham, and Isaac, and with Jacob, and with all our holy fathers, to go no more out.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-27', 'coc-bom-1908', 'Helaman', 2, 27, 'And in this year there was continual rejoicing in the land of Zarahemla and in all the regions round about, even in all the land which was possessed by the Nephites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-31', 'coc-bom-1908', 'Helaman', 2, 31, 'Nevertheless, they did fast and pray oft, and did wax stronger and stronger in their humility, and firmer and firmer in the faith of Christ, unto the filling their souls with joy and consolation, yea, even to the purifying and the sanctification of their hearts, which sanctification cometh because of their yielding their hearts unto God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-40', 'coc-bom-1908', 'Helaman', 2, 40, 'And thus those dissenters of the Nephites, with the help of a numerous army of the Lamanites, had obtained all the possession of the Nephites which was in the land southward.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-41', 'coc-bom-1908', 'Helaman', 2, 41, 'And all this was done in the fifty and eighth and ninth years of the reign of the judges.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-43', 'coc-bom-1908', 'Helaman', 2, 43, 'And it came to pass in the sixty and first year of the reign of the judges, they succeeded in retaining even the half of all their possessions.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-48', 'coc-bom-1908', 'Helaman', 2, 48, 'Yea, and did prophesy many things unto them concerning their iniquities and what should come unto them if they did not repent of their sins.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-50', 'coc-bom-1908', 'Helaman', 2, 50, 'For when Moronihah saw that they did repent, he did venture to lead them forth from place to place and from city to city, even until they had retained the one-half of their property and the one-half of all their lands.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-51', 'coc-bom-1908', 'Helaman', 2, 51, 'And thus ended the sixty and first year of the reign of the judges.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-56', 'coc-bom-1908', 'Helaman', 2, 56, 'And that they had altered and trampled under their feet the laws of Mosiah, or that which the Lord commanded him to give unto the people,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-57', 'coc-bom-1908', 'Helaman', 2, 57, 'And thus seeing that their laws had become corrupted, and that they had become a wicked people, insomuch that they were wicked, even like unto the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-61', 'coc-bom-1908', 'Helaman', 2, 61, 'For behold, they saw that the strength of the Lamanites was as great as their strength, even man for man.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-63', 'coc-bom-1908', 'Helaman', 2, 63, 'And it came to pass that in this same year, behold, Nephi delivered up the judgment seat to a man whose name was Cezoram.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-69', 'coc-bom-1908', 'Helaman', 2, 69, 'Therefore, my sons, I would that ye should do that which is good, that it may be said of you and also written, even as it has been said and written of them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-70', 'coc-bom-1908', 'Helaman', 2, 70, 'And now, my sons, behold, I have somewhat more to desire of you, which desire is that ye may not do these things that ye may boast, but that ye may do these things to lay up for yourselves a treasure in heaven, yea, which is eternal and which fadeth not away, yea, that ye may have that precious gift of eternal life, which we have reason to suppose hath been given to our fathers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-74', 'coc-bom-1908', 'Helaman', 2, 74, 'And now, my sons, remember, remember, that it is upon the rock of our Redeemer, who is Christ, the Son of God, that ye must build your foundation--that when the devil shall send forth his mighty winds, yea, his shafts in the whirlwind,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-75', 'coc-bom-1908', 'Helaman', 2, 75, 'Yea, when all his hail and his mighty storm shall beat upon you, it shall have no power over you, to drag you down to the gulf of misery and endless wo, because of the rock upon which ye are built, which is a sure foundation, a foundation whereon if men build, they cannot fall.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-78', 'coc-bom-1908', 'Helaman', 2, 78, 'And even from one city to another, until they had gone forth among all the people of Nephi who were in the land southward, and from thence into the land of Zarahemla among the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-79', 'coc-bom-1908', 'Helaman', 2, 79, 'And it came to pass that they did preach with great power, insomuch that they did confound many of those dissenters who had gone over from the Nephites, insomuch that they came forth, and did confess their sins, and were baptized unto repentance, and immediately returned to the Nephites to endeavor to repair unto them the wrongs which they had done.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-81', 'coc-bom-1908', 'Helaman', 2, 81, 'Therefore, they did speak unto the great astonishment of the Lamanites, to the convincing them, insomuch that there were eight thousand of the Lamanites, who were in the land of Zarahemla and round about, baptized unto repentance, and were convinced of the wickedness of the traditions of their fathers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-82', 'coc-bom-1908', 'Helaman', 2, 82, 'And it came to pass that Nephi and Lehi did proceed from thence to go to the land of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-83', 'coc-bom-1908', 'Helaman', 2, 83, 'And it came to pass that they were taken by an army of the Lamanites and cast into prison, yea, even in that same prison in which Ammon and his brethren were cast by the servants of Limhi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-84', 'coc-bom-1908', 'Helaman', 2, 84, 'And after they had been cast into prison many days without food, behold, they went forth into the prison to take them, that they might slay them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-85', 'coc-bom-1908', 'Helaman', 2, 85, 'And it came to pass that Nephi and Lehi were encircled about as if by fire, even insomuch that they durst not lay their hands upon them for fear, lest they should be burned.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-87', 'coc-bom-1908', 'Helaman', 2, 87, 'And when they saw that they were encircled about with a pillar of fire and that it burned them not, their hearts did take courage.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-89', 'coc-bom-1908', 'Helaman', 2, 89, 'And it came to pass that Nephi and Lehi did stand forth and began to speak unto them, saying, Fear not, for behold, it is God that has shown unto you this marvelous thing, in the which is shown unto you that ye cannot lay your hands on us to slay us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-91', 'coc-bom-1908', 'Helaman', 2, 91, 'And behold, they that were in the prison were Lamanites and Nephites who were dissenters.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-92', 'coc-bom-1908', 'Helaman', 2, 92, 'And it came to pass that they were overshadowed with a cloud of darkness, and an awful, solemn fear came upon them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-93', 'coc-bom-1908', 'Helaman', 2, 93, 'And it came to pass that there came a voice, as if it were above the cloud of darkness, saying, Repent ye, repent ye, and seek no more to destroy my servants whom I have sent unto you to declare good tidings.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-99', 'coc-bom-1908', 'Helaman', 2, 99, 'Now there was one among them who was a Nephite by birth, who had once belonged to the church of God but had dissented from them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-102', 'coc-bom-1908', 'Helaman', 2, 102, 'And it came to pass that this man did cry unto the multitude, that they might turn and look.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-104', 'coc-bom-1908', 'Helaman', 2, 104, 'And they said unto the man, Behold, what doth all these things mean? And who is it with whom these men do converse?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-105', 'coc-bom-1908', 'Helaman', 2, 105, 'Now the man''s name was Aminadab. And Aminadab said unto them, They do converse with the angels of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-106', 'coc-bom-1908', 'Helaman', 2, 106, 'And it came to pass that the Lamanites said unto him, What shall we do, that this cloud of darkness may be removed from overshadowing us?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-109', 'coc-bom-1908', 'Helaman', 2, 109, 'And it came to pass that when they cast their eyes about and saw that the cloud of darkness was dispersed from overshadowing them, behold, they saw that they were encircled about, yea, every soul, by a pillar of fire.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-112', 'coc-bom-1908', 'Helaman', 2, 112, 'And it came to pass that there came a voice unto them, yea, a pleasant voice, as if it were a whisper, saying, Peace, peace be unto you because of your faith in my well beloved, who was from the foundation of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-116', 'coc-bom-1908', 'Helaman', 2, 116, 'And as many as were convinced did lay down their weapons of war, and also their hatred, and the tradition of their fathers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-117', 'coc-bom-1908', 'Helaman', 2, 117, 'And it came to pass that they did yield up unto the Nephites the lands of their possession.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-119', 'coc-bom-1908', 'Helaman', 2, 119, 'For behold, there were many of the Nephites who had become hardened, and impenitent, and grossly wicked, insomuch that they did reject the word of God and all the preaching and prophesying which did come among them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-120', 'coc-bom-1908', 'Helaman', 2, 120, 'Nevertheless, the people of the church did have great joy because of the conversion of the Lamanites, yea, because of the church of God which had been established among them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-121', 'coc-bom-1908', 'Helaman', 2, 121, 'And they did fellowship one with another, and did rejoice one with another, and did have great joy.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-123', 'coc-bom-1908', 'Helaman', 2, 123, 'Yea, and many did preach with exceeding great power and authority, unto the bringing down many of them into the depths of humility to be the humble followers of God and the Lamb.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-125', 'coc-bom-1908', 'Helaman', 2, 125, 'And thus ended the sixty and third year.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-126', 'coc-bom-1908', 'Helaman', 2, 126, 'And behold, there was peace in all the land, insomuch that the Nephites did go into whatsoever part of the land they would, whether among the Nephites or the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-131', 'coc-bom-1908', 'Helaman', 2, 131, 'They did raise grain in abundance, both in the north and in the south. And they did flourish exceedingly, both in the north and in the south.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-132', 'coc-bom-1908', 'Helaman', 2, 132, 'And they did multiply and wax exceeding strong in the land. And they did raise many flocks and herds, yea, many fatlings.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-133', 'coc-bom-1908', 'Helaman', 2, 133, 'Behold, their women did toil and spin and did make all manner of cloth, of fine twined linen, and cloth of every kind to clothe their nakedness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-134', 'coc-bom-1908', 'Helaman', 2, 134, 'And thus the sixty and fourth year did pass away in peace.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-135', 'coc-bom-1908', 'Helaman', 2, 135, 'And in the sixty and fifth year they did also have great joy and peace, yea, much preaching, and many prophecies concerning that which was to come. And thus passed away the sixty and fifth year.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-136', 'coc-bom-1908', 'Helaman', 2, 136, 'And it came to pass that in the sixty and sixth year of the reign of the judges, behold, Cezoram was murdered by an unknown hand as he sat upon the judgment seat.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-137', 'coc-bom-1908', 'Helaman', 2, 137, 'And it came to pass that in the same year that his son, who had been appointed by the people in his stead, was also murdered. And thus ended the sixty and sixth year.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-138', 'coc-bom-1908', 'Helaman', 2, 138, 'And in the commencement of the sixty and seventh year the people began to grow exceeding wicked again.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-141', 'coc-bom-1908', 'Helaman', 2, 141, 'And now, behold, those murderers and plunderers were a band who had been formed by Kishkumen and Gadianton.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-142', 'coc-bom-1908', 'Helaman', 2, 142, 'And now, it had come to pass that there were many, even among the Nephites, of Gadianton''s band. But behold, they were more numerous among the more wicked part of the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-145', 'coc-bom-1908', 'Helaman', 2, 145, 'But behold, Satan did stir up the hearts of the more part of the Nephites, insomuch that they did unite with those bands of robbers, and did enter into their covenants and their oaths, that they would protect and preserve one another in whatsoever difficult circumstances they should be placed, that they should not suffer for their murders, and their plunderings, and their stealings.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-148', 'coc-bom-1908', 'Helaman', 2, 148, 'And whosoever of those who belonged to their band should reveal unto the world of their wickedness and their abominations should be tried, not according to the laws of their country, but according to the laws of their wickedness, which had been given by Gadianton and Kishkumen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-149', 'coc-bom-1908', 'Helaman', 2, 149, 'Now behold, it is these secret oaths and covenants which Alma commanded his son should not go forth unto the world, lest they should be a means of bringing down the people unto destruction.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-151', 'coc-bom-1908', 'Helaman', 2, 151, 'But behold, they were put into the heart of Gadianton by that same being who did entice our first parents to partake of the forbidden fruit, yea, that same being who did plot with Cain, that if he would murder his brother Abel, it should not be known unto the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-152', 'coc-bom-1908', 'Helaman', 2, 152, 'And he did plot with Cain and his followers from that time forth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-153', 'coc-bom-1908', 'Helaman', 2, 153, 'And also it is that same being who put it into the hearts of the people to build a tower sufficiently high that they might get to heaven.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-154', 'coc-bom-1908', 'Helaman', 2, 154, 'And it was that same being who led on the people who came from that tower into this land, who spread the works of darkness and abominations over all the face of the land until he dragged the people down to an entire destruction and to an everlasting hell,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-156', 'coc-bom-1908', 'Helaman', 2, 156, 'And behold, it is he who is the author of all sin. And behold, he doth carry on his works of darkness and secret murder, and doth hand down their plots, and their oaths, and their covenants, and their plans of awful wickedness from generation to generation, according as he can get hold upon the hearts of the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-158', 'coc-bom-1908', 'Helaman', 2, 158, 'Yea, the more part of them had turned out of the way of righteousness, and did trample under their feet the commandments of God, and did turn unto their own ways, and did build up unto themselves idols of their gold and their silver.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-159', 'coc-bom-1908', 'Helaman', 2, 159, 'And it came to pass that all these iniquities did come unto them in the space of not many years, insomuch that a more part of it had come unto them in the sixty and seventh year of the reign of the judges over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-160', 'coc-bom-1908', 'Helaman', 2, 160, 'And they did grow in their iniquities in the sixty and eighth year also, to the great sorrow and lamentation of the righteous.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-162', 'coc-bom-1908', 'Helaman', 2, 162, 'And thus we see that the Spirit of the Lord began to withdraw from the Nephites because of the wickedness and the hardness of their hearts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-163', 'coc-bom-1908', 'Helaman', 2, 163, 'And thus we see that the Lord began to pour out his Spirit upon the Lamanites because of their easiness and willingness to believe in his word.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-165', 'coc-bom-1908', 'Helaman', 2, 165, 'And it came to pass on the other hand, that the Nephites did build them up and support them, beginning at the more wicked part of them, until they had overspread all the land of the Nephites and had seduced the more part of the righteous until they had come down to believe in their works, and partake of their spoils, and to join with them in their secret murders and combinations.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-166', 'coc-bom-1908', 'Helaman', 2, 166, 'And thus they did obtain the sole management of the government, insomuch that they did trample under their feet, and smite, and rend, and turn their backs upon the poor, and the meek, and the humble followers of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-167', 'coc-bom-1908', 'Helaman', 2, 167, 'And thus we see that they were in an awful state and ripening for an everlasting destruction.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-2-168', 'coc-bom-1908', 'Helaman', 2, 168, 'And it came to pass that thus ended the sixty and eighth year of the reign of the judges over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-6', 'coc-bom-1908', 'Helaman', 3, 6, 'And he did exclaim in the agony of his soul, Oh, that I could have had my days in the days when my father Nephi first came out of the land of Jerusalem, that I could have joyed with him in the promised land!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-8', 'coc-bom-1908', 'Helaman', 3, 8, 'Yea, if my days could have been in those days, then would my soul have had joy in the righteousness of my brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-9', 'coc-bom-1908', 'Helaman', 3, 9, 'But behold, I am consigned that these are my days and that my soul shall be filled with sorrow because of this, the wickedness of my brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-11', 'coc-bom-1908', 'Helaman', 3, 11, 'Therefore, Nephi had bowed himself upon the tower which was in his garden, which tower was also near unto the garden gate which led by the highway.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-13', 'coc-bom-1908', 'Helaman', 3, 13, 'And now, when Nephi arose, he beheld the multitudes of people who had gathered together.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-14', 'coc-bom-1908', 'Helaman', 3, 14, 'And it came to pass that he opened his mouth and said unto them, Behold, why have ye gathered yourselves together? That I may tell you of your iniquities?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-15', 'coc-bom-1908', 'Helaman', 3, 15, 'Yea, because I have got upon my tower, that I might pour out my soul unto my God because of the exceeding sorrow of my heart, which is because of your iniquities?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-17', 'coc-bom-1908', 'Helaman', 3, 17, 'Yea, ye ought to marvel because ye are given away, that the devil has got so great hold upon your hearts. Yea, how could ye have given away to the enticing of him who is seeking to hurl away your souls down to everlasting misery and endless wo?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-18', 'coc-bom-1908', 'Helaman', 3, 18, 'Oh, repent ye, repent ye! Why will ye die? Turn ye, turn ye unto the Lord, your God. Why has he forsaken you?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-20', 'coc-bom-1908', 'Helaman', 3, 20, 'And behold, instead of gathering you, except ye will repent, behold, he shall scatter you forth, that ye shall become meat for dogs and wild beasts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-21', 'coc-bom-1908', 'Helaman', 3, 21, 'Oh, how could you have forgotten your God in the very day that he has delivered you?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-22', 'coc-bom-1908', 'Helaman', 3, 22, 'But behold, it is to get gain, to be praised of men, yea, and that ye might get gold and silver.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-25', 'coc-bom-1908', 'Helaman', 3, 25, 'For behold, thus saith the Lord, I will not show unto the wicked of my strength, to one more than the other, save it be unto those who repent of their sins and hearken unto my words.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-33', 'coc-bom-1908', 'Helaman', 3, 33, 'And they cried out against him, saying unto the people, Why do ye not seize upon this man and bring him forth, that he may be condemned according to the crime which he has done?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-34', 'coc-bom-1908', 'Helaman', 3, 34, 'Why seest thou this man and hearest him revile against this people and against our law?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-42', 'coc-bom-1908', 'Helaman', 3, 42, 'And it came to pass that those people who sought to destroy Nephi were compelled, because of their fear, that they did not lay their hands on him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-43', 'coc-bom-1908', 'Helaman', 3, 43, 'Therefore, he began again to speak unto them, seeing that he had gained favor in the eyes of some, insomuch that the remainder of them did fear.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-45', 'coc-bom-1908', 'Helaman', 3, 45, 'And now, behold, if God gave unto this man such power, then why should ye dispute among yourselves and say that he hath given unto me no power whereby I may know concerning the judgments that shall come upon you except ye repent?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-47', 'coc-bom-1908', 'Helaman', 3, 47, 'Yea, did he not bear record that the Son of God should come? And as he lifted up the brazen serpent in the wilderness, even so shall he be lifted up, who should come.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-48', 'coc-bom-1908', 'Helaman', 3, 48, 'And as many as should look upon that serpent should live, even so as many as should look upon the Son of God with faith, having a contrite spirit, might live, even unto that life which is eternal.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-49', 'coc-bom-1908', 'Helaman', 3, 49, 'And now, behold, Moses did not only testify of these things but also all the holy prophets from his days even to the days of Abraham.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-50', 'coc-bom-1908', 'Helaman', 3, 50, 'Yea, and behold, Abraham saw of his coming, and was filled with gladness, and did rejoice.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-51', 'coc-bom-1908', 'Helaman', 3, 51, 'Yea, and behold, I say unto you that Abraham not only knew of these things, but there were many before the days of Abraham who were called by the order of God, yea, even after the order of his Son--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-52', 'coc-bom-1908', 'Helaman', 3, 52, 'And this that it should be shown unto the people a great many thousand years before his coming, that even redemption should come unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-54', 'coc-bom-1908', 'Helaman', 3, 54, 'And behold, also Zenock, and also Ezaias, and also Isaiah, and Jeremiah (Jeremiah being that same prophet who testified of the destruction of Jerusalem).', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-55', 'coc-bom-1908', 'Helaman', 3, 55, 'And now, we know that Jerusalem was destroyed according to the words of Jeremiah. Oh, then why not the Son of God come according to his prophecy?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-56', 'coc-bom-1908', 'Helaman', 3, 56, 'And now, will ye dispute that Jerusalem was destroyed? Will ye say that the sons of Zedekiah were not slain, all except it were Mulek?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-57', 'coc-bom-1908', 'Helaman', 3, 57, 'Yea, and do ye not behold that the seed of Zedekiah are with us, and they were driven out of the land of Jerusalem?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-58', 'coc-bom-1908', 'Helaman', 3, 58, 'But behold, this is not all. Our father Lehi was driven out of Jerusalem because he testified of these things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-62', 'coc-bom-1908', 'Helaman', 3, 62, 'Yea, even ye have received all things, both things in heaven and all things which are in the earth, as a witness that they are true.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-66', 'coc-bom-1908', 'Helaman', 3, 66, 'And behold, they both belong to your secret band, whose author is Gadianton and the evil one who seeketh to destroy the souls of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-68', 'coc-bom-1908', 'Helaman', 3, 68, 'And they said among themselves as they went, Behold, now we will know of a surety whether this man be a prophet and God hath commanded him to prophesy such marvelous things unto us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-76', 'coc-bom-1908', 'Helaman', 3, 76, 'And it came to pass that they laid hold on them, and bound them, and cast them into prison.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-77', 'coc-bom-1908', 'Helaman', 3, 77, 'And there was a proclamation sent abroad that the judge was slain and that the murderers had been taken and were cast into prison.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-78', 'coc-bom-1908', 'Helaman', 3, 78, 'And it came to pass that on the morrow, the people did assemble themselves together to mourn and to fast at the burial of the great chief judge who had been slain.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-79', 'coc-bom-1908', 'Helaman', 3, 79, 'And thus also those judges who were at the garden of Nephi and heard his words were also gathered together at the burial.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-80', 'coc-bom-1908', 'Helaman', 3, 80, 'And it came to pass that they inquired among the people, saying, Where are the five who were sent to inquire concerning the chief judge, whether he was dead?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-87', 'coc-bom-1908', 'Helaman', 3, 87, 'And it came to pass that the five were liberated on the day of the burial.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-88', 'coc-bom-1908', 'Helaman', 3, 88, 'Nevertheless, they did rebuke the judges in the words which they had spoken against Nephi and did contend with them one by one, insomuch that they did confound them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-91', 'coc-bom-1908', 'Helaman', 3, 91, 'But Nephi said unto them, O ye fools, ye uncircumcised of heart, ye blind, and ye stiff-necked people, do ye know how long the Lord, your God, will suffer you that ye shall go on in this your way of sin?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-92', 'coc-bom-1908', 'Helaman', 3, 92, 'Oh, ye ought to begin to howl and mourn because of the great destruction at this time which doth await you, except ye shall repent.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-93', 'coc-bom-1908', 'Helaman', 3, 93, 'Behold, ye say that I have agreed with a man that he should murder Seezoram, our chief judge.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-94', 'coc-bom-1908', 'Helaman', 3, 94, 'But behold, I say unto you that this is because I have testified unto you, that ye might know concerning this thing, yea, even for a witness unto you, that I did know of the wickedness and abominations which are among you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-96', 'coc-bom-1908', 'Helaman', 3, 96, 'And now, behold, I will show unto you another sign, and see if ye will in this thing seek to destroy me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-97', 'coc-bom-1908', 'Helaman', 3, 97, 'Behold, I say unto you, Go to the house of Seantum, who is the brother of Seezoram, and say unto him, Has Nephi, the pretended prophet, who doth prophesy so much evil concerning this people, agreed with thee, in the which ye have murdered Seezoram, who is your brother? And behold, he shall say unto you, Nay.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-98', 'coc-bom-1908', 'Helaman', 3, 98, 'And ye shall say unto him, Have ye murdered your brother? And he shall stand with fear and wist not what to say.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-100', 'coc-bom-1908', 'Helaman', 3, 100, 'But behold, ye shall examine him, and ye shall find blood upon the skirts of his cloak.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-101', 'coc-bom-1908', 'Helaman', 3, 101, 'And when ye have seen this, ye shall say, From whence cometh this blood? Do we not know that it is the blood of your brother? And then shall he tremble and shall look pale, even as if death had come upon him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-102', 'coc-bom-1908', 'Helaman', 3, 102, 'And then shall ye say, Because of this fear and this paleness which has come upon your face, behold, we know that thou art guilty.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-104', 'coc-bom-1908', 'Helaman', 3, 104, 'And then shall he say unto you that I, Nephi, knew nothing concerning the matter, save it were given unto me by the power of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-105', 'coc-bom-1908', 'Helaman', 3, 105, 'And then shall ye know that I am an honest man and that I am sent unto you from God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-106', 'coc-bom-1908', 'Helaman', 3, 106, 'And it came to pass that they went and did, even according as Nephi had said unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-108', 'coc-bom-1908', 'Helaman', 3, 108, 'And he was brought to prove that he himself was the very murderer, insomuch that the five were set at liberty and also was Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-112', 'coc-bom-1908', 'Helaman', 3, 112, 'And it came to pass that there arose a division among the people, insomuch that they divided hither and thither and went their ways, leaving Nephi alone as he was standing in the midst of them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-113', 'coc-bom-1908', 'Helaman', 3, 113, 'And it came to pass that Nephi went his way towards his own house, pondering upon the things which the Lord had shown unto him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-114', 'coc-bom-1908', 'Helaman', 3, 114, 'And it came to pass as he was thus pondering--being much cast down because of the wickedness of the people of the Nephites, their secret works of darkness, and their murderings, and their plunderings, and all manner of iniquities--and it came to pass as he was thus pondering in his heart, behold, a voice came unto him, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-116', 'coc-bom-1908', 'Helaman', 3, 116, 'And thou hast not feared them, and hast not sought thine own life, but have sought my will and to keep my commandments.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-118', 'coc-bom-1908', 'Helaman', 3, 118, 'Behold, thou art Nephi, and I am God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-119', 'coc-bom-1908', 'Helaman', 3, 119, 'Behold, I declare it unto thee in the presence of mine angels that ye shall have power over this people and shall smite the earth with famine, and with pestilence, and destruction, according to the wickedness of this people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-121', 'coc-bom-1908', 'Helaman', 3, 121, 'And thus, if ye shall say unto this temple, It shall be rent in twain, it shall be done.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-122', 'coc-bom-1908', 'Helaman', 3, 122, 'And if ye shall say unto this mountain, Be thou cast down and become smooth, it shall be done.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-123', 'coc-bom-1908', 'Helaman', 3, 123, 'And behold, if ye shall say, God shall smite this people, it shall come to pass.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-124', 'coc-bom-1908', 'Helaman', 3, 124, 'And now, behold, I command you that ye shall go and declare unto this people that, Thus saith the Lord God, who is Almighty, except ye repent, ye shall be smitten, even unto destruction.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-125', 'coc-bom-1908', 'Helaman', 3, 125, 'And behold, now it came to pass that when the Lord had spoken these words unto Nephi, he did stop, and did not go unto his own house, but did return unto the multitudes who were scattered about upon the face of the land, and began to declare unto them the word of the Lord, which had been spoken unto him concerning their destruction if they did not repent.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-127', 'coc-bom-1908', 'Helaman', 3, 127, 'Therefore, Nephi did declare unto them the word of the Lord, saying, Except ye repent, thus saith the Lord, Ye shall be smitten, even unto destruction.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-130', 'coc-bom-1908', 'Helaman', 3, 130, 'And it came to pass that thus he did go forth in the Spirit, from multitude to multitude, declaring the word of God, even until he had declared it unto them all, or sent it forth among all the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-3-132', 'coc-bom-1908', 'Helaman', 3, 132, 'And thus ended the seventy and first year of the reign of the judges over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-1', 'coc-bom-1908', 'Helaman', 4, 1, 'And now, it came to pass in the seventy and second year of the reign of the judges, that the contentions did increase, insomuch that there were wars throughout all the land among all the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-2', 'coc-bom-1908', 'Helaman', 4, 2, 'And it was this secret band of robbers who did carry on this work of destruction and wickedness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-3', 'coc-bom-1908', 'Helaman', 4, 3, 'And this war did last all that year. And in the seventy and third year it did also last.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-5', 'coc-bom-1908', 'Helaman', 4, 5, 'And so it was done according to the words of Nephi. And there was a great famine upon the land among all the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-6', 'coc-bom-1908', 'Helaman', 4, 6, 'And thus, in the seventy and fourth year, the famine did continue. And the work of destruction did cease by the sword but became sore by famine.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-7', 'coc-bom-1908', 'Helaman', 4, 7, 'And this work of destruction did also continue in the seventy and fifth year.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-11', 'coc-bom-1908', 'Helaman', 4, 11, 'And it came to pass that the judges did say unto Nephi according to the words which had been desired.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-13', 'coc-bom-1908', 'Helaman', 4, 13, 'And they have swept away the band of Gadianton from amongst them, insomuch that they have become extinct, and they have concealed their secret plans in the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-14', 'coc-bom-1908', 'Helaman', 4, 14, 'Now, O Lord, because of this their humility, wilt thou turn away thine anger, and let thine anger be appeased in the destruction of those wicked men whom thou hast already destroyed?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-15', 'coc-bom-1908', 'Helaman', 4, 15, 'O Lord, wilt thou turn away thine anger, yea, thy fierce anger, and cause that this famine may cease in this land?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-16', 'coc-bom-1908', 'Helaman', 4, 16, 'O Lord, wilt thou hearken unto me, and cause that it may be done according to my words, and send forth rain upon the face of the earth, that she may bring forth her fruit and her grain in the season of grain?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-18', 'coc-bom-1908', 'Helaman', 4, 18, 'Yea, O Lord, and thou seest that they have repented because of the famine, and the pestilence, and destruction which have come unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-19', 'coc-bom-1908', 'Helaman', 4, 19, 'And now, O Lord, wilt thou turn away thine anger and try again if they will serve thee? And if so, O Lord, thou canst bless them according to thy words which thou hast said.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-20', 'coc-bom-1908', 'Helaman', 4, 20, 'And it came to pass that in the seventy and sixth year, the Lord did turn away his anger from the people and caused that rain should fall upon the earth, insomuch that it did bring forth her fruit in the season of her fruit.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-21', 'coc-bom-1908', 'Helaman', 4, 21, 'And it came to pass that it did bring forth her grain in the season of her grain.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-23', 'coc-bom-1908', 'Helaman', 4, 23, 'And behold, Lehi, his brother, was not a whit behind him as to things pertaining to righteousness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-24', 'coc-bom-1908', 'Helaman', 4, 24, 'And thus it did come to pass that the people of Nephi began to prosper again in the land, and began to build up their waste places, and began to multiply and spread, even until they did cover the whole face of the land, both on the northward and on the southward, from the sea west to the sea east.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-25', 'coc-bom-1908', 'Helaman', 4, 25, 'And it came to pass that the seventy and sixth year did end in peace.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-27', 'coc-bom-1908', 'Helaman', 4, 27, 'And also they had peace in the seventy and eighth year, save it were a few contentions concerning the points of doctrine which had been laid down by the prophets.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-28', 'coc-bom-1908', 'Helaman', 4, 28, 'And in the seventy and ninth year there began to be much strife.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-29', 'coc-bom-1908', 'Helaman', 4, 29, 'But it came to pass that Nephi, and Lehi, and many of their brethren who knew concerning the true points of doctrine--having many revelations daily--therefore, they did preach unto the people, insomuch that they did put an end to their strife in that same year.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-30', 'coc-bom-1908', 'Helaman', 4, 30, 'And it came to pass that in the eightieth year of the reign of the judges over the people of Nephi, there were a certain number of the dissenters from the people of Nephi, who had some years before gone over unto the Lamanites and took upon themselves the name of Lamanites,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-34', 'coc-bom-1908', 'Helaman', 4, 34, 'Now behold, these robbers did make great havoc, yea, even great destruction among the people of Nephi and also among the people of the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-36', 'coc-bom-1908', 'Helaman', 4, 36, 'But behold, it came to pass that in that same year they were driven back, even into their own lands.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-37', 'coc-bom-1908', 'Helaman', 4, 37, 'And thus ended the eightieth year of the reign of the judges over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-41', 'coc-bom-1908', 'Helaman', 4, 41, 'Yea, for they did visit many parts of the land and did do great destruction unto them--yea, did kill many and did carry away others captive into the wilderness, yea, and more especially their women and their children.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-42', 'coc-bom-1908', 'Helaman', 4, 42, 'Now this great evil, which came unto the people because of their iniquity, did stir them up again in remembrance of the Lord, their God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-43', 'coc-bom-1908', 'Helaman', 4, 43, 'And thus ended the eighty and first year of the reign of the judges.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-44', 'coc-bom-1908', 'Helaman', 4, 44, 'And in the eighty and second year they began again to forget the Lord, their God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-45', 'coc-bom-1908', 'Helaman', 4, 45, 'And in the eighty and third year they began to wax strong in iniquity.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-46', 'coc-bom-1908', 'Helaman', 4, 46, 'And in the eighty and fourth year they did not mend their ways.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-51', 'coc-bom-1908', 'Helaman', 4, 51, 'Yea, then is the time that they do harden their hearts, and do forget the Lord, their God, and do trample under their feet the Holy One, yea, and this because of their ease and their exceeding great prosperity.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-52', 'coc-bom-1908', 'Helaman', 4, 52, 'And thus we see that except the Lord doth chasten his people with many afflictions, yea, except he doth visit them with death, and with terror, and with famine, and with all manner of pestilences, they will not remember him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-53', 'coc-bom-1908', 'Helaman', 4, 53, 'Oh, how foolish, and how vain, and how evil, and devilish, and how quick to do iniquity, and how slow to do good are the children of men--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-54', 'coc-bom-1908', 'Helaman', 4, 54, 'Yea, how quick to hearken unto the words of the evil one, and to set their hearts upon the vain things of the world, yea, how quick to be lifted up in pride, yea, how quick to boast and do all manner of that which is iniquity,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-55', 'coc-bom-1908', 'Helaman', 4, 55, 'And how slow are they to remember the Lord, their God, and to give ear unto his counsels, yea, how slow to walk in wisdom''s paths!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-63', 'coc-bom-1908', 'Helaman', 4, 63, 'And behold, also, if he say unto the waters of the great deep, Be thou dried up, it is done.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-64', 'coc-bom-1908', 'Helaman', 4, 64, 'Behold, if he say unto this mountain, Be thou raised up and come over and fall upon that city, that it be buried up, behold, it is done.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-66', 'coc-bom-1908', 'Helaman', 4, 66, 'And if the Lord shall say, Be thou accursed, that no man shall find thee from this time henceforth and forever, behold, no man getteth it henceforth and forever.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-67', 'coc-bom-1908', 'Helaman', 4, 67, 'And behold, if the Lord shall say unto a man, Because of thine iniquities thou shalt be accursed forever, it shall be done.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-68', 'coc-bom-1908', 'Helaman', 4, 68, 'And if the Lord shall say, Because of thine iniquities thou shalt be cut off from my presence, he will cause that it shall be so.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-71', 'coc-bom-1908', 'Helaman', 4, 71, 'And may God grant, in his great fullness, that men might be brought unto repentance and good works, that they might be restored unto grace, for grace according to their works.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-4-72', 'coc-bom-1908', 'Helaman', 4, 72, 'And I would that all men might be saved. But we read that in that great and last day there are some who shall be cast out, yea, who shall be cast off from the presence of the Lord,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-1', 'coc-bom-1908', 'Helaman', 5, 1, 'And now, it came to pass in the eighty and sixth year, the Nephites did still remain in wickedness, yea, in great wickedness, while the Lamanites did observe strictly to keep the commandments of God according to the law of Moses.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-2', 'coc-bom-1908', 'Helaman', 5, 2, 'And it came to pass that in this year, there was one Samuel, a Lamanite, came into the land of Zarahemla and began to preach unto the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-4', 'coc-bom-1908', 'Helaman', 5, 4, 'But behold, the voice of the Lord came unto him, that he should return again and prophesy unto the people whatsoever things should come into his heart.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-8', 'coc-bom-1908', 'Helaman', 5, 8, 'And behold, an angel of the Lord hath declared it unto me, and he did bring glad tidings to my soul.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-16', 'coc-bom-1908', 'Helaman', 5, 16, 'Yea, wo unto this great city, for I perceive, saith the Lord, that there are many, yea, even the more part of this great city, that will harden their hearts against me, saith the Lord. But blessed are they who will repent, for them will I spare.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-17', 'coc-bom-1908', 'Helaman', 5, 17, 'But behold, if it were not for the righteous who are in this great city, behold, I would cause that fire should come down out of heaven and destroy it. But behold, it is for the righteous'' sake that it is spared.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-18', 'coc-bom-1908', 'Helaman', 5, 18, 'But behold, the time cometh, saith the Lord, that when ye shall cast out the righteous from among you, then shall ye be ripe for destruction.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-22', 'coc-bom-1908', 'Helaman', 5, 22, 'And behold, a curse shall come upon the land, saith the Lord of hosts, because of the people''s sake who are upon the land, yea, because of their wickedness and their abominations.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-23', 'coc-bom-1908', 'Helaman', 5, 23, 'And it shall come to pass, saith the Lord of hosts, yea, our great and true God, that whoso shall hide up treasures in the earth shall find them again no more because of the great curse of the land--save he be a righteous man and shall hide it up unto the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-25', 'coc-bom-1908', 'Helaman', 5, 25, 'And he that hideth not up his treasures unto me, cursed is he and also the treasure, and none shall redeem it because of the curse of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-29', 'coc-bom-1908', 'Helaman', 5, 29, 'And also are your riches cursed because ye have set your hearts upon them and have not hearkened unto the words of him who gave them unto you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-33', 'coc-bom-1908', 'Helaman', 5, 33, 'Yea, wo unto this people because of this time which has arrived, that ye do cast out the prophets, and do mock them, and cast stones at them, and do slay them, and do all manner of iniquity unto them, even as they did of old time.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-36', 'coc-bom-1908', 'Helaman', 5, 36, 'Yea, you will say that he is a false prophet and that he is a sinner and of the devil because he testifieth that your deeds are evil.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-39', 'coc-bom-1908', 'Helaman', 5, 39, 'And because he speaketh flattering words unto you and he saith that all is well, then ye will not find fault with him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-40', 'coc-bom-1908', 'Helaman', 5, 40, 'O ye wicked and ye perverse generation, ye hardened and ye stiff-necked people! How long will ye suppose that the Lord will suffer you? Yea, how long will ye suffer yourselves to be led by foolish and blind guides? Yea, how long will ye choose darkness rather than light?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-43', 'coc-bom-1908', 'Helaman', 5, 43, 'And then shall ye weep and howl in that day, saith the Lord of hosts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-47', 'coc-bom-1908', 'Helaman', 5, 47, 'Yea, we have hid up our treasures, and they have slipped away from us because of the curse of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-49', 'coc-bom-1908', 'Helaman', 5, 49, 'Behold, we are surrounded by demons, yea, we are encircled about by the angels of him who hath sought to destroy our souls.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-50', 'coc-bom-1908', 'Helaman', 5, 50, 'Behold, our iniquities are great. O Lord, canst thou not turn away thine anger from us? And this shall be your language in those days.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-53', 'coc-bom-1908', 'Helaman', 5, 53, 'O ye people of the land, that ye would hear my words. And I pray that the anger of the Lord be turned away from you, and that ye would repent and be saved.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-54', 'coc-bom-1908', 'Helaman', 5, 54, 'And now, it came to pass that Samuel, the Lamanite, did prophesy a great many more things which cannot be written.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-55', 'coc-bom-1908', 'Helaman', 5, 55, 'And behold, he said unto them, Behold, I give unto you a sign: For five years more cometh, and behold, then cometh the Son of God to redeem all those who shall believe on his name.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-61', 'coc-bom-1908', 'Helaman', 5, 61, 'And it shall come to pass that ye shall all be amazed and wonder, insomuch that ye shall fall to the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-62', 'coc-bom-1908', 'Helaman', 5, 62, 'And it shall come to pass that whosoever shall believe on the Son of God, the same shall have everlasting life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-64', 'coc-bom-1908', 'Helaman', 5, 64, 'And now, because I am a Lamanite and have spoken unto you the words which the Lord hath commanded me, and because it was hard against you, ye are angry with me, and do seek to destroy me, and have cast me out from among you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-67', 'coc-bom-1908', 'Helaman', 5, 67, 'And if ye believe on his name, ye will repent of all your sins, that thereby ye may have a remission of them through his merits.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-70', 'coc-bom-1908', 'Helaman', 5, 70, 'Yea, behold, this death bringeth to pass the resurrection and redeemeth all mankind from the first death--that spiritual death for all mankind, by the fall of Adam, being cut off from the presence of the Lord, or considered as dead, both as to things temporal and to things spiritual.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-72', 'coc-bom-1908', 'Helaman', 5, 72, 'Yea, and it bringeth to pass the conditions of repentance, that whosoever repenteth, the same is not hewn down and cast into the fire.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-74', 'coc-bom-1908', 'Helaman', 5, 74, 'Therefore, repent ye, repent ye, lest by knowing these things and not doing them, ye shall suffer yourselves to come under condemnation, and ye are brought down unto this second death.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-76', 'coc-bom-1908', 'Helaman', 5, 76, 'And there shall be no light upon the face of this land, even from the time that he shall suffer death, for the space of three days, to the time that he shall rise again from the dead.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-78', 'coc-bom-1908', 'Helaman', 5, 78, 'Yea, they shall be rent in twain, and shall ever after be found in seams, and in cracks, and in broken fragments upon the face of the whole earth, yea, both above the earth and beneath.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-82', 'coc-bom-1908', 'Helaman', 5, 82, 'And he said unto me that while the thunder and the lightning last and the tempest, that these things should be, and that darkness should cover the face of the whole earth for the space of three days.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-83', 'coc-bom-1908', 'Helaman', 5, 83, 'And the angel said unto me that many shall see greater things than these, to the intent that they might believe that these signs and these wonders should come to pass upon all the face of this land, to the intent that there should be no cause for unbelief among the children of men--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-91', 'coc-bom-1908', 'Helaman', 5, 91, 'But behold, my brethren, the Lamanites, hath he hated because their deeds have been evil continually--and this because of the iniquity of the tradition of their fathers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-95', 'coc-bom-1908', 'Helaman', 5, 95, 'And behold, ye do know of yourselves, for ye have witnessed it, that as many of them as are brought to the knowledge of the truth, and to know of the wicked and abominable traditions of their fathers, and are led to believe the holy scriptures--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-96', 'coc-bom-1908', 'Helaman', 5, 96, 'Yea, the prophecies of the holy prophets, which are written, which leadeth them to faith on the Lord and unto repentance, which faith and repentance bringeth a change of heart unto them--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-97', 'coc-bom-1908', 'Helaman', 5, 97, 'Therefore, as many as have come to this, ye know of yourselves, are firm and steadfast in the faith and in the things wherewith they have been made free.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-99', 'coc-bom-1908', 'Helaman', 5, 99, 'For behold, they will suffer themselves that they be trodden down and slain by their enemies and will not lift their swords against them, and this because of their faith in Christ.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-101', 'coc-bom-1908', 'Helaman', 5, 101, 'Yea, even if they should dwindle in unbelief, the Lord shall prolong their days until the time shall come which hath been spoken of by our fathers, and also by the prophet Zenos, and many other prophets concerning the restoration of our brethren, the Lamanites, again to the knowledge of the truth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-104', 'coc-bom-1908', 'Helaman', 5, 104, 'And this is according to the prophecy that they shall again be brought to the true knowledge--which is the knowledge of their Redeemer, and their great and true Shepherd--and be numbered among his sheep.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-105', 'coc-bom-1908', 'Helaman', 5, 105, 'Therefore, I say unto you, It shall be better for them than for you, except ye repent.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-107', 'coc-bom-1908', 'Helaman', 5, 107, 'Therefore, saith the Lord, I will not utterly destroy them, but I will cause that in the day of my wisdom they shall return again unto me, saith the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-109', 'coc-bom-1908', 'Helaman', 5, 109, 'And now, it came to pass that there were many who heard the words of Samuel, the Lamanite, which he spake upon the walls of the city.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-112', 'coc-bom-1908', 'Helaman', 5, 112, 'But the Spirit of the Lord was with him, insomuch that they could not hit him with their stones, neither with their arrows.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-113', 'coc-bom-1908', 'Helaman', 5, 113, 'Now when they saw that they could not hit him, there were many more who did believe on his words, insomuch that they went away unto Nephi to be baptized.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-114', 'coc-bom-1908', 'Helaman', 5, 114, 'For behold, Nephi was baptizing, and prophesying, and preaching, crying repentance unto the people, showing signs and wonders, working miracles among the people, that they might know that the Christ must shortly come,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-115', 'coc-bom-1908', 'Helaman', 5, 115, 'Telling them of things which must shortly come, that they might know and remember at the time of their coming that they had been made known unto them beforehand, to the intent that they might believe.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-116', 'coc-bom-1908', 'Helaman', 5, 116, 'Therefore, as many as believed on the words of Samuel went forth unto him to be baptized, for they came repenting and confessing their sins.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-119', 'coc-bom-1908', 'Helaman', 5, 119, 'And as they went forth to lay their hands on him, behold, he did cast himself down from the wall, and did flee out of their lands, yea, even unto his own country, and began to preach and to prophesy among his own people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-121', 'coc-bom-1908', 'Helaman', 5, 121, 'And thus ended the eighty and sixth year of the reign of the judges over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-122', 'coc-bom-1908', 'Helaman', 5, 122, 'And thus ended, also, the eighty and seventh year of the reign of the judges, the more part of the people remaining in their pride and wickedness, and the lesser part walking more circumspectly before God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-123', 'coc-bom-1908', 'Helaman', 5, 123, 'And these were the conditions, also, in the eighty and eighth year of the reign of the judges.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-124', 'coc-bom-1908', 'Helaman', 5, 124, 'And there was but little alteration in the affairs of the people, save it were the people began to be more hardened in iniquity and do more and more of that which was contrary to the commandments of God, in the eighty and ninth year of the reign of the judges.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-127', 'coc-bom-1908', 'Helaman', 5, 127, 'Nevertheless, the people began to harden their hearts, all save it were the most believing part of them, both of the Nephites and also of the Lamanites, and began to depend upon their own strength and upon their own wisdom, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-129', 'coc-bom-1908', 'Helaman', 5, 129, 'And they began to reason and to contend among themselves, saying that it is not reasonable that such a being as a Christ shall come.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-130', 'coc-bom-1908', 'Helaman', 5, 130, 'If so, and he be the Son of God, the Father of heaven and of earth, as it has been spoken, why will he not show himself unto us as well as unto them who shall be at Jerusalem?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-131', 'coc-bom-1908', 'Helaman', 5, 131, 'Yea, why will he not show himself in this land as well as in the land at Jerusalem?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-133', 'coc-bom-1908', 'Helaman', 5, 133, 'Therefore, they can keep us in ignorance, for we cannot witness with our own eyes that they are true.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-135', 'coc-bom-1908', 'Helaman', 5, 135, 'And thus will they keep us in ignorance if we will yield ourselves unto them all the days of our lives.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-138', 'coc-bom-1908', 'Helaman', 5, 138, 'And notwithstanding the signs and the wonders which were wrought among the people of the Lord and the many miracles which they did, Satan did get great hold upon the hearts of the people upon all the face of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-139', 'coc-bom-1908', 'Helaman', 5, 139, 'And thus ended the ninetieth year of the reign of the judges over the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:helaman-5-140', 'coc-bom-1908', 'Helaman', 5, 140, 'And thus ended the book of Helaman, according to the record of Helaman and his sons.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-1', 'coc-bom-1908', 'Ether', 1, 1, 'And now, I, Moroni, proceed to give an account of those ancient inhabitants who were destroyed by the hand of the Lord upon the face of this north country.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-2', 'coc-bom-1908', 'Ether', 1, 2, 'And I take mine account from the twenty and four plates which were found by the people of Limhi, which is called the book of Ether.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-3', 'coc-bom-1908', 'Ether', 1, 3, 'And as I suppose that the first part of this record, which speaks concerning the creation of the world, and also of Adam, and an account from that time even to the great tower, and whatsoever things transpired among the children of men until that time, is had among the Jews,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-8', 'coc-bom-1908', 'Ether', 1, 8, 'And the Brother of Jared, being a large and a mighty man and being a man highly favored of the Lord--for Jared, his brother, said unto him, Cry unto the Lord that he will not confound us, that we may not understand our words.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-10', 'coc-bom-1908', 'Ether', 1, 10, 'Then Jared said unto his brother, Cry again unto the Lord, and it may be that he will turn away his anger from them who are our friends, that he confound not their language.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-13', 'coc-bom-1908', 'Ether', 1, 13, 'And who knoweth but the Lord will carry us forth into a land which is choice above all the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-14', 'coc-bom-1908', 'Ether', 1, 14, 'And if it so be, let us be faithful unto the Lord, that we may receive it for our inheritance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-15', 'coc-bom-1908', 'Ether', 1, 15, 'And it came to pass that the Brother of Jared did cry unto the Lord according to that which had been spoken by the mouth of Jared.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-17', 'coc-bom-1908', 'Ether', 1, 17, 'And when thou hast done this, thou shalt go at the head of them down into the valley which is northward.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-18', 'coc-bom-1908', 'Ether', 1, 18, 'And there will I meet thee, and I will go before thee into a land which is choice above all the land of the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-19', 'coc-bom-1908', 'Ether', 1, 19, 'And there will I bless thee and thy seed and raise up unto me of thy seed, and of the seed of thy brother, and they who shall go with thee, a great nation.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-20', 'coc-bom-1908', 'Ether', 1, 20, 'And there shall be none greater than the nation which I will raise up unto me of thy seed upon all the face of the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-21', 'coc-bom-1908', 'Ether', 1, 21, 'And this I will do unto thee because this long time ye have cried unto me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-22', 'coc-bom-1908', 'Ether', 1, 22, 'And it came to pass that Jared, and his brother, and their families, and also the friends of Jared and his brother, and their families went down into the valley which was northward (and the name of the valley was Nimrod, being called after the mighty hunter) with their flocks which they had gathered together, male and female of every kind.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-26', 'coc-bom-1908', 'Ether', 1, 26, 'And it came to pass that the Lord commanded them that they should go forth into the wilderness, yea, into that quarter where there never had man been.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-27', 'coc-bom-1908', 'Ether', 1, 27, 'And it came to pass that the Lord did go before them, and did talk with them as he stood in a cloud, and gave directions whither they should travel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-28', 'coc-bom-1908', 'Ether', 1, 28, 'And it came to pass that they did travel in the wilderness and did build barges in which they did cross many waters, being directed continually by the hand of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-30', 'coc-bom-1908', 'Ether', 1, 30, 'And he had sworn in his wrath unto the Brother of Jared that whoso should possess this land of promise, from that time henceforth and forever, should serve him, the true and only God, or they should be swept off when the fullness of his wrath should come upon them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-33', 'coc-bom-1908', 'Ether', 1, 33, 'And it is not until the fullness of iniquity among the children of the land, that they are swept off.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-34', 'coc-bom-1908', 'Ether', 1, 34, 'And this cometh unto you, O ye Gentiles, that ye may know the decrees of God, that ye may repent and not continue in your iniquities until the fullness come, that ye may not bring down the fullness of the wrath of God upon you as the inhabitants of the land have hitherto done.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-38', 'coc-bom-1908', 'Ether', 1, 38, 'And it came to pass at the end of four years that the Lord came again unto the Brother of Jared, and stood in a cloud, and talked with him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-39', 'coc-bom-1908', 'Ether', 1, 39, 'And for the space of three hours did the Lord talk with the Brother of Jared and chastened him because he remembered not to call upon the name of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-40', 'coc-bom-1908', 'Ether', 1, 40, 'And the Brother of Jared repented of the evil which he had done and did call upon the name of the Lord for his brethren who were with him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-43', 'coc-bom-1908', 'Ether', 1, 43, 'And the Lord said, Go to work, and build after the manner of barges which ye have hitherto built.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-44', 'coc-bom-1908', 'Ether', 1, 44, 'And it came to pass that the Brother of Jared did go to work, and also his brethren, and built barges after the manner which they had built according to the instructions of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-47', 'coc-bom-1908', 'Ether', 1, 47, 'And it came to pass that the Brother of Jared cried unto the Lord, saying, O Lord, I have performed the work which thou hast commanded me, and I have made the barges according as thou hast directed me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-48', 'coc-bom-1908', 'Ether', 1, 48, 'And behold, O Lord, in them there is no light. Whither shall we steer?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-51', 'coc-bom-1908', 'Ether', 1, 51, 'And if it so be that the water come in upon thee, behold, ye shall stop the hole thereof, that ye may not perish in the flood.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-52', 'coc-bom-1908', 'Ether', 1, 52, 'And it came to pass that the Brother of Jared did so according as the Lord had commanded.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-54', 'coc-bom-1908', 'Ether', 1, 54, 'Behold, O Lord, wilt thou suffer that we shall cross this great water in darkness?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-55', 'coc-bom-1908', 'Ether', 1, 55, 'And the Lord said unto the Brother of Jared, What will ye that I should do that ye may have light in your vessels?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-59', 'coc-bom-1908', 'Ether', 1, 59, 'Therefore, what will ye that I should prepare for you, that ye may have light when ye are swallowed up in the depths of the sea?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-61', 'coc-bom-1908', 'Ether', 1, 61, 'And they were white and clear, even as transparent glass, and he did carry them in his hands upon the top of the mount and cried again unto the Lord, saying, O Lord, thou hast said that we must be encompassed about by the floods.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-65', 'coc-bom-1908', 'Ether', 1, 65, 'O Lord, look upon me in pity, and turn away thine anger from this thy people, and suffer not that they shall go forth across this raging deep in darkness, but behold these things which I have molten out of the rock.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-67', 'coc-bom-1908', 'Ether', 1, 67, 'Behold, O Lord, thou canst do this. We know that thou art able to show forth great power, which looks small unto the understanding of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-73', 'coc-bom-1908', 'Ether', 1, 73, 'And he answered, Nay, Lord. Show thyself unto me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-74', 'coc-bom-1908', 'Ether', 1, 74, 'And the Lord said unto him, Believest thou the words which I shall speak?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-75', 'coc-bom-1908', 'Ether', 1, 75, 'And he answered, Yea, Lord, I know that thou speakest the truth, for thou art a God of truth and canst not lie.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-77', 'coc-bom-1908', 'Ether', 1, 77, 'Behold, I am he who was prepared from the foundation of the world to redeem my people. Behold, I am Jesus Christ. I am the Father and the Son.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-79', 'coc-bom-1908', 'Ether', 1, 79, 'And never have I showed myself unto man whom I have created, for never has man believed in me as thou hast.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-80', 'coc-bom-1908', 'Ether', 1, 80, 'Seest thou that ye are created after mine own image? Yea, even all men were created in the beginning after mine own image.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-83', 'coc-bom-1908', 'Ether', 1, 83, 'And he ministered unto him, even as he ministered unto the Nephites--and all this, that this man knew that he was God because of the many great works which the Lord had showed unto him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-88', 'coc-bom-1908', 'Ether', 1, 88, 'And behold, these two stones will I give unto thee, and ye shall seal them up also with the things which ye shall write.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-92', 'coc-bom-1908', 'Ether', 1, 92, 'And the Lord said unto him, Write these things and seal them up, and I will show them in mine own due time unto the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-93', 'coc-bom-1908', 'Ether', 1, 93, 'And it came to pass that the Lord commanded him that he should seal up the two stones which he had received and show them not until the Lord should show them unto the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-95', 'coc-bom-1908', 'Ether', 1, 95, 'And for this cause did King Benjamin* keep them, that they should not come unto the world until after Christ should show himself unto his people. *["Mosiah" is used in some editions of the Book of Mormon.]', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-96', 'coc-bom-1908', 'Ether', 1, 96, 'And after Christ truly had showed himself unto his people, he commanded that they should be made manifest.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-97', 'coc-bom-1908', 'Ether', 1, 97, 'And now, after that they have all dwindled in unbelief, and there is none save it be the Lamanites, and they have rejected the gospel of Christ, therefore, I am commanded that I should hide them up again in the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-101', 'coc-bom-1908', 'Ether', 1, 101, 'And in that day that they shall exercise faith in me, saith the Lord, even as the Brother of Jared did, that they may become sanctified in me, then will I manifest unto them the things which the Brother of Jared saw, even to the unfolding unto them all my revelations, saith Jesus Christ, the Son of God, the Father of the heavens, and of the earth, and all things that in them are.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-109', 'coc-bom-1908', 'Ether', 1, 109, 'Come unto me, O ye Gentiles, and I will show unto you the greater things, the knowledge which is hid up because of unbelief.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-111', 'coc-bom-1908', 'Ether', 1, 111, 'Behold, when ye shall rend that veil of unbelief which doth cause you to remain in your awful state of wickedness, and hardness of heart, and blindness of mind, then shall the great and marvelous things which have been hid up from the foundation of the world from you--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-113', 'coc-bom-1908', 'Ether', 1, 113, 'And then shall my revelations which I have caused to be written by my servant John be unfolded in the eyes of all the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-116', 'coc-bom-1908', 'Ether', 1, 116, 'And blessed is he that is found faithful unto my name at the last day, for he shall be lifted up to dwell in the kingdom prepared for him from the foundation of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-1-117', 'coc-bom-1908', 'Ether', 1, 117, 'And behold, it is I that hath spoken it. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-2-3', 'coc-bom-1908', 'Ether', 2, 3, 'And in the mouth of three witnesses shall these things be established--and the testimony of three and this work, in the which shall be shown forth the power of God and also his word, of which the Father, and the Son, and the Holy Ghost bear record--and all this shall stand as a testimony against the world at the last day.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-2-4', 'coc-bom-1908', 'Ether', 2, 4, 'And if it so be that they repent and come unto the Father in the name of Jesus, they shall be received into the kingdom of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-1', 'coc-bom-1908', 'Ether', 3, 1, 'And now, I, Moroni, proceed to give the record of Jared and his brother:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-3', 'coc-bom-1908', 'Ether', 3, 3, 'And thus the Lord caused stones to shine in darkness to give light unto men, women, and children, that they might not cross the great waters in darkness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-4', 'coc-bom-1908', 'Ether', 3, 4, 'And it came to pass that they prepared all manner of food, that thereby they might subsist upon the water, and also food for their flocks and herds, and whatsoever beast, or animal, or fowl that they should carry with them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-5', 'coc-bom-1908', 'Ether', 3, 5, 'And it came to pass that when they had done all these things, they got aboard their vessels, or barges, and set forth into the sea, commending themselves unto the Lord, their God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-7', 'coc-bom-1908', 'Ether', 3, 7, 'And it came to pass that they were many times buried in the depths of the sea because of the mountain waves which broke upon them, and also the great and terrible tempests which were caused by the fierceness of the wind.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-14', 'coc-bom-1908', 'Ether', 3, 14, 'And when they had set their feet upon the shores of the promised land, they bowed themselves down upon the face of the land, and did humble themselves before the Lord, and did shed tears of joy before the Lord because of the multitude of his tender mercies over them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-15', 'coc-bom-1908', 'Ether', 3, 15, 'And it came to pass that they went forth upon the face of the land and began to till the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-17', 'coc-bom-1908', 'Ether', 3, 17, 'And the Brother of Jared also begat sons and daughters.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-22', 'coc-bom-1908', 'Ether', 3, 22, 'And accordingly the people were gathered together.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-25', 'coc-bom-1908', 'Ether', 3, 25, 'And it came to pass that the people desired of them that they should anoint one of their sons to be a king over them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-26', 'coc-bom-1908', 'Ether', 3, 26, 'And now, behold, this was grievous unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-27', 'coc-bom-1908', 'Ether', 3, 27, 'But the Brother of Jared said unto them, Surely, this thing leadeth into captivity.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-28', 'coc-bom-1908', 'Ether', 3, 28, 'But Jared said unto his brother, Suffer them that they may have a king. And therefore, he said unto them, Choose ye out from among our sons a king, even whom ye will.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-30', 'coc-bom-1908', 'Ether', 3, 30, 'And it came to pass that he refused and would not be their king.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-32', 'coc-bom-1908', 'Ether', 3, 32, 'And it came to pass that they chose all the brothers of Pagag, and they would not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-35', 'coc-bom-1908', 'Ether', 3, 35, 'And it came to pass that Jared died and his brother also.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-36', 'coc-bom-1908', 'Ether', 3, 36, 'And it came to pass that Orihah did walk humbly before the Lord, and did remember how great things the Lord had done for his father, and also taught his people how great things the Lord had done for their fathers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-37', 'coc-bom-1908', 'Ether', 3, 37, 'And it came to pass that Orihah did execute judgment upon the land in righteousness all his days, whose days were exceeding many.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-38', 'coc-bom-1908', 'Ether', 3, 38, 'And he begat sons and daughters, yea, he begat thirty and one, among whom were twenty and three sons.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-39', 'coc-bom-1908', 'Ether', 3, 39, 'And it came to pass that he also begat Kib in his old age.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-42', 'coc-bom-1908', 'Ether', 3, 42, 'And when he had gathered together an army, he came up unto the land of Moron, where the king dwelt, and took him captive, which brought to pass the saying of the Brother of Jared that they would be brought into captivity.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-43', 'coc-bom-1908', 'Ether', 3, 43, 'Now the land of Moron, where the king dwelt, was near the land which is called Desolation by the Nephites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-49', 'coc-bom-1908', 'Ether', 3, 49, 'And it came to pass that Shule also begat many sons and daughters.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-51', 'coc-bom-1908', 'Ether', 3, 51, 'And it came to pass that Corihor had many sons and daughters.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-52', 'coc-bom-1908', 'Ether', 3, 52, 'And among the sons of Corihor there was one whose name was Noah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-53', 'coc-bom-1908', 'Ether', 3, 53, 'And it came to pass that Noah rebelled against Shule, the king, and also his father Corihor, and drew away Cohor, his brother, and also all his brethren, and many of the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-59', 'coc-bom-1908', 'Ether', 3, 59, 'And Cohor, the son of Noah, caused that his people should give battle unto Shule, in which Shule did beat them and did slay Cohor.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-61', 'coc-bom-1908', 'Ether', 3, 61, 'And also in the reign of Shule there came prophets among the people, who were sent from the Lord, prophesying that the wickedness and idolatry of the people was bringing a curse upon the land and they should be destroyed if they did not repent.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-62', 'coc-bom-1908', 'Ether', 3, 62, 'And it came to pass that the people did revile against the prophets and did mock them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-65', 'coc-bom-1908', 'Ether', 3, 65, 'And it came to pass that Shule begat sons and daughters in his old age.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-67', 'coc-bom-1908', 'Ether', 3, 67, 'And it came to pass that he begat Omer, and Omer reigned in his stead.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-69', 'coc-bom-1908', 'Ether', 3, 69, 'And Jared rebelled against his father and came and dwelt in the land of Heth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-70', 'coc-bom-1908', 'Ether', 3, 70, 'And it came to pass that he did flatter many people because of his cunning words until he had gained the half of the kingdom.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-72', 'coc-bom-1908', 'Ether', 3, 72, 'And now, in the days of the reign of Omer, he was in captivity the half of his days.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-74', 'coc-bom-1908', 'Ether', 3, 74, 'And it came to pass that they did give battle unto him by night.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-76', 'coc-bom-1908', 'Ether', 3, 76, 'And it came to pass that they did grant unto him his life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-77', 'coc-bom-1908', 'Ether', 3, 77, 'And now, Jared became exceeding sorrowful because of the loss of the kingdom, for he had set his heart upon the kingdom and upon the glory of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-78', 'coc-bom-1908', 'Ether', 3, 78, 'Now the daughter of Jared, being exceeding expert and seeing the sorrow of her father, thought to devise a plan whereby she could redeem the kingdom unto her father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-79', 'coc-bom-1908', 'Ether', 3, 79, 'Now the daughter of Jared was exceeding fair. And it came to pass that she did talk with her father and said unto him, Whereby hath my father so much sorrow?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-80', 'coc-bom-1908', 'Ether', 3, 80, 'Hath he not read the record which our fathers brought across the great deep?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-81', 'coc-bom-1908', 'Ether', 3, 81, 'Behold, is there not an account concerning them of old, that they by their secret plans did obtain kingdoms and great glory?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-84', 'coc-bom-1908', 'Ether', 3, 84, 'And it came to pass that he said unto Jared, Give her unto me to wife.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-85', 'coc-bom-1908', 'Ether', 3, 85, 'And Jared said unto him, I will give her unto you if ye will bring unto me the head of my father, the king.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-86', 'coc-bom-1908', 'Ether', 3, 86, 'And it came to pass that Akish gathered in unto the house of Jared all his kinsfolks and said unto them, Will ye swear unto me that ye will be faithful unto me in the thing which I shall desire of you?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-88', 'coc-bom-1908', 'Ether', 3, 88, 'And whoso should divulge whatsoever thing Akish made known unto them, the same should lose his life. And it came to pass that thus they did agree with Akish.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-89', 'coc-bom-1908', 'Ether', 3, 89, 'And Akish did administer unto them the oaths which were given by them of old who also sought power, which had been handed down even from Cain, who was a murderer from the beginning.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-90', 'coc-bom-1908', 'Ether', 3, 90, 'And they were kept up by the power of the devil to administer these oaths unto the people, to keep them in darkness, to help such as sought power to gain power, and to murder, and to plunder, and to lie, and to commit all manner of wickedness and whoredoms.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-97', 'coc-bom-1908', 'Ether', 3, 97, 'Yea, even the sword of the justice of the eternal God shall fall upon you, to your overthrow and destruction, if ye shall suffer these things to be.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-99', 'coc-bom-1908', 'Ether', 3, 99, 'For it cometh to pass that whoso buildeth it up seeketh to overthrow the freedom of all lands, nations, and countries.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-101', 'coc-bom-1908', 'Ether', 3, 101, 'Yea, even that same liar who hath caused man to commit murder from the beginning, who hath hardened the hearts of men, that they have murdered the prophets, and stoned them, and cast them out from the beginning.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-3-102', 'coc-bom-1908', 'Ether', 3, 102, 'Wherefore, I, Moroni, am commanded to write these things, that evil may be done away, and that the time may come that Satan may have no power upon the hearts of the children of men, but that they may be persuaded to do good continually, that they may come unto the fountain of all righteousness and be saved.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-1', 'coc-bom-1908', 'Ether', 4, 1, 'And now, I, Moroni, proceed with my record.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-9', 'coc-bom-1908', 'Ether', 4, 9, 'And now, the brother of him that suffered death (and his name was Nimrah) was angry with his father because of that which his father had done unto his brother.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-10', 'coc-bom-1908', 'Ether', 4, 10, 'And it came to pass that Nimrah gathered together a small number of men, and fled out of the land, and came over and dwelt with Omer.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-13', 'coc-bom-1908', 'Ether', 4, 13, 'And there began to be a war between the sons of Akish and Akish, which lasted for the space of many years, yea, unto the destruction of nearly all the people of the kingdom,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-17', 'coc-bom-1908', 'Ether', 4, 17, 'And it came to pass that Emer did reign in his stead and did fill the steps of his father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-19', 'coc-bom-1908', 'Ether', 4, 19, 'And in the space of sixty and two years, they had become exceeding strong, insomuch that they became exceeding rich, having all manner of fruit and of grain, and of silks and of fine linen, and of gold and of silver, and of precious things,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-25', 'coc-bom-1908', 'Ether', 4, 25, 'And it came to pass that Coriantum did walk in the steps of his father, and did build many mighty cities, and did administer that which was good unto his people in all his days.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-26', 'coc-bom-1908', 'Ether', 4, 26, 'And it came to pass that he had no children, even until he was exceeding old.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-27', 'coc-bom-1908', 'Ether', 4, 27, 'And it came to pass that his wife died, being a hundred and two years old.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-34', 'coc-bom-1908', 'Ether', 4, 34, 'And it came to pass that they did all these things according to the commandment of the king Heth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-36', 'coc-bom-1908', 'Ether', 4, 36, 'And it came to pass that their flocks began to flee before the poisonous serpents towards the land southward, which was called by the Nephites, Zarahemla.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-38', 'coc-bom-1908', 'Ether', 4, 38, 'And it came to pass that the Lord did cause the serpents that they should pursue them no more, but that they should hedge up the way, that the people could not pass, that whoso should attempt to pass might fall by the poisonous serpents.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-39', 'coc-bom-1908', 'Ether', 4, 39, 'And it came to pass that the people did follow the course of the beasts and did devour the carcasses of them which fell by the way, until they had devoured them all.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-40', 'coc-bom-1908', 'Ether', 4, 40, 'Now when the people saw that they must perish, they began to repent of their iniquities and cry unto the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-42', 'coc-bom-1908', 'Ether', 4, 42, 'And the Lord did show forth his power unto them in preserving them from famine.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-43', 'coc-bom-1908', 'Ether', 4, 43, 'And it came to pass that Shez--who was a descendant of Heth, for Heth had perished by the famine and all his household, save it were Shez--wherefore, Shez began to build up again a broken people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-46', 'coc-bom-1908', 'Ether', 4, 46, 'And it came to pass that his father did build up many cities upon the face of the land, and the people began again to spread over all the face of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-60', 'coc-bom-1908', 'Ether', 4, 60, 'And it came to pass that Levi did serve in captivity, after the death of his father, for the space of forty and two years.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-61', 'coc-bom-1908', 'Ether', 4, 61, 'And he did make war against the king of the land, by which he did obtain unto himself the kingdom.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-64', 'coc-bom-1908', 'Ether', 4, 64, 'And it came to pass that Kish passed away also, and Lib reigned in his stead.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-65', 'coc-bom-1908', 'Ether', 4, 65, 'And it came to pass that Lib also did that which was good in the sight of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-67', 'coc-bom-1908', 'Ether', 4, 67, 'And Lib also himself became a great hunter.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-68', 'coc-bom-1908', 'Ether', 4, 68, 'And they built a great city by the narrow neck of land, by the place where the sea divides the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-69', 'coc-bom-1908', 'Ether', 4, 69, 'And they did preserve the land southward for a wilderness to get game.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-72', 'coc-bom-1908', 'Ether', 4, 72, 'And they did work all manner of fine work.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-74', 'coc-bom-1908', 'Ether', 4, 74, 'And they did make all manner of tools to till the earth, both to plow and to sow, to reap and to hoe, and also to thrash.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-75', 'coc-bom-1908', 'Ether', 4, 75, 'And they did make all manner of tools with which they did work their beasts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-76', 'coc-bom-1908', 'Ether', 4, 76, 'And they did make all manner of weapons of war.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-77', 'coc-bom-1908', 'Ether', 4, 77, 'And they did work all manner of work of exceeding curious workmanship.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-78', 'coc-bom-1908', 'Ether', 4, 78, 'And never could be a people more blessed than were they, and more prospered by the hand of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-79', 'coc-bom-1908', 'Ether', 4, 79, 'And they were in a land that was choice above all lands, for the Lord had spoken it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-81', 'coc-bom-1908', 'Ether', 4, 81, 'And it came to pass that Hearthom reigned in the stead of his father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-82', 'coc-bom-1908', 'Ether', 4, 82, 'And when Hearthom had reigned twenty and four years, behold, the kingdom was taken away from him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-83', 'coc-bom-1908', 'Ether', 4, 83, 'And he served many years in captivity, yea, even all the remainder of his days.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-84', 'coc-bom-1908', 'Ether', 4, 84, 'And he begat Heth, and Heth lived in captivity all his days.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-86', 'coc-bom-1908', 'Ether', 4, 86, 'And it came to pass that Com drew away the half of the kingdom.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-90', 'coc-bom-1908', 'Ether', 4, 90, 'And there came also in the days of Com many prophets and prophesied of the destruction of that great people, except they should repent, and turn unto the Lord, and forsake their murders and wickedness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-96', 'coc-bom-1908', 'Ether', 4, 96, 'And their bones should become as heaps of earth upon the face of the land, except they should repent of their wickedness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-108', 'coc-bom-1908', 'Ether', 4, 108, 'And it came to pass that Moron did overthrow him and did obtain the kingdom again.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-111', 'coc-bom-1908', 'Ether', 4, 111, 'And it came to pass that Coriantor dwelt in captivity all his days.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-113', 'coc-bom-1908', 'Ether', 4, 113, 'And that the Lord God would send, or bring forth, another people to possess the land, by his power, after the manner which he brought their fathers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-4-114', 'coc-bom-1908', 'Ether', 4, 114, 'And they did reject all the words of the prophets because of their secret society and wicked abominations.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-5-4', 'coc-bom-1908', 'Ether', 5, 4, 'Wherefore, whoso believeth in God might with surety hope for a better world, yea, even a place at the right hand of God, which hope cometh of faith, maketh an anchor to the souls of men, which would make them sure and steadfast, always abounding in good works, being led to glorify God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-5-5', 'coc-bom-1908', 'Ether', 5, 5, 'And it came to pass that Ether did prophesy great and marvelous things unto the people which they did not believe because they saw them not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-5-10', 'coc-bom-1908', 'Ether', 5, 10, 'Wherefore, ye may also have hope and be partakers of the gift if ye will but have faith.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-5-14', 'coc-bom-1908', 'Ether', 5, 14, 'Behold, it was the faith of Alma and Amulek that caused the prison to tumble to the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-5-15', 'coc-bom-1908', 'Ether', 5, 15, 'Behold, it was the faith of Nephi and Lehi that wrought the change upon the Lamanites, that they were baptized with fire and with the Holy Ghost.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-5-19', 'coc-bom-1908', 'Ether', 5, 19, 'And there were many whose faith was so exceeding strong even before Christ came, who could not be kept from within the veil, but truly saw with their eyes the things which they had beheld with an eye of faith, and they were glad.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-5-25', 'coc-bom-1908', 'Ether', 5, 25, 'Behold, thou hast not made us mighty in writing like unto the Brother of Jared, for thou madest him that the things which he wrote were mighty, even as thou art, unto the overpowering of man to read them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-5-33', 'coc-bom-1908', 'Ether', 5, 33, 'And again, I remember that thou hast said that thou hast loved the world, even unto the laying down of thy life for the world, that thou mightest take it again to prepare a place for the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-5-35', 'coc-bom-1908', 'Ether', 5, 35, 'Wherefore, I know by this thing which thou hast said, that if the Gentiles have not charity because of our weakness, that thou wilt prove them and take away their talent, yea, even that which they have received, and give unto them who shall have more abundantly.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-5-36', 'coc-bom-1908', 'Ether', 5, 36, 'And it came to pass that I prayed unto the Lord that he would give unto the Gentiles grace, that they might have charity.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-5-38', 'coc-bom-1908', 'Ether', 5, 38, 'And because thou hast seen thy weakness, thou shalt be made strong, even unto the sitting down in the place which I have prepared in the mansions of my Father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-5-41', 'coc-bom-1908', 'Ether', 5, 41, 'And now, I would commend you to seek this Jesus of whom the prophets and apostles have written, that the grace of God, the Father, and also the Lord Jesus Christ, and the Holy Ghost, which beareth record of them, may be and abide in you forever. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-1', 'coc-bom-1908', 'Ether', 6, 1, 'And now, I, Moroni, proceed to finish my record concerning the destruction of the people of whom I have been writing.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-12', 'coc-bom-1908', 'Ether', 6, 12, 'And they are they who were scattered and gathered in from the four quarters of the earth, and from the north countries, and are partakers of the fulfilling of the covenant which God made with their father Abraham.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-15', 'coc-bom-1908', 'Ether', 6, 15, 'And as he dwelt in the cavity of a rock, he made the remainder of this record, viewing the destructions which came upon the people by night.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-19', 'coc-bom-1908', 'Ether', 6, 19, 'Wherefore, it came to pass that in the first year that Ether dwelt in the cavity of a rock, there were many people who were slain by the sword of those secret combinations fighting against Coriantumr, that they might obtain the kingdom.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-20', 'coc-bom-1908', 'Ether', 6, 20, 'And it came to pass that the sons of Coriantumr fought much and bled much.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-26', 'coc-bom-1908', 'Ether', 6, 26, 'And the sons of Coriantumr in the fourth year did beat Shared and did obtain the kingdom again unto their father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-27', 'coc-bom-1908', 'Ether', 6, 27, 'Now there began to be a war upon all the face of the land, every man with his band, fighting for that which he desired.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-28', 'coc-bom-1908', 'Ether', 6, 28, 'And there were robbers and, in fine, all manner of wickedness upon all the face of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-30', 'coc-bom-1908', 'Ether', 6, 30, 'And it came to pass that Shared fought against him for the space of three days.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-31', 'coc-bom-1908', 'Ether', 6, 31, 'And it came to pass that Coriantumr beat him and did pursue him until he came to the plains of Heshlon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-33', 'coc-bom-1908', 'Ether', 6, 33, 'And Coriantumr gave Shared battle again in the valley of Gilgal, in which he beat Shared and slew him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-35', 'coc-bom-1908', 'Ether', 6, 35, 'And now, there began to be a great curse upon the land because of the iniquity of the people, in which if a man should lay his tool or his sword upon the shelf or upon the place whither he would keep it, and behold, upon the morrow he could not find it, so great was the curse upon the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-39', 'coc-bom-1908', 'Ether', 6, 39, 'And it came to pass that Coriantumr did lay siege to the wilderness, and the brother of Shared did march forth out of the wilderness by night and slew a part of the army of Coriantumr as they were drunken.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-40', 'coc-bom-1908', 'Ether', 6, 40, 'And he came forth to the land of Moron and placed himself upon the throne of Coriantumr.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-41', 'coc-bom-1908', 'Ether', 6, 41, 'And it came to pass that Coriantumr dwelt with his army in the wilderness for the space of two years, in which he did receive great strength to his army.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-42', 'coc-bom-1908', 'Ether', 6, 42, 'Now the brother of Shared, whose name was Gilead, also received great strength to his army because of secret combinations.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-43', 'coc-bom-1908', 'Ether', 6, 43, 'And it came to pass that his high priest murdered him as he sat upon his throne.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-45', 'coc-bom-1908', 'Ether', 6, 45, 'And it came to pass that in the first year of Lib, Coriantumr came up unto the land of Moron and gave battle unto Lib.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-48', 'coc-bom-1908', 'Ether', 6, 48, 'And it came to pass that Lib did smite the army of Coriantumr, that they fled again to the wilderness of Akish.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-49', 'coc-bom-1908', 'Ether', 6, 49, 'And it came to pass that Lib did pursue him until he came to the plains of Agosh.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-50', 'coc-bom-1908', 'Ether', 6, 50, 'And Coriantumr had taken all the people with him as he fled before Lib in that quarter of the land whither he fled.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-52', 'coc-bom-1908', 'Ether', 6, 52, 'Now the name of the brother of Lib was called Shiz.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-55', 'coc-bom-1908', 'Ether', 6, 55, 'And it came to pass that the people began to flock together in armies throughout all the face of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-56', 'coc-bom-1908', 'Ether', 6, 56, 'And they were divided, and a part of them fled to the army of Shiz, and a part of them fled to the army of Coriantumr.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-61', 'coc-bom-1908', 'Ether', 6, 61, 'And thus we see that the Lord did visit them in the fullness of his wrath, and their wickedness and abominations had prepared a way for their everlasting destruction.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-65', 'coc-bom-1908', 'Ether', 6, 65, 'And Coriantumr pitched his tents in the valley of Shurr.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-68', 'coc-bom-1908', 'Ether', 6, 68, 'And it came to pass that they came again the third time, and the battle became exceeding sore.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-69', 'coc-bom-1908', 'Ether', 6, 69, 'And it came to pass that Shiz smote upon Coriantumr, that he gave him many deep wounds.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-70', 'coc-bom-1908', 'Ether', 6, 70, 'And Coriantumr, having lost his blood, fainted and was carried away as though he were dead.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-76', 'coc-bom-1908', 'Ether', 6, 76, 'And it came to pass that when Shiz had received his epistle, he wrote an epistle unto Coriantumr, that if he would give himself up that he might slay him with his own sword, that he would spare the lives of the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-79', 'coc-bom-1908', 'Ether', 6, 79, 'And when Coriantumr saw that he was about to fall, he fled again before the people of Shiz.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-81', 'coc-bom-1908', 'Ether', 6, 81, 'And it came to pass that they fought an exceeding sore battle, in which Coriantumr was wounded again, and he fainted with the loss of blood.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-84', 'coc-bom-1908', 'Ether', 6, 84, 'And it came to pass that they did gather together all the people upon all the face of the land who had not been slain, save it was Ether.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-86', 'coc-bom-1908', 'Ether', 6, 86, 'Wherefore, they were for the space of four years gathering together the people, that they might get all who were upon the face of the land, and that they might receive all the strength which it was possible that they could receive.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-91', 'coc-bom-1908', 'Ether', 6, 91, 'And it came to pass that Coriantumr wrote again an epistle unto Shiz, desiring that he would not come again to battle, but that he would take the kingdom and spare the lives of the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-95', 'coc-bom-1908', 'Ether', 6, 95, 'And when the night came, they had all fallen by the sword, save it were fifty and two of the people of Coriantumr and sixty and nine of the people of Shiz.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-97', 'coc-bom-1908', 'Ether', 6, 97, 'And when the night came, there were thirty and two of the people of Shiz and twenty and seven of the people of Coriantumr.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-98', 'coc-bom-1908', 'Ether', 6, 98, 'And it came to pass that they ate, and slept, and prepared for death on the morrow.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-99', 'coc-bom-1908', 'Ether', 6, 99, 'And they were large and mighty men, as to the strength of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-100', 'coc-bom-1908', 'Ether', 6, 100, 'And it came to pass that they fought for the space of three hours, and they fainted with the loss of blood.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-103', 'coc-bom-1908', 'Ether', 6, 103, 'And it came to pass that when they had all fallen by the sword, save it were Coriantumr and Shiz, behold, Shiz had fainted with the loss of blood.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-104', 'coc-bom-1908', 'Ether', 6, 104, 'And it came to pass that when Coriantumr had leaned upon his sword, that he rested a little, he smote off the head of Shiz.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-106', 'coc-bom-1908', 'Ether', 6, 106, 'And it came to pass that Coriantumr fell to the earth and became as if he had no life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-107', 'coc-bom-1908', 'Ether', 6, 107, 'And the Lord spake unto Ether and said unto him, Go forth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:ether-6-109', 'coc-bom-1908', 'Ether', 6, 109, 'Now the last words which are written by Ether are these: Whether the Lord will that I be translated or that I suffer the will of the Lord in the flesh, it mattereth not if it so be that I am saved in the kingdom of God. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-1', 'coc-bom-1908', 'Mormon', 1, 1, 'And now, I, Mormon, make a record of the things which I have both seen and heard and call it the book of Mormon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-6', 'coc-bom-1908', 'Mormon', 1, 6, 'And I, Mormon, being a descendant of Nephi (and my father''s name was Mormon), I remembered the things which Ammoron commanded me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-10', 'coc-bom-1908', 'Mormon', 1, 10, 'And it came to pass that the war began to be among them in the borders of Zarahemla by the waters of Sidon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-11', 'coc-bom-1908', 'Mormon', 1, 11, 'And it came to pass that the Nephites had gathered together a great number of men, even to exceed the number of thirty thousand.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-12', 'coc-bom-1908', 'Mormon', 1, 12, 'And it came to pass that they did have in this same year a number of battles, in the which the Nephites did beat the Lamanites and did slay many of them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-15', 'coc-bom-1908', 'Mormon', 1, 15, 'And there were no gifts from the Lord, and the Holy Ghost did not come upon any because of their wickedness and unbelief.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-16', 'coc-bom-1908', 'Mormon', 1, 16, 'And I, being fifteen years of age and being somewhat of a sober mind, therefore, I was visited of the Lord and tasted and knew of the goodness of Jesus.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-21', 'coc-bom-1908', 'Mormon', 1, 21, 'And it came to pass that in that same year, there began to be a war again between the Nephites and the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-22', 'coc-bom-1908', 'Mormon', 1, 22, 'And notwithstanding, I, being young, was large in stature, therefore, the people of Nephi appointed me that I should be their leader, or the leader of their armies.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-25', 'coc-bom-1908', 'Mormon', 1, 25, 'And it came to pass that we did come to the city of Angola, and we did take possession of the city and make preparations to defend ourselves against the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-27', 'coc-bom-1908', 'Mormon', 1, 27, 'And they did also drive us forth out of the land of David. And we marched forth and came to the land of Joshua, which was in the borders west by the seashore.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-28', 'coc-bom-1908', 'Mormon', 1, 28, 'And it came to pass that we did gather in our people as fast as it were possible, that we might get them together in one body.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-32', 'coc-bom-1908', 'Mormon', 1, 32, 'And behold, I withstood him with forty and two thousand. And it came to pass that I beat him with my army, that he fled before me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-33', 'coc-bom-1908', 'Mormon', 1, 33, 'And behold, all this was done, and three hundred and thirty years had passed away.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-35', 'coc-bom-1908', 'Mormon', 1, 35, 'Thus there began to be a mourning and a lamentation in all the land because of these things, and more especially among the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-36', 'coc-bom-1908', 'Mormon', 1, 36, 'And it came to pass that when I, Mormon, saw their lamentations, and their mourning, and their sorrowing before the Lord, my heart did begin to rejoice within me, knowing the mercies and the long-suffering of the Lord, therefore, supposing that he would be merciful unto them, that they would again become a righteous people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-38', 'coc-bom-1908', 'Mormon', 1, 38, 'And they did not come unto Jesus with broken hearts and contrite spirits, but they did curse God and wish to die.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-39', 'coc-bom-1908', 'Mormon', 1, 39, 'Nevertheless, they would struggle with the sword for their lives.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-41', 'coc-bom-1908', 'Mormon', 1, 41, 'And thus three hundred and forty and four years had passed away.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-43', 'coc-bom-1908', 'Mormon', 1, 43, 'And now, the city of Jashon was near the land where Ammoron had deposited the records unto the Lord, that they might not be destroyed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-44', 'coc-bom-1908', 'Mormon', 1, 44, 'And behold, I had gone according to the word of Ammoron, and taken the plates of Nephi, and did make a record according to the words of Ammoron.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-47', 'coc-bom-1908', 'Mormon', 1, 47, 'And it came to pass that in this year the people of Nephi again were hunted and driven.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-48', 'coc-bom-1908', 'Mormon', 1, 48, 'And it came to pass that we were driven forth until we had come northward to the land which was called Shem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-49', 'coc-bom-1908', 'Mormon', 1, 49, 'And it came to pass that we did fortify the city of Shem, and we did gather in our people as much as it were possible, that perhaps we might save them from destruction.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-50', 'coc-bom-1908', 'Mormon', 1, 50, 'And it came to pass in the three hundred and forty and sixth year, they began to come upon us again.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-51', 'coc-bom-1908', 'Mormon', 1, 51, 'And it came to pass that I did speak unto my people and did urge them with great energy that they would stand boldly before the Lamanites and fight for their wives, and their children, and their houses, and their homes.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-52', 'coc-bom-1908', 'Mormon', 1, 52, 'And my words did arouse them somewhat to vigor, insomuch that they did not flee from before the Lamanites but did stand with boldness against them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-53', 'coc-bom-1908', 'Mormon', 1, 53, 'And it came to pass that we did contend, with an army of thirty thousand against an army of fifty thousand.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-54', 'coc-bom-1908', 'Mormon', 1, 54, 'And it came to pass that we did stand before them with such firmness that they did flee from before us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-57', 'coc-bom-1908', 'Mormon', 1, 57, 'And my heart did sorrow because of this the great calamity of my people, because of their wickedness and their abominations.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-58', 'coc-bom-1908', 'Mormon', 1, 58, 'But behold, we did go forth against the Lamanites and the robbers of Gadianton until we had again taken possession of the lands of our inheritance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-59', 'coc-bom-1908', 'Mormon', 1, 59, 'And the three hundred and forty and ninth year had passed away.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-60', 'coc-bom-1908', 'Mormon', 1, 60, 'And in the three hundred and fiftieth year, we made a treaty with the Lamanites and the robbers of Gadianton, in which we did get the lands of our inheritance divided.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-61', 'coc-bom-1908', 'Mormon', 1, 61, 'And the Lamanites did give unto us the land northward, yea, even to the narrow passage which led into the land southward.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-62', 'coc-bom-1908', 'Mormon', 1, 62, 'And we did give unto the Lamanites all the land southward.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-63', 'coc-bom-1908', 'Mormon', 1, 63, 'And it came to pass that the Lamanites did not come to battle again until ten years more had passed away.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-64', 'coc-bom-1908', 'Mormon', 1, 64, 'And behold, I had employed my people, the Nephites, in preparing their lands and their arms against the time of battle.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-65', 'coc-bom-1908', 'Mormon', 1, 65, 'And it came to pass that the Lord did say unto me, Cry unto this people, Repent ye, and come unto me, and be ye baptized, and build up again my church, and ye shall be spared.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-67', 'coc-bom-1908', 'Mormon', 1, 67, 'And behold, they did harden their hearts against the Lord, their God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-68', 'coc-bom-1908', 'Mormon', 1, 68, 'And it came to pass that after this tenth year had passed away, making, in the whole, three hundred and sixty years from the coming of Christ, the king of the Lamanites sent an epistle unto me, which gave unto me to know that they were preparing to come again to battle against us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-69', 'coc-bom-1908', 'Mormon', 1, 69, 'And it came to pass that I did cause my people that they should gather themselves together at the land Desolation, to a city which was in the borders by the narrow pass which led into the land southward.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-72', 'coc-bom-1908', 'Mormon', 1, 72, 'And in the three hundred and sixty and second year, they did come down again to battle.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-73', 'coc-bom-1908', 'Mormon', 1, 73, 'And we did beat them again and did slay a great number of them, and their dead were cast into the sea.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-74', 'coc-bom-1908', 'Mormon', 1, 74, 'And now, because of this great thing which my people, the Nephites, had done, they began to boast in their own strength and began to swear before the heavens that they would avenge themselves of the blood of their brethren who had been slain by their enemies.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-75', 'coc-bom-1908', 'Mormon', 1, 75, 'And they did swear by the heavens and also by the throne of God that they would go up to battle against their enemies and would cut them off from the face of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-76', 'coc-bom-1908', 'Mormon', 1, 76, 'And it came to pass that I, Mormon, did utterly refuse from this time forth to be a commander and a leader of this people because of their wickedness and abomination.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-79', 'coc-bom-1908', 'Mormon', 1, 79, 'And thrice have I delivered them out of the hands of their enemies, and they have repented not of their sins.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-86', 'coc-bom-1908', 'Mormon', 1, 86, 'And for this cause I write unto you, that ye may know that ye must all stand before the judgment seat of Christ--yea, every soul who belongs to the whole human family of Adam--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-1-89', 'coc-bom-1908', 'Mormon', 1, 89, 'And I would that I could persuade all ye ends of the earth to repent and prepare to stand before the judgment seat of Christ.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-1', 'coc-bom-1908', 'Mormon', 2, 1, 'And now, it came to pass that in the three hundred and sixty and third year, the Nephites did go up with their armies to battle against the Lamanites out of the land of Desolation.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-2', 'coc-bom-1908', 'Mormon', 2, 2, 'And it came to pass that the armies of the Nephites were driven back again to the land of Desolation.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-7', 'coc-bom-1908', 'Mormon', 2, 7, 'And it came to pass that the Lamanites did make preparation to come against the city Teancum.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-8', 'coc-bom-1908', 'Mormon', 2, 8, 'And it came to pass in the three hundred and sixty and fourth year, the Lamanites did come against the city Teancum, that they might take possession of the city Teancum also.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-9', 'coc-bom-1908', 'Mormon', 2, 9, 'And it came to pass that they were repulsed and driven back by the Nephites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-14', 'coc-bom-1908', 'Mormon', 2, 14, 'And there never had been so great wickedness among all the children of Lehi, nor even among all the house of Israel, according to the words of the Lord, as was among this people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-15', 'coc-bom-1908', 'Mormon', 2, 15, 'And it came to pass that the Lamanites did take possession of the city Desolation, and this because their number did exceed the number of the Nephites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-16', 'coc-bom-1908', 'Mormon', 2, 16, 'And they did also march forward against the city Teancum, and did drive the inhabitants forth out of her, and did take many prisoners, both women and children, and did offer them up as sacrifices unto their idol gods.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-18', 'coc-bom-1908', 'Mormon', 2, 18, 'And the Lamanites did not come again against the Nephites until the three hundred and seventy and fifth year.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-20', 'coc-bom-1908', 'Mormon', 2, 20, 'And from this time forth did the Nephites gain no power over the Lamanites, but began to be swept off by them, even as a dew before the sun.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-24', 'coc-bom-1908', 'Mormon', 2, 24, 'And it came to pass that the Nephites did again flee from before them, taking all the inhabitants with them, both in towns and villages.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-25', 'coc-bom-1908', 'Mormon', 2, 25, 'And now, I, Mormon, seeing that the Lamanites were about to overthrow the land, therefore, I did go to the hill Shim and did take up all the records which Ammoron had hid up unto the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-29', 'coc-bom-1908', 'Mormon', 2, 29, 'And it came to pass that they came against us again, and we did maintain the city.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-30', 'coc-bom-1908', 'Mormon', 2, 30, 'And there were also other cities which were maintained by the Nephites, which strongholds did cut them off, that they could not get into the country which lay before us to destroy the inhabitants of our land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-34', 'coc-bom-1908', 'Mormon', 2, 34, 'And now, behold, I, Mormon, do not desire to harrow up the souls of men in casting before them such an awful scene of blood and carnage as was laid before mine eyes,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-35', 'coc-bom-1908', 'Mormon', 2, 35, 'But I--knowing that these things must surely be made known, and that all things which are hid must be revealed upon the housetops, and also that a knowledge of these things must come unto the remnant of these people and also unto the Gentiles, which the Lord hath said should scatter this people, and this people should be counted as naught among them--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-36', 'coc-bom-1908', 'Mormon', 2, 36, 'Therefore, I write a small abridgment, daring not to give a full account of the things which I have seen--because of the commandment which I have received and also that ye might not have too great sorrow because of the wickedness of this people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-37', 'coc-bom-1908', 'Mormon', 2, 37, 'And now, behold, this I speak unto their seed and also to the Gentiles, who have care for the house of Israel, that realize and know from whence their blessings come.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-42', 'coc-bom-1908', 'Mormon', 2, 42, 'That the Father may bring about, through his most beloved, his great and eternal purpose in restoring the Jews, or all the house of Israel, to the land of their inheritance, which the Lord, their God, hath given them, unto the fulfilling of his covenant,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-44', 'coc-bom-1908', 'Mormon', 2, 44, 'For this people shall be scattered and shall become a dark, a filthy, and a loathsome people, beyond the description of that which ever hath been amongst us, yea, even that which hath been among the Lamanites--and this because of their unbelief and idolatry.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-48', 'coc-bom-1908', 'Mormon', 2, 48, 'And behold, the Lord hath reserved their blessings, which they might have received in the land, for the Gentiles who shall possess the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-50', 'coc-bom-1908', 'Mormon', 2, 50, 'And also the Lord will remember the prayers of the righteous which have been put up unto him for them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-51', 'coc-bom-1908', 'Mormon', 2, 51, 'And then, O ye Gentiles, how can ye stand before the power of God, except ye shall repent and turn from your evil ways?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-52', 'coc-bom-1908', 'Mormon', 2, 52, 'Know ye not that ye are in the hands of God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-53', 'coc-bom-1908', 'Mormon', 2, 53, 'Know ye not that he hath all power and at his great command the earth shall be rolled together as a scroll?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-2-54', 'coc-bom-1908', 'Mormon', 2, 54, 'Therefore, repent ye, and humble yourselves before him, lest he shall come out in justice against you, lest a remnant of the seed of Jacob shall go forth among you as a lion and tear you in pieces, and there is none to deliver.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-3-1', 'coc-bom-1908', 'Mormon', 3, 1, 'And now, I finish my record concerning the destruction of my people, the Nephites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-3-2', 'coc-bom-1908', 'Mormon', 3, 2, 'And it came to pass that we did march forth before the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-3-4', 'coc-bom-1908', 'Mormon', 3, 4, 'And it came to pass that the king of the Lamanites did grant unto me the thing which I desired.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-3-6', 'coc-bom-1908', 'Mormon', 3, 6, 'And when three hundred and eighty and four years had passed away, we had gathered in all the remainder of our people unto the land Cumorah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-3-8', 'coc-bom-1908', 'Mormon', 3, 8, 'Therefore, I made this record out of the plates of Nephi and hid up in the hill Cumorah all the records which had been entrusted to me by the hand of the Lord, save it were these few plates which I gave unto my son Moroni.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-3-10', 'coc-bom-1908', 'Mormon', 3, 10, 'And it came to pass that they came to battle against us, and every soul was filled with terror because of the greatness of their numbers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-3-11', 'coc-bom-1908', 'Mormon', 3, 11, 'And it came to pass that they did fall upon my people with the sword, and with the bow, and with the arrow, and with the ax, and with all manner of weapons of war.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-3-13', 'coc-bom-1908', 'Mormon', 3, 13, 'And when they had gone through and hewn down all my people, save it were twenty and four of us (among whom was my son Moroni),', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-3-17', 'coc-bom-1908', 'Mormon', 3, 17, 'And their flesh, and bones, and blood lay upon the face of the earth, being left by the hands of those who slew them, to moulder upon the land, and to crumble, and to return to their mother earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-3-19', 'coc-bom-1908', 'Mormon', 3, 19, 'Behold, if ye had not done this, ye would not have fallen. But behold, ye are fallen, and I mourn your loss.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-3-20', 'coc-bom-1908', 'Mormon', 3, 20, 'O ye fair sons and daughters, ye fathers and mothers, ye husbands and wives, ye fair ones, how is it that ye could have fallen!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-3-25', 'coc-bom-1908', 'Mormon', 3, 25, 'Know ye that ye must come unto repentance, or ye cannot be saved.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-3-26', 'coc-bom-1908', 'Mormon', 3, 26, 'Know ye that ye must lay down your weapons of war, and delight no more in the shedding of blood, and take them not again, save it be that God shall command you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-3-28', 'coc-bom-1908', 'Mormon', 3, 28, 'And he bringeth to pass the resurrection of the dead, whereby man must be raised to stand before his judgment seat.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-3-29', 'coc-bom-1908', 'Mormon', 3, 29, 'And he hath brought to pass the redemption of the world, whereby he that is found guiltless before him at the judgment day hath it given unto him to dwell in the presence of God in his kingdom, to sing ceaseless praises with the choirs above unto the Father, and unto the Son, and unto the Holy Ghost, which are one God, in a state of happiness which hath no end.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-3-30', 'coc-bom-1908', 'Mormon', 3, 30, 'Therefore, repent, and be baptized in the name of Jesus, and lay hold upon the gospel of Christ, which shall be set before you, not only in this record, but also in the record which shall come unto the Gentiles from the Jews, which record shall come from the Gentiles unto you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-3-33', 'coc-bom-1908', 'Mormon', 3, 33, 'And if it so be that ye believe in Christ, and are baptized, first with water, then with fire and with the Holy Ghost, following the example of our Savior according to that which he hath commanded us, it shall be well with you in the day of judgment. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-1', 'coc-bom-1908', 'Mormon', 4, 1, 'Behold, I, Moroni, do finish the record of my father Mormon. Behold, I have but few things to write, which things I have been commanded of my father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-3', 'coc-bom-1908', 'Mormon', 4, 3, 'But behold, they are gone, and I fulfill the commandment of my father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-5', 'coc-bom-1908', 'Mormon', 4, 5, 'Behold, my father hath made this record, and he hath written the intent thereof.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-7', 'coc-bom-1908', 'Mormon', 4, 7, 'Behold, four hundred years have passed since the coming of our Lord and Savior.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-9', 'coc-bom-1908', 'Mormon', 4, 9, 'And behold, it is the hand of the Lord which hath done it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-13', 'coc-bom-1908', 'Mormon', 4, 13, 'But behold, my father and I have seen them, and they have ministered unto us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-14', 'coc-bom-1908', 'Mormon', 4, 14, 'And whoso receiveth this record and shall not condemn it because of the imperfections which are in it, the same shall know of greater things than these.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-16', 'coc-bom-1908', 'Mormon', 4, 16, 'Behold, I make an end of speaking concerning this people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-23', 'coc-bom-1908', 'Mormon', 4, 23, 'And he that saith, Show unto me or ye shall be smitten, let him beware, lest he commandeth that which is forbidden of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-27', 'coc-bom-1908', 'Mormon', 4, 27, 'Search the prophecies of Isaiah. Behold, I cannot write them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-29', 'coc-bom-1908', 'Mormon', 4, 29, 'And he knoweth their prayers, that they were in behalf of their brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-31', 'coc-bom-1908', 'Mormon', 4, 31, 'Yea, even the fiery furnace could not harm them, neither wild beasts nor poisonous serpents, because of the power of his word.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-32', 'coc-bom-1908', 'Mormon', 4, 32, 'And behold, their prayers were also in behalf of him that the Lord should suffer to bring these things forth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-36', 'coc-bom-1908', 'Mormon', 4, 36, 'Yea, it shall come in a day when the power of God shall be denied, and churches become defiled and shall be lifted up in the pride of their hearts, yea, even in a day when leaders of churches and teachers, in the pride of their hearts, even to the envying of them who belong to their churches--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-39', 'coc-bom-1908', 'Mormon', 4, 39, 'There shall be murders and robbing, and lying, and deceivings, and whoredoms, and all manner of abominations--when there shall be many who will say, Do this or do that, and it mattereth not, for the Lord will uphold such at the last day.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-40', 'coc-bom-1908', 'Mormon', 4, 40, 'But wo unto such, for they are in the gall of bitterness and in the bonds of iniquity.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-41', 'coc-bom-1908', 'Mormon', 4, 41, 'Yea, it shall come in a day when there shall be churches built up that shall say, Come unto me, and for your money you shall be forgiven of your sins.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-42', 'coc-bom-1908', 'Mormon', 4, 42, 'O ye wicked, and perverse, and stiff-necked people, why have ye built up churches unto yourselves to get gain?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-43', 'coc-bom-1908', 'Mormon', 4, 43, 'Why have ye transfigured the holy word of God, that ye might bring damnation upon your souls?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-44', 'coc-bom-1908', 'Mormon', 4, 44, 'Behold, look ye unto the revelations of God. For behold, the time cometh at that day when all these things must be fulfilled.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-45', 'coc-bom-1908', 'Mormon', 4, 45, 'Behold, the Lord hath shown unto me great and marvelous things concerning that which must shortly come at that day when these things shall come forth among you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-46', 'coc-bom-1908', 'Mormon', 4, 46, 'Behold, I speak unto you as if ye were present, and yet ye are not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-49', 'coc-bom-1908', 'Mormon', 4, 49, 'And your churches, yea, even every one has become polluted because of the pride of your hearts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-50', 'coc-bom-1908', 'Mormon', 4, 50, 'For behold, ye do love money, and your substance, and your fine apparel, and the adorning of your churches more than ye love the poor and the needy, the sick and the afflicted.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-51', 'coc-bom-1908', 'Mormon', 4, 51, 'O ye pollutions, ye hypocrites, ye teachers, who sell yourselves for that which will canker, why have ye polluted the holy church of God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-52', 'coc-bom-1908', 'Mormon', 4, 52, 'Why are ye ashamed to take upon you the name of Christ?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-53', 'coc-bom-1908', 'Mormon', 4, 53, 'Why do you not think that greater is the value of an endless happiness than that misery which never dies because of the praise of the world?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-54', 'coc-bom-1908', 'Mormon', 4, 54, 'Why do ye adorn yourselves with that which hath no life, and yet suffer the hungry, and the needy, and the naked, and the sick, and the afflicted to pass by you, and notice them not?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-55', 'coc-bom-1908', 'Mormon', 4, 55, 'Yea, why do ye build up your secret abominations to get gain and cause that widows should mourn before the Lord, and also orphans to mourn before the Lord, and also the blood of their fathers and their husbands to cry unto the Lord from the ground for vengeance upon your heads?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-57', 'coc-bom-1908', 'Mormon', 4, 57, 'And now, I speak also concerning those who do not believe in Christ.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-58', 'coc-bom-1908', 'Mormon', 4, 58, 'Behold, will ye believe in the day of your visitation, behold, when the Lord shall come, yea, even that great day when the earth shall be rolled together as a scroll and the elements shall melt with fervent heat?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-59', 'coc-bom-1908', 'Mormon', 4, 59, 'Yea, in that great day when ye shall be brought to stand before the Lamb of God, then will ye say that there is no God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-60', 'coc-bom-1908', 'Mormon', 4, 60, 'Then will ye longer deny the Christ, or can ye behold the Lamb of God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-61', 'coc-bom-1908', 'Mormon', 4, 61, 'Do ye suppose that ye shall dwell with him under a consciousness of your guilt?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-62', 'coc-bom-1908', 'Mormon', 4, 62, 'Do ye suppose that ye could be happy to dwell with that holy being when your souls are racked with a consciousness of your guilt that ye have ever abused his laws?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-63', 'coc-bom-1908', 'Mormon', 4, 63, 'Behold, I say unto you that ye would be more miserable to dwell with a holy and just God, under a consciousness of your filthiness before him, than ye would to dwell with the damned souls in hell.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-64', 'coc-bom-1908', 'Mormon', 4, 64, 'For behold, when ye shall be brought to see your nakedness before God, and also the glory of God, and the holiness of Jesus Christ, it will kindle a flame of unquenchable fire upon you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-66', 'coc-bom-1908', 'Mormon', 4, 66, 'And again, I speak unto you who deny the revelations of God and say that they are done away, that there are no revelations, nor prophecies, nor gifts, nor healing, nor speaking with tongues, and the interpretation of tongues.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-69', 'coc-bom-1908', 'Mormon', 4, 69, 'And now, if ye have imagined up unto yourselves a god who doth vary and in him there is shadow of changing, then have ye imagined up unto yourselves a god who is not a god of miracles.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-75', 'coc-bom-1908', 'Mormon', 4, 75, 'And now, O all ye that have imagined up unto yourselves a god who can do no miracles, I would ask of you, Have all these things passed of which I have spoken? Has the end come yet?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-77', 'coc-bom-1908', 'Mormon', 4, 77, 'Behold, are not the things that God hath wrought marvelous in our eyes? Yea, and who can comprehend the marvelous works of God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-79', 'coc-bom-1908', 'Mormon', 4, 79, 'And who shall say that Jesus Christ did not do many mighty miracles?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-80', 'coc-bom-1908', 'Mormon', 4, 80, 'And there were many mighty miracles wrought by the hands of the apostles.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-81', 'coc-bom-1908', 'Mormon', 4, 81, 'And if there were miracles wrought, then why has God ceased to be a God of miracles and yet be an unchangeable being?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-83', 'coc-bom-1908', 'Mormon', 4, 83, 'And the reason why he ceaseth to do miracles among the children of men is because that they dwindle in unbelief, and depart from the right way, and know not the God in whom they should trust.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-85', 'coc-bom-1908', 'Mormon', 4, 85, 'For behold, thus said Jesus Christ, the Son of God, unto his disciples who should tarry, yea, and also to all his disciples, in the hearing of the multitude:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-88', 'coc-bom-1908', 'Mormon', 4, 88, 'And whosoever shall believe in my name, doubting nothing, unto him will I confirm all my words, even unto the ends of the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-89', 'coc-bom-1908', 'Mormon', 4, 89, 'And now, behold, who can stand against the works of the Lord? Who can deny his sayings?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-90', 'coc-bom-1908', 'Mormon', 4, 90, 'Who will rise up against the almighty power of the Lord? Who will despise the works of the Lord? Who will despise the children of Christ?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-91', 'coc-bom-1908', 'Mormon', 4, 91, 'Behold, all ye who are despisers of the works of the Lord, for ye shall wonder and perish.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-92', 'coc-bom-1908', 'Mormon', 4, 92, 'Oh, then despise not, and wonder not, but hearken unto the words of the Lord, and ask the Father in the name of Jesus for what things soever ye shall stand in need.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-98', 'coc-bom-1908', 'Mormon', 4, 98, 'And now, behold, we have written this record according to our knowledge in the characters, which are called among us the reformed Egyptian, being handed down and altered by us according to our manner of speech.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-101', 'coc-bom-1908', 'Mormon', 4, 101, 'And these things are written that we may rid our garments of the blood of our brethren who have dwindled in unbelief.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mormon-4-102', 'coc-bom-1908', 'Mormon', 4, 102, 'And behold, these things which we have desired concerning our brethren, yea, even their restoration to the knowledge of Christ, is according to the prayers of all the saints who have dwelt in the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-2-1', 'coc-bom-1908', 'Moroni', 2, 1, 'The words of Christ which he spake unto his disciples, the twelve whom he had chosen, as he laid his hands upon them:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-3-1', 'coc-bom-1908', 'Moroni', 3, 1, 'The manner which the disciples, who were called the elders of the church, ordained priests and teachers:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-3-2', 'coc-bom-1908', 'Moroni', 3, 2, 'After they had prayed unto the Father in the name of Christ, they laid their hands upon them and said, In the name of Jesus Christ I ordain you to be a priest (or if he be a teacher, I ordain you to be a teacher) to preach repentance and remission of sins through Jesus Christ, by the endurance of faith on his name to the end. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-4-1', 'coc-bom-1908', 'Moroni', 4, 1, 'The manner of their elders and priests administering the flesh and blood of Christ unto the church:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-4-3', 'coc-bom-1908', 'Moroni', 4, 3, 'And they did kneel down with the church and pray to the Father in the name of Christ, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-4-4', 'coc-bom-1908', 'Moroni', 4, 4, 'O God, the eternal Father, we ask thee, in the name of thy Son Jesus Christ, to bless and sanctify this bread to the souls of all those who partake of it, that they may eat in remembrance of the body of thy Son and witness unto thee, O God, the eternal Father, that they are willing to take upon them the name of thy Son, and always remember him, and keep his commandments which he hath given them, that they may always have his Spirit to be with them. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-5-1', 'coc-bom-1908', 'Moroni', 5, 1, 'The manner of administering the wine:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-5-2', 'coc-bom-1908', 'Moroni', 5, 2, 'Behold, they took the cup and said,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-5-3', 'coc-bom-1908', 'Moroni', 5, 3, 'O God, the eternal Father, we ask thee, in the name of thy Son Jesus Christ, to bless and sanctify this wine to the souls of all those who drink of it, that they may do it in remembrance of the blood of thy Son which was shed for them, that they may witness unto thee, O God, the eternal Father, that they do always remember him, that they may have his Spirit to be with them. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-6-1', 'coc-bom-1908', 'Moroni', 6, 1, 'And now, I speak concerning baptism:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-6-3', 'coc-bom-1908', 'Moroni', 6, 3, 'And none were received unto baptism save they took upon them the name of Christ, having a determination to serve him to the end.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-6-4', 'coc-bom-1908', 'Moroni', 6, 4, 'And after they had been received unto baptism and were wrought upon and cleansed by the power of the Holy Ghost, they were numbered among the people of the church of Christ.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-6-5', 'coc-bom-1908', 'Moroni', 6, 5, 'And their names were taken, that they might be remembered and nourished by the good word of God to keep them in the right way, to keep them continually watchful unto prayer, relying alone upon the merits of Christ, who was the author and the finisher of their faith.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-7-3', 'coc-bom-1908', 'Moroni', 7, 3, 'Wherefore, I would speak unto you that are of the church, that are the peaceable followers of Christ, and that have obtained a sufficient hope, by which ye can enter into the rest of the Lord from this time henceforth until ye shall rest with him in heaven.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-7-6', 'coc-bom-1908', 'Moroni', 7, 6, 'For behold, it is not counted unto him for righteousness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-7-12', 'coc-bom-1908', 'Moroni', 7, 12, 'Wherefore, take heed, my beloved brethren, that ye do not judge that which is evil to be of God or that which is good and of God to be of the devil.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-7-19', 'coc-bom-1908', 'Moroni', 7, 19, 'And now, my brethren, how is it possible that ye can lay hold upon every good thing?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-7-22', 'coc-bom-1908', 'Moroni', 7, 22, 'And God also declared unto prophets by his own mouth that Christ should come.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-7-26', 'coc-bom-1908', 'Moroni', 7, 26, 'And as sure as Christ liveth, he spake these words unto our fathers, saying, Whatsoever thing ye shall ask the Father in my name, which is good, in faith believing that ye shall receive, behold, it shall be done unto you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-7-27', 'coc-bom-1908', 'Moroni', 7, 27, 'Wherefore, my beloved brethren, hath miracles ceased because Christ hath ascended into heaven and hath sat down on the right hand of God, to claim of the Father his rights of mercy which he hath upon the children of men?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-7-29', 'coc-bom-1908', 'Moroni', 7, 29, 'And because he hath done this, my beloved brethren, hath miracles ceased?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-7-31', 'coc-bom-1908', 'Moroni', 7, 31, 'For behold, they are subject unto him, to minister according to the word of his command, showing themselves unto them of strong faith and a firm mind in every form of godliness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-7-33', 'coc-bom-1908', 'Moroni', 7, 33, 'And by so doing, the Lord God prepareth the way that the residue of men may have faith in Christ, that the Holy Ghost may have place in their hearts according to the power thereof.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-7-34', 'coc-bom-1908', 'Moroni', 7, 34, 'And after this manner bringeth to pass the Father the covenants which he hath made unto the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-7-35', 'coc-bom-1908', 'Moroni', 7, 35, 'And Christ hath said, If ye will have faith in me, ye shall have power to do whatsoever thing is expedient in me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-7-36', 'coc-bom-1908', 'Moroni', 7, 36, 'And he hath said, Repent, all ye ends of the earth, and come unto me, and be baptized in my name, and have faith in me, that ye may be saved.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-7-37', 'coc-bom-1908', 'Moroni', 7, 37, 'And now, my beloved brethren, if this be the case, that these things are true which I have spoken unto you--and God will show unto you with power and great glory at the last day that they are true--and if they are true, has the day of miracles ceased?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-7-38', 'coc-bom-1908', 'Moroni', 7, 38, 'Or have angels ceased to appear unto the children of men?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-7-39', 'coc-bom-1908', 'Moroni', 7, 39, 'Or has he withheld the power of the Holy Ghost from them?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-7-40', 'coc-bom-1908', 'Moroni', 7, 40, 'Or will he, so long as time shall last, or the earth shall stand, or there shall be one man upon the face thereof to be saved?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-7-45', 'coc-bom-1908', 'Moroni', 7, 45, 'And again, my beloved brethren, I would speak unto you concerning hope.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-7-46', 'coc-bom-1908', 'Moroni', 7, 46, 'How is it that ye can attain unto faith, save ye shall have hope? And what is it that ye shall hope for?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-8-2', 'coc-bom-1908', 'Moroni', 8, 2, 'And on this wise did he write unto me, saying, My beloved son, Moroni, I rejoice exceedingly that your Lord Jesus Christ hath been mindful of you and hath called you to his ministry and to his holy work.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-8-3', 'coc-bom-1908', 'Moroni', 8, 3, 'I am mindful of you always in my prayers, continually praying unto God, the Father, in the name of his holy child, Jesus, that he, through his infinite goodness and grace, will keep you through the endurance of faith on his name to the end.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-8-5', 'coc-bom-1908', 'Moroni', 8, 5, 'For if I have learned the truth, there have been disputations among you concerning the baptism of your little children.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-8-7', 'coc-bom-1908', 'Moroni', 8, 7, 'For immediately after I had learned these things of you, I inquired of the Lord concerning the matter.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-8-8', 'coc-bom-1908', 'Moroni', 8, 8, 'And the word of the Lord came to me by the power of the Holy Ghost, saying, Listen to the words of Christ, your Redeemer, your Lord, and your God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-8-12', 'coc-bom-1908', 'Moroni', 8, 12, 'Behold, baptism is unto repentance, to the fulfilling the commandments unto the remission of sins.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-8-14', 'coc-bom-1908', 'Moroni', 8, 14, 'Wherefore, if little children could not be saved without baptism, these must have gone to an endless hell.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-8-16', 'coc-bom-1908', 'Moroni', 8, 16, 'For awful is the wickedness to suppose that God saveth one child because of baptism and the other must perish because he hath no baptism.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-8-17', 'coc-bom-1908', 'Moroni', 8, 17, 'Wo be unto him that shall pervert the ways of the Lord after this manner, for they shall perish except they repent.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-8-21', 'coc-bom-1908', 'Moroni', 8, 21, 'And he that saith that little children need baptism denieth the mercies of Christ and setteth at naught the atonement of him and the power of his redemption.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-8-22', 'coc-bom-1908', 'Moroni', 8, 22, 'Wo unto such, for they are in danger of death, hell, and an endless torment.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-8-24', 'coc-bom-1908', 'Moroni', 8, 24, 'Listen unto them and give heed, or they stand against you at the judgment seat of Christ.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-8-25', 'coc-bom-1908', 'Moroni', 8, 25, 'For behold that all little children are alive in Christ, and also all they that are without the law.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-8-27', 'coc-bom-1908', 'Moroni', 8, 27, 'But it is mockery before God, denying the mercies of Christ and the power of his Holy Spirit, and putting trust in dead works.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-8-30', 'coc-bom-1908', 'Moroni', 8, 30, 'Behold, my son, I will write unto you again if I go not out soon against the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-8-31', 'coc-bom-1908', 'Moroni', 8, 31, 'Behold, the pride of this nation, or the people of the Nephites, hath proven their destruction except they should repent.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-8-32', 'coc-bom-1908', 'Moroni', 8, 32, 'Pray for them, my son, that repentance may come unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-8-34', 'coc-bom-1908', 'Moroni', 8, 34, 'And after rejecting so great a knowledge, my son, they must perish soon, unto the fulfilling of the prophecies which were spoken by the prophets, as well as the words of our Savior himself.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-8-35', 'coc-bom-1908', 'Moroni', 8, 35, 'Farewell, my son, until I shall write unto you or shall meet you again. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-9-7', 'coc-bom-1908', 'Moroni', 9, 7, 'And now, I write somewhat concerning the sufferings of this people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-9-10', 'coc-bom-1908', 'Moroni', 9, 10, 'And notwithstanding this great abomination of the Lamanites, it doth not exceed that of our people in Moriantum.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-9-12', 'coc-bom-1908', 'Moroni', 9, 12, 'O my beloved son, how can a people like this, that are without civilization (and only a few years have passed away, and they were a civil and a delightsome people), but, O my son, how can a people like this, whose delight is in so much abomination, how can we expect that God will stay his hand in judgment against us?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-9-13', 'coc-bom-1908', 'Moroni', 9, 13, 'Behold, my heart cries, Wo unto this people!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-9-14', 'coc-bom-1908', 'Moroni', 9, 14, 'Come out in judgment, O God, and hide their sins, and wickedness, and abominations from before thy face!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-9-17', 'coc-bom-1908', 'Moroni', 9, 17, 'Oh, the depravity of my people! They are without order and without mercy.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-9-20', 'coc-bom-1908', 'Moroni', 9, 20, 'And now, my son, I dwell no longer upon this horrible scene.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-9-22', 'coc-bom-1908', 'Moroni', 9, 22, 'Behold, my son, I cannot recommend them unto God lest he should smite me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-9-28', 'coc-bom-1908', 'Moroni', 9, 28, 'And may the grace of God, the Father, whose throne is high in the heavens, and our Lord Jesus Christ, who sitteth on the right hand of his power until all things shall become subject unto him, be and abide with you forever. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-10-2', 'coc-bom-1908', 'Moroni', 10, 2, 'And I seal up these records after I have spoken a few words by way of exhortation unto you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-10-3', 'coc-bom-1908', 'Moroni', 10, 3, 'Behold, I would exhort you that when ye shall read these things, if it be wisdom in God that ye should read them, that ye would remember how merciful the Lord hath been unto the children of men--from the creation of Adam even down until the time that ye shall receive these things--and ponder it in your hearts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-10-13', 'coc-bom-1908', 'Moroni', 10, 13, 'And I would exhort you, my beloved brethren, that ye remember that every good gift cometh of Christ.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-10-14', 'coc-bom-1908', 'Moroni', 10, 14, 'And I would exhort you, my beloved brethren, that ye remember that he is the same yesterday, today, and forever, and that all these gifts of which I have spoken, which are spiritual, never will be done away, even as long as the world shall stand, only according to the unbelief of the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-10-17', 'coc-bom-1908', 'Moroni', 10, 17, 'And Christ truly said unto our fathers, If ye have faith, ye can do all things which are expedient unto me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-10-18', 'coc-bom-1908', 'Moroni', 10, 18, 'And now, I speak unto all the ends of the earth, that if the day cometh that the power and gifts of God shall be done away among you, it shall be because of unbelief.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-10-20', 'coc-bom-1908', 'Moroni', 10, 20, 'For if there be one among you that doeth good, he shall work by the power and gifts of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-10-23', 'coc-bom-1908', 'Moroni', 10, 23, 'Yea, even as one speaking out of the dust?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-10-24', 'coc-bom-1908', 'Moroni', 10, 24, 'I declare these things unto the fulfilling of the prophecies.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-10-26', 'coc-bom-1908', 'Moroni', 10, 26, 'And God shall show unto you that that which I have written is true.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-10-27', 'coc-bom-1908', 'Moroni', 10, 27, 'And again, I would exhort you that ye would come unto Christ, and lay hold upon every good gift, and touch not the evil gift nor the unclean thing.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-10-30', 'coc-bom-1908', 'Moroni', 10, 30, 'And again, if ye, by the grace of God, are perfect in Christ and deny not his power, then are ye sanctified in Christ by the grace of God, through the shedding of the blood of Christ, which is in the covenant of the Father, unto the remission of your sins, that ye become holy without spot.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:moroni-10-31', 'coc-bom-1908', 'Moroni', 10, 31, 'And now, I bid unto all, Farewell. I soon go to rest in the paradise of God until my spirit and body shall again reunite and I am brought forth triumphant through the air, to meet you before the pleasing bar of the great Jehovah, the eternal Judge of both quick and dead. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-1', 'coc-bom-1908', 'Mosiah', 1, 1, 'And now, there was no more contention in all the land of Zarahemla among all the people who belonged to King Benjamin, so that King Benjamin had continual peace all the remainder of his days.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-3', 'coc-bom-1908', 'Mosiah', 1, 3, 'And he caused that they should be taught in all the language of his fathers, that thereby they might become men of understanding and that they might know concerning the prophecies which had been spoken by the mouths of their fathers, which were delivered them by the hand of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-6', 'coc-bom-1908', 'Mosiah', 1, 6, 'For he, having been taught in the language of the Egyptians, therefore, he could read these engravings and teach them to his children, that thereby they could teach them to their children, and so fulfilling the commandments of God, even down to this present time.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-8', 'coc-bom-1908', 'Mosiah', 1, 8, 'And we should have been like unto our brethren, the Lamanites, who know nothing concerning these things, or even do not believe them when they are taught them, because of the traditions of their fathers which are not correct.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-9', 'coc-bom-1908', 'Mosiah', 1, 9, 'O my sons, I would that ye should remember that these sayings are true, and also that these records are true,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-12', 'coc-bom-1908', 'Mosiah', 1, 12, 'And I would that ye should keep the commandments of God, that ye may prosper in the land according to the promises which the Lord made unto our fathers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-13', 'coc-bom-1908', 'Mosiah', 1, 13, 'And many more things did King Benjamin teach his sons, which are not written in this book.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-16', 'coc-bom-1908', 'Mosiah', 1, 16, 'For on the morrow, I shall proclaim unto this my people, out of mine own mouth, that thou art a king and a ruler over this people whom the Lord, our God, hath given us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-18', 'coc-bom-1908', 'Mosiah', 1, 18, 'And I give unto them a name that never shall be blotted out, except it be through transgression.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-20', 'coc-bom-1908', 'Mosiah', 1, 20, 'And he will no more preserve them by his matchless and marvelous power, as he has hitherto preserved our fathers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-21', 'coc-bom-1908', 'Mosiah', 1, 21, 'For I say unto you that if he had not extended his arm in the preservation of our fathers, they must have fallen into the hands of the Lamanites and become victims to their hatred.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-22', 'coc-bom-1908', 'Mosiah', 1, 22, 'And it came to pass that after King Benjamin had made an end of these sayings to his son, that he gave him charge concerning all the affairs of the kingdom.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-23', 'coc-bom-1908', 'Mosiah', 1, 23, 'And moreover, he also gave him charge concerning the records which were engraven on the plates of brass, and also the plates of Nephi,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-24', 'coc-bom-1908', 'Mosiah', 1, 24, 'And also the sword of Laban, and the ball, or director, which led our fathers through the wilderness, which was prepared by the hand of the Lord, that thereby they might be led, everyone according to the heed and diligence which they gave unto him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-26', 'coc-bom-1908', 'Mosiah', 1, 26, 'And therefore, they were smitten with famine and sore afflictions to stir them up in remembrance of their duty.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-27', 'coc-bom-1908', 'Mosiah', 1, 27, 'And now, it came to pass that Mosiah went and did as his father had commanded him and proclaimed unto all the people who were in the land of Zarahemla, that thereby they might gather themselves together, to go up to the temple to hear the words which his father should speak unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-28', 'coc-bom-1908', 'Mosiah', 1, 28, 'And it came to pass that after Mosiah had done as his father had commanded him and had made a proclamation throughout all the land, that the people gathered themselves together throughout all the land, that they might go up to the temple to hear the words which King Benjamin should speak unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-30', 'coc-bom-1908', 'Mosiah', 1, 30, 'And they also took of the firstlings of their flocks, that they might offer sacrifice and burnt offerings according to the law of Moses,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-31', 'coc-bom-1908', 'Mosiah', 1, 31, 'And also that they might give thanks to the Lord, their God, who had brought them out of the land of Jerusalem, and who had delivered them out of the hands of their enemies, and had appointed just men to be their teachers and also a just man to be their king,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-32', 'coc-bom-1908', 'Mosiah', 1, 32, 'Who had established peace in the land of Zarahemla and who had taught them to keep the commandments of God, that thereby they might rejoice and be filled with love towards God and all men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-34', 'coc-bom-1908', 'Mosiah', 1, 34, 'And they pitched their tents round about the temple, every man having his tent with the door thereof towards the temple, that thereby they might remain in their tents and hear the words which King Benjamin should speak unto them,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-35', 'coc-bom-1908', 'Mosiah', 1, 35, 'For the multitude being so great that King Benjamin could not teach them all within the walls of the temple, therefore, he caused a tower to be erected, that thereby his people might hear the words which he should speak unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-37', 'coc-bom-1908', 'Mosiah', 1, 37, 'Therefore, he caused that the words which he spake should be written and sent forth among those that were not under the sound of his voice, that they might also receive his words.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-38', 'coc-bom-1908', 'Mosiah', 1, 38, 'And these are the words which he spake and caused to be written, saying, My brethren, all ye that have assembled yourselves together, you that can hear my words which I shall speak unto you this day,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-39', 'coc-bom-1908', 'Mosiah', 1, 39, 'For I have not commanded you to come up hither to trifle with the words which I shall speak, but that you should hearken unto me and open your ears that ye may hear, and your hearts that ye may understand, and your minds that the mysteries of God may be unfolded to your view.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-41', 'coc-bom-1908', 'Mosiah', 1, 41, 'But I am like as yourselves, subject to all manner of infirmities in body and mind.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-42', 'coc-bom-1908', 'Mosiah', 1, 42, 'Yet, as I have been chosen by this people, and was consecrated by my father, and was suffered by the hand of the Lord that I should be a ruler and a king over this people, and have been kept and preserved by his matchless power to serve thee with all the might, mind, and strength which the Lord hath granted unto me,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-43', 'coc-bom-1908', 'Mosiah', 1, 43, 'I say unto you that as I have been suffered to spend my days in your service, even up to this time, and have not sought gold, nor silver, nor any manner of riches of you,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-44', 'coc-bom-1908', 'Mosiah', 1, 44, 'Neither have I suffered that ye should be confined in dungeons, nor that ye should make slaves one of another, or that ye should murder, or plunder, or steal, or commit adultery,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-45', 'coc-bom-1908', 'Mosiah', 1, 45, 'Or even I have not suffered that ye should commit any manner of wickedness, and have taught you that ye should keep the commandments of the Lord in all things which he hath commanded you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-48', 'coc-bom-1908', 'Mosiah', 1, 48, 'Behold, I say unto you that because I said unto you that I had spent my days in your service, I do not desire to boast, for I have only been in the service of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-49', 'coc-bom-1908', 'Mosiah', 1, 49, 'And behold, I tell you these things that ye may learn wisdom, that ye may learn that when ye are in the service of your fellow beings, ye are only in the service of your God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-51', 'coc-bom-1908', 'Mosiah', 1, 51, 'And behold, also, if I, whom ye call your king, who has spent his days in your service, and yet has been in the service of God, doth merit any thanks from you, Oh, how had you ought to thank your heavenly King!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-52', 'coc-bom-1908', 'Mosiah', 1, 52, 'I say unto you, my brethren, that if you should render all the thanks and praise, which your whole souls have power to possess, to that God who has created you, and has kept and preserved you, and has caused that ye should rejoice, and has granted that ye should live in peace one with another,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-53', 'coc-bom-1908', 'Mosiah', 1, 53, 'I say unto you that if ye should serve him who has created you from the beginning and is preserving you from day to day by lending you breath, that ye may live, and move, and do according to your own will, and even supporting you from one moment to another--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-54', 'coc-bom-1908', 'Mosiah', 1, 54, 'I say, if ye should serve him with all your whole soul, yet ye would be unprofitable servants.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-57', 'coc-bom-1908', 'Mosiah', 1, 57, 'And now, in the first place, he hath created you and granted unto you your lives, for which ye are indebted unto him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-60', 'coc-bom-1908', 'Mosiah', 1, 60, 'And now, I ask, Can ye say aught of yourselves? I answer you, Nay.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-63', 'coc-bom-1908', 'Mosiah', 1, 63, 'And ye behold that I am old and am about to yield up this mortal frame to its mother earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-64', 'coc-bom-1908', 'Mosiah', 1, 64, 'Therefore, as I said unto you that I had served you, walking with a clear conscience before God, even so I at this time have caused that ye should assemble yourselves together, that I might be found blameless and that your blood should not come upon me when I shall stand to be judged of God of the things whereof he hath commanded me concerning you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-65', 'coc-bom-1908', 'Mosiah', 1, 65, 'I say unto you that I have caused that ye should assemble yourselves together, that I might rid my garments of your blood, at this period of time when I am about to go down to my grave,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-66', 'coc-bom-1908', 'Mosiah', 1, 66, 'That I might go down in peace, and my immortal spirit may join the choirs above in singing the praises of a just God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-68', 'coc-bom-1908', 'Mosiah', 1, 68, 'For even at this time, my whole frame doth tremble exceedingly while attempting to speak unto you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-69', 'coc-bom-1908', 'Mosiah', 1, 69, 'But the Lord God doth support me, and hath suffered me that I should speak unto you, and hath commanded me that I should declare unto you this day that my son Mosiah is a king and a ruler over you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-70', 'coc-bom-1908', 'Mosiah', 1, 70, 'And now, my brethren, I would that ye should do as ye have hitherto done.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-71', 'coc-bom-1908', 'Mosiah', 1, 71, 'As ye have kept my commandments and also the commandments of my father, and have prospered, and have been kept from falling into the hands of your enemies,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-72', 'coc-bom-1908', 'Mosiah', 1, 72, 'Even so, if ye shall keep the commandments of my son, or the commandments of God which shall be delivered unto you by him, ye shall prosper in the land, and your enemies shall have no power over you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-73', 'coc-bom-1908', 'Mosiah', 1, 73, 'But, O my people, beware lest there shall arise contentions among you, and ye list to obey the evil spirit, which was spoken of by my father Mosiah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-75', 'coc-bom-1908', 'Mosiah', 1, 75, 'For he receiveth for his wages an everlasting punishment, having transgressed the law of God, contrary to his own knowledge.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-76', 'coc-bom-1908', 'Mosiah', 1, 76, 'I say unto you that there are not any among you, except it be your little children, that have not been taught concerning these things, but what knoweth that ye are eternally indebted to your heavenly Father,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-77', 'coc-bom-1908', 'Mosiah', 1, 77, 'To render to him all that you have, and are, and also have been taught concerning the records which contain the prophecies which have been spoken by the holy prophets, even down to the time our father Lehi left Jerusalem, and also, all that has been spoken by our fathers until now.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-79', 'coc-bom-1908', 'Mosiah', 1, 79, 'And now, I say unto you, my brethren, that after ye have known and have been taught all these things, if ye should transgress and go contrary to that which has been spoken, that ye do withdraw yourselves from the Spirit of the Lord, that it may have no place in you to guide you in wisdom''s path, that ye may be blessed, prospered, and preserved.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-82', 'coc-bom-1908', 'Mosiah', 1, 82, 'Therefore, the Lord has no place in him, for he dwelleth not in unholy temples.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-83', 'coc-bom-1908', 'Mosiah', 1, 83, 'Therefore, if that man repenteth not and remaineth and dieth an enemy to God, the demands of divine justice doth awaken his immortal soul to a lively sense of his own guilt,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-84', 'coc-bom-1908', 'Mosiah', 1, 84, 'Which doth cause him to shrink from the presence of the Lord and doth fill his breast with guilt, and pain, and anguish, which is like an unquenchable fire, whose flames ascendeth up forever and ever.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-86', 'coc-bom-1908', 'Mosiah', 1, 86, 'O all ye old men, and also ye young men, and you little children who can understand my words (for I have spoken plain unto you, that ye might understand),', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-88', 'coc-bom-1908', 'Mosiah', 1, 88, 'And moreover, I would desire that ye should consider on the blessed and happy state of those that keep the commandments of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-90', 'coc-bom-1908', 'Mosiah', 1, 90, 'And if they hold out faithful to the end, they are received into heaven, that thereby they may dwell with God in a state of never-ending happiness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-92', 'coc-bom-1908', 'Mosiah', 1, 92, 'And again, my brethren, I would call your attention, for I have somewhat more to speak unto you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-96', 'coc-bom-1908', 'Mosiah', 1, 96, 'For the Lord hath heard thy prayers, and hath judged of thy righteousness, and hath sent me to declare unto thee that thou mayest rejoice and that thou mayest declare unto thy people, that they may also be filled with joy.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-97', 'coc-bom-1908', 'Mosiah', 1, 97, 'For behold, the time cometh, and is not far distant, that with power, the Lord Omnipotent, who reigneth, who was and is from all eternity to all eternity, shall come down from heaven among the children of men, and shall dwell in a tabernacle of clay,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-98', 'coc-bom-1908', 'Mosiah', 1, 98, 'And shall go forth amongst men, working mighty miracles, such as healing the sick, raising the dead, causing the lame to walk, the blind to receive their sight, and the deaf to hear, and curing all manner of diseases.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-99', 'coc-bom-1908', 'Mosiah', 1, 99, 'And he shall cast out devils, or the evil spirits, which dwell in the hearts of the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-101', 'coc-bom-1908', 'Mosiah', 1, 101, 'For behold, blood cometh from every pore, so great shall be his anguish for the wickedness and the abominations of his people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-104', 'coc-bom-1908', 'Mosiah', 1, 104, 'And even after all this, they shall consider him a man, and say that he hath a devil, and shall scourge him, and shall crucify him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-106', 'coc-bom-1908', 'Mosiah', 1, 106, 'And behold, all these things are done, that a righteous judgment might come upon the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-107', 'coc-bom-1908', 'Mosiah', 1, 107, 'For behold, and also his blood atoneth for the sins of those who have fallen by the transgression of Adam, who have died, not knowing the will of God concerning them, or who have ignorantly sinned.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-109', 'coc-bom-1908', 'Mosiah', 1, 109, 'And the Lord God hath sent his holy prophets among all the children of men to declare these things to every kindred, nation, and tongue, that thereby whosoever should believe that Christ should come, the same might receive remission of their sins and rejoice with exceeding great joy, even as though he had already come among them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-110', 'coc-bom-1908', 'Mosiah', 1, 110, 'Yet the Lord God saw that his people were a stiff-necked people, and he appointed unto them a law, even the law of Moses.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-112', 'coc-bom-1908', 'Mosiah', 1, 112, 'And also holy prophets spake unto them concerning his coming.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-115', 'coc-bom-1908', 'Mosiah', 1, 115, 'For behold, as in Adam, or by nature, they fall, even so the blood of Christ atoneth for their sins.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-116', 'coc-bom-1908', 'Mosiah', 1, 116, 'And moreover, I say unto you that there shall be no other name given, nor any other way nor means whereby salvation can come unto the children of men, only in and through the name of Christ, the Lord Omnipotent.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-118', 'coc-bom-1908', 'Mosiah', 1, 118, 'But men drink damnation to their own souls, except they humble themselves, and become as little children, and believe that salvation was, and is, and is to come, in and through the atoning blood of Christ, the Lord Omnipotent.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-120', 'coc-bom-1908', 'Mosiah', 1, 120, 'But if he yields to the enticings of the Holy Spirit, and putteth off the natural man, and becometh a saint through the atonement of Christ, the Lord, and becometh as a child--submissive, meek, humble, patient, full of love, willing to submit to all things which the Lord seeth fit to inflict upon him, even as a child doth submit to his father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-121', 'coc-bom-1908', 'Mosiah', 1, 121, 'And moreover, I say unto you that the time shall come when the knowledge of a Savior shall spread throughout every nation, kindred, tongue, and people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-123', 'coc-bom-1908', 'Mosiah', 1, 123, 'And even at this time, when thou shalt have taught thy people the things which the Lord, thy God, hath commanded thee, even then are they found no more blameless in the sight of God, only according to the words which I have spoken unto thee.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-124', 'coc-bom-1908', 'Mosiah', 1, 124, 'And now, I have spoken the words which the Lord God hath commanded me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-125', 'coc-bom-1908', 'Mosiah', 1, 125, 'And thus saith the Lord: They shall stand as a bright testimony against this people at the judgment day,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-129', 'coc-bom-1908', 'Mosiah', 1, 129, 'And their torment is as a lake of fire and brimstone, whose flames are unquenchable and whose smoke ascendeth up forever and ever.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-1-130', 'coc-bom-1908', 'Mosiah', 1, 130, 'Thus hath the Lord commanded me. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-2', 'coc-bom-1908', 'Mosiah', 2, 2, 'And they had viewed themselves in their own carnal state, even less than the dust of the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-4', 'coc-bom-1908', 'Mosiah', 2, 4, 'For we believe in Jesus Christ, the Son of God, who created heaven and earth, and all things, who shall come down among the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-5', 'coc-bom-1908', 'Mosiah', 2, 5, 'And it came to pass that after they had spoken these words, the Spirit of the Lord came upon them, and they were filled with joy,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-6', 'coc-bom-1908', 'Mosiah', 2, 6, 'Having received a remission of their sins, and having peace of conscience, because of the exceeding faith which they had in Jesus Christ, who should come, according to the words which King Benjamin had spoken unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-8', 'coc-bom-1908', 'Mosiah', 2, 8, 'For behold, if the knowledge of the goodness of God at this time has awakened you to a sense of your nothingness and your worthless and fallen state,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-9', 'coc-bom-1908', 'Mosiah', 2, 9, 'I say unto you, If ye have come to a knowledge of the goodness of God, and his matchless power, and his wisdom, and his patience, and his long-suffering towards the children of men,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-10', 'coc-bom-1908', 'Mosiah', 2, 10, 'And also, the atonement which has been prepared from the foundation of the world, that thereby salvation might come to him that should put his trust in the Lord, and should be diligent in keeping his commandments, and continue in the faith even unto the end of his life (I mean the life of the mortal body),', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-15', 'coc-bom-1908', 'Mosiah', 2, 15, 'Believe that man doth not comprehend all things which the Lord can comprehend.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-16', 'coc-bom-1908', 'Mosiah', 2, 16, 'And again, believe that ye must repent of your sins, and forsake them, and humble yourselves before God, and ask in sincerity of heart that he would forgive you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-17', 'coc-bom-1908', 'Mosiah', 2, 17, 'And now, if you believe all these things, see that ye do them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-18', 'coc-bom-1908', 'Mosiah', 2, 18, 'And again, I say unto you, as I have said before, that as ye have come to the knowledge of the glory of God,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-19', 'coc-bom-1908', 'Mosiah', 2, 19, 'Or if ye have known of his goodness, and have tasted of his love, and have received a remission of your sins, which causeth such exceeding great joy in your souls,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-20', 'coc-bom-1908', 'Mosiah', 2, 20, 'Even so, I would that ye should remember, and always retain in remembrance, the greatness of God, and your own nothingness, and his goodness and long-suffering towards you unworthy creatures,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-21', 'coc-bom-1908', 'Mosiah', 2, 21, 'And humble yourselves, even in the depths of humility, calling on the name of the Lord daily and standing steadfastly in the faith of that which is to come, which was spoken by the mouth of the angel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-23', 'coc-bom-1908', 'Mosiah', 2, 23, 'And ye shall grow in the knowledge of the glory of him that created you, or in the knowledge of that which is just and true.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-24', 'coc-bom-1908', 'Mosiah', 2, 24, 'And ye will not have a mind to injure one another, but to live peaceably and to render to every man according to that which is his due.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-29', 'coc-bom-1908', 'Mosiah', 2, 29, 'And ye will not suffer that the beggar putteth up his petition to you in vain, and turn him out to perish.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-32', 'coc-bom-1908', 'Mosiah', 2, 32, 'For behold, are we not all beggars? Do we not all depend upon the same being, even God, for all the substance which we have--for both food, and raiment, and for gold, and for silver, and for all the riches which we have of every kind?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-33', 'coc-bom-1908', 'Mosiah', 2, 33, 'And behold, even at this time, ye have been calling on his name and begging for a remission of your sins.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-34', 'coc-bom-1908', 'Mosiah', 2, 34, 'And has he suffered that ye have begged in vain?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-36', 'coc-bom-1908', 'Mosiah', 2, 36, 'And now, if God, who has created you, on whom you are dependent for your lives and for all that ye have and are, doth grant unto you whatsoever ye ask that is right, in faith, believing that ye shall receive, oh, then, how had ye ought to impart of the substance that ye have one to another?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-38', 'coc-bom-1908', 'Mosiah', 2, 38, 'And yet ye put up no petition nor repent of the thing which thou hast done.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-42', 'coc-bom-1908', 'Mosiah', 2, 42, 'And now, for the sake of these things which I have spoken unto you, that is, for the sake of retaining a remission of your sins from day to day, that ye may walk guiltless before God,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-46', 'coc-bom-1908', 'Mosiah', 2, 46, 'And I would that ye should remember that whosoever among you that borroweth of his neighbor should return the thing that he borroweth, according as he doth agree,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-47', 'coc-bom-1908', 'Mosiah', 2, 47, 'Or else thou shalt commit sin, and perhaps thou shalt cause thy neighbor to commit sin also.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-49', 'coc-bom-1908', 'Mosiah', 2, 49, 'But this much I can tell you: that if ye do not watch yourselves, and your thoughts, and your words, and your deeds, and observe to keep the commandments of God, and continue in the faith of what ye have heard concerning the coming of our Lord, even unto the end of your lives, ye must perish.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-2-50', 'coc-bom-1908', 'Mosiah', 2, 50, 'And now, O man, remember, and perish not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-3-1', 'coc-bom-1908', 'Mosiah', 3, 1, 'And now, it came to pass that when King Benjamin had thus spoken to his people, he sent among them, desiring to know of his people if they believed the words which he had spoken unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-3-3', 'coc-bom-1908', 'Mosiah', 3, 3, 'And also, we know of their surety and truth because of the Spirit of the Lord Omnipotent, which has wrought a mighty change in us, or in our hearts, that we have no more disposition to do evil, but to do good continually.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-3-6', 'coc-bom-1908', 'Mosiah', 3, 6, 'And we are willing to enter into a covenant with our God, to do his will and to be obedient to his commandments in all things that he shall command us, all the remainder of our days--that we may not bring upon ourselves a never-ending torment, as has been spoken by the angel, that we may not drink out of the cup of the wrath of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-3-15', 'coc-bom-1908', 'Mosiah', 3, 15, 'Therefore, take heed that ye do not transgress, that the name be not blotted out of your hearts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-3-16', 'coc-bom-1908', 'Mosiah', 3, 16, 'I say unto you, I would that ye should remember to retain the name written always in your hearts, that ye are not found on the left hand of God, but that ye hear and know the voice by which ye shall be called, and also the name by which he shall call you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-3-17', 'coc-bom-1908', 'Mosiah', 3, 17, 'For how knoweth a man the master whom he has not served, and who is a stranger unto him, and is far from the thoughts and intents of his heart?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-3-18', 'coc-bom-1908', 'Mosiah', 3, 18, 'And again, Doth a man take an ass which belongeth to his neighbor and keep him?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-3-20', 'coc-bom-1908', 'Mosiah', 3, 20, 'I say unto you that even so shall it be among you if ye know not the name by which ye are called.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-3-21', 'coc-bom-1908', 'Mosiah', 3, 21, 'Therefore, I would that ye should be steadfast and immovable, always abounding in good works, that Christ, the Lord God Omnipotent, may seal you his, that you may be brought to heaven, that ye may have everlasting salvation and eternal life through the wisdom, and power, and justice, and mercy of him, who created all things in heaven and in earth, who is God above all. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-4-1', 'coc-bom-1908', 'Mosiah', 4, 1, 'And now, King Benjamin thought it was expedient, after having finished speaking to the people, that he should take the names of all those who had entered into a covenant with God to keep his commandments.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-4-2', 'coc-bom-1908', 'Mosiah', 4, 2, 'And it came to pass that there was not one soul, except it were little children, but what had entered into the covenant and had taken upon them the name of Christ.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-4-3', 'coc-bom-1908', 'Mosiah', 4, 3, 'And again, it came to pass that when King Benjamin had made an end of all these things, and had consecrated his son Mosiah to be a ruler and a king over his people, and had given him all the charges concerning the kingdom,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-4-5', 'coc-bom-1908', 'Mosiah', 4, 5, 'And Mosiah began to reign in his father''s stead.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-4-6', 'coc-bom-1908', 'Mosiah', 4, 6, 'And he began to reign in the thirtieth year of his age, making in the whole about four hundred and seventy-six years from the time that Lehi left Jerusalem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-4-7', 'coc-bom-1908', 'Mosiah', 4, 7, 'And King Benjamin lived three years, and he died.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-4-8', 'coc-bom-1908', 'Mosiah', 4, 8, 'And it came to pass that King Mosiah did walk in the ways of the Lord, and did observe his judgments and his statutes, and did keep his commandments in all things whatsoever he commanded him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-4-9', 'coc-bom-1908', 'Mosiah', 4, 9, 'And King Mosiah did cause his people that they should till the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-4-10', 'coc-bom-1908', 'Mosiah', 4, 10, 'And he also, himself, did till the earth, that thereby he might not become burdensome to his people, that he might do according to that which his father had done in all things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-4-11', 'coc-bom-1908', 'Mosiah', 4, 11, 'And there was no contention among all his people for the space of three years.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-3', 'coc-bom-1908', 'Mosiah', 5, 3, 'And it came to pass that King Mosiah granted that sixteen of their strong men might go up to the land of Lehi-Nephi to inquire concerning their brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-9', 'coc-bom-1908', 'Mosiah', 5, 9, 'And they were surrounded by the king''s guard, and were taken, and were bound, and were committed to prison.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-11', 'coc-bom-1908', 'Mosiah', 5, 11, 'And they stood before the king and were permitted, or rather commanded, that they should answer the questions which he should ask them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-12', 'coc-bom-1908', 'Mosiah', 5, 12, 'And he said unto them, Behold, I am Limhi, the son of Noah, who was the son of Zeniff, who came up out of the land of Zarahemla to inherit this land, which was the land of their fathers, who was made a king by the voice of the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-13', 'coc-bom-1908', 'Mosiah', 5, 13, 'And now, I desire to know the cause whereby ye were so bold as to come near the walls of the city when I, myself, was with my guards without the gate.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-17', 'coc-bom-1908', 'Mosiah', 5, 17, 'For I am Ammon, and am a descendant of Zarahemla, and have come up out of the land of Zarahemla to inquire concerning our brethren, whom Zeniff brought up out of that land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-18', 'coc-bom-1908', 'Mosiah', 5, 18, 'And now, it came to pass that after Limhi had heard the words of Ammon, he was exceeding glad and said, Now I know of a surety that my brethren who were in the land of Zarahemla are yet alive.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-20', 'coc-bom-1908', 'Mosiah', 5, 20, 'For behold, we are in bondage to the Lamanites and are taxed with a tax which is grievous to be borne.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-22', 'coc-bom-1908', 'Mosiah', 5, 22, 'For it is better that we be slaves to the Nephites than to pay tribute to the king of the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-25', 'coc-bom-1908', 'Mosiah', 5, 25, 'And now, it came to pass on the morrow that King Limhi sent a proclamation among all his people, that thereby they might gather themselves together to the temple to hear the words which he should speak unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-26', 'coc-bom-1908', 'Mosiah', 5, 26, 'And it came to pass that when they had gathered themselves together, that he spake unto them on this wise, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-28', 'coc-bom-1908', 'Mosiah', 5, 28, 'Therefore, lift up your heads, and rejoice, and put your trust in God--in that God who was the God of Abraham, and Isaac, and Jacob,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-30', 'coc-bom-1908', 'Mosiah', 5, 30, 'And again, that same God has brought our fathers out of the land of Jerusalem and has kept and preserved his people, even until now.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-31', 'coc-bom-1908', 'Mosiah', 5, 31, 'And behold, it is because of our iniquities and abominations that have brought us into bondage.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-32', 'coc-bom-1908', 'Mosiah', 5, 32, 'And ye all are witnesses this day, that Zeniff, who was made king over this people, he being overzealous to inherit the land of his fathers,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-33', 'coc-bom-1908', 'Mosiah', 5, 33, 'Therefore being deceived by the cunning and craftiness of King Laman, who, having entered into a treaty with King Zeniff and having yielded up into his hands the possessions of a part of the land, or even the city of Lehi-Nephi, and the city of Shilom, and the land round about--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-34', 'coc-bom-1908', 'Mosiah', 5, 34, 'And all this he did for the sole purpose of bringing this people into subjection, or into bondage.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-36', 'coc-bom-1908', 'Mosiah', 5, 36, 'And even one-half of all we have or possess, the king of the Lamanites doth exact of us, or our lives.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-37', 'coc-bom-1908', 'Mosiah', 5, 37, 'And now, is not this grievous to be borne?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-38', 'coc-bom-1908', 'Mosiah', 5, 38, 'And is not this our affliction great?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-39', 'coc-bom-1908', 'Mosiah', 5, 39, 'Now behold, how great reason have we to mourn.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-41', 'coc-bom-1908', 'Mosiah', 5, 41, 'For if this people had not fallen into transgression, the Lord would not have suffered that this great evil should come upon them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-43', 'coc-bom-1908', 'Mosiah', 5, 43, 'And a prophet of the Lord have they slain, yea, a chosen man of God, who told them of their wickedness and abominations and prophesied of many things which are to come, yea, even the coming of Christ.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-44', 'coc-bom-1908', 'Mosiah', 5, 44, 'And because he said unto them that Christ was the God, the Father of all things, and said that he should take upon him the image of man, and it should be the image after which man was created in the beginning,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-45', 'coc-bom-1908', 'Mosiah', 5, 45, 'Or, in other words, he said that man was created after the image of God, and that God should come down among the children of men, and take upon him flesh and blood, and go forth upon the face of the earth,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-47', 'coc-bom-1908', 'Mosiah', 5, 47, 'Therefore, who wondereth that they are in bondage, and that they are smitten with sore afflictions.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-50', 'coc-bom-1908', 'Mosiah', 5, 50, 'And again, he saith, If my people shall sow filthiness, they shall reap the east wind, which bringeth immediate destruction.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-52', 'coc-bom-1908', 'Mosiah', 5, 52, 'But if ye will turn to the Lord with full purpose of heart, and put your trust in him, and serve him with all diligence of mind, if ye do this, he will, according to his own will and pleasure, deliver you out of bondage.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-54', 'coc-bom-1908', 'Mosiah', 5, 54, 'And he caused that Ammon should stand up before the multitude and rehearse unto them all that had happened unto their brethren, from the time that Zeniff went up out of the land, even until the time that he himself came up out of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-55', 'coc-bom-1908', 'Mosiah', 5, 55, 'And he also rehearsed unto them the last words which King Benjamin had taught them and explained them to the people of King Limhi, so that they might understand all the words which he spake.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-56', 'coc-bom-1908', 'Mosiah', 5, 56, 'And it came to pass that after he had done all this, that King Limhi dismissed the multitude and caused that they should return, everyone unto his own house.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-57', 'coc-bom-1908', 'Mosiah', 5, 57, 'And it came to pass that he caused that the plates which contained the record of his people, from the time that they left the land of Zarahemla, should be brought before Ammon, that he might read them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-58', 'coc-bom-1908', 'Mosiah', 5, 58, 'Now, as soon as Ammon had read the record, the king inquired of him to know if he could interpret languages.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-59', 'coc-bom-1908', 'Mosiah', 5, 59, 'And Ammon told him that he could not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-62', 'coc-bom-1908', 'Mosiah', 5, 62, 'Having discovered a land which was covered with bones of men and of beasts, etc., and was also covered with ruins of buildings of every kind,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-63', 'coc-bom-1908', 'Mosiah', 5, 63, 'Having discovered a land which had been peopled with a people who were as numerous as the hosts of Israel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-67', 'coc-bom-1908', 'Mosiah', 5, 67, 'And there is no one in the land that is able to interpret the language or the engravings that are on the plates.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-68', 'coc-bom-1908', 'Mosiah', 5, 68, 'Therefore, I said unto thee, Canst thou translate?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-69', 'coc-bom-1908', 'Mosiah', 5, 69, 'And I say unto thee again, Knowest thou of anyone that can translate? For I am desirous that these records should be translated into our language.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-74', 'coc-bom-1908', 'Mosiah', 5, 74, 'And whosoever is commanded to look in them, the same is called seer.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-75', 'coc-bom-1908', 'Mosiah', 5, 75, 'And behold, the king of the people who is in the land of Zarahemla is the man that is commanded to do these things and who has this high gift from God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-76', 'coc-bom-1908', 'Mosiah', 5, 76, 'And the king said that a seer is greater than a prophet.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-80', 'coc-bom-1908', 'Mosiah', 5, 80, 'And also, things shall be made known by them which otherwise could not be known.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-82', 'coc-bom-1908', 'Mosiah', 5, 82, 'And now, when Ammon had made an end of speaking these words, the king rejoiced exceedingly and gave thanks to God, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-84', 'coc-bom-1908', 'Mosiah', 5, 84, 'Oh, how marvelous are the works of the Lord, and how long doth he suffer with his people!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-5-86', 'coc-bom-1908', 'Mosiah', 5, 86, 'Yea, they are as a wild flock, which fleeth from the shepherd, and scattereth, and are driven, and are devoured by the beasts of the forest.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-5', 'coc-bom-1908', 'Mosiah', 6, 5, 'And we returned, those of us that were spared, to the land of Zarahemla, to relate that tale to their wives and their children.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-7', 'coc-bom-1908', 'Mosiah', 6, 7, 'Nevertheless, after many days'' wandering in the wilderness, we pitched our tents in the place where our brethren were slain, which was near to the land of our fathers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-8', 'coc-bom-1908', 'Mosiah', 6, 8, 'And it came to pass that I went again with four of my men into the city, in unto the king, that I might know of the disposition of the king and that I might know if I might go in with my people and possess the land in peace.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-9', 'coc-bom-1908', 'Mosiah', 6, 9, 'And I went in unto the king, and he covenanted with me that I might possess the land of Lehi-Nephi and the land of Shilom.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-11', 'coc-bom-1908', 'Mosiah', 6, 11, 'And we began to build buildings and to repair the walls of the city, yea, even the walls of the city of Lehi-Nephi and the city of Shilom.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-13', 'coc-bom-1908', 'Mosiah', 6, 13, 'Now, it was the cunning and the craftiness of King Laman to bring my people into bondage, that he yielded up the land, that we might possess it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-14', 'coc-bom-1908', 'Mosiah', 6, 14, 'Therefore, it came to pass that after we had dwelt in the land for the space of twelve years, that King Laman began to grow uneasy, lest by any means my people should wax strong in the land and that they could not overpower them and bring them into bondage.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-17', 'coc-bom-1908', 'Mosiah', 6, 17, 'For in the thirteenth year of my reign in the land of Nephi, away on the south of the land of Shilom, when my people were watering and feeding their flocks and tilling their lands, a numerous host of Lamanites came upon them, and began to slay them, and to take of their flocks and the corn of their fields.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-18', 'coc-bom-1908', 'Mosiah', 6, 18, 'Yea, and it came to pass that they fled, all that were not overtaken, even into the city of Nephi, and did call upon me for protection.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-21', 'coc-bom-1908', 'Mosiah', 6, 21, 'For I and my people did cry mightily to the Lord, that he would deliver us out of the hands of our enemies, for we were awakened to a remembrance of the deliverance of our fathers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-24', 'coc-bom-1908', 'Mosiah', 6, 24, 'And I, myself, with mine own hands did help bury their dead.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-25', 'coc-bom-1908', 'Mosiah', 6, 25, 'And behold, to our great sorrow and lamentation, two hundred and seventy-nine of our brethren were slain.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-27', 'coc-bom-1908', 'Mosiah', 6, 27, 'And I caused that there should be weapons of war made of every kind, that thereby I might have weapons for my people against the time the Lamanites should come up again to war against my people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-29', 'coc-bom-1908', 'Mosiah', 6, 29, 'And thus I did guard my people and my flocks and keep them from falling into the hands of our enemies.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-30', 'coc-bom-1908', 'Mosiah', 6, 30, 'And it came to pass that we did inherit the land of our fathers for many years, yea, for the space of twenty and two years.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-31', 'coc-bom-1908', 'Mosiah', 6, 31, 'And I did cause that the men should till the ground and raise all manner of grain and all manner of fruit of every kind.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-34', 'coc-bom-1908', 'Mosiah', 6, 34, 'And it came to pass that King Laman died, and his son began to reign in his stead.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-36', 'coc-bom-1908', 'Mosiah', 6, 36, 'But I had sent my spies out round about the land of Shemlon, that I might discover their preparations, that I might guard against them, that they might not come upon my people and destroy them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-41', 'coc-bom-1908', 'Mosiah', 6, 41, 'And it came to pass that we did go up to battle against the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-42', 'coc-bom-1908', 'Mosiah', 6, 42, 'And I, even I, in my old age, did go up to battle against the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-43', 'coc-bom-1908', 'Mosiah', 6, 43, 'And it came to pass that we did go up in the strength of the Lord to battle.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-46', 'coc-bom-1908', 'Mosiah', 6, 46, 'Believing that they were driven out of the land of Jerusalem because of the iniquities of their fathers, and that they were wronged in the wilderness by their brethren, and they were also wronged while crossing the sea,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-50', 'coc-bom-1908', 'Mosiah', 6, 50, 'They were also wroth with him upon the waters because they hardened their hearts against the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-6-57', 'coc-bom-1908', 'Mosiah', 6, 57, 'And it came to pass that we returned again to our own land, and my people again began to tend their flocks and to till their ground.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-2', 'coc-bom-1908', 'Mosiah', 7, 2, 'For behold, he did not keep the commandments of God, but he did walk after the desires of his own heart.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-3', 'coc-bom-1908', 'Mosiah', 7, 3, 'And he had many wives and concubines,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-4', 'coc-bom-1908', 'Mosiah', 7, 4, 'And did cause his people to commit sin and do that which was abominable in the sight of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-5', 'coc-bom-1908', 'Mosiah', 7, 5, 'Yea, and they did commit whoredoms and all manner of wickedness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-6', 'coc-bom-1908', 'Mosiah', 7, 6, 'And he laid a tax of one-fifth part of all they possessed: a fifth part of their gold and of their silver, and a fifth part of their ziff, and of their copper, and of their brass and their iron, and a fifth part of their fatlings, and also a fifth part of all their grain.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-8', 'coc-bom-1908', 'Mosiah', 7, 8, 'For he put down all the priests that had been consecrated by his father and consecrated new ones in their stead, such as were lifted up in the pride of their hearts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-10', 'coc-bom-1908', 'Mosiah', 7, 10, 'Yea, and they also became idolatrous because they were deceived by the vain and flattering words of the king and priests, for they did speak flattering things unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-12', 'coc-bom-1908', 'Mosiah', 7, 12, 'And he also built him a spacious palace and a throne in the midst thereof, all of which was of fine wood and was ornamented with gold, and silver, and with precious things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-15', 'coc-bom-1908', 'Mosiah', 7, 15, 'And he caused a breastwork to be built before them, that they might rest their bodies and their arms upon while they should speak lying and vain words to his people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-19', 'coc-bom-1908', 'Mosiah', 7, 19, 'And thus he did do with the riches which he obtained by the taxation of his people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-22', 'coc-bom-1908', 'Mosiah', 7, 22, 'And it came to pass that the Lamanites began to come in upon his people, upon small numbers, and to slay them in their fields and while they were tending their flocks.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-24', 'coc-bom-1908', 'Mosiah', 7, 24, 'Thus the Lamanites began to destroy them and to exercise their hatred upon them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-27', 'coc-bom-1908', 'Mosiah', 7, 27, 'And thus they did boast and did delight in blood and the shedding of the blood of their brethren--and this because of the wickedness of their king and priests.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-29', 'coc-bom-1908', 'Mosiah', 7, 29, 'Behold, thus saith the Lord, and thus hath he commanded me, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-30', 'coc-bom-1908', 'Mosiah', 7, 30, 'Go forth and say unto this people, Thus saith the Lord:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-34', 'coc-bom-1908', 'Mosiah', 7, 34, 'And it shall come to pass that they shall know that I am the Lord, their God, and am a jealous God, visiting the iniquities of my people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-38', 'coc-bom-1908', 'Mosiah', 7, 38, 'And thus saith the Lord, and thus hath he commanded me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-41', 'coc-bom-1908', 'Mosiah', 7, 41, 'And he said, Who is Abinadi, that I and my people should be judged of him? Or who is the Lord, that shall bring upon my people such great afflictions?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-45', 'coc-bom-1908', 'Mosiah', 7, 45, 'And it came to pass that after the space of two years, that Abinadi came among them in disguise, that they knew him not, and began again to prophesy among them, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-48', 'coc-bom-1908', 'Mosiah', 7, 48, 'And the Lord said unto me, Stretch forth thy hand and prophesy, saying, Thus saith the Lord: It shall come to pass that this generation, because of their iniquities, shall be brought into bondage, and shall be smitten on the cheek,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-57', 'coc-bom-1908', 'Mosiah', 7, 57, 'Yea, even this will I do, that I may discover the abominations of this people to other nations.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-58', 'coc-bom-1908', 'Mosiah', 7, 58, 'And many things did Abinadi prophesy against this people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-61', 'coc-bom-1908', 'Mosiah', 7, 61, 'And he also prophesieth evil concerning thy life and saith that thy life shall be as a garment in a furnace of fire.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-62', 'coc-bom-1908', 'Mosiah', 7, 62, 'And again, he saith that thou shalt be as a stalk, even as a dry stalk of the field, which is run over by the beasts and trodden underfoot.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-65', 'coc-bom-1908', 'Mosiah', 7, 65, 'And now, O King, what great evil hast thou done, or what great sins have thy people committed, that we should be condemned of God or judged of this man?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-70', 'coc-bom-1908', 'Mosiah', 7, 70, 'And he commanded that the priests should gather themselves together, that he might hold a council with them what he should do with him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-71', 'coc-bom-1908', 'Mosiah', 7, 71, 'And it came to pass that they said unto the king, Bring him hither, that we may question him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-72', 'coc-bom-1908', 'Mosiah', 7, 72, 'And the king commanded that he should be brought before them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-75', 'coc-bom-1908', 'Mosiah', 7, 75, 'For he did withstand them in all their questions and did confound them in all their words.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-76', 'coc-bom-1908', 'Mosiah', 7, 76, 'And it came to pass that one of them said unto him, What meaneth the words which are written and which have been taught by our fathers, saying,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-81', 'coc-bom-1908', 'Mosiah', 7, 81, 'And now, Abinadi said unto them, Are you priests and pretend to teach this people, and to understand the spirit of prophesying, and yet desire to know of me what these things mean?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-84', 'coc-bom-1908', 'Mosiah', 7, 84, 'And they said, We teach the law of Moses.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-85', 'coc-bom-1908', 'Mosiah', 7, 85, 'And again, he said unto them, If ye teach the law of Moses, why do ye not keep it?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-86', 'coc-bom-1908', 'Mosiah', 7, 86, 'Why do ye set your hearts upon riches?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-87', 'coc-bom-1908', 'Mosiah', 7, 87, 'Why do ye commit whoredoms, and spend your strength with harlots, yea, and cause this people to commit sin, that the Lord has cause to send me to prophesy against this people, yea, even a great evil against this people?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-88', 'coc-bom-1908', 'Mosiah', 7, 88, 'Know ye not that I speak the truth?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-91', 'coc-bom-1908', 'Mosiah', 7, 91, 'And what know ye concerning the law of Moses?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-92', 'coc-bom-1908', 'Mosiah', 7, 92, 'Doth salvation come by the law of Moses? What say ye?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-93', 'coc-bom-1908', 'Mosiah', 7, 93, 'And they answered and said that salvation did come by the law of Moses.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-95', 'coc-bom-1908', 'Mosiah', 7, 95, 'Yea, if ye keep the commandments which the Lord delivered unto Moses, in the mount of Sinai, saying, I am the Lord, thy God, who has brought thee out of the land of Egypt, out of the house of bondage.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-96', 'coc-bom-1908', 'Mosiah', 7, 96, 'Thou shalt have no other god before me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-97', 'coc-bom-1908', 'Mosiah', 7, 97, 'Thou shalt not make unto thee any graven image, or any likeness of anything in heaven above, or things which are in the earth beneath.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-98', 'coc-bom-1908', 'Mosiah', 7, 98, 'Now Abinadi said unto them, Have ye done all this? I say unto you, Nay, ye have not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-99', 'coc-bom-1908', 'Mosiah', 7, 99, 'And have ye taught this people that they should do all these things? I say unto you, Nay, ye have not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-104', 'coc-bom-1908', 'Mosiah', 7, 104, 'And again, because I have spoken the word of God, ye have judged me that I am mad.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-110', 'coc-bom-1908', 'Mosiah', 7, 110, 'But this much I tell you: What you do with me after this shall be as a type and a shadow of things which are to come.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-112', 'coc-bom-1908', 'Mosiah', 7, 112, 'I perceive that ye have studied and taught iniquity the most part of your lives.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-113', 'coc-bom-1908', 'Mosiah', 7, 113, 'And now, ye remember that I said unto you, Thou shalt not make unto thee any graven image, or any likeness of things which are in heaven above, or which are in the earth beneath, or which are in the water under the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-116', 'coc-bom-1908', 'Mosiah', 7, 116, 'Remember the Sabbath day, to keep it holy.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-119', 'coc-bom-1908', 'Mosiah', 7, 119, 'Honor thy father and thy mother, that thy days may be long upon the land which the Lord, thy God, giveth thee.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-120', 'coc-bom-1908', 'Mosiah', 7, 120, 'Thou shalt not kill.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-121', 'coc-bom-1908', 'Mosiah', 7, 121, 'Thou shalt not commit adultery.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-122', 'coc-bom-1908', 'Mosiah', 7, 122, 'Thou shalt not steal.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-7-123', 'coc-bom-1908', 'Mosiah', 7, 123, 'Thou shalt not bear false witness against thy neighbor.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-1', 'coc-bom-1908', 'Mosiah', 8, 1, 'And it came to pass that after Abinadi had made an end of these sayings, that he said unto them, Have ye taught this people that they should observe to do all these things, for to keep these commandments?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-3', 'coc-bom-1908', 'Mosiah', 8, 3, 'And now, ye have said that salvation cometh by the law of Moses.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-7', 'coc-bom-1908', 'Mosiah', 8, 7, 'Therefore, there was a law given them, yea, a law of performances and of ordinances, a law which they were to observe strictly from day to day, to keep them in remembrance of God and their duty towards him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-8', 'coc-bom-1908', 'Mosiah', 8, 8, 'But behold, I say unto you that all these things were types of things to come.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-9', 'coc-bom-1908', 'Mosiah', 8, 9, 'And now, did they understand the law?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-11', 'coc-bom-1908', 'Mosiah', 8, 11, 'For behold, did not Moses prophesy unto them concerning the coming of the Messiah, and that God should redeem his people, yea, and even all the prophets who have prophesied ever since the world began?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-12', 'coc-bom-1908', 'Mosiah', 8, 12, 'Have they not spoken more or less concerning these things?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-13', 'coc-bom-1908', 'Mosiah', 8, 13, 'Have they not said that God himself should come down among the children of men, and take upon him the form of man, and go forth in mighty power upon the face of the earth?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-14', 'coc-bom-1908', 'Mosiah', 8, 14, 'Yea, and have they not said also that he should bring to pass the resurrection of the dead and that he, himself, should be oppressed and afflicted?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-15', 'coc-bom-1908', 'Mosiah', 8, 15, 'Yea, even doth not Isaiah say,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-16', 'coc-bom-1908', 'Mosiah', 8, 16, 'Who hath believed our report, and to whom is the arm of the Lord revealed?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-31', 'coc-bom-1908', 'Mosiah', 8, 31, 'And they are one God, yea, the very eternal Father of heaven and of earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-32', 'coc-bom-1908', 'Mosiah', 8, 32, 'And thus the flesh, becoming subject to the Spirit, or the Son to the Father, being one God, suffereth temptation and yieldeth not to the temptation, but suffereth himself to be mocked, and scourged, and cast out, and disowned by his people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-33', 'coc-bom-1908', 'Mosiah', 8, 33, 'And after all this, and after working many mighty miracles among the children of men, he shall be led, yea, even as Isaiah said, as a sheep before the shearer is dumb, so he opened not his mouth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-35', 'coc-bom-1908', 'Mosiah', 8, 35, 'And thus God breaketh the bands of death, having gained the victory over death, giving the Son power to make intercession for the children of men,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-36', 'coc-bom-1908', 'Mosiah', 8, 36, 'Having ascended into heaven, having the bowels of mercy, being filled with compassion toward the children of men,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-37', 'coc-bom-1908', 'Mosiah', 8, 37, 'Standing betwixt them and justice, having broken the bands of death, taken upon himself their iniquity and their transgressions, having redeemed them and satisfied the demands of justice.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-38', 'coc-bom-1908', 'Mosiah', 8, 38, 'And now, I say unto you, Who shall declare his generation?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-39', 'coc-bom-1908', 'Mosiah', 8, 39, 'Behold, I say unto you that when his soul has been made an offering for sin, he shall see his seed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-40', 'coc-bom-1908', 'Mosiah', 8, 40, 'And now, what say ye? And who shall be his seed?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-41', 'coc-bom-1908', 'Mosiah', 8, 41, 'Behold, I say unto you that whosoever has heard the words of the prophets, yea, all the holy prophets who have prophesied concerning the coming of the Lord,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-42', 'coc-bom-1908', 'Mosiah', 8, 42, 'I say unto you that all those who have hearkened unto their words, and believed that the Lord would redeem his people, and have looked forward to that day for a remission of their sins,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-45', 'coc-bom-1908', 'Mosiah', 8, 45, 'And now, are they not his seed?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-46', 'coc-bom-1908', 'Mosiah', 8, 46, 'Yea, and are not the prophets, every one that has opened his mouth to prophesy, that has not fallen into transgression--I mean all the holy prophets ever since the world began?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-48', 'coc-bom-1908', 'Mosiah', 8, 48, 'And oh, how beautiful upon the mountains were their feet!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-49', 'coc-bom-1908', 'Mosiah', 8, 49, 'And again, how beautiful upon the mountains are the feet of those that are still publishing peace!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-50', 'coc-bom-1908', 'Mosiah', 8, 50, 'And again, how beautiful upon the mountains are the feet of those who shall hereafter publish peace, yea, from this time henceforth and forever!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-52', 'coc-bom-1908', 'Mosiah', 8, 52, 'Yea, even the Lord, who has redeemed his people, yea, he who has granted salvation unto his people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-53', 'coc-bom-1908', 'Mosiah', 8, 53, 'For were it not for the redemption which he hath made for his people, which was prepared from the foundation of the world, I say unto you, Were it not for this, all mankind must have perished.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-60', 'coc-bom-1908', 'Mosiah', 8, 60, 'And little children also have eternal life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-62', 'coc-bom-1908', 'Mosiah', 8, 62, 'Yea, even all those that have perished in their sins ever since the world began, that have willfully rebelled against God, that have known the commandments of God and would not keep them--these are they that have no part in the first resurrection.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-63', 'coc-bom-1908', 'Mosiah', 8, 63, 'Therefore, had ye not ought to tremble?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-66', 'coc-bom-1908', 'Mosiah', 8, 66, 'And now, I say unto you that the time shall come that the salvation of the Lord shall be declared to every nation, kindred, tongue, and people,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-70', 'coc-bom-1908', 'Mosiah', 8, 70, 'And now, it came to pass that after Abinadi had spoken these words, he stretched forth his hand and said, The time shall come when all shall see the salvation of the Lord,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-71', 'coc-bom-1908', 'Mosiah', 8, 71, 'When every nation, kindred, tongue, and people shall see eye to eye and shall confess before God that his judgments are just.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-74', 'coc-bom-1908', 'Mosiah', 8, 74, 'Yea, even that old serpent that did beguile our first parents, which was the cause of their fall,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-75', 'coc-bom-1908', 'Mosiah', 8, 75, 'Which was the cause of all mankind becoming carnal, sensual, devilish, knowing evil from good, subjecting themselves to the devil.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-79', 'coc-bom-1908', 'Mosiah', 8, 79, 'And now, if Christ had not come into the world, speaking of things to come as though they had already come, there could have been no redemption.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-80', 'coc-bom-1908', 'Mosiah', 8, 80, 'And if Christ had not risen from the dead, or have broken the bands of death, that the grave should have no victory and that death should have no sting, there could have been no resurrection.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-82', 'coc-bom-1908', 'Mosiah', 8, 82, 'He is the light and the life of the world, yea, a light that is endless, that can never be darkened, yea, and also a life which is endless, that there can be no more death.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-84', 'coc-bom-1908', 'Mosiah', 8, 84, 'If they be good, to the resurrection of endless life and happiness, and if they be evil, to the resurrection of endless damnation,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-85', 'coc-bom-1908', 'Mosiah', 8, 85, 'Being delivered up to the devil, who hath subjected them, which is damnation,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-86', 'coc-bom-1908', 'Mosiah', 8, 86, 'Having gone according to their own carnal wills and desires, having never called upon the Lord while the arms of mercy were extended towards them,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-87', 'coc-bom-1908', 'Mosiah', 8, 87, 'For the arms of mercy were extended towards them, and they would not--they being warned of their iniquities, and yet they would not depart from them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-88', 'coc-bom-1908', 'Mosiah', 8, 88, 'And they were commanded to repent, and yet they would not repent.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-89', 'coc-bom-1908', 'Mosiah', 8, 89, 'And now, had ye not ought to tremble, and repent of your sins, and remember only in and through Christ ye can be saved?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-8-91', 'coc-bom-1908', 'Mosiah', 8, 91, 'Teach them that redemption cometh through Christ the Lord, who is the very eternal Father. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-1', 'coc-bom-1908', 'Mosiah', 9, 1, 'And now, it came to pass that when Abinadi had finished these sayings, that the king commanded that the priests should take him and cause that he should be put to death.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-2', 'coc-bom-1908', 'Mosiah', 9, 2, 'But there was one among them whose name was Alma, he also being a descendant of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-4', 'coc-bom-1908', 'Mosiah', 9, 4, 'Therefore, he began to plead with the king that he would not be angry with Abinadi, but suffer that he might depart in peace.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-5', 'coc-bom-1908', 'Mosiah', 9, 5, 'But the king was more wroth, and caused that Alma should be cast out from among them, and sent his servants after him that they might slay him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-6', 'coc-bom-1908', 'Mosiah', 9, 6, 'But he fled from before them and hid himself, that they found him not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-7', 'coc-bom-1908', 'Mosiah', 9, 7, 'And he, being concealed for many days, did write all the words which Abinadi had spoken.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-9', 'coc-bom-1908', 'Mosiah', 9, 9, 'And after three days, having counseled with his priests, he caused that he should again be brought before him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-10', 'coc-bom-1908', 'Mosiah', 9, 10, 'And he said unto him, Abinadi, we have found an accusation against thee, and thou art worthy of death.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-12', 'coc-bom-1908', 'Mosiah', 9, 12, 'And now, for this cause thou shalt be put to death, unless thou wilt recall all the words which thou hast spoken evil concerning me and my people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-14', 'coc-bom-1908', 'Mosiah', 9, 14, 'And that ye may know of their surety, I have suffered myself that I have fallen into your hands.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-18', 'coc-bom-1908', 'Mosiah', 9, 18, 'But the priests lifted up their voices against him and began to accuse him, saying, He has reviled the king.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-19', 'coc-bom-1908', 'Mosiah', 9, 19, 'Therefore, the king was stirred up in anger against him, and he delivered him up that he might be slain.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-20', 'coc-bom-1908', 'Mosiah', 9, 20, 'And it came to pass that they took him, and bound him, and scourged his skin with fagots, yea, even unto death.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-21', 'coc-bom-1908', 'Mosiah', 9, 21, 'And now, when the flames began to scorch him, he cried unto them, saying, Behold, even as ye have done unto me, so shall it come to pass that thy seed shall cause that many shall suffer the pains that I do suffer, even the pains of death by fire, and this because they believe in the salvation of the Lord, their God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-22', 'coc-bom-1908', 'Mosiah', 9, 22, 'And it will come to pass that ye shall be afflicted with all manner of diseases because of your iniquities.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-23', 'coc-bom-1908', 'Mosiah', 9, 23, 'Yea, and ye shall be smitten on every hand, and shall be driven, and scattered to and fro, even as a wild flock is driven by wild and ferocious beasts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-24', 'coc-bom-1908', 'Mosiah', 9, 24, 'And in that day ye shall be hunted, and ye shall be taken by the hand of your enemies, and then ye shall suffer, as I suffer, the pains of death by fire.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-25', 'coc-bom-1908', 'Mosiah', 9, 25, 'Thus God executeth vengeance upon those that destroy his people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-26', 'coc-bom-1908', 'Mosiah', 9, 26, 'O God, receive my soul.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-27', 'coc-bom-1908', 'Mosiah', 9, 27, 'And now, when Abinadi had said these words, he fell, having suffered death by fire, yea, having been put to death because he would not deny the commandments of God, having sealed the truth of his words by his death.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-28', 'coc-bom-1908', 'Mosiah', 9, 28, 'And now, it came to pass that Alma, who had fled from the servants of King Noah, repented of his sins and iniquities, and went about privately among the people, and began to teach the words of Abinadi,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-29', 'coc-bom-1908', 'Mosiah', 9, 29, 'Yea, concerning that which was to come, and also concerning the resurrection of the dead, and the redemption of the people, which was to be brought to pass through the power, and sufferings, and death of Christ, and his resurrection and ascension into heaven.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-30', 'coc-bom-1908', 'Mosiah', 9, 30, 'And as many as would hear his word he did teach.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-31', 'coc-bom-1908', 'Mosiah', 9, 31, 'And he taught them privately, that it might not come to the knowledge of the king. And many did believe his words.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-32', 'coc-bom-1908', 'Mosiah', 9, 32, 'And it came to pass that as many as did believe him did go forth to a place which was called Mormon, having received its name from the king, being in the borders of the land having been infested by times, or at seasons, by wild beasts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-33', 'coc-bom-1908', 'Mosiah', 9, 33, 'Now there was in Mormon a fountain of pure water, and Alma resorted thither, there being near the water a thicket of small trees, where he did hide himself in the daytime from the searches of the king.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-34', 'coc-bom-1908', 'Mosiah', 9, 34, 'And it came to pass that as many as believed him went thither to hear his words.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-35', 'coc-bom-1908', 'Mosiah', 9, 35, 'And it came to pass after many days, there were a goodly number gathered together to the place of Mormon to hear the words of Alma.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-36', 'coc-bom-1908', 'Mosiah', 9, 36, 'Yea, all were gathered together that believed on his word, to hear him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-37', 'coc-bom-1908', 'Mosiah', 9, 37, 'And he did teach them and did preach unto them repentance, and redemption, and faith on the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-38', 'coc-bom-1908', 'Mosiah', 9, 38, 'And it came to pass that he said unto them, Behold, here are the waters of Mormon, for thus were they called.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-39', 'coc-bom-1908', 'Mosiah', 9, 39, 'And now, as ye are desirous to come into the fold of God, and to be called his people, and are willing to bear one another''s burdens, that they may be light,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-40', 'coc-bom-1908', 'Mosiah', 9, 40, 'Yea, and are willing to mourn with those that mourn, yea, and comfort those that stand in need of comfort, and to stand as witnesses of God at all times, and in all things, and in all places that ye may be in, even until death, that ye may be redeemed of God and be numbered with those of the first resurrection, that ye may have eternal life,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-41', 'coc-bom-1908', 'Mosiah', 9, 41, 'Now I say unto you, If this be the desire of your hearts, what have you against being baptized in the name of the Lord, as a witness before him that ye have entered into a covenant with him that ye will serve him and keep his commandments, that he may pour out his Spirit more abundantly upon you?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-42', 'coc-bom-1908', 'Mosiah', 9, 42, 'And now, when the people had heard these words, they clapped their hands for joy and exclaimed, This is the desire of our hearts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-43', 'coc-bom-1908', 'Mosiah', 9, 43, 'And now, it came to pass that Alma took Helam, he being one of the first, and went and stood forth in the water, and cried, saying, O Lord, pour out thy Spirit upon thy servant, that he may do this work with holiness of heart.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-46', 'coc-bom-1908', 'Mosiah', 9, 46, 'And again, Alma took another, and went forth a second time into the water, and baptized him according to the first, only he did not bury himself again in the water.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-49', 'coc-bom-1908', 'Mosiah', 9, 49, 'And they were called the church of God, or the church of Christ, from that time forward.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-50', 'coc-bom-1908', 'Mosiah', 9, 50, 'And it came to pass that whosoever was baptized by the power and authority of God was added to his church.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-52', 'coc-bom-1908', 'Mosiah', 9, 52, 'And he commanded them that they should teach nothing save it were the things which he had taught and which had been spoken by the mouth of the holy prophets.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-53', 'coc-bom-1908', 'Mosiah', 9, 53, 'Yea, even he commanded them that they should preach nothing save it were repentance and faith on the Lord, who had redeemed his people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-54', 'coc-bom-1908', 'Mosiah', 9, 54, 'And he commanded them that there should be no contention one with another, but that they should look forward with one eye, having one faith and one baptism, having their hearts knit together in unity and in love, one towards another.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-55', 'coc-bom-1908', 'Mosiah', 9, 55, 'And thus he commanded them to preach. And thus they became the children of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-56', 'coc-bom-1908', 'Mosiah', 9, 56, 'And he commanded them that they should observe the Sabbath day and keep it holy, and also every day they should give thanks to the Lord, their God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-57', 'coc-bom-1908', 'Mosiah', 9, 57, 'And he also commanded them that the priests whom he had ordained should labor with their own hands for their support.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-58', 'coc-bom-1908', 'Mosiah', 9, 58, 'And there was one day in every week that was set apart that they should gather themselves together to teach the people, and to worship the Lord, their God, and also, as often as it was in their power, to assemble themselves together.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-62', 'coc-bom-1908', 'Mosiah', 9, 62, 'And thus they should impart of their substance of their own free will and good desires towards God, and to those priests that stood in need, yea, and to every needy, naked soul.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-63', 'coc-bom-1908', 'Mosiah', 9, 63, 'And this he said unto them, having been commanded of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-64', 'coc-bom-1908', 'Mosiah', 9, 64, 'And they did walk uprightly before God, imparting to one another, both temporally and spiritually, according to their needs and their wants.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-67', 'coc-bom-1908', 'Mosiah', 9, 67, 'Yea, and how blessed are they, for they shall sing to his praise forever.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-68', 'coc-bom-1908', 'Mosiah', 9, 68, 'And these things were done in the borders of the land, that they might not come to the knowledge of the king.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-69', 'coc-bom-1908', 'Mosiah', 9, 69, 'But behold, it came to pass that the king, having discovered a movement among the people, sent his servants to watch them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-70', 'coc-bom-1908', 'Mosiah', 9, 70, 'Therefore, on the day that they were assembling themselves together to hear the word of the Lord, they were discovered unto the king.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-73', 'coc-bom-1908', 'Mosiah', 9, 73, 'And they were in number about four hundred and fifty souls.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-74', 'coc-bom-1908', 'Mosiah', 9, 74, 'And it came to pass that the army of the king returned, having searched in vain for the people of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-76', 'coc-bom-1908', 'Mosiah', 9, 76, 'And the lesser part began to breathe out threatenings against the king, and there began to be a great contention among them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-83', 'coc-bom-1908', 'Mosiah', 9, 83, 'And it came to pass that the Lamanites did pursue them, and did overtake them, and began to slay them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-84', 'coc-bom-1908', 'Mosiah', 9, 84, 'And it came to pass that the king commanded them that all the men should leave their wives and their children and flee before the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-85', 'coc-bom-1908', 'Mosiah', 9, 85, 'Now there were many that would not leave them, but had rather stay and perish with them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-86', 'coc-bom-1908', 'Mosiah', 9, 86, 'And the rest left their wives and their children and fled.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-87', 'coc-bom-1908', 'Mosiah', 9, 87, 'And it came to pass that those who tarried with their wives and their children caused that their fair daughters should stand forth and plead with the Lamanites, that they would not slay them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-89', 'coc-bom-1908', 'Mosiah', 9, 89, 'Therefore, the Lamanites did spare their lives, and took them captives, and carried them back to the land of Nephi, and granted unto them that they might possess the land, under the conditions that they would deliver up King Noah into the hands of the Lamanites and deliver up their property,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-91', 'coc-bom-1908', 'Mosiah', 9, 91, 'And now, there was one of the sons of the king among those that were taken captive, whose name was Limhi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-93', 'coc-bom-1908', 'Mosiah', 9, 93, 'And it came to pass that Gideon sent men into the wilderness secretly to search for the king and those that were with him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-94', 'coc-bom-1908', 'Mosiah', 9, 94, 'And it came to pass that they met the people in the wilderness, all save the king and his priests.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-97', 'coc-bom-1908', 'Mosiah', 9, 97, 'And they were about to take the priests also to put them to death, and they fled before them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-98', 'coc-bom-1908', 'Mosiah', 9, 98, 'And it came to pass that they were about to return to the land of Nephi, and they met the men of Gideon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-99', 'coc-bom-1908', 'Mosiah', 9, 99, 'And the men of Gideon told them of all that had happened to their wives and their children and that the Lamanites had granted unto them that they might possess the land by paying a tribute to the Lamanites of one-half of all they possessed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-100', 'coc-bom-1908', 'Mosiah', 9, 100, 'And the people told the men of Gideon that they had slain the king, and his priests had fled from them farther into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-102', 'coc-bom-1908', 'Mosiah', 9, 102, 'And it came to pass that the king of the Lamanites made an oath unto them that his people should not slay them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-103', 'coc-bom-1908', 'Mosiah', 9, 103, 'And also Limhi, being the son of the king, having the kingdom conferred upon him by the people, made an oath unto the king of the Lamanites that his people should pay tribute unto him, even one-half of all they possessed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-104', 'coc-bom-1908', 'Mosiah', 9, 104, 'And it came to pass that Limhi began to establish the kingdom and to establish peace among his people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-106', 'coc-bom-1908', 'Mosiah', 9, 106, 'And he did support his guards out of the tribute which he did receive from the Nephites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-107', 'coc-bom-1908', 'Mosiah', 9, 107, 'And now, King Limhi did have continual peace in his kingdom for the space of two years, that the Lamanites did not molest them nor seek to destroy them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-108', 'coc-bom-1908', 'Mosiah', 9, 108, 'Now there was a place in Shemlon where the daughters of the Lamanites did gather themselves together to sing, and to dance, and to make themselves merry.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-109', 'coc-bom-1908', 'Mosiah', 9, 109, 'And it came to pass that there was one day a small number of them gathered together to sing and to dance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-110', 'coc-bom-1908', 'Mosiah', 9, 110, 'And now, the priests of King Noah, being ashamed to return to the city of Nephi, yea, and also fearing that the people would slay them, therefore, they durst not return to their wives and their children.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-112', 'coc-bom-1908', 'Mosiah', 9, 112, 'Yea, twenty and four of the daughters of the Lamanites they carried into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-116', 'coc-bom-1908', 'Mosiah', 9, 116, 'And it came to pass that when the Lamanites had come up, that the people of Limhi began to fall upon them from their waiting places and began to slay them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-117', 'coc-bom-1908', 'Mosiah', 9, 117, 'And it came to pass that the battle became exceeding sore, for they fought like lions for their prey.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-118', 'coc-bom-1908', 'Mosiah', 9, 118, 'And it came to pass that the people of Limhi began to drive the Lamanites before them, yet they were not half so numerous as the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-122', 'coc-bom-1908', 'Mosiah', 9, 122, 'But Limhi said unto them, Ye shall not slay him, but bring him hither, that I may see him. And they brought him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-123', 'coc-bom-1908', 'Mosiah', 9, 123, 'And Limhi said unto him, What cause have ye to come up to war against my people?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-127', 'coc-bom-1908', 'Mosiah', 9, 127, 'Therefore, he caused a search to be made among his people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-128', 'coc-bom-1908', 'Mosiah', 9, 128, 'Now when Gideon had heard these things, he being the king''s captain, he went forth and said unto the king, I pray thee forbear, and do not search this people, and lay not this thing to their charge.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-129', 'coc-bom-1908', 'Mosiah', 9, 129, 'For do ye not remember the priests of thy father, whom this people sought to destroy?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-130', 'coc-bom-1908', 'Mosiah', 9, 130, 'And are they not in the wilderness? And are not they the ones who have stolen the daughters of the Lamanites?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-133', 'coc-bom-1908', 'Mosiah', 9, 133, 'For are not the words of Abinadi fulfilled, which he prophesied against us? And all this because we would not hearken unto the word of the Lord and turn from our iniquities?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-135', 'coc-bom-1908', 'Mosiah', 9, 135, 'And now, Limhi told the king all the things concerning his father and the priests that had fled into the wilderness and attributed the carrying away of their daughters to them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-137', 'coc-bom-1908', 'Mosiah', 9, 137, 'And it came to pass that they followed the king and went forth without arms to meet the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-139', 'coc-bom-1908', 'Mosiah', 9, 139, 'And when the Lamanites saw the people of Limhi, that they were without arms, they had compassion on them, and were pacified towards them, and returned with their king in peace to their own land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-140', 'coc-bom-1908', 'Mosiah', 9, 140, 'And it came to pass that Limhi and his people returned to the city of Nephi and began to dwell in the land again in peace.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-146', 'coc-bom-1908', 'Mosiah', 9, 146, 'And they gathered themselves together again, and put on their armor, and went forth against the Lamanites to drive them out of their land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-147', 'coc-bom-1908', 'Mosiah', 9, 147, 'And it came to pass that the Lamanites did beat them, and drove them back, and slew many of them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-148', 'coc-bom-1908', 'Mosiah', 9, 148, 'And now, there was a great mourning and lamentation among the people of Limhi--the widow mourning for her husband, the son and the daughter mourning for their father, and the brothers for their brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-150', 'coc-bom-1908', 'Mosiah', 9, 150, 'And it came to pass that their continual cries did stir up the remainder of the people of Limhi to anger against the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-153', 'coc-bom-1908', 'Mosiah', 9, 153, 'And they did humble themselves even to the dust, subjecting themselves to the yoke of bondage, submitting themselves to be smitten, and to be driven to and fro, and burdened, according to the desires of their enemies.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-157', 'coc-bom-1908', 'Mosiah', 9, 157, 'And it came to pass that they began to prosper by degrees in the land and began to raise grain more abundantly, and flocks, and herds, that they did not suffer with hunger.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-160', 'coc-bom-1908', 'Mosiah', 9, 160, 'And the king himself did not trust his person without the walls of the city unless he took his guards with him, fearing that he might by some means fall into the hands of the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-163', 'coc-bom-1908', 'Mosiah', 9, 163, 'And it came to pass that there was no more disturbance between the Lamanites and the people of Limhi, even until the time that Ammon and his brethren came into the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-168', 'coc-bom-1908', 'Mosiah', 9, 168, 'And they, having supposed it to be the land of Zarahemla, returned to the land of Nephi, having arrived in the borders of the land not many days before the coming of Ammon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-173', 'coc-bom-1908', 'Mosiah', 9, 173, 'Yea, they did mourn for their departure, for they knew not whither they had fled.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-174', 'coc-bom-1908', 'Mosiah', 9, 174, 'Now they would have gladly joined with them, for they themselves had entered into a covenant with God, to serve him and keep his commandments.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-175', 'coc-bom-1908', 'Mosiah', 9, 175, 'And now, since the coming of Ammon, King Limhi had also entered into a covenant with God, and also many of his people, to serve him and keep his commandments.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-178', 'coc-bom-1908', 'Mosiah', 9, 178, 'Now they were desirous to become even as Alma and his brethren, who had fled into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-9-181', 'coc-bom-1908', 'Mosiah', 9, 181, 'And now, all the study of Ammon and his people, and King Limhi and his people, was to deliver themselves out of the hands of the Lamanites and from bondage.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-10-3', 'coc-bom-1908', 'Mosiah', 10, 3, 'And it came to pass that they could find no way to deliver themselves out of bondage, except it were to take their women and children, and their flocks and their herds, and their tents and depart into the wilderness--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-10-4', 'coc-bom-1908', 'Mosiah', 10, 4, 'For the Lamanites being so numerous that it was impossible for the people of Limhi to contend with them, thinking to deliver themselves out of bondage by the sword.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-10-5', 'coc-bom-1908', 'Mosiah', 10, 5, 'Now it came to pass that Gideon went forth, and stood before the king, and said unto him, Now, O King, thou hast hitherto hearkened unto my words many times when we have been contending with our brethren, the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-10-7', 'coc-bom-1908', 'Mosiah', 10, 7, 'And the king granted unto him that he might speak.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-10-8', 'coc-bom-1908', 'Mosiah', 10, 8, 'And Gideon said unto him, Behold the back pass through the back wall, on the back side of the city.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-10-12', 'coc-bom-1908', 'Mosiah', 10, 12, 'And it came to pass that the king hearkened unto the words of Gideon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-10-16', 'coc-bom-1908', 'Mosiah', 10, 16, 'And after being many days in the wilderness, they arrived in the land of Zarahemla, and joined his people, and became his subjects.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-1', 'coc-bom-1908', 'Mosiah', 11, 1, 'Now Alma, having been warned of the Lord that the armies of King Noah would come upon them, and had made it known to his people, therefore, they gathered together their flocks, and took of their grain, and departed into the wilderness before the armies of King Noah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-2', 'coc-bom-1908', 'Mosiah', 11, 2, 'And the Lord did strengthen them, that the people of King Noah could not overtake them to destroy them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-3', 'coc-bom-1908', 'Mosiah', 11, 3, 'And they fled eight days'' journey into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-4', 'coc-bom-1908', 'Mosiah', 11, 4, 'And they came to a land, yea, even a very beautiful and pleasant land, a land of pure water.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-6', 'coc-bom-1908', 'Mosiah', 11, 6, 'And the people were desirous that Alma should be their king, for he was beloved by his people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-8', 'coc-bom-1908', 'Mosiah', 11, 8, 'Nevertheless, if it were possible that ye could always have just men to be your kings, it would be well for you to have a king.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-10', 'coc-bom-1908', 'Mosiah', 11, 10, 'Nevertheless, after much tribulation, the Lord did hear my cries, and did answer my prayers, and has made me an instrument in his hands in bringing so many of you to a knowledge of his truth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-11', 'coc-bom-1908', 'Mosiah', 11, 11, 'Nevertheless, in this I do not glory, for I am unworthy to glory of myself.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-14', 'coc-bom-1908', 'Mosiah', 11, 14, 'Yea, even out of the hands of King Noah and his people, and also from the bonds of iniquity, even so I desire that ye should stand fast in this liberty wherewith ye have been made free, and that ye trust no man to be a king over you,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-15', 'coc-bom-1908', 'Mosiah', 11, 15, 'And also trusting no one to be your teacher nor your minister, except he be a man of God, walking in his ways and keeping his commandments.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-16', 'coc-bom-1908', 'Mosiah', 11, 16, 'Thus did Alma teach his people that every man should love his neighbor as himself, that there should be no contention among them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-17', 'coc-bom-1908', 'Mosiah', 11, 17, 'And now, Alma was their high priest, he being the founder of their church.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-18', 'coc-bom-1908', 'Mosiah', 11, 18, 'And it came to pass that none received authority to preach or to teach, except it were by him from God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-20', 'coc-bom-1908', 'Mosiah', 11, 20, 'Therefore, they did watch over their people and did nourish them with things pertaining to righteousness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-24', 'coc-bom-1908', 'Mosiah', 11, 24, 'Nevertheless, whoever putteth his trust in him, the same shall be lifted up at the last day.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-25', 'coc-bom-1908', 'Mosiah', 11, 25, 'Yea, and thus it was with this people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-28', 'coc-bom-1908', 'Mosiah', 11, 28, 'For behold, it came to pass that while they were in the land of Helam, yea, in the city of Helam, while tilling the land round about, behold, an army of the Lamanites were in the borders of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-31', 'coc-bom-1908', 'Mosiah', 11, 31, 'Therefore, they hushed their fears and began to cry unto the Lord, that he would soften the hearts of the Lamanites, that they would spare them, and their wives, and their children.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-32', 'coc-bom-1908', 'Mosiah', 11, 32, 'And it came to pass that the Lord did soften the hearts of the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-34', 'coc-bom-1908', 'Mosiah', 11, 34, 'Now the armies of the Lamanites, which had followed after the people of King Limhi, had been lost in the wilderness for many days.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-36', 'coc-bom-1908', 'Mosiah', 11, 36, 'Now the name of the leader of those priests was Amulon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-38', 'coc-bom-1908', 'Mosiah', 11, 38, 'And the Lamanites had compassion on Amulon and his brethren and did not destroy them because of their wives.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-40', 'coc-bom-1908', 'Mosiah', 11, 40, 'And it came to pass that the Lamanites promised unto Alma and his brethren that if they would show them the way which led to the land of Nephi, that they would grant unto them their lives and their liberty.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-49', 'coc-bom-1908', 'Mosiah', 11, 49, 'And thus the language of Nephi began to be taught among all the people of the Lamanites.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-52', 'coc-bom-1908', 'Mosiah', 11, 52, 'And thus the Lamanites began to increase in riches, and began to trade one with another, and wax great, and began to be a cunning and a wise people, as to the wisdom of the world,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-53', 'coc-bom-1908', 'Mosiah', 11, 53, 'Yea, a very cunning people, delighting in all manner of wickedness and plunder, except it were among their own brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-56', 'coc-bom-1908', 'Mosiah', 11, 56, 'Yet he exercised authority over them, and put tasks upon them, and put taskmasters over them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-57', 'coc-bom-1908', 'Mosiah', 11, 57, 'And it came to pass that so great were their afflictions that they began to cry mightily to God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-62', 'coc-bom-1908', 'Mosiah', 11, 62, 'And this will I do, that ye may stand as witnesses for me hereafter and that ye may know of a surety that I, the Lord God, do visit my people in their afflictions.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-64', 'coc-bom-1908', 'Mosiah', 11, 64, 'Yea, the Lord did strengthen them that they could bear up their burdens with ease, and they did submit cheerfully and with patience to all the will of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-65', 'coc-bom-1908', 'Mosiah', 11, 65, 'And it came to pass that so great was their faith and their patience, that the voice of the Lord came unto them again, saying, Be of good comfort, for on the morrow I will deliver you out of bondage.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-66', 'coc-bom-1908', 'Mosiah', 11, 66, 'And he said unto Alma, Thou shalt go before this people, and I will go with thee and deliver this people out of bondage.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-68', 'coc-bom-1908', 'Mosiah', 11, 68, 'And in the morning the Lord caused a deep sleep to come upon the Lamanites, yea, and all their taskmasters were in a profound sleep.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-71', 'coc-bom-1908', 'Mosiah', 11, 71, 'For they were in bondage, and none could deliver them, except it were the Lord, their God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-72', 'coc-bom-1908', 'Mosiah', 11, 72, 'And they gave thanks to God, yea, all their men, and all their women, and all their children that could speak lifted their voices in the praises of their God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-75', 'coc-bom-1908', 'Mosiah', 11, 75, 'And it came to pass that they departed out of the valley and took their journey into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-77', 'coc-bom-1908', 'Mosiah', 11, 77, 'And now, King Mosiah caused that all the people should be gathered together.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-80', 'coc-bom-1908', 'Mosiah', 11, 80, 'And now, all the people of Nephi were assembled together and also all the people of Zarahemla, and they were gathered together in two bodies.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-82', 'coc-bom-1908', 'Mosiah', 11, 82, 'And he also read the account of Alma, and his brethren, and all their afflictions, from the time they left the land of Zarahemla until the time they returned again.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-84', 'coc-bom-1908', 'Mosiah', 11, 84, 'For when they beheld those that had been delivered out of bondage, they were filled with exceeding great joy.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-86', 'coc-bom-1908', 'Mosiah', 11, 86, 'And again, when they thought of the immediate goodness of God, and his power in delivering Alma and his brethren out of the hands of the Lamanites and of bondage, they did raise their voices and give thanks to God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-87', 'coc-bom-1908', 'Mosiah', 11, 87, 'And again, when they thought upon the Lamanites, who were their brethren, of their sinful and polluted state, they were filled with pain and anguish for the welfare of their souls.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-88', 'coc-bom-1908', 'Mosiah', 11, 88, 'And it came to pass that those who were the children of Amulon and his brethren, who had taken to wife the daughters of the Lamanites, were displeased with the conduct of their fathers,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-90', 'coc-bom-1908', 'Mosiah', 11, 90, 'And now, all the people of Zarahemla were numbered with the Nephites, and this because the kingdom had been conferred upon none but those who were descendants of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-91', 'coc-bom-1908', 'Mosiah', 11, 91, 'And now, it came to pass that when Mosiah had made an end of speaking and reading to the people, he desired that Alma should also speak to the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-92', 'coc-bom-1908', 'Mosiah', 11, 92, 'And Alma did speak unto them when they were assembled together in large bodies, and he went from one body to another, preaching unto the people repentance and faith on the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-93', 'coc-bom-1908', 'Mosiah', 11, 93, 'And he did exhort the people of Limhi and his brethren, all those that had been delivered out of bondage, that they should remember that it was the Lord that did deliver them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-97', 'coc-bom-1908', 'Mosiah', 11, 97, 'And it came to pass that King Mosiah granted unto Alma that he might establish churches throughout all the land of Zarahemla and gave him power to ordain priests and teachers over every church.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-99', 'coc-bom-1908', 'Mosiah', 11, 99, 'Every church having their priests and their teachers, and every priest preaching the word according as it was delivered to him by the mouth of Alma.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-101', 'coc-bom-1908', 'Mosiah', 11, 101, 'For there was nothing preached in all the churches except it were repentance and faith in God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-102', 'coc-bom-1908', 'Mosiah', 11, 102, 'And now, there were seven churches in the land of Zarahemla.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-104', 'coc-bom-1908', 'Mosiah', 11, 104, 'And the Lord did pour out his Spirit upon them, and they were blessed and prospered in the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-112', 'coc-bom-1908', 'Mosiah', 11, 112, 'Therefore, it became expedient that those who committed sin, that were in the church, should be admonished by the church.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-114', 'coc-bom-1908', 'Mosiah', 11, 114, 'Now King Mosiah had given Alma the authority over the church.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-121', 'coc-bom-1908', 'Mosiah', 11, 121, 'And it came to pass that after he had poured out his whole soul to God, the voice of the Lord came to him, saying, Blessed art thou, Alma, and blessed are they who were baptized in the waters of Mormon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-122', 'coc-bom-1908', 'Mosiah', 11, 122, 'Thou art blessed because of thy exceeding faith in the words alone of my servant Abinadi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-123', 'coc-bom-1908', 'Mosiah', 11, 123, 'And blessed are they because of their exceeding faith in the words alone which thou hast spoken unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-126', 'coc-bom-1908', 'Mosiah', 11, 126, 'And because thou hast inquired of me concerning the transgressor, thou art blessed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-136', 'coc-bom-1908', 'Mosiah', 11, 136, 'Therefore, I say unto you that he that will not hear my voice, the same shall ye not receive into my church, for him I will not receive at the last day.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-139', 'coc-bom-1908', 'Mosiah', 11, 139, 'Yea, and as often as my people repent, will I forgive them their trespasses against me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-142', 'coc-bom-1908', 'Mosiah', 11, 142, 'And it came to pass when Alma had heard these words, he wrote them down, that he might have them and that he might judge the people of that church according to the commandments of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-143', 'coc-bom-1908', 'Mosiah', 11, 143, 'And it came to pass that Alma went and judged those that had been taken in iniquity, according to the word of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-145', 'coc-bom-1908', 'Mosiah', 11, 145, 'And those that would not confess their sins and repent of their iniquity, the same were not numbered among the people of the church, and their names were blotted out.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-147', 'coc-bom-1908', 'Mosiah', 11, 147, 'And they began again to have peace and to prosper exceedingly in the affairs of the church, walking circumspectly before God, receiving many, and baptizing many.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-148', 'coc-bom-1908', 'Mosiah', 11, 148, 'And now, all these things did Alma and his fellow laborers do, who were over the church: walking in all diligence, teaching the word of God in all things, suffering all manner of afflictions, being persecuted by all those who did not belong to the church of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-151', 'coc-bom-1908', 'Mosiah', 11, 151, 'And Alma laid the case before their King Mosiah. And Mosiah consulted with his priests.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-152', 'coc-bom-1908', 'Mosiah', 11, 152, 'And it came to pass that King Mosiah sent a proclamation throughout the land round about, that there should not any unbeliever persecute any of those who belonged to the church of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-153', 'coc-bom-1908', 'Mosiah', 11, 153, 'And there was a strict command throughout all the churches that there should be no persecutions among them, that there should be an equality among all men, that they should let no pride nor haughtiness disturb their peace,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-157', 'coc-bom-1908', 'Mosiah', 11, 157, 'Yea, on the north and on the south, on the east and on the west, building large cities and villages in all quarters of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-158', 'coc-bom-1908', 'Mosiah', 11, 158, 'And the Lord did visit them and prosper them, and they became a large and a wealthy people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-161', 'coc-bom-1908', 'Mosiah', 11, 161, 'And he became a great hinderment to the prosperity of the church of God, stealing away the hearts of the people, causing much dissension among the people, giving a chance for the enemy of God to exercise his power over them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-162', 'coc-bom-1908', 'Mosiah', 11, 162, 'And now, it came to pass that while he was going about to destroy the church of God--for he did go about secretly with the sons of Mosiah, seeking to destroy the church and to lead astray the people of the Lord, contrary to the commandments of God, or even the king--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-164', 'coc-bom-1908', 'Mosiah', 11, 164, 'And so great was their astonishment that they fell to the earth and understood not the words which he spake unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-165', 'coc-bom-1908', 'Mosiah', 11, 165, 'Nevertheless, he cried again, saying, Alma, arise, and stand forth. For why persecuteth thou the church of God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-168', 'coc-bom-1908', 'Mosiah', 11, 168, 'For he has prayed with much faith concerning thee, that thou mightest be brought to the knowledge of the truth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-169', 'coc-bom-1908', 'Mosiah', 11, 169, 'Therefore, for this purpose have I come to convince thee of the power and authority of God, that the prayers of his servants might be answered according to their faith.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-170', 'coc-bom-1908', 'Mosiah', 11, 170, 'And now, behold, can ye dispute the power of God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-171', 'coc-bom-1908', 'Mosiah', 11, 171, 'For behold, doth not my voice shake the earth?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-172', 'coc-bom-1908', 'Mosiah', 11, 172, 'And can ye not also behold me before you?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-173', 'coc-bom-1908', 'Mosiah', 11, 173, 'And I am sent from God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-176', 'coc-bom-1908', 'Mosiah', 11, 176, 'And now, it came to pass that these were the last words which the angel spake unto Alma, and he departed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-178', 'coc-bom-1908', 'Mosiah', 11, 178, 'And they knew that there was nothing, save the power of God, that could shake the earth and cause it to tremble as though it would part asunder.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-180', 'coc-bom-1908', 'Mosiah', 11, 180, 'Therefore, he was taken by those that were with him and carried helpless, even until he was laid before his father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-182', 'coc-bom-1908', 'Mosiah', 11, 182, 'And he caused that a multitude should be gathered together, that they might witness what the Lord had done for his son and also for those that were with him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-184', 'coc-bom-1908', 'Mosiah', 11, 184, 'And also that his limbs might receive their strength, that the eyes of the people might be opened to see and know of the goodness and glory of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-185', 'coc-bom-1908', 'Mosiah', 11, 185, 'And it came to pass after they had fasted and prayed for the space of two days and two nights, the limbs of Alma received their strength, and he stood up and began to speak unto them, bidding them to be of good comfort.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-191', 'coc-bom-1908', 'Mosiah', 11, 191, 'My soul hath been redeemed from the gall of bitterness and bonds of iniquity.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-194', 'coc-bom-1908', 'Mosiah', 11, 194, 'I rejected my Redeemer and denied that which had been spoken of by our fathers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-195', 'coc-bom-1908', 'Mosiah', 11, 195, 'But now that they may foresee that he will come, and that he remembereth every creature of his creating,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-199', 'coc-bom-1908', 'Mosiah', 11, 199, 'And they shall quake, and tremble, and shrink beneath the glance of his all-searching eye.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-200', 'coc-bom-1908', 'Mosiah', 11, 200, 'And now, it came to pass that Alma began from this time forward to teach the people, and those who were with Alma at the time the angel appeared unto them,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-202', 'coc-bom-1908', 'Mosiah', 11, 202, 'But notwithstanding all this, they did impart much consolation to the church, confirming their faith, and exhorting them with long-suffering and much travail to keep the commandments of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-204', 'coc-bom-1908', 'Mosiah', 11, 204, 'And they traveled throughout all the land of Zarahemla and among all the people who were under the reign of King Mosiah, zealously striving to repair all the injuries which they had done to the church--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-205', 'coc-bom-1908', 'Mosiah', 11, 205, 'Confessing all their sins, and publishing all the things which they had seen, and explaining the prophecies and the scriptures to all who desired to hear them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-11-206', 'coc-bom-1908', 'Mosiah', 11, 206, 'And thus they were instruments in the hands of God in bringing many to the knowledge of the truth, yea, to the knowledge of their Redeemer.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-12-1', 'coc-bom-1908', 'Mosiah', 12, 1, 'Now it came to pass that after the sons of Mosiah had done all these things, they took a small number with them, and returned to their father, the king, and desired of him that he would grant unto them that they might, with those whom they had selected, go up to the land of Nephi,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-12-3', 'coc-bom-1908', 'Mosiah', 12, 3, 'And that perhaps they might cure them of their hatred towards the Nephites, that they might also be brought to rejoice in the Lord, their God,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-12-4', 'coc-bom-1908', 'Mosiah', 12, 4, 'That they might become friendly to one another, and that there should be no more contentions in all the land which the Lord, their God, had given them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-12-6', 'coc-bom-1908', 'Mosiah', 12, 6, 'Yea, even the very thoughts that any soul should endure endless torment did cause them to quake and tremble.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-12-7', 'coc-bom-1908', 'Mosiah', 12, 7, 'And thus did the Spirit of the Lord work upon them, for they were the very vilest of sinners.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-12-9', 'coc-bom-1908', 'Mosiah', 12, 9, 'And it came to pass that they did plead with their father many days that they might go up to the land of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-12-10', 'coc-bom-1908', 'Mosiah', 12, 10, 'And King Mosiah went and inquired of the Lord if he should let his sons go up among the Lamanites to preach the word.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-12-15', 'coc-bom-1908', 'Mosiah', 12, 15, 'Therefore, he took the records which were engraven on the plates of brass, and also the plates of Nephi, and all the things which he had kept and preserved according to the commandments of God,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-12-17', 'coc-bom-1908', 'Mosiah', 12, 17, 'And this he did because of the great anxiety of his people, for they were desirous beyond measure to know concerning those people who had been destroyed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-12-18', 'coc-bom-1908', 'Mosiah', 12, 18, 'And now, he translated them by the means of those two stones which were fastened into the two rims of a bow.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-12-21', 'coc-bom-1908', 'Mosiah', 12, 21, 'And whosoever has these things is called seer, after the manner of old times.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-12-23', 'coc-bom-1908', 'Mosiah', 12, 23, 'And they were scattered abroad upon the face of all the earth, yea, and even from that time until the creation of Adam.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-12-25', 'coc-bom-1908', 'Mosiah', 12, 25, 'Nevertheless, it gave them much knowledge, in the which they did rejoice.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-1', 'coc-bom-1908', 'Mosiah', 13, 1, 'And now, as I said unto you, that after King Mosiah had done these things, he took the plates of brass and all the things which he had kept and conferred them upon Alma, who was the son of Alma--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-2', 'coc-bom-1908', 'Mosiah', 13, 2, 'Yea, all the records and also the interpreters--and conferred them upon him, and commanded him that he should keep and preserve them, and also keep a record of the people, handing them down from one generation to another, even as they had been handed down from the time that Lehi left Jerusalem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-3', 'coc-bom-1908', 'Mosiah', 13, 3, 'Now when Mosiah had done this, he sent out through all the land, among all the people, desiring to know their will concerning who should be their king.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-4', 'coc-bom-1908', 'Mosiah', 13, 4, 'And it came to pass that the voice of the people came, saying, We are desirous that Aaron, thy son, should be our king and our ruler.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-8', 'coc-bom-1908', 'Mosiah', 13, 8, 'Now I declare unto you that he to whom the kingdom doth rightly belong has declined and will not take upon him the kingdom.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-10', 'coc-bom-1908', 'Mosiah', 13, 10, 'And who knoweth but what my son, to whom the kingdom doth belong, should turn to be angry and draw away a part of this people after him, which would cause wars and contentions among you, which would be the cause of shedding much blood and perverting the way of the Lord, yea, and destroy the souls of many people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-12', 'coc-bom-1908', 'Mosiah', 13, 12, 'And if my son should turn again to his pride and vain things, he would recall the things which he had said and claim his right to the kingdom, which would cause him and also this people to commit much sin.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-13', 'coc-bom-1908', 'Mosiah', 13, 13, 'And now, let us be wise, and look forward to these things, and do that which will make for the peace of this people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-17', 'coc-bom-1908', 'Mosiah', 13, 17, 'Therefore, if it were possible that ye could have just men to be your kings, who would establish the laws of God and judge this people according to his commandments--yea, if ye could have men for your kings who would do even as my father Benjamin did for this people--I say unto you, If this could always be the case, then it would be expedient that ye should always have kings to rule over you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-18', 'coc-bom-1908', 'Mosiah', 13, 18, 'And even I myself have labored, with all the power and faculties which I have possessed, to teach you the commandments of God and to establish peace throughout the land,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-20', 'coc-bom-1908', 'Mosiah', 13, 20, 'And whosoever has committed iniquity, him have I punished according to the crime which he has committed, according to the law which has been given to us by our fathers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-21', 'coc-bom-1908', 'Mosiah', 13, 21, 'Now I say unto you that because all men are not just, it is not expedient that ye should have a king or kings to rule over you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-22', 'coc-bom-1908', 'Mosiah', 13, 22, 'For behold, how much iniquity doth one wicked king cause to be committed! yea, and what great destruction!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-23', 'coc-bom-1908', 'Mosiah', 13, 23, 'Yea, remember King Noah, his wickedness and his abominations, and also the wickedness and abominations of his people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-24', 'coc-bom-1908', 'Mosiah', 13, 24, 'Behold, what great destruction did come upon them! And also because of their iniquities, they were brought into bondage.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-25', 'coc-bom-1908', 'Mosiah', 13, 25, 'And were it not for the interposition of their all-wise Creator, and this because of their sincere repentance, they must unavoidably have remained in bondage until now.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-27', 'coc-bom-1908', 'Mosiah', 13, 27, 'And thus doth the Lord work with his power in all cases among the children of men, extending the arm of mercy towards them that put their trust in him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-28', 'coc-bom-1908', 'Mosiah', 13, 28, 'And behold, now I say unto you, Ye cannot dethrone an iniquitous king, save it be through much contention and the shedding of much blood.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-32', 'coc-bom-1908', 'Mosiah', 13, 32, 'And thus an unrighteous king doth pervert the ways of all righteousness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-34', 'coc-bom-1908', 'Mosiah', 13, 34, 'Therefore, choose you by the voice of this people, judges, that ye may be judged according to the laws which have been given you by our fathers, which are correct and which were given them by the hand of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-36', 'coc-bom-1908', 'Mosiah', 13, 36, 'Therefore, this shall ye observe and make it your law--to do your business by the voice of the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-38', 'coc-bom-1908', 'Mosiah', 13, 38, 'Yea, then is the time he will visit you with great destruction, even as he has hitherto visited this land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-40', 'coc-bom-1908', 'Mosiah', 13, 40, 'If your higher judges do not judge righteous judgments, ye shall cause that a small number of your lower judges should be gathered together, and they shall judge your higher judges according to the voice of the people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-42', 'coc-bom-1908', 'Mosiah', 13, 42, 'And I command you to do these things and that ye have no king--that if these people commit sins and iniquities, they shall be answered upon their own heads.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-45', 'coc-bom-1908', 'Mosiah', 13, 45, 'But I desire that this land be a land of liberty, and every man may enjoy his rights and privileges alike, so long as the Lord sees fit, that we may live and inherit the land,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-46', 'coc-bom-1908', 'Mosiah', 13, 46, 'Yea, even as long as any of our posterity remains upon the face of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-47', 'coc-bom-1908', 'Mosiah', 13, 47, 'And many more things did King Mosiah write unto them, unfolding unto them all the trials and troubles of a righteous king,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-50', 'coc-bom-1908', 'Mosiah', 13, 50, 'And he also unfolded unto them all the disadvantages they labored under by having an unrighteous king to rule over them,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-51', 'coc-bom-1908', 'Mosiah', 13, 51, 'Yea, all his iniquities and abominations, and all the wars, and contentions, and bloodshed, and the stealing, and the plundering, and the committing of whoredoms, and all manner of iniquities, which cannot be enumerated,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-52', 'coc-bom-1908', 'Mosiah', 13, 52, 'Telling them that these things ought not to be, that they were expressly repugnant to the commandments of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-55', 'coc-bom-1908', 'Mosiah', 13, 55, 'Yea, and every man expressed a willingness to answer for his own sins.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-57', 'coc-bom-1908', 'Mosiah', 13, 57, 'And they were exceedingly rejoiced because of the liberty which had been granted unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-59', 'coc-bom-1908', 'Mosiah', 13, 59, 'For they did not look upon him as a tyrant, who was seeking for gain, yea, for that lucre which doth corrupt the soul,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-61', 'coc-bom-1908', 'Mosiah', 13, 61, 'Therefore, they did esteem him, yea, exceedingly, beyond measure.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-63', 'coc-bom-1908', 'Mosiah', 13, 63, 'And it came to pass that Alma was appointed to be the chief judge, he being also the high priest--his father having conferred the office upon him and had given him the charge concerning all the affairs of the church.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:mosiah-13-66', 'coc-bom-1908', 'Mosiah', 13, 66, 'And now, it came to pass that his father died, being eighty and two years old, having lived to fulfill the commandments of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-1-2', 'coc-bom-1908', 'Jacob', 1, 2, 'And he gave me, Jacob, a commandment that I should write upon these plates a few of the things which I considered to be most precious, that I should not touch, save it were lightly, concerning the history of this people, which are called the people of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-1-3', 'coc-bom-1908', 'Jacob', 1, 3, 'For he said that the history of his people should be engraven upon his other plates and that I should preserve these plates and hand them down unto my seed from generation to generation.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-1-5', 'coc-bom-1908', 'Jacob', 1, 5, 'For because of faith and great anxiety, it truly had been made manifest unto us concerning our people what things should happen unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-1-7', 'coc-bom-1908', 'Jacob', 1, 7, 'Wherefore, we labored diligently among our people, that we might persuade them to come unto Christ and partake of the goodness of God, that they might enter into his rest, lest by any means he should swear in his wrath they should not enter in, as in the provocation in the days of temptation while the children of Israel were in the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-1-10', 'coc-bom-1908', 'Jacob', 1, 10, 'The people, having loved Nephi exceedingly, he having been a great protector for them, having wielded the sword of Laban in their defense, and having labored in all his days for their welfare, wherefore, the people were desirous to retain in remembrance his name.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-1-12', 'coc-bom-1908', 'Jacob', 1, 12, 'And it came to pass that Nephi died.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-1-17', 'coc-bom-1908', 'Jacob', 1, 17, 'Wherefore, I, Jacob, gave unto them these words as I taught them in the temple, having firstly obtained mine errand from the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-1-18', 'coc-bom-1908', 'Jacob', 1, 18, 'For I, Jacob, and my brother Joseph had been consecrated priests and teachers of this people by the hand of Nephi.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-1', 'coc-bom-1908', 'Jacob', 2, 1, 'The words which Jacob, the brother of Nephi, spake unto the people of Nephi, after the death of Nephi:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-4', 'coc-bom-1908', 'Jacob', 2, 4, 'For behold, as yet, ye have been obedient unto the word of the Lord which I have given unto you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-5', 'coc-bom-1908', 'Jacob', 2, 5, 'But behold, hearken ye unto me and know that, by the help of the all-powerful Creator of heaven and earth, I can tell you concerning your thoughts, how that ye are beginning to labor in sin, which sin appeareth very abominable unto me, yea, and abominable unto God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-8', 'coc-bom-1908', 'Jacob', 2, 8, 'And it supposeth me that they have come up hither to hear the pleasing word of God, yea, the word which healeth the wounded soul.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-10', 'coc-bom-1908', 'Jacob', 2, 10, 'And those which have not been wounded, instead of feasting upon the pleasing word of God, have daggers placed to pierce their souls and wound their delicate minds.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-11', 'coc-bom-1908', 'Jacob', 2, 11, 'But, notwithstanding the greatness of the task, I must do according to the strict commands of God and tell you concerning your wickedness and abominations, in the presence of the pure in heart and the broken heart and under the glance of the piercing eye of the Almighty God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-12', 'coc-bom-1908', 'Jacob', 2, 12, 'Wherefore, I must tell you the truth according to the plainness of the word of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-13', 'coc-bom-1908', 'Jacob', 2, 13, 'For behold, as I inquired of the Lord, thus came the word unto me, saying, Jacob, get thou up into the temple on the morrow and declare the word which I shall give thee unto this people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-14', 'coc-bom-1908', 'Jacob', 2, 14, 'And now, behold, my brethren, this is the word which I declare unto you: that many of you have begun to search for gold, and for silver, and all manner of precious ores, in the which this land, which is a land of promise unto you and to your seed, doth abound most plentifully.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-16', 'coc-bom-1908', 'Jacob', 2, 16, 'And because some of you have obtained more abundantly than that of your brethren, ye are lifted up in the pride of your hearts, and wear stiff necks and high heads because of the costliness of your apparel, and persecute your brethren because ye suppose that ye are better than they.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-17', 'coc-bom-1908', 'Jacob', 2, 17, 'And now, my brethren, do ye suppose that God justifieth you in this thing? Behold, I say unto you, Nay.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-19', 'coc-bom-1908', 'Jacob', 2, 19, 'Oh, that he would show you that he can pierce you, and with one glance of his eye he can smite you to the dust.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-20', 'coc-bom-1908', 'Jacob', 2, 20, 'Oh, that he would rid you from this iniquity and abomination.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-21', 'coc-bom-1908', 'Jacob', 2, 21, 'And oh, that ye would listen unto the word of his commands and let not this pride of your hearts destroy your souls.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-22', 'coc-bom-1908', 'Jacob', 2, 22, 'Think of your brethren like unto yourselves, and be familiar with all and free with your substance, that they may be rich like unto you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-23', 'coc-bom-1908', 'Jacob', 2, 23, 'But before ye seek for riches, seek ye for the kingdom of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-25', 'coc-bom-1908', 'Jacob', 2, 25, 'And now, my brethren, I have spoken unto you concerning pride. And those of you which have afflicted your neighbor and persecuted him because ye were proud in your hearts of the things which God hath given you, what say ye of it?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-26', 'coc-bom-1908', 'Jacob', 2, 26, 'Do ye not suppose that such things are abominable unto him who created all flesh?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-27', 'coc-bom-1908', 'Jacob', 2, 27, 'And the one being is as precious in his sight as the other.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-29', 'coc-bom-1908', 'Jacob', 2, 29, 'And now, I make an end of speaking unto you concerning this pride.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-30', 'coc-bom-1908', 'Jacob', 2, 30, 'And were it not that I must speak unto you concerning a grosser crime, my heart would rejoice exceedingly because of you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-31', 'coc-bom-1908', 'Jacob', 2, 31, 'But the word of God burdens me because of your grosser crimes.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-33', 'coc-bom-1908', 'Jacob', 2, 33, 'Behold, David and Solomon truly had many wives and concubines, which thing was abominable before me, saith the Lord,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-34', 'coc-bom-1908', 'Jacob', 2, 34, 'Wherefore, thus saith the Lord, I have led this people forth out of the land of Jerusalem by the power of mine arm, that I might raise up unto me a righteous branch from the fruit of the loins of Joseph.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-35', 'coc-bom-1908', 'Jacob', 2, 35, 'Wherefore, I, the Lord God, will not suffer that this people shall do like unto them of old.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-38', 'coc-bom-1908', 'Jacob', 2, 38, 'Wherefore, this people shall keep my commandments, saith the Lord of hosts, or cursed be the land for their sakes.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-43', 'coc-bom-1908', 'Jacob', 2, 43, 'For they shall not commit whoredoms like unto them of old, saith the Lord of hosts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-45', 'coc-bom-1908', 'Jacob', 2, 45, 'Behold, ye have done greater iniquity than the Lamanites, our brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-47', 'coc-bom-1908', 'Jacob', 2, 47, 'And because of the strictness of the word of God, which cometh down against you, many hearts died, pierced with deep wounds.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-48', 'coc-bom-1908', 'Jacob', 2, 48, 'But behold, I, Jacob, would speak unto you that are pure in heart.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-52', 'coc-bom-1908', 'Jacob', 2, 52, 'And the Lamanites which are not filthy like unto you (nevertheless, they are cursed with a sore cursing) shall scourge you even unto destruction.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-53', 'coc-bom-1908', 'Jacob', 2, 53, 'And the time speedily cometh that, except ye repent, they shall possess the land of your inheritance, and the Lord God will lead away the righteous out from among you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-58', 'coc-bom-1908', 'Jacob', 2, 58, 'And their unbelief and their hatred towards you is because of the iniquity of their fathers. Wherefore, how much better are you than they in the sight of your great Creator?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-59', 'coc-bom-1908', 'Jacob', 2, 59, 'O my brethren, I fear that unless ye shall repent of your sins, that their skins will be whiter than yours when ye shall be brought with them before the throne of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-61', 'coc-bom-1908', 'Jacob', 2, 61, 'But ye shall remember your own filthiness and remember that their filthiness came because of their fathers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-63', 'coc-bom-1908', 'Jacob', 2, 63, 'And also, remember that ye may, because of your filthiness, bring your children unto destruction, and their sins be heaped upon your heads at the last day.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-65', 'coc-bom-1908', 'Jacob', 2, 65, 'And loose yourselves from the pains of hell, that ye may not become angels to the devil, to be cast into that lake of fire and brimstone, which is the second death.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-68', 'coc-bom-1908', 'Jacob', 2, 68, 'But many of their proceedings are written upon the larger plates, and their wars, and their contentions, and the reigns of their kings.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-2-70', 'coc-bom-1908', 'Jacob', 2, 70, 'And I make an end of speaking these words.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-1', 'coc-bom-1908', 'Jacob', 3, 1, 'Now behold, it came to pass that I, Jacob, having ministered much unto my people in word (and I cannot write but little of my words because of the difficulty of engraving our words upon plates), and we know that the things which we write upon plates must remain--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-8', 'coc-bom-1908', 'Jacob', 3, 8, 'Nevertheless, the Lord God showeth us our weakness, that we may know that it is by his grace and his great condescensions unto the children of men that we have power to do these things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-9', 'coc-bom-1908', 'Jacob', 3, 9, 'Behold, great and marvelous are the works of the Lord!', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-12', 'coc-bom-1908', 'Jacob', 3, 12, 'For behold, by the power of his word, man came upon the face of the earth, which earth was created by the power of his word.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-13', 'coc-bom-1908', 'Jacob', 3, 13, 'Wherefore, if God, being able to speak and the world was, and to speak and man was created, oh, then, why not able to command the earth, or the workmanship of his hands upon the face of it, according to his will and pleasure.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-14', 'coc-bom-1908', 'Jacob', 3, 14, 'Wherefore, brethren, seek not to counsel the Lord but to take counsel from his hand.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-16', 'coc-bom-1908', 'Jacob', 3, 16, 'Wherefore, beloved brethren, be reconciled unto him through the atonement of Christ, his Only Begotten Son,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-17', 'coc-bom-1908', 'Jacob', 3, 17, 'That ye may obtain a resurrection, according to the power of the resurrection which is in Christ, and be presented as the firstfruits of Christ unto God, having faith, and obtained a good hope of glory in him before he manifesteth himself in the flesh.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-18', 'coc-bom-1908', 'Jacob', 3, 18, 'And now, beloved, marvel not that I tell you these things. For why not speak of the atonement of Christ, and attain to a perfect knowledge of him, as to attain to the knowledge of a resurrection and the world to come?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-24', 'coc-bom-1908', 'Jacob', 3, 24, 'For God hath taken away his plainness from them and delivered unto them many things which they cannot understand because they desired it.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-25', 'coc-bom-1908', 'Jacob', 3, 25, 'And because they desired it, God hath done it, that they may stumble.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-27', 'coc-bom-1908', 'Jacob', 3, 27, 'But behold, according to the scriptures, this stone shall become the great, and the last, and the only sure foundation upon which the Jews can build.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-28', 'coc-bom-1908', 'Jacob', 3, 28, 'And now, my beloved, how is it possible that these, after having rejected the sure foundation, can ever build upon it, that it may become the head of their corner?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-29', 'coc-bom-1908', 'Jacob', 3, 29, 'Behold, my beloved brethren, I will unfold this mystery unto you if I do not by any means get shaken from my firmness in the Spirit and stumble because of my overanxiety for you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-30', 'coc-bom-1908', 'Jacob', 3, 30, 'Behold, my brethren, do ye not remember to have read the words of the prophet Zenos, which spake unto the house of Israel, saying, Hearken, O ye house of Israel, and hear the words of me, a prophet of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-33', 'coc-bom-1908', 'Jacob', 3, 33, 'And it came to pass that he pruned it, and digged about it, and nourished it, according to his word.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-39', 'coc-bom-1908', 'Jacob', 3, 39, 'Wherefore, I will take these young and tender branches, and I will graft them whithersoever I will.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-41', 'coc-bom-1908', 'Jacob', 3, 41, 'And these, which I have plucked off, I will cast into the fire and burn them, that they may not cumber the ground of my vineyard.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-42', 'coc-bom-1908', 'Jacob', 3, 42, 'And it came to pass that the servant of the Lord of the vineyard did according to the word of the Lord of the vineyard and grafted in the branches of the wild olive tree.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-44', 'coc-bom-1908', 'Jacob', 3, 44, 'Wherefore, that perhaps I might preserve the roots thereof that they perish not, that I might preserve them unto myself, I have done this thing.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-48', 'coc-bom-1908', 'Jacob', 3, 48, 'And it came to pass that the Lord of the vineyard went his way and hid the natural branches of the tame olive tree in the nethermost parts of the vineyard--some in one and some in another, according to his will and pleasure.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-49', 'coc-bom-1908', 'Jacob', 3, 49, 'And it came to pass that a long time passed away, and the Lord of the vineyard said unto his servant, Come, let us go down into the vineyard, that we may labor in the vineyard.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-50', 'coc-bom-1908', 'Jacob', 3, 50, 'And it came to pass that the Lord of the vineyard and also the servant went down into the vineyard to labor.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-55', 'coc-bom-1908', 'Jacob', 3, 55, 'And because of the much strength of the root thereof, the wild branches have brought forth tame fruit.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-56', 'coc-bom-1908', 'Jacob', 3, 56, 'Now, if we had not grafted in these branches, the tree thereof would have perished.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-59', 'coc-bom-1908', 'Jacob', 3, 59, 'And it came to pass that they went forth whither the master of the vineyard had hid the natural branches of the tree, and he said unto the servant, Behold these.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-62', 'coc-bom-1908', 'Jacob', 3, 62, 'For behold, said he, this long time have I nourished it, and it hath brought forth much fruit.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-63', 'coc-bom-1908', 'Jacob', 3, 63, 'And it came to pass that the servant said unto his master, How comest thou hither to plant this tree, or this branch of the tree? For behold, it was the poorest spot in all the land of thy vineyard.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-69', 'coc-bom-1908', 'Jacob', 3, 69, 'And it came to pass that the Lord of the vineyard said unto the servant, Pluck off the branches that have not brought forth good fruit and cast them into the fire.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-70', 'coc-bom-1908', 'Jacob', 3, 70, 'But behold, the servant said unto him, Let us prune it, and dig about it, and nourish it a little longer, that perhaps it may bring forth good fruit unto thee, that thou canst lay it up against the season.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-71', 'coc-bom-1908', 'Jacob', 3, 71, 'And it came to pass that the Lord of the vineyard and the servant of the Lord of the vineyard did nourish all the fruit of the vineyard.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-75', 'coc-bom-1908', 'Jacob', 3, 75, 'And it came to pass that the Lord of the vineyard did taste of the fruit, every sort according to its number.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-77', 'coc-bom-1908', 'Jacob', 3, 77, 'But behold, this time it hath brought forth much fruit, and there is none of it which is good.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-79', 'coc-bom-1908', 'Jacob', 3, 79, 'And the Lord of the vineyard said unto the servant, What shall we do unto the tree, that I may preserve again good fruit thereof unto mine own self?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-85', 'coc-bom-1908', 'Jacob', 3, 85, 'And it came to pass that the Lord of the vineyard said unto his servant, Let us go down into the nethermost parts of the vineyard and behold if the natural branches have also brought forth evil fruit.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-86', 'coc-bom-1908', 'Jacob', 3, 86, 'And it came to pass that they went down into the nethermost parts of the vineyard.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-88', 'coc-bom-1908', 'Jacob', 3, 88, 'And the wild fruit of the last had overcome that part of the tree which brought forth good fruit, even that the branch had withered away and died.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-89', 'coc-bom-1908', 'Jacob', 3, 89, 'And it came to pass that the Lord of the vineyard wept and said unto the servant, What could I have done more for my vineyard?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-90', 'coc-bom-1908', 'Jacob', 3, 90, 'Behold, I knew that all the fruit of the vineyard, save it were these, had become corrupted.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-91', 'coc-bom-1908', 'Jacob', 3, 91, 'And now, these which once have brought forth good fruit have also become corrupted.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-92', 'coc-bom-1908', 'Jacob', 3, 92, 'And now, all the trees of my vineyard are good for nothing, save it be to be hewn down and cast into the fire.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-93', 'coc-bom-1908', 'Jacob', 3, 93, 'And behold, this last, whose branch hath withered away, I did plant in a good spot of ground, yea, even that which was choice unto me above all other parts of the land of my vineyard.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-94', 'coc-bom-1908', 'Jacob', 3, 94, 'And thou beheldest that I also cut down that which cumbered this spot of ground, that I might plant this tree in the stead thereof.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-96', 'coc-bom-1908', 'Jacob', 3, 96, 'And because I plucked not the branches thereof and cast them into the fire, behold, they have overcome the good branch, that it has withered away.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-97', 'coc-bom-1908', 'Jacob', 3, 97, 'And now, behold, notwithstanding all the care which we have taken of my vineyard, the trees thereof have become corrupted, that they bring forth no good fruit.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-98', 'coc-bom-1908', 'Jacob', 3, 98, 'And these I had hoped to preserve, to have laid up fruit thereof, against the season, unto mine own self.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-100', 'coc-bom-1908', 'Jacob', 3, 100, 'But what could I have done more in my vineyard?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-101', 'coc-bom-1908', 'Jacob', 3, 101, 'Have I slackened my hand, that I have not nourished it?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-103', 'coc-bom-1908', 'Jacob', 3, 103, 'And it grieveth me that I should hew down all the trees of my vineyard and cast them into the fire, that they should be burned.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-104', 'coc-bom-1908', 'Jacob', 3, 104, 'Who is it that has corrupted my vineyard?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-105', 'coc-bom-1908', 'Jacob', 3, 105, 'And it came to pass that the servant said unto his master, Is it not the loftiness of thy vineyard?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-106', 'coc-bom-1908', 'Jacob', 3, 106, 'Have not the branches thereof overcome the roots, which are good?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-107', 'coc-bom-1908', 'Jacob', 3, 107, 'And because the branches have overcome the roots thereof, behold, they grew faster than the strength of the roots, taking strength unto themselves.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-108', 'coc-bom-1908', 'Jacob', 3, 108, 'Behold, I say, Is not this the cause that the trees of thy vineyard have become corrupted?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-110', 'coc-bom-1908', 'Jacob', 3, 110, 'But behold, the servant said unto the Lord of the vineyard, Spare it a little longer.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-113', 'coc-bom-1908', 'Jacob', 3, 113, 'And let us pluck from the tree those branches whose fruit is most bitter and graft in the natural branches of the tree in the stead thereof.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-114', 'coc-bom-1908', 'Jacob', 3, 114, 'And this will I do, that the tree may not perish, that perhaps I may preserve unto myself the roots thereof for mine own purpose.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-116', 'coc-bom-1908', 'Jacob', 3, 116, 'Wherefore, that I may preserve them also for mine own purpose, I will take of the branches of this tree, and I will graft them in unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-117', 'coc-bom-1908', 'Jacob', 3, 117, 'Yea, I will graft in unto them the branches of their mother tree, that I may preserve the roots also unto mine own self, that when they shall be sufficiently strong, perhaps they may bring forth good fruit unto me, and I may yet have glory in the fruit of my vineyard.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-119', 'coc-bom-1908', 'Jacob', 3, 119, 'And they also took of the natural trees which had become wild and grafted into their mother tree.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-122', 'coc-bom-1908', 'Jacob', 3, 122, 'And this I do, that perhaps the roots thereof may take strength because of their goodness, and because of the change of the branches, that the good may overcome the evil--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-123', 'coc-bom-1908', 'Jacob', 3, 123, 'And because that I have preserved the natural branches and the roots thereof, and that I have grafted in the natural branches again into their mother tree and have preserved the roots of their mother tree--that perhaps the trees of my vineyard may bring forth again good fruit,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-125', 'coc-bom-1908', 'Jacob', 3, 125, 'Wherefore, go to, and call servants, that we may labor diligently with our mights in the vineyard, that we may prepare the way, that I may bring forth again the natural fruit, which natural fruit is good and the most precious above all other fruit.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-131', 'coc-bom-1908', 'Jacob', 3, 131, 'And ye shall not clear away the bad thereof all at once, lest the roots thereof should be too strong for the graft, and the graft thereof shall perish, and I lose the trees of my vineyard.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-134', 'coc-bom-1908', 'Jacob', 3, 134, 'And thus will I bring them together again, that they shall bring forth the natural fruit, and they shall be one.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-137', 'coc-bom-1908', 'Jacob', 3, 137, 'And the Lord of the vineyard said unto them, Go to, and labor in the vineyard with your mights.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-139', 'coc-bom-1908', 'Jacob', 3, 139, 'And if ye labor with your mights with me, ye shall have joy in the fruit which I shall lay up unto myself, against the time which will soon come.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-147', 'coc-bom-1908', 'Jacob', 3, 147, 'For because ye have been diligent in laboring with me in my vineyard, and have kept my commandments, and have brought unto me again the natural fruit, that my vineyard is no more corrupted and the bad is cast away, behold, ye shall have joy with me because of the fruit of my vineyard.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-3-150', 'coc-bom-1908', 'Jacob', 3, 150, 'Wherefore, I will lay up unto mine own self of the fruit for a long time, according to that which I have spoken.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-4-1', 'coc-bom-1908', 'Jacob', 4, 1, 'And now, behold, my brethren, as I said unto you that I would prophesy, behold, this is my prophecy:', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-4-2', 'coc-bom-1908', 'Jacob', 4, 2, 'That the things which this prophet Zenos spake concerning the house of Israel, in the which he likened them unto a tame olive tree, must surely come to pass.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-4-5', 'coc-bom-1908', 'Jacob', 4, 5, 'And the world shall be burned with fire.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-4-8', 'coc-bom-1908', 'Jacob', 4, 8, 'Wherefore, my beloved brethren, I beseech of you in words of soberness that ye would repent, and come with full purpose of heart, and cleave unto God as he cleaveth unto you.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-4-9', 'coc-bom-1908', 'Jacob', 4, 9, 'And while his arm of mercy is extended towards you in the light of the day, harden not your hearts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-4-10', 'coc-bom-1908', 'Jacob', 4, 10, 'Yea, today if ye will hear his voice, harden not your hearts. For why will ye die?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-4-11', 'coc-bom-1908', 'Jacob', 4, 11, 'For behold, after ye have been nourished by the good word of God all the day long, will ye bring forth evil fruit, that ye must be hewn down and cast into the fire?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-4-12', 'coc-bom-1908', 'Jacob', 4, 12, 'Behold, will ye reject these words?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-4-13', 'coc-bom-1908', 'Jacob', 4, 13, 'Will ye reject the words of the prophets and will ye reject all the words which have been spoken concerning Christ, after so many have spoken concerning him? and deny the good word of Christ, and the power of God, and the gift of the Holy Ghost, and quench the Holy Spirit? and make a mock of the great plan of redemption which hath been laid for you?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-4-14', 'coc-bom-1908', 'Jacob', 4, 14, 'Know ye not that if ye will do these things, that the power of the redemption and the resurrection which is in Christ will bring you to stand with shame and awful guilt before the bar of God?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-4-15', 'coc-bom-1908', 'Jacob', 4, 15, 'And according to the power of justice, for justice cannot be denied, ye must go away into that lake of fire and brimstone, whose flames are unquenchable, and whose smoke ascendeth up forever and ever, which lake of fire and brimstone is endless torment.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-4-17', 'coc-bom-1908', 'Jacob', 4, 17, 'Oh, be wise. What can I say more?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-4-18', 'coc-bom-1908', 'Jacob', 4, 18, 'Finally, I bid you farewell until I shall meet you before the pleasing bar of God, which bar striketh the wicked with awful dread and fear. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-1', 'coc-bom-1908', 'Jacob', 5, 1, 'And now, it came to pass after some years had passed away, there came a man among the people of Nephi whose name was Sherem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-2', 'coc-bom-1908', 'Jacob', 5, 2, 'And it came to pass that he began to preach among the people and to declare unto them that there should be no Christ.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-5', 'coc-bom-1908', 'Jacob', 5, 5, 'And he, knowing that I, Jacob, had faith in Christ who should come, he sought much opportunity that he might come unto me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-10', 'coc-bom-1908', 'Jacob', 5, 10, 'And ye have led away much of this people, that they pervert the right way of God and keep not the law of Moses, which is the right way, and convert the law of Moses into the worship of a being which ye say shall come many hundred years hence.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-12', 'coc-bom-1908', 'Jacob', 5, 12, 'And after this manner did Sherem contend against me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-13', 'coc-bom-1908', 'Jacob', 5, 13, 'But behold, the Lord God poured in his Spirit into my soul, insomuch that I did confound him in all his words.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-14', 'coc-bom-1908', 'Jacob', 5, 14, 'And I said unto him, Deniest thou the Christ which shall come?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-16', 'coc-bom-1908', 'Jacob', 5, 16, 'And I said unto him, Believest thou the scriptures?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-17', 'coc-bom-1908', 'Jacob', 5, 17, 'And he said, Yea.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-19', 'coc-bom-1908', 'Jacob', 5, 19, 'Behold, I say unto you that none of the prophets have written, nor prophesied, save they have spoken concerning this Christ.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-21', 'coc-bom-1908', 'Jacob', 5, 21, 'Wherefore, I know if there should be no atonement made, all mankind must be lost.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-22', 'coc-bom-1908', 'Jacob', 5, 22, 'And it came to pass that he said unto me, Show me a sign by this power of the Holy Ghost, in the which ye know so much.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-23', 'coc-bom-1908', 'Jacob', 5, 23, 'And I said unto him, What am I, that I should tempt God to show unto thee a sign in the thing which thou knowest to be true?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-24', 'coc-bom-1908', 'Jacob', 5, 24, 'Yet thou wilt deny it because thou art of the devil.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-26', 'coc-bom-1908', 'Jacob', 5, 26, 'And thy will, O Lord, be done, and not mine.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-27', 'coc-bom-1908', 'Jacob', 5, 27, 'And it came to pass that when I, Jacob, had spoken these words, the power of the Lord came upon him, insomuch that he fell to the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-28', 'coc-bom-1908', 'Jacob', 5, 28, 'And it came to pass that he was nourished for the space of many days.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-31', 'coc-bom-1908', 'Jacob', 5, 31, 'And he spake plainly unto them that he had been deceived by the power of the devil.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-32', 'coc-bom-1908', 'Jacob', 5, 32, 'And he spake of hell, and of eternity, and of eternal punishment.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-43', 'coc-bom-1908', 'Jacob', 5, 43, 'That the time passed away with us, and also our lives passed away, like as it were unto us a dream--we being a lonesome and a solemn people, wanderers, cast out from Jerusalem,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-47', 'coc-bom-1908', 'Jacob', 5, 47, 'And I make an end of my writing upon these plates, which writing has been small.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-bom-1908:jacob-5-48', 'coc-bom-1908', 'Jacob', 5, 48, 'And to the reader I bid farewell, hoping that many of my brethren may read my words. Brethren, adieu.', 'standard')
ON CONFLICT (id) DO NOTHING;

