INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-dc-2017:section-12-1c', 'coc-dc-2017', 'Doctrine and Covenants', 12, 3, 'therefore, give heed unto my word.', 'standard')
