INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-dc-2017:section-12-3a', 'coc-dc-2017', 'Doctrine and Covenants', 12, 6, 'Seek to bring forth and establish my Zion.', 'standard')
