INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-dc-2017:section-12-4a', 'coc-dc-2017', 'Doctrine and Covenants', 12, 8, 'And it shall come to pass that if you shall ask the Father in my name, in faith believing, you shall receive the Holy Ghost, which giveth utterance, that you may stand as a witness of the things of which you shall both hear and see,', 'standard')
