INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-dc-2017:section-12-4b', 'coc-dc-2017', 'Doctrine and Covenants', 12, 9, 'and also that you may declare repentance unto this generation.', 'standard')
