INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-dc-2017:section-12-5c', 'coc-dc-2017', 'Doctrine and Covenants', 12, 12, 'And behold, thou art David, and thou art called to assist, which thing if thou doest and art faithful, thou shalt be blessed both spiritually and temporally, and great shall be thy reward. Amen.', 'standard')
