INSERT INTO verses (id, "editionId", book, chapter, verse, text, "verseType")
VALUES ('coc-dc-2017:section-15-1c', 'coc-dc-2017', 'Doctrine and Covenants', 15, 3, 'and it is by your faith that you shall obtain a view of them, even by that faith which was had by the prophets of old.', 'standard')
